  var C=window.YLT_CFG||{};var books=C.books||(window.GAME_CONFIG&&window.GAME_CONFIG.books)||[];var byId={};for(var i=0;i<books.length;i++)byId[books[i].id]=books[i];
  function acc(id,chs){var b=byId[id];if(!b)return;b.chapters=(b.chapters||[]).concat(chs);}
  acc("b_bencao",[{"n": 26, "text": "卷二十六\n\n点茶、烹肉皆宜。气味皆似香蕈，而不及其风韵也。又广西横州出雷菌，遇雷过即生，须疾 \n采之，稍迟则腐或老，故名。作羹甚美，亦如鸡 之属。 \n此数种其价并珍。 \n【气味】甘，平，无毒。 \n【主治】益胃清神，治痔（时珍）。 \n\n\n\n<目录>菜部二十八卷\\菜之五\n\n<篇名>舵菜\n\n内容：（《纲目》） \n【集解】时珍曰∶此即海舶舵上所生菌也。亦不多得。 \n【气味】咸、甘，寒，无毒。 \n【主治】瘿结气，痰饮（时珍）。 \n\n\n\n<目录>菜部二十八卷\\菜之五\n\n<篇名>土菌\n\n内容：（《拾遗》） \n【校正】自草部移入此。 \n【释名】杜蕈（《菌谱》）、地蕈（《拾遗》）、菰子（《食物》）、地鸡（《尔雅》）、獐头。 \n藏器曰∶地生者为菌，木生者为 。江东人呼为蕈。《尔雅》云∶中馗，菌也。孙炎注 \n云∶地蕈子也。或云地鸡，亦云獐头。 \n郭璞注云∶地蕈似钉盖，江东名为土菌，可啖。凡菌从地中出者，皆主疮疥，牛粪上黑 \n菌尤佳。若烧灰地上经秋雨，生菌重台者，名仙人帽，大主血病。 \n时珍曰∶中馗神名，又槌名也。此菌钉上若伞，其状如槌及中馗之帽，故以名之。 \n【气味】甘，寒，有毒。 \n诜曰∶菌子有数般，槐树上者良。野田中者有毒杀人，又多发冷气，令人腹中微微痛， \n发五脏风，拥经脉，动痔病，令人昏昏多睡，背膊四肢无力。 \n藏器曰∶菌，冬春无毒，夏秋有毒，有蛇、虫从下过也。夜中有光者，欲烂无虫者，煮 \n之不熟者，煮讫照人无影者，上有毛下无纹者，仰卷赤色者，并有毒杀人。中其毒者，地浆 \n及粪汁解之。 \n颖曰∶凡煮菌，投以姜屑、饭粒，若色黑者杀人，否则无毒。 \n时珍曰∶按∶《菌谱》云∶杜蕈生土中，与山中鹅膏蕈相乱。俗言毒 之气所成，食之 \n杀人。 \n甚美有恶，食肉不食马肝，未为不知味也。凡中其毒者，必笑不止。解之以苦茗、白矾， \n酌新水并咽之，无不立愈。又按∶杨士瀛《直指方》云∶广南人杀毒蛇，覆之以草，以水洒 \n之，数日菌生。采干为末，入酒毒人。遇再饮酒，毒发立死。又陈氏《拾遗》云∶南夷以胡 \n蔓草毒人至死，悬尸于树，汁滴地上，生菌子收之，名菌药，毒人至烈。此皆不可不知，故 \n并记之。马勃亦菌类，见草部。 \n【主治】烧灰，敷疮疥（藏器）。 \n【附方】新一。 \n疔肿∶黑牯牛撒粪石上，待生菌子，焙干， 草等分为末。以竹筒去两头，紧缚，合 \n住疔上。用水和末一钱，入筒内。 \n少顷沸起，则根拔出。未出，再作二、三次。（《医学正传》）。 \n【附录】鬼盖 《别录》有名未用曰∶味甘，平，无毒。主小儿寒热痫。丛生垣墙下， \n赤色，旦生暮死。一名地盖。 \n弘景曰∶一名朝生，即今鬼伞也。 \n藏器曰∶一名鬼屋。生阴湿处，如菌，其盖黑而茎赤。和醋，敷肿毒、恶疮、马脊肿。 \n杜正伦曰∶鬼伞有小毒。夏日得雨，聚生粪堆，见日即消黑。 \n时珍曰∶此亦土菌之类，朝生夕死者。烧灰治疔肿，以针刺破四边，纳灰入内，经宿出 \n根。 \n\n\n\n<目录>菜部二十八卷\\菜之五\n\n<篇名>地芩\n\n内容：《别录》曰∶味苦，无毒。主小儿痫，除邪养胎，风痹洗洗寒热，目中青翳，女子带下。 \n生腐木积草处。天雨生盖，如朝生，黄白色。四月采之。 \n时珍曰∶此即鬼盖之色黄白者，其功亦相近。 \n鬼笔（《拾遗》） \n藏器曰∶鬼笔生粪秽处。头如笔，紫色。朝生暮死，名朝生暮落花。 \n小儿呼为狗溺苔。主治疮疽 疥痈 。并晒干研末，和油涂之。 \n凡菌从地出者，皆主疮疥，牛粪上黑菌尤佳。 \n时珍曰∶此亦鬼盖之类而无伞者。红紫松虚，如花之状，故得花名。研末，敷下疳疮。 \n\n\n\n<目录>菜部二十八卷\\菜之五\n\n<篇名>竹蓐\n\n内容：（《食疗》） \n【校正】并入《拾遗》竹肉。 \n【释名】竹肉（《拾遗》）、竹菰（《纲目》）、竹蕈。 \n时珍曰∶草更生曰蓐，得溽湿之气而成也。陈藏器《本草》作竹肉，因其味也。 \n【集解】诜曰∶慈竹林夏月逢雨，滴汁着地生蓐。似鹿角，白色，可食。 \n藏器曰∶竹肉生苦竹枝上。如鸡子，似肉脔，有大毒。以灰汁煮三度炼讫，然后依常菜 \n茹食之。炼不熟者，戟人喉出血，手爪尽脱。应别有功，人未尽识之。 \n时珍曰∶此即竹菰也。生朽竹根节上。状如木耳，红色。段成式《酉阳杂俎》云∶江淮 \n有竹肉，大如弹丸，味如白树鸡。即此物也。惟苦竹生者有毒耳。 \n【气味】甘、咸，寒，无毒。 \n藏器曰∶苦竹肉∶有大毒。 \n【主治】一切赤白痢，和姜、酱食之（孟诜）。苦竹肉∶灰汁炼过食，杀三虫毒邪气， \n破老血（藏器）。 \n\n\n\n<目录>菜部二十八卷\\菜之五\n\n<篇名>菌\n\n内容：（音桓郡。《本经》下品） \n【校正】自草部移入此。 \n【释名】 芦（《本经》）。 \n时珍曰∶ 当作萑，乃芦苇之属，此菌生于其下，故名也。若 音观，乃鸟名，与萑芦 \n无关。 \n【集解】《别录》曰∶ 菌生东海池泽及渤海章武。八月采，阴干。 \n弘景曰∶出北来，此亦无有。形状似菌，云鹳屎所化生，一名鹳菌。单末之，猪肉 \n和食，可以遣蛔虫。 \n恭曰∶ 菌今出渤海芦苇泽中碱卤地，自然有此菌尔，非鹳屎所化生也。其菌色白轻虚， \n表里相似，与众菌不同。疗蛔有效。 \n保升曰∶今出沧州。秋雨以时即有，天旱久霖即稀。晒干者良。 \n【气味】咸，平，有小毒。 \n《别录》曰∶甘，微温。 \n权曰∶苦。得酒良，畏鸡子。 \n【主治】心痛，温中，去长虫白癣蛲虫，蛇螫毒，症瘕诸虫（《本经》）。疽蜗，去蛔虫、 \n寸白，恶疮（《别录》）。除腹内冷痛，治白秃（甄权）。 \n【附方】旧一。 \n蛔虫攻心如刺，吐清汁者∶萑菌一两杵末，羊肉 和食之，日一顿，大效。（《外台秘 \n要》） \n【附录】蜀格 《别录》曰∶味苦，平，无毒。主寒热痿痹，女子带下痈肿。生山阳， \n如萑菌而有刺。 \n\n\n\n<目录>菜部二十八卷\\菜之五\n\n<篇名>地耳\n\n内容：（《别录》） \n【校正】自有名未用移入此。 \n【释名】地踏菰（《纲目》）。 \n【集解】《别录》曰∶地耳生丘陵，如碧石青也。 \n时珍曰∶地耳亦石耳之属，生于地者也。状如木耳。春夏生雨中，雨后即早采之，见日 \n即不堪。俗名地踏菰是也。 \n【气味】甘，寒，无毒。 \n【主治】明目益气，令人有子（《别录》）。 \n\n\n\n<目录>菜部二十八卷\\菜之五\n\n<篇名>石耳\n\n内容：（《日用》） \n【释名】灵芝（《灵苑方》）。 \n【集解】瑞曰∶石耳生天台、四明、河南、宣州、黄山、巴西、边徼诸山石崖上，远望 \n如烟。 \n时珍曰∶庐山亦多，状如地耳。山僧采曝馈远。洗去沙土，作茹胜于木耳，佳品也。 \n【气味】甘，平，无毒。 \n颖曰∶冷。段成式曰∶热。 \n【主治】久食益色，至老不改，令人不饥，大小便少（吴瑞）。 \n明目益精（时珍）。 \n【附方】新一。 \n泻血脱肛∶石耳五两（炒），白枯矾一两，密陀僧半两，为末，蒸饼丸梧子大，每米饮 \n下二十丸。（《普济方》） \n互考诸菜香薷 紫苏 紫菀 錾菜 牛膝苗 防风苗 薄荷 荏苏 马兰 蒌蒿 泽兰 \n根地黄苗 诸葵 菜 酸模 菖蒲 牛蒡苗 青葙苗 龙葵 决明 甘蓝 萝 红花 \n苗车前苗 萱草 芦笋 茭笋 苹 海苔菜 独帚苗 羊蹄 蒲笋 菜 齐头蒿 \n昆布苗 昆布 地菘 蓼芽 海藻 王瓜 百部 藕丝 荷 头 芡茎 菱茎 豆藿 \n豆芽 豆荚 豆腐 罂粟苗 椿芽 槐芽 芜荑 枸杞 皂荚苗 榆芽 槿芽 棕笋 五加 \n\n\n\n<目录>\n\n<篇名>果部第二十九卷\n\n内容：李时珍曰∶木实曰果，草实曰 。熟则可食，干则可脯。 \n丰俭可以济时，疾苦可以备药。辅助粒食，以养民生。故《素问》云∶五果为助。五果 \n者，以五味、五色应五脏，李、杏、桃、栗、枣是矣。古书欲知五谷之收否，但看五果之盛 \n衰（李主小豆，杏主大麦，桃主小麦，栗主稻，枣主禾）。《礼记·内则》列果品菱、 、榛、 \n瓜之类。周官职方氏辨五地之物，山林宜皂物（柞 \n、栗之属），川泽宜膏物（菱、芡之属）。 \n丘陵宜核物（梅、李之属）。甸师掌野果 。场人树果 珍异之物，以时藏之。观此， \n则果 \n之土产常异，性味良毒，岂可纵嗜欲而不知物理乎？于是集草木之实号为果 者为果部，凡 \n一百二十七种。分为六类∶曰五果，曰山，曰夷，曰味，曰 ，曰水。旧本果部三品共五十 \n三种。今移一种入菜部，四种入草部。自木部移入并附三十一种，草部移入四种，菜部移入 \n一种，外类移入四种。 \n《神农本草经》十二种（梁陶弘景注） 《名医别录》十六种（同上） 《唐本草》十 \n一种（唐苏恭） 《本草拾遗》二十种（唐陈藏器） 《海药本草》一种（唐李 ） 《食 \n性本草》一种（唐陈士良） 《食疗本草》一种（唐孟诜） 《开宝本草》十九种（宋马志） \n《嘉 本草》二种（宋掌禹锡） 《图经本草》五种（宋苏颂） 《日华本草》二种（宋人 \n大明） 《食物本草》一种（明汪颖） 《日用本草》二种（元吴瑞） 《本草会编》一种 \n（明汪机） 《本草纲目》三十三种（明李时珍） \n【附注】魏《吴普本草》 李当之《本草》 宋雷 《炮炙论》 齐徐之才《药对》 唐·甄 \n权《药性》 孙思邈《千金》 唐·萧炳《四声》 杨损之《删繁》 蜀韩保升《重注》 宋·寇 \n宗《衍义》 唐·慎微《证类》 金·张元素《珍珠囊》 元·李杲《法象》 王好古《汤 \n液》 朱震亨《补遗》 明·宁原《食鉴》 周定王《救荒》 陈嘉谟《蒙筌》 \n\n\n\n<目录>果部第二十九卷\n\n<篇名>果之一\n\n内容：（五果类一十一种） \n\n\n\n<目录>果部第二十九卷\\果之一\n\n<篇名>李\n\n内容：（《别录》下品） \n【释名】嘉庆子。 \n时珍曰∶按∶罗愿《尔雅翼》云∶李乃木之多子者，故字从木、子。窃谓木之多子者多 \n矣，何独李称木子耶？按∶《素问》言∶李味酸属肝，东方之果也 \n。则李于五果属木，故得专称尔。今人呼干李为嘉庆子。按∶韦述《两京记》云∶东都嘉庆 \n坊有美李，人称为嘉庆子。 \n久之称谓既熟，不复知其所自矣。梵书名李曰居陵迦。 \n【集解】弘景曰∶李类甚多。京口有麦李，麦秀时熟，小而肥甜，核不入药。姑熟有南 \n居李，解核如杏子形者，入药为佳。 \n志曰∶李有绿李、黄李、紫李、牛李、水李，并甘美堪食，核不中用。有野李，味苦， \n核仁入药。 \n颂曰∶李处处有之。郭璞注《尔雅》∶休，乃无实李也。一名赵李。痤（音磋），乃接虑 \n李也。一名麦李。细熟有沟道，与麦同熟。驳，乃赤李也。陶氏所谓南居李，今不复识。医 \n家但用核若杏核者。 \n宗 曰∶李树大者高丈许。一种御李子，大如樱桃，红黄色，先诸李熟，医家用者亦少。 \n时珍曰∶李，绿叶白花，树能耐久，其种近百。其子大者如杯如卵，小者如弹如樱。其 \n味有甘、酸、苦、涩数种。其色有青、绿、紫、朱、黄、赤、缥绮、胭脂、青皮、紫灰之殊。 \n其形有牛心、马肝、柰李、杏李、水李、离核、合核、无核、匾缝之异。其产有武陵、房陵 \n诸李。早则麦李、御李，四月熟。迟则晚李、冬李，十月、十一月熟。又有季春李，冬花春 \n实也。按∶王祯《农书》云∶北方一种御黄李，形大而肉浓核小，甘香而美。江南建宁一种 \n均亭李，紫而肥大，味甘如蜜。有擘李，熟则自裂。有糕李，肥粘如糕。皆李之嘉美者也。 \n今人用盐曝、糖藏、蜜煎为果，惟曝干白李有益。其法∶夏李色黄时摘之，以盐 去汁 \n，合盐晒萎，去核复晒干，荐酒、作 皆佳。 \n\\x实\\x \n【气味】苦、酸，微温，无毒。 \n时珍曰∶李味甘酸，其苦涩者不可食。不沉水者有毒，不可食。 \n大明曰∶多食令人胪胀，发虚热。 \n诜曰∶临水食之，令发痰疟。不可合雀肉食。合蜜食，损五脏。 \n宗 曰∶不可合浆水食，发霍乱，涩气而然。服术人忌之。 \n【主治】暴食，去痼热，调中（《别录》）。去骨节间劳热（孟诜）。肝病宜食之（思邈）。 \n\\x核仁\\x \n【气味】苦，平，无毒。 \n【主治】僵仆 折，瘀血骨痛（《别录》）。 \n令人好颜色（吴普）。治女子少腹肿满。利小肠，下水气，除浮肿（甄权）。治面 黑子 \n（苏颂）。 \n【附方】旧一，新一。 \n女人面 ∶用李核仁去皮细研，以鸡子白和如稀饧涂之。至旦以浆水洗去，后涂胡粉。 \n不过五、六日效。忌见风。（崔元亮《海上方》）。 \n蝎虿螫痛∶苦李仁嚼涂之，良。（《古今录验》）。 \n\\x根白皮\\x \n【修治】时珍曰∶李根皮取东行者，刮去皱皮，炙黄入药用。《别录》不言用何等李根， \n亦不言其味。但《药性论》云∶入药用苦李根皮，味咸。而张仲景治奔豚气，奔豚汤中用甘 \n李根白皮。则甘、苦二种皆可用欤？ \n【气味】大寒，无毒。大明曰∶凉，无毒。 \n【主治】消渴，止心烦逆奔豚气（《别录》）。治疮（吴普）。煎水含漱，治齿痛（弘景）。 \n煎汁饮，主赤白痢（大明）。炙黄煎汤，日再饮之，治女人卒赤白下，有验（孟诜）。治小儿 \n暴热，解丹毒（时珍）。苦李根皮∶味咸，治脚下气，主热毒烦躁。煮汁服，止消渴（甄权）。 \n【附方】新二。 \n小儿丹毒，从两股走及阴头∶用李根烧为末，以田中流水和涂之。（《千金》）。 \n咽喉卒塞，无药处，以皂角末吹鼻取嚏∶仍以李树近根皮，磨水涂喉外，良验。（《菽 \n园杂记》）。 \n\\x花\\x \n【气味】苦，香，无毒。 \n【主治】令人面泽，去粉滓 （时珍）。 \n【附方】新一。 \n面黑粉滓∶用李花、梨花、樱桃花、白蜀葵花、白莲花、红莲花、旋复花、秦椒各六两， \n桃花、木瓜花、丁香、沉香、青木香、钟乳粉各三两，珍珠、玉屑各二两，蜀水花一两，大 \n豆末七合，为细末瓶收。每日盥 ，用洗手面，百日光洁如玉也。（《普济方》）。 \n\\x叶\\x \n【气味】甘、酸，平，无毒。 \n【主治】小儿壮热， 疾惊痫，煎汤浴之，良（大明）。 \n【附方】新一。 \n恶刺疮痛∶李叶、枣叶捣汁点之，效。（《千金》）。 \n\\x树胶\\x \n【气味】苦，寒，无毒。 \n【主治】目翳，定痛消肿（时珍）。 \n【附录】徐李 《别录》有名未用曰∶生太山之阴。树如李而小。 \n其实青色，无核。熟则采食之，轻身益气延年。 \n时珍曰∶此即无核李也。唐崔奉国家有之，乃异种也。谬言龙耳血堕地所生。 \n\n\n\n<目录>果部第二十九卷\\果之一\n\n<篇名>杏\n\n内容：（《别录》下品） \n【释名】甜梅。 \n时珍曰∶杏字篆文象子在木枝之形。或云从口及从可者，并非也。《江南录》云 \n∶杨行密改杏名甜梅。 \n【集解】《别录》曰∶杏生晋山川谷。五月采之。 \n颂曰∶今处处有之。有数种∶黄而圆者名金杏，相传种出自济南郡之分流山，彼人谓之 \n汉帝杏，言汉武帝上苑之种也。今近汴洛皆种之，熟最早。其扁而青黄者名木杏，味酢不及 \n之。 \n山杏不堪入药。杏仁今以从东来人家种者为胜。 \n宗 曰∶金杏深赭色，核大而扁，乃接成者，其味最胜。又有白杏，熟时色青白或微黄 \n，味甘淡而不酢。生杏可晒脯作干果食之。山杏辈只可收仁用耳。 \n时珍曰∶诸杏，叶皆圆而有尖，二月开红花，亦有千叶者，不结实。甘而有沙者为沙杏 \n，黄而带酢者为梅杏，青而带黄者为柰杏。其金杏大如梨，黄如橘。《西京杂记》载蓬莱杏 \n花五色，盖异种也。按∶王祯《农书》云∶北方肉杏甚佳，赤大而扁，谓之金刚拳。凡杏熟 \n时，榨浓汁，涂盘中晒干，以手摩刮收之，可和水调 食，亦五果为助之义也。 \n\\x实\\x \n【气味】酸，热，有小毒。生食多，伤筋骨（《别录》）。 \n颂曰∶杏之类梅者味酢，类桃者味甘。 \n宗 曰∶凡杏性皆热。小儿多食，致疮痈膈热。 \n扁鹊曰∶多食动宿疾，令人目盲、须眉落。 \n源曰∶多食，生痰热，昏精神。产妇尤忌之。 \n【主治】曝脯食，止渴，去冷热毒。心之果，心病宜食之（思邈）。 \n\\x核仁\\x \n【修治】《别录》曰∶五月采之。 \n弘景曰∶凡用杏仁，以汤浸去皮尖，炒黄。或用面麸炒过。 \n曰∶凡用，以汤浸去皮尖。每斤入白火石一斤，乌豆三合，以东流水同煮，从巳至午 \n，取出晒干用。 \n时珍曰∶治风寒肺病药中，亦有连皮尖用者，取其发散也。 \n【气味】甘、苦，温、冷利，有小毒。两仁者杀人，可以毒狗。 \n震亨曰∶杏仁性热，因寒者可用。 \n思邈曰∶杏仁作汤如白沫不解者，食之令气壅身热。汤经宿者动冷气。 \n时珍曰∶凡杏、桃诸花皆五出。若六出必双仁，为其反常，故有毒也。 \n徐之才曰∶得火良。恶黄芩、黄 、葛根，畏 草。 \n【主治】咳逆上气雷鸣，喉痹，下气，产乳金疮，寒心奔豚（《本经》）。惊痫，心下烦 \n热，风气往来，时行头痛，解肌，消心下急满痛，杀狗毒（《别录》）。解锡毒（之才）。治腹 \n痹不通，发汗，主温病香港脚，咳嗽上气喘促。入天门冬煎，润心肺。和酪作汤，润声气 \n（甄权）。除肺热，治上焦风燥，利胸膈气逆，润大肠气秘（元素）。杀虫，治诸疮疥，消肿， \n去头面诸风气 （时珍）。 \n【发明】元素曰∶杏仁气薄味浓，浊而沉坠，降也、阴也。入手太阴经。其用有三∶润 \n肺也，消食积也，散滞气也。 \n杲曰∶杏仁散结润燥，除肺中风热咳嗽。杏仁下喘，治气也；桃仁疗狂，治血也。俱治 \n大便秘，当分气、血。昼则便难，行阳气也；夜则便难，行阴血也。故虚人便闭，不可过泄。 \n脉浮者属气，用杏仁、陈皮；脉沉者属血，用桃仁、陈皮。手阳明与手太阴为表里，贲 \n门主往来，魄门主收闭，为气之通道，故并用陈皮佐之。 \n好古曰∶张仲景麻黄汤，及王朝奉治伤寒气上喘逆，并用杏仁者，为其利气、泻肺、解 \n肌也。 \n时珍曰∶杏仁能散能降，故解肌散风、降气润燥、消积治伤损药中用之。治疮杀虫，用 \n其毒也。按∶《医余》云∶凡索面、豆粉近杏仁则烂。顷一兵官食粉成积，医师以积气丸、 \n杏仁相半研为丸，熟水下，数服愈。又《野人闲话》云∶翰林学士辛士逊，在青城山道院中， \n梦皇姑谓曰∶可服杏仁，令汝聪明，老而健壮，心力不倦。求其方，则用杏仁一味，每盥漱 \n毕，以七枚纳口中，良久脱去皮，细嚼和津液顿咽。日日食之，一年必换血，令人轻健。此 \n申天师方也。又杨士瀛《直指方》云∶凡人以水浸杏仁五枚，五更端坐，逐粒细嚼至尽，和 \n津吞下。久则能润五脏，去尘滓，驱风明目，治肝肾风虚，瞳人带青，眼翳风痒之病。珍按∶ \n杏仁性热降气，亦非久服之药。此特其咀嚼吞纳津液，以消积秽则可耳。古有服杏丹法，云 \n是左慈之方。唐慎微收入本草，云久服寿至千万。其说妄诞可鄙，今删其纰谬之辞，存之于 \n下，使读者毋信其诳也。 \n【附方】旧三十七，新二十二。 \n杏金丹《左慈秘诀》云∶亦名草金丹。方出浑皇子，服之长年不死。 \n夏姬服之，寿年七百，乃仙去也。世人不信，皆由不肯精心修治故也。其法∶须人罕到 \n处。 \n寅月 杏树地下，通阳气。二月除树下草。三月离树五步作畦垄，以通水。亢旱则引 \n泉灌溉。有霜雪则烧火树下，以救花苞。至五月杏熟自落，收仁六斗，以汤浸去皮及双仁者， \n用南流水三石和研，取汁两石八斗，去滓。以新铁釜用酥三斤，以糠火及炭然釜，少少磨酥 \n至尽，乃内汁入釜。釜上安盆，盆上钻孔，用弦悬车辖至釜底，以纸塞孔，勿令泄气。初着 \n糠火，一日三动车辖，以衮其汁。五日有露液生，十日白霜起，又二日白霜尽，即金花出， \n丹乃成也。开盆炙干，以翎扫下，枣肉和，丸梧子大。每服三丸，空心暖酒下。至七日宿疾 \n皆除，喑盲挛跛、疝痔瘿痫疮肿，万病皆愈。久服通灵不死云云。衍文不录。颂曰∶古方用 \n杏仁修治如法，自朝蒸至午，便以慢火微烘，至七日乃收之。每旦空腹啖之，久久不止，驻 \n颜延年，云是夏姬之法。然杏仁能使人血溢，少误必出血不已，或至委顿，故近人少有服者。 \n或云服至二、三年，往往或泻，或脐中出物，皆不可治也。 \n杏酥法颂曰∶去风虚，除百病。捣烂杏仁一石，以好酒二石，研滤取汁一石五斗，入白 \n蜜一斗五升搅匀，封于新瓮中，勿泄气。三十日看酒上酥出，即掠取纳瓷器中贮之。取其酒 \n滓团如梨大，置空屋中，作格安之。候成饴脯状，旦服一枚，以前酒下。 \n藏器曰∶杏酪服之，润五脏，去痰嗽。生、熟吃俱可，若半生半熟服之杀人。 \n又法宗 曰∶治肺燥喘热，大肠秘，润五脏。用杏仁去皮研细，每一升，入水一升半， \n捣稠汁。入生蜜四两，甘草一寸，银、石器中慢火熬成稀膏，入酥二两同收。每夜沸汤，点 \n服一匙。（《衍义》）。 \n万病丸∶治男妇五劳七伤，一切诸疾。杏仁一斗二升，童子小便煮七次，以蜜四两拌匀， \n再以童便五升于碗内重蒸，取出日晒夜露数日。任意嚼食，即愈。 \n补肺丸，治咳嗽。用杏仁二大升（山中者不用，去双仁者），以童子小便二斗浸之，春 \n夏 \n七日，秋冬二七日，连皮尖于砂盆中研滤取汁，煮令鱼眼沸，候软如面糊即成。以粗布摊曝 \n之，可丸即丸服之。食前后总须服三、五十丸，茶、酒任下。忌白水粥。（刘禹锡《传信方》）。 \n咳嗽寒热，旦夕加重，少喜多嗔，面色不润，忽进忽退，积渐少食，脉弦紧者∶杏仁半斤去 \n皮尖，童子小便二斗浸七日，漉出温水淘洗，砂盆内研如泥，以小便三升煎如膏。每服一钱， \n熟水下。妇人室女服之，尤妙。（《千金方》）。 \n久患肺气，喘急至咳。甚者不过二剂，永瘥∶杏仁去皮尖二两，童子小便浸，一日一换， \n夏月三、四换，满半月取出，焙干研细。每服一枣大，薄荷一叶，蜜一鸡头大，水一钟，煎 \n七分，食后温服。忌腥物。（《胜金方》）。 \n咳逆上气，不拘大人小儿∶以杏仁三升去皮尖，炒黄研膏，入蜜一升，杵熟。每食前含 \n之，咽汁。（《千金》）。 \n上气喘急∶杏仁、桃仁各半两，去皮尖炒研，用水调生面和，丸梧子大。每服十丸，姜、 \n蜜汤下，微利为度。（《圣济总录》）。 \n喘促浮肿，小便淋沥∶用杏仁一两，去皮尖熬研，和米煮粥，空心吃二合妙。（《心镜》）。 \n头面风肿∶杏仁捣膏，鸡子黄和杵，涂帛上，浓裹之。干则又涂，不过七、八次愈也。 \n（《千金方》）。 \n风虚头痛欲破者∶杏仁去皮尖，晒干研末，水九升研滤汁，煎如麻腐状，取和羹粥食。 \n七日后大汗出，诸风渐减。此法神妙，可深秘之。慎风、冷、猪、鸡、鱼、蒜、醋。（《千 \n金方》）。 \n头面诸风，眼 鼻塞，眼出冷泪∶用杏仁三升研细，水煮四、五沸，洗头。待冷汗尽， \n三度愈。（《千金》）。 \n偏风不遂，失音不语∶生吞杏仁七枚，不去皮尖，逐日加至七七枚，周而复始。食后仍 \n饮竹沥，以瘥为度。（《外台秘要》）。 \n破伤风肿∶杏仁杵膏浓涂上，然烛遥炙之。（《千金方》）。 \n金疮中风，角弓反张∶用杏仁杵碎，蒸令气溜，绞脂服一小升，兼摩疮上良。（《必效方》）。 \n温病食劳∶杏仁五两，酢二升，煎取一升，服之取汗瘥。（《类要》）。 \n心腹结气∶杏仁、桂枝、橘皮、诃黎勒皮等分，为丸。每服三十丸，白汤下。无忌。（孟 \n诜《食疗》）。 \n喉痹痰嗽∶杏仁（去皮熬黄）三分，和桂末一分，研泥，裹含之，咽汁。（陈藏器《本 \n草》）。 \n喉热生疮∶方同上。 \n卒失音声∶方同上。（文潞公《药准》）。 \n肺病咯血∶杏仁四十个，以黄蜡炒黄，研入青黛一钱，作饼。用柿饼一个，破开包药， \n湿纸裹煨熟食之，取效。（丹溪方）。 \n卒不小便∶杏仁二七枚，去皮尖，炒黄研末，米饮服之。（《古今录验》方）。 \n血崩不止∶诸药不效，服此立止。用甜杏仁上黄皮，烧存性，为末。每服三钱，空心热 \n酒服。（《保寿堂方》）。 \n五痔下血∶杏仁去皮尖及双仁者，水三升，研滤汁，煎减半，同米煮粥食之。（《食医 \n心镜》）。 \n谷道 痛肿痒∶杏仁杵膏，频频敷之。（《肘后方》）。 \n阴疮烂痛∶杏仁烧黑研成膏，时时敷之。（《钤方》）。 \n产门虫疽，痛痒不可忍∶用杏仁去皮烧存性，杵烂绵裹，纳入阴中，取效。（孟诜《食 \n疗本草》）。 \n身面疣目∶杏仁烧黑研膏，擦破，日日涂之。（《千金方》）。 \n面上 ∶杏仁去皮，捣和鸡子白。夜涂之，旦以暖酒洗去。（孟诜《食疗》）。 \n两颊赤痒，其状如痱，名头面风。以杏仁频频揩之。内服消风散。（《证治要诀》）。 \n耳卒聋闭∶杏仁七枚，去皮拍碎，分作三分，以绵裹之，着盐如小豆许，以器盛于饭上 \n蒸熟。令病患侧卧，以一裹捻油滴耳中。良久又以一裹滴之，取效。（《外台》）。 \n耳出脓汁∶杏仁炒黑，捣膏绵裹纳入，日三、四易之妙。（《梅师方》）。 \n鼻中生疮∶杏仁研末，乳汁和敷。（《千金方》）。 \n疳疮蚀鼻∶杏仁烧，压取油敷之。（《千金方》）。 \n牙齿虫 ∶杏仁烧存性，研膏发裹，纳虫孔中。杀虫去风，其痛便止。重者不过再上。 \n（《本草拾遗》）。 \n牙龈痒痛∶杏仁一百枚，去皮尖，两仁，以盐方寸匕，水一升，煮令汁出，含漱吐之。 \n三度愈。（《千金方》）。 \n风虫牙痛∶杏仁，针刺于灯上烧烟，乘热搭病牙上。又复烧搭七次。绝不疼，病牙逐时 \n断落也。（《普济方》）。 \n目中赤脉痒痛，时见黑花。用初生杏子仁一升，古五铢钱七文，入瓶内密封，埋门限下， \n一百日化为水，每夕点之。（《圣济总录》）。 \n胎赤眼疾∶杏仁压油半鸡子壳，食盐一钱，入石器中，以柳枝一握紧束，研至色黑，以 \n熟艾一团安碗内烧烘之，令气透火尽即成。每点少许入两 ，甚效。（《圣济总录》）。 \n目中翳遮，但瞳子不破者∶用杏仁三升去皮，面裹作三包， 火煨熟，去面研烂，压去 \n油。每用一钱，入铜绿一钱，研匀点之。（同上）。 \n目生 肉，或痒或痛，渐覆瞳人∶用杏仁（去皮）二钱半，腻粉半钱，研匀，绵裹箸头 \n点之。（同上）。 \n伤目生 《广利方》∶用生杏仁七枚，去皮细嚼，吐于掌中，乘热以绵裹箸头点 肉上。 \n不过四、五度愈。《总录》∶用杏仁研膏，人乳化开，日点三次。 \n小儿血眼∶儿初生艰难，血瘀 睚，遂溅渗其睛，不见瞳人。轻则外胞赤肿，上下弦烂∶ \n用杏仁二枚去皮尖，嚼，乳汁三、五匙，入腻粉少许，蒸熟，绢包频点。重者加黄连、朴硝 \n最良。（《全幼心鉴》）。 \n小儿脐烂成风∶杏仁去皮研敷。（《子母秘录》）。 \n小儿咽肿∶杏仁炒黑，研烂含咽。（《普济方》）。 \n针入肉内不出者∶双杏仁捣烂，以车脂调贴。其针自出。（《瑞竹堂方》）。 \n箭镝在咽，或刀刃在咽膈诸隐处∶杵杏仁敷之。（《肘后方》）。 \n狐尿疮痛∶杏仁研烂，煮一、两沸，及热浸之。冷即易。（《必效方》）。 \n狗咬伤疮∶烂嚼杏仁涂之。（寇氏）。 \n食狗不消，心下坚胀，口干发热妄语∶杏仁一升去皮尖，水三升煎沸，去渣取汁分三服， \n下肉为度。（《梅师方》）。 \n解野狼毒毒∶杏仁捣烂，水和服之。（《千金方》）。 \n一切食停，气满膨胀∶用红杏仁三百粒，巴豆二十粒同炒，色变去豆不用，研杏为末， \n橘皮汤调下。（《杨氏家藏方》） \n白癜风斑∶杏仁连皮尖，每早嚼二七粒，揩令赤色。夜卧再用。（《圣济总录》）。 \n诸疮肿痛∶杏仁去皮，研滤取膏，入轻粉、麻油调搽神效。不拘大人、小儿。（鲍氏）。 \n小儿头疮∶杏仁烧研敷之。（《事林广记》）。 \n蛆虫入耳∶杏仁捣泥，取油滴入。非出则死。（《扶寿精方》） \n\\x花\\x \n【气味】苦，温，无毒。 \n【主治】补不足，女子伤中，寒热痹厥逆（《别录》）。 \n【附方】新二。 \n妇人无子∶二月丁亥日，取杏花、桃花阴干为末。戊子日和井华水服方寸匕，日三服。 \n（《卫生易简方》）。 \n粉滓面 ∶杏花、桃花各一升，东流水浸七日。洗面三七遍，极妙。（《圣济总录》）。 \n\\x叶\\x \n【主治】人卒肿满，身面洪大，煮浓汁热渍，亦少少服之（《肘后》）。 \n\\x枝\\x \n【主治】堕伤，取一握，水一升煮减半，入酒三合和匀，分再服，大效（苏颂）。 \n【附方】旧一。 \n坠扑瘀血在内，烦闷者∶用东引杏树枝三两，细锉微熬，好酒二升煎十余沸，分二服。 \n（《塞上方》） \n\\x根\\x \n【主治】食杏仁多，致迷乱将死，切碎煎汤服，即解（时珍）。 \n\n\n\n<目录>果部第二十九卷\\果之一\n\n<篇名>巴旦杏\n\n内容：（《纲目》） \n【释名】八担杏（《正要》）、忽鹿麻。 \n【集解】时珍曰∶巴旦杏，出回回旧地，今关西诸土亦有。树如杏而叶差小，实亦尖小 \n而肉薄。其核如梅核，壳薄而仁甘美。点茶食之，味如榛子。西人以充方物。 \n【气味】甘，平，温，无毒。 \n【主治】止咳下气，消心腹逆闷（时珍。出《饮膳正要》）。 \n\n\n\n<目录>果部第二十九卷\\果之一\n\n<篇名>梅\n\n内容：（《本经》中品） \n【释名】时珍曰∶梅古文作呆，象子在木上之形。梅乃杏类，故反杏为呆。书家讹为甘 \n木。后作梅，从每，谐声也。或云∶梅者媒也，媒合众味。故书云∶若作和羹，尔惟盐梅。 \n而梅字亦从某也。陆佃《埤雅》言梅入北方变为杏，郭璞注《尔雅》以 为梅，皆误矣。 \n即 木，荆人呼为梅，见陆玑《草木疏》。 \n【集解】《别录》曰∶梅实生汉中山谷。五月采实，火干。 \n颂曰∶今襄汉、川蜀、江湖、淮岭皆有之。 \n时珍曰∶按∶陆玑《诗疏》云∶梅，杏类也。树、叶皆略似杏，叶有长尖，先众木而花 \n。其实酢，曝干为脯，入羹 齑中，又含之可以香口。子赤者材坚，子白者材脆。范成大《梅 \n谱》云∶江梅，野生者，不经栽接，花小而香，子小而硬。消梅，实圆松脆，多液无滓，惟 \n可生啖，不入煎造。绿萼梅，枝跗皆绿。重叶梅，花叶重叠，结实多双。红梅，花色如杏。 \n杏梅，色淡红，实扁而斑，味全似杏。鸳鸯梅，即多叶红梅也，一蒂双实。一云∶苦楝接梅， \n则花带黑色。谭子化书云∶李接桃而本强者其实毛，梅接杏而本强者其实甘。梅实采半黄者， \n以烟熏之为乌梅；青者盐腌曝干为白梅。亦可蜜煎、糖藏，以充果 。熟者笮汁晒收为梅酱 \n惟乌梅、白梅可入药。梅酱，夏月可调渴水饮之。 \n\\x实\\x \n【气味】酸，平，无毒。 \n大明曰∶多食损齿伤筋，蚀脾胃，令人发膈上痰热。服黄精人忌食之。食梅齿 者，嚼 \n胡桃肉解之。 \n《物类相感志》云∶梅子同韶粉食，则不酸，不软牙。 \n【发明】宗 曰∶食梅则津液泄者，水生木也。津液泄则伤肾，肾属水，外为齿故也。 \n时珍曰∶梅，花开于冬而实熟于夏，得木之全气，故其味最酸，所谓曲直作酸也。肝为 \n乙木，胆为甲木。人之舌下有四窍，两窍通胆液，故食梅则津生者，类相感应也。故《素问》 \n云∶味过于酸，肝气以津。又云∶酸走筋，筋病无多食酸。不然，物之味酸者多矣，何独梅 \n能生津耶？ \n\\x乌梅\\x \n【修治】弘景曰∶用须去核，微炒之。 \n时珍曰∶造法∶取青梅篮盛，于突上熏黑。若以稻灰淋汁润湿蒸过，则肥泽不蠹。 \n【气味】酸，温、平，涩，无毒。 \n杲曰∶寒。忌猪肉。 \n【主治】下气，除热烦满，安心，止肢体痛，偏枯不仁，死肌，去青黑痣，蚀恶肉（《本 \n经》）。去痹，利筋脉，止下痢，好唾口干（《别录》）。水渍汁饮，治伤寒烦热（弘景）。止 \n渴调中，去痰治疟瘴，止吐逆霍乱，除冷热痢（藏器）。治虚劳骨蒸，消酒毒，令人得睡。 \n和建茶、干姜为丸服，止休息痢，大验（大明）。敛肺涩肠，止久嗽泻痢，反胃噎膈，蛔厥 \n吐利，消肿涌痰，杀虫，解鱼毒、马汗毒、硫黄毒（时珍）。 \n\\x白梅\\x \n【释名】盐梅、霜梅。 \n【修治】取大青梅以盐汁渍之，日晒夜渍，十日成矣。久乃上霜。 \n【气味】酸、咸，平，无毒。 \n【主治】和药点痣，蚀恶肉（弘景）。刺在肉中者，嚼敷之即出（孟诜）。治刀箭伤，止 \n血，研烂敷之（大明）。 \n乳痈肿毒，杵烂贴之，佳（汪颖）。除痰。（苏颂）。 \n治中风惊痫，喉痹痰厥僵仆，牙关紧闭者，取梅肉揩擦牙龈，涎出即开。又治泻痢烦 \n渴，霍乱吐下，下血血崩，功同乌梅（时珍）。 \n【发明】弘景曰∶生梅、乌梅、白梅，功应相似。 \n好古曰∶乌梅，脾、肺二经血分药也。能收肺气，治燥嗽。肺欲收，急食酸以收之。 \n时珍曰∶乌梅、白梅所主诸病，皆取其酸收之义。惟张仲景治蛔厥乌梅丸及虫 方中用 \n者，取虫得酸即止之义，稍有不同耳。《医说》载∶曾鲁公痢血百余日，国医不能疗。陈应 \n之用盐水梅肉一枚研烂，合腊茶，入醋服之，一啜而安。大丞梁庄肃公亦痢血，应之用乌梅、 \n胡黄连、灶下土等分为末，茶调服，亦效。盖血得酸则敛，得寒则止，得苦则涩故也。其蚀 \n恶疮 肉，虽是酸收，却有物理之妙。说出《本经》。其法载于《刘涓子鬼遗方》∶用乌梅肉 \n烧存性研，敷恶肉上，一夜立尽。《圣惠》用乌梅和蜜作饼贴者，其力缓。按∶杨起《简便 \n方》云∶起臂生一疽，脓溃百日方愈，中有恶肉突起，如蚕豆大，月余不消，医治不效。因 \n阅本草得此方，试之，一日夜去其大半，再上一日而平。乃知世有奇方如此，遂留心搜刻诸 \n方，始基于此方也。 \n【附方】旧十一，新二十二。 \n诸疮 肉∶方见上。 \n痈疽疮肿，已溃未溃皆可用∶盐白梅烧存性为末，入轻粉少许，香油调，涂四围。（王 \n氏《易简方》）。 \n喉痹乳蛾∶冰梅丸∶用青梅二十枚（盐十二两，腌五日，取梅汁），入明矾三两，桔梗、 \n白芷、防风各二两，猪牙皂角三十条，俱为细末，拌汁和梅入瓶收之。每用一枚，噙咽津液。 \n凡中风痰厥，牙关不开，用此擦之尤佳。《总录》∶用白梅包生矾末作丸含咽，或纳吞之。 \n消渴烦闷∶乌梅肉二两，微炒为末。每服二钱，水二盏，煎一盏，去滓，入豉二百粒， \n煎至半盏，温服。（《简要济众方》）。 \n泄痢口渴∶乌梅煎汤，日饮代茶。（《扶寿精方》）。 \n产后痢渴∶乌梅肉二十个，麦门冬十二分，以水一升，煮七合，细呷之 \n。（《必效方》）。 \n赤痢腹痛《直指》∶用陈白梅同真茶、蜜水各半，煎饮之。《圣惠》∶用乌梅肉（炒）、黄 \n连各四两，为末，炼蜜丸梧子大。每米饮服二十丸，日三服。 \n便痢脓血∶乌梅一两去核，烧过为末。每服二钱，米饮下，立止。（《圣济总录》）。 \n久痢不止，肠垢已出∶《肘后》∶用乌梅肉二十个，水一盏，煎六分，食前分二服。《袖珍》∶ \n用乌梅肉、白梅肉各七个捣烂，入乳香末少许，杵丸梧桐子大。每服二、三十丸，茶汤下， \n日三。大便下血，及酒痢、久痢不止∶用乌梅三两，烧存性为末，醋煮米糊和，丸梧子大。 \n每空心米饮服二十丸，日三。（《济生方》）。 \n小便尿血∶乌梅，烧存性研末，醋糊丸梧子大。每服四十丸，酒下。 \n血崩不止∶乌梅肉七枚，烧存性研末。米饮服之，日二。 \n大便不通，气奔欲死者∶乌梅十颗，汤浸去核，丸枣大。纳入下部，少时即通。（《食 \n疗本草》）。 \n霍乱吐利∶盐梅煎汤，细细饮之。（《如宜方》）。 \n蛔虫上行，出于口鼻∶乌梅煎汤频饮，并含之，即安。（《食鉴本草》）。 \n水气满急∶乌梅、大枣各三枚。水四升，煮二升，纳蜜和匀，含咽之。（《圣济总录》）。 \n梅核膈气∶取半青半黄梅子，每个用盐一两腌一日夜，晒干，又浸又晒至水尽乃止。用 \n青钱三个，夹二梅，麻线缚定，通装瓷罐内封埋地下，百日取出。每用一枚，含之咽汁，入 \n喉即消。收一年者治一人，二年者治二人，其妙绝伦。（《龚氏经验方》）。 \n心腹胀痛，短气欲绝者∶乌梅二七枚，水五升，煮一沸，纳大钱二七枚，煮二升半，顿 \n服之。（《肘后》）。 \n劳疟劣弱∶乌梅十四枚，豆豉二合，桃、柳枝各一虎口，甘草三寸，生姜一块，以童子 \n小便二升，煎一半，温服即止。（《图经本草》）。 \n久咳不已∶乌梅肉（微炒）、罂粟壳去筋膜蜜炒，等分为末。每服二钱，睡时蜜汤调下。 \n痰厥头痛如破者∶乌梅肉三十个，盐三撮，酒三升，煮一升，顿服，取吐即愈。（《肘 \n后方》）。 \n伤寒头痛，壮热，胸中烦痛，四、五日不解∶乌梅十四枚，盐五合，水一升，煎半升， \n温服取吐。吐后避风良。（《梅师方》）。 \n折伤金疮∶干梅烧存性，敷之，一宿瘥。（《千金方》）。 \n马汗入疮作痛∶用乌梅连核捣烂，以头醋和敷。仍先刺疮，出去紫血，乃敷之系定。（《经 \n验方》）。 \n犬伤毒∶乌梅末，酒服二钱。（《千金》）。 \n指头肿毒痛甚者∶乌梅肉，和鱼 捣封之妙。（李楼《奇方》）。 \n伤寒 疮，生下部者∶乌梅肉三两炒为末，炼蜜丸梧子大。 \n以石榴根皮煎汤，食前下三十丸。（《圣惠方》）。 \n小儿头疮∶乌梅烧末，生油调涂。（《圣济录》）。 \n香口去臭∶曝干梅脯，常时含之。（《毛诗疏》）。 \n硫黄毒发，令人背膊疼闷，目暗漠漠∶乌梅肉（焙）一两，沙糖半两，浆水一大盏，煎 \n七分，呷之。（《总录》） \n\\x核仁\\x \n【气味】酸，平，无毒。 \n【主治】明目，益气，不饥（吴普）。除烦热（甄权）。 \n治代指忽然肿痛，捣烂，和醋浸之（时珍。《肘后方》）。 \n\\x花\\x \n【气味】微酸，涩，无毒。 \n【发明】时珍曰∶白梅花古方未见用者。近时有梅花汤∶用半开花，溶蜡封花口，投蜜 \n罐中，过时以一两朵同蜜一匙点沸汤服。 \n又有蜜渍梅花法∶用白梅肉少许，浸雪水，润花，露一宿，蜜浸荐酒。又梅花粥法∶用 \n落英入熟米粥再煮食之。故杨诚斋有“蜜点梅花带露餐”及“脱蕊收将熬粥吃”之句，皆取 \n其助雅致、清神思而已。 \n\\x叶\\x \n【气味】酸，平，无毒。 \n【主治】休息痢及霍乱，煮浓汁饮之（大明）。 \n藏器曰∶嵩阳子言∶清水揉梅叶，洗蕉葛衣，经夏不脆。有验。 \n时珍曰∶夏衣生霉点，梅叶煎汤洗之即去，甚妙。 \n【附方】旧一，新二。 \n中水毒病，初起头痛恶寒，心烦拘急，旦醒暮剧∶梅叶捣汁三升饮之良。（《肘后》）。 \n下部虫 ∶梅叶、桃叶一斛，杵烂蒸极热，纳小器中，隔布坐蒸之，虫尽死也。（《外 \n台秘要》）。 \n月水不止∶梅叶（焙）、棕榈皮灰各等分为末。每服二钱，酒调下。（《圣济总录》） \n\\x根\\x \n【主治】风痹（《别录》。出土者杀人）。 \n初生小儿，取根同桃、李根煮汤浴之，无疮热之患（崔氏《纂要》）。 \n煎汤饮，治霍乱，止休息痢（大明）。 \n\n\n\n<目录>果部第二十九卷\\果之一\n\n<篇名>梅\n\n内容：（《纲目》） \n【集解】时珍曰∶ 梅出均州太和山。相传真武折梅枝插于 树。誓曰∶吾道若成，开 \n花结果。后果如其言。今树尚在五龙宫北， 木梅实，杏形桃核。道士每岁采而蜜渍，以充 \n贡献焉。 乃榆树也。 \n\\x实\\x \n【气味】甘、酸，平，无毒。 \n【主治】生津止渴，清神下气，消酒（时珍）。 \n\n\n\n<目录>果部第二十九卷\\果之一\n\n<篇名>桃\n\n内容：（《本经》下品） \n【校正】木部有《拾遗》桃橛，今并入此。 \n【释名】时珍曰∶桃性早花，易植而子繁，故字从木、兆。十亿曰兆，言其多也。或云 \n从兆谐声也。 \n【集解】《别录》曰∶桃生太山川谷。 \n弘景曰∶今处处有之。核仁入药，当取解核者种之为佳，山桃仁不堪用。 \n颂曰∶汴东、陕西者尤大而美。大抵佳果肥美者，皆圃人以他木接成，殊失本性。入药 \n当用本生者为佳。今市肆卖者，多杂接核之仁，为不堪也。 \n宗 曰∶山中一种桃，正合《月令》桃始华者，花多子少，不堪啖，惟堪取仁入药。汴 \n中有油桃，小于众桃，光如涂油，不益脾胃。太原有金桃，色深黄。洛中有昆仑桃，肉深红 \n紫色。又有饼子桃，状如香饼子。其味皆甘。 \n时珍曰∶桃品甚多，易于栽种，且早结实。五年宜以刀 其皮，出其脂液，则多延数年。 \n其花有红、紫、白、千叶、二色之殊，其实有红桃、绯桃、碧桃、缃桃、白桃、乌桃、金桃、 \n银桃、胭脂桃，皆以色名者也。有绵桃、油桃、御桃、方桃、匾桃、偏核桃，皆以形名者也。 \n有五月早桃、十月冬桃、秋桃、霜桃，皆以时名者也。并可供食。惟山中毛桃，即《尔雅》 \n所谓 桃者，小而多毛，核粘味恶。其仁充满多脂，可入药用，盖外不足者内有余也。冬桃 \n一名西王母桃，一名仙人桃，即昆仑桃，形如栝蒌，表里微赤，得霜始熟。方桃形微方。匾 \n桃出南番，形匾肉涩，核状如盒，其仁甘美。番人珍之，名波淡树，树甚高硕。偏核桃出波 \n斯，形薄而尖，头偏，状如半月，其仁酷似新罗松子，可食，性热。又杨维桢、宋濂集中并 \n载元朝御库蟠桃，核大如碗，以为神异。按∶王子年《拾遗记》载∶汉明帝时，常山献巨核 \n桃，霜下始花，隆暑方熟。《玄中记》载∶积石之桃，大如斗斛器。《酉阳杂俎》载∶九疑有 \n桃核，半扇可容米一升；及蜀后主有桃核杯，半扇容水五升，良久如酒味可饮。此皆桃之极 \n大者。昔人谓桃为仙果，殆此类欤？生桃切片瀹过，曝干为脯，可充果食。又桃酢法∶取烂 \n熟桃纳瓮中，盖口七日，漉去皮核，密封二七日酢成，香美可食。《种树书》云∶柿接桃则 \n为金桃，李接桃则为李桃，梅接桃则脆。桃树生虫，煮猪头汁浇之即止。皆物性之微妙也。 \n\\x实\\x \n【气味】辛、酸、甘，热，微毒。多食令人有热。 \n诜曰∶能发丹石毒，生者尤损人。 \n思邈曰∶《黄帝书》云∶食桃饱，入水浴，令人成淋及寒热病。 \n时珍曰∶生桃多食，令人膨胀及生痈疖，有损无益。五果列桃为下以此。 \n瑞曰∶桃与鳖同食，患心痛。服术人忌食之。 \n【主治】作脯食，益颜色（大明）。肺之果，肺病宜食之（思邈）。 \n冬桃，食之解劳热（时珍。出《尔雅注》）。 \n\\x核仁\\x \n【修治】《别录》曰∶七月采，取仁阴干。 \n曰∶凡使须去皮，用白术、乌豆二味，同于坩锅中煮二伏时，漉出劈开，心黄如金色 \n乃用。时珍曰∶桃仁行血，宜连皮、尖生用。润燥活血，宜汤浸去皮、尖炒黄用。或麦麸同 \n炒，或烧存性，各随本方。双仁者有毒，不可食，说见杏仁下。 \n【气味】苦、甘，平，无毒。 \n思邈曰∶苦、甘、辛，平。诜曰∶温。 \n弘景曰∶桃仁作酪，性冷。香附为之使。 \n【主治】瘀血血闭，症瘕邪气，杀小虫（《本经》）。 \n止咳逆上气，消心下坚硬，除卒暴击血，通月水，止心腹痛（《别录》）。 \n治血结、血秘、血燥，通润大便，破畜血（元素）。杀三虫。 \n又每夜嚼一枚和蜜涂手、面良（孟诜）。主血滞风痹骨蒸，肝疟寒热，鬼注疼痛，产后 \n血病（时珍）。 \n【发明】杲曰∶桃仁苦重于甘，气薄味浓，沉而降，阴中之阳，手、足厥阴经血分药也。 \n苦以泄滞血，甘以生新血，故破凝血者用之。其功有四∶治热入血室，一也；泄腹中滞血， \n二也；除皮肤血热燥痒，三也；行皮肤凝聚之血，四也。 \n成无己曰∶肝者血之源，血聚则肝气燥。肝苦急，急食甘以缓之。桃仁之甘以缓肝散血 \n，故张仲景抵当汤用之，以治伤寒八、九日，内有畜血，发热如狂，小腹满痛，小便自利者。 \n又有当汗失汗，热毒深入，吐血及血结胸，烦躁谵语者，亦以此汤主之。与虻虫、水蛭、大 \n黄同用。 \n【附方】旧十九，新十一。 \n延年去风，令人光润∶用桃仁五合去皮，用粳米饭浆同研，绞汁令尽，温温洗面极妙。 \n（《千金翼》）。 \n偏风不遂，及癖疾∶用桃仁二千七百枚，去皮、尖、双仁，以好酒一斗三升，浸二十一 \n日，取出晒干杵细，作丸如梧子大。每服二十丸，以原酒吞之。（《外台秘要》）。 \n风劳毒肿挛痛，或牵引小腹及腰痛∶桃仁一升去皮尖，熬令黑烟出，热研如脂膏，以酒 \n三升搅和服，暖卧取汗。不过三度瘥。（《食医心镜》）。 \n疟疾寒热∶桃仁一百枚去皮尖，乳钵内研成膏，不得犯生水，入黄丹三钱，丸梧子大。 \n每服三丸，当发日面北温酒吞下。五月五日午时合之，忌鸡、犬、妇人。（见唐慎微《本草》）。 \n骨蒸作热∶桃仁一百二十枚，留尖去皮及双仁，杵为丸，平旦井花水顿服之。令尽量饮 \n酒至醉，仍须任意吃水。隔日一剂。百日不得食肉。（《外台秘要》）。 \n上气喘急∶方见杏仁。 \n上气咳嗽，胸满气喘∶桃仁三两去皮尖，以水一大升研汁，和粳米二合煮粥食之。（《心 \n镜》）。 \n卒得咳嗽∶桃仁三升去皮杵，着器中密封，蒸熟晒干，绢袋盛，浸二斗酒中，七日可饮， \n日饮四、五合。 \n尸疰鬼疰，乃五尸之一，又挟鬼邪为祟。其病变动，有三十六种至九十九种。大略使人 \n寒热淋沥，沉沉默默，不知所苦而无处不恶。累年积月，以至于死，死后复传旁人∶急以桃 \n仁五十枚研泥，水煮取四升，服之取吐。吐不尽，三、四日再吐。（《肘后方》）。 \n传尸鬼气，咳嗽 癖注气，血气不通，日渐消瘦∶桃仁一两去皮尖杵碎，水一升半煮汁， \n入米作粥，空心食之。（《心镜》）。 \n鬼疰心痛∶桃仁一合烂研，煎汤服之。（《备急方》）。 \n卒然心痛∶桃仁七枚，去皮尖研烂，水一合服之。（《肘后方》）。 \n人好魇寐∶桃仁（熬去皮尖）三、七枚，以小便服之。（《千金方》）。 \n下部虫 ，病患齿龈无色，舌上白，喜睡愦愦不知痛痒处，或下痢，乃下部生虫食肛也∶ \n桃仁十五枚，苦酒二升，盐一合，煮六合服之。（《肘后方》）。 \n崩中漏下不止者∶桃核烧存性研细，酒服方寸匕，日三。（《千金》）。 \n妇人难产，数日不出∶桃仁一个劈开，一片书可字，一片书出字，还合吞之即生。（《删 \n繁方》）。 \n产后百病∶《千金》桃仁煎∶治妇人产后百病诸气。取桃仁一千二百枚，去皮、尖、双 \n仁，熬捣极细，以清酒一斗半，研如麦粥法，纳小项瓷瓶中，面封，入汤中煮一伏时。每服 \n一匙，温酒和服，日再。（《图经本草》）。 \n产后身热如火，皮如粟粒者∶桃仁研泥，同腊猪脂敷之，日日易之。（《千金方》）。 \n产后血闭∶桃仁二十枚（去皮尖），藕一块，水煎服之良。（唐瑶《经验方》）。 \n产后阴肿∶桃仁，烧研敷之。 \n妇人阴痒∶桃仁杵烂，绵裹塞之。（《肘后方》）。 \n男子阴肿作痒。用桃仁炒香为末，酒服方寸匕，日二。仍捣敷之。 \n（《外台》）∶ \n小儿卵 ∶方同上。 \n小儿烂疮，初起肿浆似火疮，桃仁研烂敷之。（《秘录》）。 \n小儿 耳∶桃仁炒研绵裹，日日塞之。（《千金方》）。 \n风虫牙痛∶针刺桃仁，灯上烧烟出吹灭，安痛齿上咬之。不过五、六次愈。（《卫生家 \n宝方》）。 \n唇干裂痛∶桃仁捣和猪脂敷。（《海上》）。 \n大便不快，里急后重。用桃仁三两（去皮），吴茱萸二两，食盐一两，同炒熟，去盐、 \n茱，每嚼桃仁五、七粒。（《总录》） \n急劳咳嗽烦热。用桃仁三两（去皮尖），猪肝一枚，童子小便五升。同煮干，于木臼内 \n捣烂，入蒸饼和，丸梧子大。每温水下三十丸。（《圣惠方》）。 \n冷劳减食，渐至黑瘦。用桃仁五百颗，吴茱萸三两，同入铁铛中，微火炒一炊久，将桃 \n仁一颗去皮，看似微黄色即渐加火，待微烟出，即乘热收入新瓶内，浓纸封住，勿令泄气。 \n每日空心取桃仁二十粒去皮嚼之，以温酒下。至重者服五百粒愈。（《圣惠方》）。 \n预辟瘴疠∶桃仁一斤，吴茱萸、青盐各四两，同炒熟，以新瓶密封一七，取出拣去茱、 \n盐，将桃仁去皮尖，每嚼一、二十枚。山居尤宜之。（余居士《选奇方》） \n\\x桃毛\\x \n毛桃实上毛也。刮取用之。 \n【气味】辛，平，微毒。 \n【主治】破血闭，下血瘕，寒热积聚，无子，带下诸疾（《别录》）。 \n疗崩中，破癖气（大明）。治恶鬼邪气（孟诜）。 \n\\x桃枭\\x \n【释名】桃奴（《别录》）、枭景（同上）、神桃。 \n《别录》曰∶此是桃实着树经冬不落者，正月采之，中实者良。 \n时珍曰∶桃子干悬如枭首 木之状，故名。 \n奴者，言其不能成实也。《家宝方》谓之神桃，言其辟恶也。千叶桃花结子在树不落者， \n名鬼髑髅。 \n雷 《炮炙论》有修治之法，而方书未见用者。 \n曰∶鬼髑髅，十一月采得，以酒拌蒸之，从巳至未，焙干，以铜刀切，焙取肉用。 \n【气味】苦，微温，有小毒。 \n【主治】杀百鬼精物（《本经》）。杀精魅五毒不祥，疗中恶腹痛（《别录》。颂曰∶胡洽 \n治中恶毒瓦斯蛊疰有桃枭汤。治肺气腰痛，破血，疗心痛，酒磨暖服之（大明）。 \n主吐血诸药不效，烧存性，研末，米汤调服，有验（汪颖）。 \n治小儿虚汗，妇人妊娠下血，破伏梁结气，止邪疟。烧烟熏痔疮。烧黑油调，敷小儿 \n头上肥疮软疖（时珍）。 \n【附方】旧三，新五。 \n伏梁结气，在心下不散∶桃奴三两为末，空心温酒，每服二钱。（《圣惠》）。 \n鬼疟寒热∶树上自干桃子二、七枚为末，滴水丸梧子大，朱砂为衣。每服一丸，侵晨面 \n东井华水下，食。（《圣济总录》）。 \n五种疟疾∶《家宝》通神丸∶用神桃（即桃奴）十四枚，巴豆七粒，黑豆一两。研匀， \n以冷水和丸梧子大，朱砂为衣。发日五更念药王菩萨七遍，井华水下一丸，立瘥。不过二次， \n妙不可言。（王隐君《养生主论》） \n妊娠下血不止∶用桃枭，烧存性，研，水服取瘥。（葛洪方） \n盗汗不止∶树上干桃子一个，霜梅二个，葱根七个，灯心二茎，陈皮一钱，稻根、大麦 \n芽各一撮。水二钟，煎服。（《经验方》） \n白秃头疮∶干桃一两，黑豆一合，为末，腊猪脂调搽。（《圣惠》）。 \n小儿头疮∶树上干桃烧研，入腻粉、麻油调搽。（《圣惠》）。 \n食桃成病∶桃枭烧灰二钱，水服取吐即愈。陆光禄说有人食桃不消化作病时，于林间得 \n槁桃烧服，登时吐出即愈，此以类相攻也。（张文仲《备急方》） \n\\x花\\x \n【修治】《别录》曰∶三月三日采，阴干之。 \n曰∶桃花勿用千叶者，令人鼻衄不止，目黄。收花拣净，以绢袋盛，悬檐下令干用。 \n【气味】苦，平，无毒。 \n【主治】杀疰恶鬼，令人好颜色（《本经》）。 \n悦泽人面，除水气，破石淋，利大小便，下三虫（《别录》）。 \n消肿满，下恶气（苏恭）。治心腹痛及秃疮（孟诜）。利宿水痰饮积滞，治风狂。研末， \n敷头上肥疮，手足 疮（时珍）。 \n【发明】弘景曰∶《肘后方》言∶服三树桃花尽，则面色红润悦泽如桃花也。 \n颂曰∶《太清草木方》言∶酒渍桃花饮之，除百疾，益颜色。 \n时珍曰∶按∶欧阳询《初学记》载∶北齐崔氏以桃花、白雪与儿 面，云令面妍华光悦， \n盖得本草令人好颜色、悦泽人面之义，而陶、苏二氏乃引服桃花法，则因本草之言而谬用者 \n也。桃花性走泄下降，利大肠甚快，用以治气实人病水饮肿满积滞、大、小便闭塞者，则有 \n功无害。若久服，即耗人阴血，损元气，岂能悦泽颜色耶？按∶张从正《儒门事亲》载∶一 \n妇滑泻数年，百治不效。或言∶此伤饮有积也。桃花落时，以棘针刺取数十萼，勿犯人手。 \n以面和作饼，煨熟食之，米饮送下。不一、二时，泻下如倾。六、七日，行至数百行，昏困 \n，惟饮凉水而平。观此，则桃花之峻利可征矣。又苏鹗《杜阳编》载∶范纯佑女丧夫发狂， \n闭之室中，夜断窗棂，登桃树上食桃花几尽。及旦，家人接下，自是遂愈也。珍按∶此亦惊 \n怒伤肝，痰夹败血，遂致发狂。偶得桃花利痰饮、散滞血之功，与张仲景治积热发狂用承气 \n汤，畜血发狂用桃仁承气汤之意相同；而陈藏器乃言桃花食之患淋，何耶？ \n【附方】旧三，新十三。 \n大便艰难∶桃花为末，水服方寸匕，即通。（《千金》）。 \n产后秘塞，大、小便不通∶用桃花、葵子、滑石、槟榔等分，为末。每空心葱白汤服二 \n钱，即利。（《集验方》）。 \n心腹积痛∶三月三日采桃花晒干杵末，以水服二钱匕，良。（孟诜《食疗本草》）。 \n疟疾不已∶桃花为末，酒服方寸匕良。（《梅师方》）。 \n痰饮宿水∶桃花散∶收桃花阴干为末，温酒服一合，取利。觉虚，食少粥。不似转下药 \n也。（崔行功《纂要方》）。 \n香港脚肿痛∶桃花一升，阴干为末。每温酒细呷之，一宿即消。（《外台秘要》）。 \n腰脊作痛∶三月三日取桃花一斗一升，井华水三斗，曲六升，米六斗，炊熟，如常酿酒。 \n每服一升，日三服，神良。（《千金》）。 \n脓 不止∶桃花为末，猪脂和敷之，日二。（《千金》）。 \n头上秃疮∶三月三日收未开桃花阴干，与桑椹（赤者）等分作末，以猪脂和。先取灰汁 \n洗去痂，即涂之。（《食疗》）。 \n头上肥疮∶一百五日寒食节，收桃花为末。食后以水半盏调服方寸匕，日三，甚良。（崔 \n元亮《海上方》）。 \n黄水面疮∶方同上。 \n足上 疮∶桃花、食盐等分杵匀，醋和敷之。（《肘后方》）。 \n雀卵面 ∶桃花、冬瓜仁研末等分，蜜调敷之。（《圣惠》）。 \n干粪塞肠，胀痛不通∶用毛桃花湿者一两，和面三两，作馄饨煮熟，空心食之。日午腹 \n鸣如雷，当下恶物也。（《圣惠方》）。 \n面上粉刺， 子如米粉∶用桃花、丹砂各三两，为末。每服一钱，空心井水下，日三服。 \n十日知，二十日小盒饭出黑汁，面色莹白也。（《圣惠方》）。 \n令面光华∶三月三日收桃花，七月七日收鸡血，和涂面上。三、二日后脱下，则光华颜 \n色也。（《圣济总录》）。 \n\\x叶\\x \n颂曰∶采嫩者名桃心，入药尤胜。 \n【气味】苦，平，无毒。 \n【主治】除尸虫，出疮中小虫（《别录》）。治恶气，小儿寒热客忤（大明）。疗伤寒、时 \n气、风痹无汗，治头风，通大小便，止霍乱腹痛（时珍）。 \n【发明】颂曰∶桃叶蒸汗法∶张文仲《备急方》治天行病，有支太医桃叶汤熏法∶用水 \n一石煮桃叶，取七斗，安床箦下，浓被盖卧床上，乘热熏之。少时当雨汗，汗遍去汤，速粉 \n之，并灸大椎穴，则愈。又陈廪丘《短剧方》，有阮河南桃叶蒸法云∶连发汗，汗不出者死， \n可蒸之，如中风法。烧地令热，去火，以少水洒之，布干桃叶于上浓二、三寸，安席叶上卧 \n之，温覆得大汗，被中敷粉极燥，便瘥也。凡柏叶、麦麸、蚕砂皆可如此法用。张苗言∶曾 \n有人疲极汗出，卧簟受冷，但苦寒倦。四日凡八发汗，汗不出，用此法而瘥也。 \n时珍曰∶按∶许叔微《本事方》云∶伤寒病，医者须顾表里，循次第。昔范云为梁武帝 \n属官，得时疫热疾，召徐文伯诊之。是时武帝有九锡之命，期在旦夕。云恐不预，求速愈。 \n文伯曰∶此甚易，政恐二年后不复起尔。云曰∶朝闻道夕死可矣，况二年乎。文伯乃以火 \n地，布桃、柏叶于上，令云卧之。少顷汗出粉之，翌日遂愈。后二年云果卒。取汗先期，尚 \n能促寿；况罔顾表里时日，便欲速愈者乎？夫桃叶发汗妙法也，犹有此戒，可不慎欤？ \n【附方】旧九，新二。 \n风袭项强，不得顾视∶穿地作坑， 赤，以水洒之令冷，铺生桃叶于内。卧席上，以项 \n着坑上，蒸至汗出，良久即瘥。（《千金方》）。 \n小儿伤寒时气∶用桃叶三两，水五升，煮十沸取汁，日五、六遍淋之。后烧雄鼠粪二枚 \n服之，妙。（《伤寒类要》）。 \n二便不通∶桃叶杵汁半升服。冬用桃皮。（孙真人方）。 \n霍乱腹痛吐利∶桃叶三升切，水五升，煮一升三合，分二服。（《外台》）。 \n除三尸虫∶桃叶杵汁，服一升。（《外台秘要》）。 \n肠痔出血∶桃叶一斛杵，蒸之，纳小口器中坐，有虫自出。（《肘后方》）。 \n女人阴疮，如虫咬痒痛者∶生捣桃叶，绵裹纳之，日三、四易。（《食疗本草》）。 \n足上 疮∶桃叶捣，和苦酒敷之。（《肘后方》）。 \n鼻内生疮∶桃叶嫩心，杵烂塞之。无叶用枝。（《简便方》）。 \n身面癣疮∶日午捣桃叶，取汁搽之。（《千金》）。 \n诸虫入耳∶桃叶 熟塞之。或捣汁滴之。或作枕，枕一夕自出。（《梅师方》） \n\\x茎及白皮\\x \n【修治】时珍曰∶树皮、根皮皆可，用根皮尤良。并取东行者，刮去粗皮，取白皮入药。 \n【气味】苦，平，无毒。 \n【主治】除邪鬼中恶腹痛，去胃中热（《别录》）。治疰忤心腹痛，解蛊毒，辟疫疠，疗 \n黄胆身目如金，杀诸疮虫（时珍）。 \n【附方】旧十五，新五。 \n天行疫疠∶常以东行桃枝煎熬汤浴之，佳。（《类要》）。 \n黄胆如金∶晴明时，清晨勿令鸡、犬、妇人见，取东引桃根细如箸、若钗股者一握，切 \n细，以水一大升，煎一小升，空腹顿服。后三、五日，其黄离离如薄云散开，百日方平复也。 \n黄散后，可时时饮清酒一杯，则眼中易散，否则散迟。忌食热面、猪、鱼等物。此是徐之才 \n家秘方也。《类要》。 \n肺热喘急《集验》∶治肺热闷喘急，客热往来，欲死，不堪服药者。用桃皮、芫花各一 \n升，以水四升，煮取一升五合。以故布纳汁中，取薄胸口，温四肢，不盈数刻即止。（《图 \n经》）。 \n喉痹塞痛∶桃皮煮汁三升服。（《千金方》）。 \n心虚健忘《圣惠》，令耳目聪明∶用戊子日，取东引桃枝二七寸枕之。又方∶五月 \n五日日未出时，取东引桃枝刻作三寸木人，着衣领带中佩之。（《千金方》）。 \n卒得心痛∶东引桃枝一把切，以酒一升，煎半升，顿服大效。（《肘后方》）。 \n鬼疰心痛∶东引桃枝一握，去粗皮切，水二升，煎半升，频服。（崔氏）。 \n解中蛊毒∶用东引桃白皮（烘干）、大戟、斑蝥（去足翅熬），三物等分，为末。以冷水 \n服半方寸匕，即出。不出更服。或因酒得以酒服，因食得以食服。必效方云∶此乃李饶州法 \n也。亦可以米泔丸服。（苏颂《图经》）。 \n卒得恶疮，人不识者∶取桃皮作屑纳之。（孙真人方）。 \n卒患瘰 ，不痛者∶取桃树白皮贴疮上，灸二、七壮良。（孙真人方）。 \n热病口疮成 ∶桃枝煎浓汁含之。下部有疮，纳入之。（《类要》）。 \n下部 疮∶桃白皮煮取浓汁如稀饧，入熊胆少许，以绵蘸药纳入下部疮上。（《梅师》）。 \n五痔作痛∶桃根，水煎汁浸洗之，当有虫出。 \n小儿湿癣∶桃树青皮为末和醋频敷之。（《子母秘录》）。 \n狂狗咬伤∶桃白皮一握，水三升，煎一升服。（《梅师方》）。 \n水肿尿短∶桃皮三斤（去内外皮），秫米一斗，女曲一升，以水二斗煮桃皮，取汁一斗， \n以一半渍曲，一半渍秫饭，如常酿成酒。每服一合，日三次，以体中有热为候。小便多是病 \n去。忌生冷、一切毒物。（《圣济总录》）。 \n妇人经闭，数年不通，面色萎黄，唇口青白，腹内成块，肚上筋起，腿胫或肿，桃根煎 \n主之∶用桃树根、牛蒡根、马鞭草根、牛膝、蓬 各一斤锉，以水三斗，煎一斗去滓，更以 \n慢火煎如饧状收之。每以热酒调服一匙。（《圣惠》）。 \n牙疼颊肿∶桃白皮、柳白皮、槐白皮等分，煎酒热漱。冷则吐之。（《圣惠方》）。 \n小儿白秃∶桃皮五两煎汁，入白面沐之，并服。（同上）。 \n\\x桃胶\\x \n【修治】时珍曰∶桃茂盛时，以刀割树皮，久则胶溢出，采收，以桑灰汤浸过，曝干用。 \n如服食，当依本方修炼。 \n【气味】苦，平，无毒。 \n【主治】炼服，保中不饥，忍风寒（《别录》）。下石淋，破血，治中恶疰忤（苏恭）。主 \n恶鬼邪气（孟诜）。和血益气，治下痢，止痛（时珍）。 \n【发明】颂曰∶《本草》言桃胶炼服，保中不饥。按∶仙方服胶法∶取胶二十斤，绢袋 \n盛，于栎木灰汁一石中，煮三、五沸，取挂高处，候干再煮，如此三度，曝干研筛，蜜和丸 \n梧子大，每空腹酒服二十丸。久服身轻不老。 \n时珍曰∶按∶《抱朴子》云∶桃胶以桑灰汁渍过服之，除百病，数月断谷，久则晦夜有 \n光如月。又《列仙传》云∶高丘公服桃胶得仙。古方以桃胶为仙药，而后人不复用之，岂其 \n功亦未必如是之殊耶？ \n【附方】旧二，新三。 \n虚热作渴∶桃胶如弹丸大，含之佳。（《外台》）。 \n石淋作痛∶桃木胶如枣大，夏以冷水三合，冬以汤三合，和服，日三服。当下石，石尽 \n即止。（《古今录验》）。 \n血淋作痛∶桃胶（炒）、木通、石膏各一钱，水一盏，煎七分，食后服。（《杨氏家藏方》）。 \n产后下痢赤白，里急后重， 痛∶用桃胶（焙干）、沉香、蒲黄（炒）各等分，为末。每服 \n二钱，食前米饮下。（《妇人良方》）。 \n痘 发搐黑陷者∶用桃胶煎汤饮之。或水熬成膏，酒化服之，大效。（《总微论》）。 \n\\x桃符\\x \n【主治】中恶，精魅邪气，水煮汁服之（孟诜）。 \n【发明】时珍曰∶《典术》云∶桃乃西方之木，五木之精，仙木也。 \n味辛气恶，故能厌伏邪气，制百鬼。今人门上用桃符以此。《玉烛宝典》云∶户上着桃 \n板辟邪，取《山海经》神荼、郁垒居东海蟠桃树下，主领众鬼之义。 \n许慎云∶羿死于桃 。 ，仗也。故鬼畏桃，而今人用桃梗作 橛以辟鬼也。《礼记》 \n云∶王吊则巫祝以桃 前引，以辟不祥。 者，桃枝作帚也。《博物志》云∶桃根为印，可 \n以召鬼。《甄异传》云∶鬼但畏东南枝尔。据此诸说，则本草桃之枝、叶、根、核、桃枭、 \n桃橛，皆辟鬼祟产忤，盖有由来矣。钱乙小儿方∶疏取积热及结胸，用巴豆、 、汞之药， \n以桃符煎汤下，亦是厌之之义也。 \n\\x桃橛\\x（《拾遗》） \n时珍曰∶橛音掘，即 也。人多钉于地上，以镇家宅，三载者良。 \n【主治】卒心腹痛，鬼疰，破血，辟邪恶气胀满，煮汁服之，与桃符同功（藏器）。 \n【附方】新一。 \n风虫牙痛∶门下桃橛烧取汁，少少纳孔中，以蜡固之。（《圣惠方》）。 \n\\x桃寄生\\x 见木部。 \n\\x桃蠹虫\\x 移入虫部。 \n\n\n\n<目录>果部第二十九卷\\果之一\n\n<篇名>栗\n\n内容：（《别录》上品） \n【释名】时珍曰∶栗，《说文》作KT ，从 （音条），象花实下垂之状也。梵书名笃 \n迦。 \n【集解】《别录》曰∶栗生山阴，九月采。 \n弘景曰∶今会稽诸暨栗，形大皮浓，不美；剡及始丰栗，皮薄而甜，乃佳。 \n颂曰∶栗处处有之，而兖州、宣州者最胜。木高二、三丈，叶极类栎。四月开花青黄 \n色，长条似胡桃花。实有房 ，大者若拳，中子三、五；小者若桃李，中子唯一、二。将熟 \n则罅拆子出。栗类亦多。按∶陆玑《诗疏》云∶栗，五方皆有之，周、秦、吴、扬特饶。惟 \n濮阳及范阳栗甜美味长，他方者不及也。倭、韩国诸岛上栗大如鸡子，味短不美。桂阳有莘 \n栗，丛生，实大如杏仁，皮、子形色与栗无异，但小耳。又有奥栗，皆与栗同，子圆而细， \n惟江湖有之，或云即莘也。莘音榛，《诗》云“树之莘栗”是矣。 \n保升曰∶板栗、锥栗二树皆大。茅栗似板栗而细如橡子，其树虽小，叶亦不殊，但春生 \n夏花、秋实冬枯为异耳。 \n宗 曰∶湖北一种旋栗，顶圆末尖，即榛栗，象榛子形也。栗欲干收，莫如曝之；欲生 \n收，莫如润沙藏之，至夏初尚如新也。 \n时珍曰∶栗但可种成，不可移栽。按∶《事类合璧》云∶栗木高二、三丈，苞生多刺如 \n毛，每枝不下四、五个苞，有青、黄、赤三色。中子或单或双，或三或四。其壳生黄熟紫， \n壳内有膜裹仁，九月霜降乃熟。其苞自裂而子坠者，乃可久藏，苞未裂者易腐也。其花作条， \n大如箸头，长四、五寸，可以点灯。栗之大者为板栗，中心扁子为栗楔。稍小者为山栗。山 \n栗之圆而末尖者为锥栗。圆小如橡子者为莘栗。小如指顶者为茅栗，即《尔雅》所谓 栗也， \n一名 栗，可炒食之。刘恂《岭表录》异云∶广中无栗。惟勤州山中有石栗，一年方熟，圆 \n如弹子，皮浓而味如胡桃。得非栗乃水果，不宜于炎方耶？ \n\\x实\\x \n【气味】咸，温，无毒。 \n诜曰∶吴栗虽大味短，不如北栗。凡栗日中曝干食，即下气补益；不尔犹有木气，不补 \n益也。火煨去汗，亦杀水气。生食则发气，蒸炒熟食则壅气。凡患风水人不宜食，味咸生水 \n也。 \n恭曰∶栗作粉食，胜于菱、芡；但以饲孩儿，令齿不生。 \n宗 曰∶小儿不可多食。生则难化，熟则滞气，膈食生虫，往往致病。 \n【主治】益气，浓肠胃，补肾气，令人耐饥（《别录》）。 \n生食，治腰脚不遂（思邈）。疗筋骨断碎，肿痛瘀血，生嚼涂之，有效（苏恭）。 \n栗楔（音屑） 时珍曰∶一球三颗，其中扁者栗楔也。 \n【主治】筋骨风痛（士良）。活血尤效（颂曰∶今衡山合活血丹用之）。每日生食七枚， \n破冷 癖。又生嚼， 恶刺，出箭头，敷瘰 肿毒痛（大明）。 \n【发明】思邈曰∶栗，肾之果也。肾病宜食之。 \n弘景曰∶相传有人患腰脚弱，往栗树下食数升，便能起行。此是补肾之义，然应生啖。 \n若服饵则宜蒸曝之。 \n宗 曰∶栗之补肾，为其味咸，又滞其气也。 \n时珍曰∶栗于五果属水。水潦之年则栗不熟，类相应也。有人内寒，暴泄如注，令食煨 \n栗二、三十枚，顿愈。肾主大便，栗能通肾，于此可验。《经验后方》治肾虚腰脚无力，以 \n袋盛生栗悬干，每旦吃十余颗，次吃猪肾粥助之，久必强健。盖风干之栗，胜于日曝，而火 \n煨油炒，胜于煮蒸。仍须细嚼，连液吞咽，则有益。若顿食至饱，反致伤脾矣。按∶苏子由 \n诗云∶老去自添腰脚病，山翁服栗旧传方。客来为说晨兴晚，三咽徐收白玉浆。此得食栗之 \n诀也。王祯《农书》云∶《史记》载∶秦饥，应侯请发五苑枣、栗。则本草栗浓肠胃、补肾 \n气、令人耐饥之说，殆非虚语矣。 \n【附方】旧三，新五。 \n小儿疳疮∶生嚼栗子敷之。（《外台》）。 \n苇刺入肉∶方同上。 \n马汗入肉成疮者。方同上。（《胜金方》）。 \n马咬成疮∶独颗栗子烧研敷之。（《医说》）。 \n熊虎爪伤∶嚼栗敷之。（《肘后》）。 \n小儿口疮∶大栗煮熟，日日与食之，甚效。（《普济》）。 \n衄血不止∶宣州大栗七枚刺破，连皮烧存性，出火毒，入麝香少许研匀。每服二钱，温 \n水下。（《圣济总录》）。 \n金刃斧伤∶用独壳大栗研傅，或仓卒嚼敷亦可。（《集简方》）。 \n栗 （音孚） 恭曰∶栗内薄皮也。 \n【气味】甘，平，涩，无毒。 \n【主治】捣散，和蜜涂面，令光急去皱纹（苏恭）。 \n【附方】新二。 \n骨鲠在咽∶栗子内薄皮烧存性，研末，吹入咽中即下。《圣济总录》∶用栗子肉上皮半两 \n（为末）， 鱼肝一个，乳香二钱半，同捣，丸梧子大。看鲠远近，以线系绵裹一丸，水润 \n吞之，提线钓出也。 \n\\x栗壳\\x（栗之黑壳也） \n【气味】同 。 \n【主治】反胃消渴，煮汁饮之（孟诜）。煮汁饮，止泻血（大明）。 \n【附方】新一。 \n鼻衄不止，累医不效。栗壳烧存性，研末，粥饮服二钱。（《圣惠方》） \n\\x毛球\\x（栗外刺包也） \n【主治】煮汁，洗火丹毒肿（苏恭）。 \n\\x花\\x \n【主治】瘰 （吴瑞）。 \n\\x树皮\\x \n【主治】煮汁，洗沙虱、溪毒（苏恭）。疗疮毒（苏颂）。治丹毒五色无常。剥皮有刺者， \n煎水洗之（孟诜。出《肘后方》）。 \n\\x根\\x \n【主治】偏肾气，酒煎服之（汪颖）。 \n\n\n\n<目录>果部第二十九卷\\果之一\n\n<篇名>天师栗\n\n内容：（《纲目》） \n【集解】时珍曰∶按∶宋祁《益州方物记》云∶天师栗，惟西蜀青城山中有之，他处无 \n有也。云张天师学道于此所遗，故名。似栗而味美，惟独房若橡为异耳。今武当山所卖娑罗 \n子，恐即此物也。 \n【气味】甘，温，无毒。 \n【主治】久食，已风挛（时珍。出《益州记》）。 \n\n\n\n<目录>果部第二十九卷\\果之一\n\n<篇名>枣\n\n内容：（《本经》上品） \n【释名】时珍曰∶按陆佃《埤雅》云∶大曰枣，小曰棘。棘，酸枣也。枣性高，故重 ； \n棘性低，故并 。 音次。枣、棘皆有刺针，会意也。 \n【集解】《别录》曰∶枣生河东平泽。 \n弘景曰∶世传河东猗氏县枣特异。今青州出者形大而核细，多膏甚甜。郁州互市者亦好 \n，小不及耳。江东临沂、金城枣形大而虚，少脂，好者亦可用之。南枣大恶，不堪啖。 \n颂曰∶近北州郡皆出枣，惟青州之种特佳。晋州、绛州者虽大，而不及青州肉浓也。江 \n南出者，坚燥少脂。今园圃种莳者，其种甚多。美者有水菱枣、御枣之类，皆不堪入药，盖 \n肌肉轻虚故也。南郡人煮而曝干，皮薄而皱，味更甘于他枣，谓之天蒸枣，亦不入药。按∶ \n郭璞注《尔雅》云∶壶枣大而锐，壶犹瓠也。边，腰枣也，细腰，今谓之辘轳枣。 ，白枣 \n也，子白乃熟。洗，大枣，也，出河东猗氏县，大如鸡卵。遵，羊枣也，实小紫黑，俗名羊 \n矢枣。 ，酸枣也，木小而实酢。还味， 枣也，其味短。蹶泄，苦枣也，其味苦。晰，无 \n实枣也。 \n宗 曰∶大枣先青州，次晋州，皆可晒曝入药，益脾胃。余者止可充食用耳。青州人以 \n枣去皮核，焙干为枣圈，以为奇果。有御枣，甘美轻脆，后众枣熟而易生虫，今人所谓扑落 \n酥者是也。又有牙枣，先众枣熟，亦甘美，微酸而尖长。二枣皆可啖，不堪收曝。 \n时珍曰∶枣木赤心有刺。四月生小叶，尖觥光泽。五月开小花，白色微青。南北皆有， \n惟青、晋所出者肥大甘美，入药为良。其类甚繁，《尔雅》所载之外，郭义恭《广志》有狗 \n牙、鸡心、牛头、羊矢、猕猴、细腰、赤心、三星、骈白之名，又有木枣、氐枣、桂枣、夕 \n枣、灌枣、墟枣、蒸枣、白枣、丹枣、棠枣，及安邑、信都诸枣。谷城紫枣长二寸，羊角枣 \n长三寸。密云所出小枣，脆润核细，味亦甘美，皆可充果食，不堪入药。入药须用青州及晋 \n地晒干大枣为良。按∶贾思勰《齐民要术》云∶凡枣全赤时，日日撼而收曝，则红皱。若半 \n赤收者，肉未充满，干即色黄而皮皱，将赤收者，味亦不佳。《食经》作干枣法∶须治净地， \n铺菰箔之类承枣，日晒夜露，择去胖烂，曝干收之。切而晒干者为枣脯。煮熟榨出者为枣膏， \n亦曰枣瓤。蒸熟者为胶枣，加以糖、蜜拌蒸则更甜；以麻油叶同蒸，则色更润泽。捣胶枣晒 \n干者为枣油，其法取红软干枣入釜，以水仅淹平，煮沸漉出，砂盆研细，生布绞取汁，涂盘 \n上晒干，其形如油，以手摩刮为末收之。每以一匙，投汤碗中，酸甜味足，即成美浆，用和 \n米，最止饥渴、益脾胃也。卢谌《祭法》云∶春祀用枣油。即此。 \n\\x生枣\\x \n【气味】甘、辛，热，无毒。多食令人寒热。凡羸瘦者不可食。 \n思邈曰∶多食令人热渴膨胀，动脏腑，损脾元，助湿热。 \n\\x大枣\\x \n【释名】干枣（《别录》）、美枣（《别录》）、良枣。 \n《别录》曰∶八月采，曝干。 \n瑞曰∶此即晒干大枣也。味最良美，故宜入药。今人亦有用胶枣之肥大者。 \n【气味】甘，平，无毒。 \n思邈曰∶甘、辛，热，滑，无毒。 \n杲曰∶温。 \n大明曰∶有齿病、疳病、虫 人不宜啖枣，小儿尤不宜食。又忌与葱同食，令人五 \n脏不和；与鱼同食，令人腰腹痛。 \n时珍曰∶今人蒸枣多用糖、蜜拌过，久食最损脾、助湿热也。啖枣多，令人齿黄生 \n。故嵇康《养生论》云∶齿处晋而黄，虱处头而黑。 \n【主治】心腹邪气，安中，养脾气，平胃气，通九窍，助十二经，补少气、少津液、身 \n中不足，大惊四肢重，和百药。久服轻身延年（《本经》。宗 曰∶（煮取肉，和脾胃药甚佳）。 \n补中益气，坚志强力，除烦闷，疗心下悬，除肠 。久服不饥神仙（《别录》）。 \n润心肺，止嗽，补五脏，治虚损，除肠胃癖气。和光粉烧，治疳痢（大明）。小儿患秋 \n痢，与蛀枣食之良（孟诜）。杀乌头、附子、天雄毒（之才）。和阴阳，调营卫，生津液（李 \n杲）。 \n【发明】弘景曰∶道家方药，以枣为佳饵。其皮利，肉补虚，所以合汤皆擘之也。 \n杲曰∶大枣气味俱浓，阳也。温以补不足，甘以缓阴血。 \n成无己曰∶邪在营卫者，辛甘以解之。故用姜、枣以和营卫，生发脾胃升腾之气。张仲 \n景治奔豚，用大枣滋脾土以平肾气也。治水饮胁痛有十枣汤，益土而胜水也。 \n震亨曰∶枣属土而有火，味甘性缓。甘先入脾，补脾者未尝用甘。故今人食甘多者，脾 \n必受病也。时珍曰∶《素问》言∶枣为脾之果，脾病宜食之。谓治病和药，枣为脾经血分药 \n也。若无故频食，则生虫损齿，贻害多矣。按∶王好古云∶中满者勿食甘，甘令人满。故张 \n仲景建中汤心下痞者，减饧、枣，与甘草同例，此得用枣之方矣。又按∶许叔微《本事方》 \n云∶一妇病脏燥悲泣不止，祈祷备至。予忆古方治此证用大枣汤，遂治，与服尽剂而愈。古 \n人识病治方，妙绝如此。又陈自明《妇人良方》云∶程虎卿内人妊娠四、五个月，遇昼则惨 \n戚悲伤，泪下数欠，如有所凭，医巫兼治皆无益。管伯周说∶先人曾语此，治须大枣汤乃愈。 \n虎卿借方治药，一投而愈。方见下条。又《摘玄方》治此证，用红枣烧存性，酒服三钱，亦 \n大枣汤变法也。 \n【附方】旧七，新十二。 \n调和胃气∶以干枣去核，缓火逼燥为末。量多少入少生姜末，白汤点服。调和胃气甚良。 \n（《衍义》）。 \n反胃吐食∶大枣一枚去核，用斑蝥一枚去头翅，入在内，煨熟去蝥，空心食之，白汤下 \n良。 \n小肠气痛∶大枣一枚去核，用斑蝥一枚去头、足、翅，入枣内，纸包煨熟，去蝥食枣， \n以桂心、荜澄茄汤下。（《直指》）。 \n伤寒热病后，口干咽痛，喜唾∶大枣二十枚，乌梅十枚，捣入蜜丸。 \n含如杏核大，咽汁甚效。（《千金方》）。 \n妇人脏燥，悲伤欲哭，象若神灵，数欠者，大枣汤主之∶大枣十枚，小麦一升，甘草二 \n两，每服一两，水煎服之。亦补脾气。（《金匮》）。 \n妊娠腹痛∶大红枣十四枚，烧焦为末，以小便服之。（《梅师》）。 \n大便燥塞∶大枣一枚去核，入轻粉半钱缚定，煨熟食之，仍以枣汤送下。（《直指》）。 \n咒枣治疟∶执枣一枚，咒曰∶吾有枣一枚，一心归大道。优他或优降，或劈火烧之。念 \n七遍，吹枣上，与病患食之，即愈。（《 嵝神书》）。 \n烦闷不眠∶大枣十四枚，葱白七茎，水三升，煮一升，顿服。（《千金》）。 \n上气咳嗽，治伤中筋脉急，上气咳嗽者∶用枣二十枚去核，以酥四两微火煎，入枣肉中 \n泣尽酥，取收之。常含一枚，微微咽之取瘥。（《圣惠方》）。 \n肺疽吐血，因啖辛辣，热物致伤者∶用红枣（连核烧存性）、百药煎（ 过）等分为末。 \n每服二钱，米饮下。（《三因》）。 \n耳聋鼻塞，不闻音声、香臭者∶取大枣十五枚（去皮核），蓖麻子三百枚（去皮），和捣。 \n绵裹塞耳、鼻，日一度。三十余日，闻声及香臭也。先治耳，后治鼻，不可并塞。（孟诜《食 \n疗》）。 \n久服香身∶用大枣肉和桂心、白瓜仁、松树皮为丸，久服之。（《食疗本草》）。 \n走马牙疳∶新枣肉一枚，同黄柏烧焦为末。油和敷之。若加砒少许更妙。（王氏《博济》）。 \n诸疮久坏不愈者。枣膏三升，煎水频洗，取愈。（《千金》）。 \n痔疮疼痛∶大肥枣一枚剥去皮，取水银掌中，以唾研令极熟，敷枣瓤上，纳入下部良。 \n（《外台》）。 \n下部虫痒∶蒸大枣取膏，以水银和捻，长三寸，以绵裹，夜纳下部中，明日虫皆出也。 \n（《肘后》）。 \n卒急心疼∶《海上方》诀云∶一个乌梅二个枣，七枚杏仁一处捣。男酒女醋送下之，不 \n害心疼直到老。 \n食椒闭气∶京枣食之即解也。（《百一选方》）。 \n\\x三岁陈枣核中仁\\x \n【气味】燔之，苦，平，无毒。 \n【主治】腹痛邪气（《别录》）。恶气卒疰忤（孟诜）。核烧研，掺胫疮良（时珍）。 \n【发明】时珍曰∶按∶《刘根别传》云∶道士陈孜如痴人，江夏袁仲阳敬事之。 \n孜曰∶今春当有疾，可服枣核中仁二十七枚。后果大病，服之而愈。又云∶常服枣仁， \n百邪不复干也。仲阳服之有效，则枣果有治邪之说矣。又《道书》云∶常含枣核治气，令口 \n行津液，咽之佳。谢承《后汉书》亦云∶孟节能含枣核，不食可至十年也。此皆藉枣以生津 \n受气，而咽之又能达黄宫，以交离坎之义耳。 \n\\x叶\\x \n【气味】甘，温，微毒。《别录》曰∶散服使人瘦，久则呕吐。 \n【主治】覆麻黄，能令出汗（《本经》）。和葛粉，揩热痱疮，良（《别录》）。治小儿壮 \n热，煎汤浴之（大明）。 \n【附方】新二。 \n小儿伤寒∶五日以后热不退。用枣叶半握，麻黄半两，葱白、豆豉各一合，童子小便二 \n钟，煎一钟，分二服，取汗。（《总录》） \n反胃呕哕∶干枣叶一两，藿香半两，丁香二钱半，每服二钱，姜三片，水一盏煎服。（ \n《圣惠方》）。 \n\\x木心\\x \n【气味】甘，涩，温，有小毒。 \n【主治】中蛊腹痛，面目青黄，淋露骨立。锉取一斛，水淹三寸，煮至二斗澄清，煎 \n五升。旦服五合，取吐即愈。又煎红水服之，能通经脉。（时珍，出《短剧方》）。 \n\\x根\\x \n【主治】小儿赤丹从脚趺起，煎汤频浴之。（时珍，出《千金》）。 \n【附方】旧一。 \n令发易长∶取东行枣根三尺，横安甑上蒸之，两头汗出，收取敷发，即易长。（《圣惠 \n方》）。 \n\\x皮\\x \n【主治】同老桑树皮，并取北向者，等分，烧研。每用一合，井水煎，澄取清，洗目。 \n一月三洗，昏者复明。忌荤、酒、房事（时珍）。 \n\n\n\n<目录>果部第二十九卷\\果之一\n\n<篇名>仲思枣\n\n内容：（宋《开宝》） \n【释名】仙枣。 \n志曰∶北齐时有仙人仲思得此枣种之，因以为名。 \n【集解】志曰∶仲思枣形如大枣，长一、二寸，正紫色，细纹小核，味甘。今亦少有。 \n时珍曰∶按∶杜宝《大业拾遗记》云∶隋时信都郡献仲思枣，长四寸，围五寸，肉肥核 \n小有味，胜于青州枣，亦名仙枣。观此，则《广志》之西王母枣、谷城紫枣，皆此类也。 \n【气味】甘，温，无毒。 \n【主治】补虚益气，润五脏，去痰嗽冷气。久服令人肥健，好颜色，神仙不饥（《开宝》）。 \n\n\n\n<目录>果部第二十九卷\\果之一\n\n<篇名>苦枣\n\n内容：（《食性》） \n【释名】蹶泄（《尔雅》。名义未详）。 \n【集解】士良曰∶苦枣处处有之。色青而小，味苦不堪，人多不食。 \n\\x实\\x \n【气味】苦，大寒，无毒。 \n【主治】伤寒热伏在脏腑，狂荡烦满，大小便闭涩。取肉煮研，和蜜丸服（士良）。 \n\n\n\n<目录>果部第三十卷\n\n<篇名>果之二\n\n内容：（山果类三十四种） \n\n\n\n<目录>果部第三十卷\\果之二\n\n<篇名>梨\n\n内容：（《别录》下品） \n【释名】快果、果宗、玉乳、蜜父。 \n震亨曰∶梨者，利也。其性下行流利也。 \n弘景曰∶梨种殊多，并皆冷利，多食损人，故俗人谓之快果，不入药用。 \n【集解】颂曰∶梨，处处皆有，而种类殊别。医方相承，用乳梨、鹅梨。乳梨，出宣城 \n，皮浓而肉实，其味极长；鹅梨，河之南北州郡皆有之，皮薄而浆多，味差短，其香则过之 \n。其余水梨、消梨、紫糜梨、赤梨、青梨、茅梨、甘棠梨、御儿梨之类甚多，俱不入药也。 \n一种桑梨，惟堪蜜煮食之，止口干，生食不益人，冷中。又有紫花梨，疗心热。唐武宗有此 \n疾，百药不效。青城山邢道人以此梨绞汁进之，帝疾遂愈。复求之，不可得。常山郡忽有一 \n株，因缄封以进。帝多食之，解烦燥殊效。岁久木枯，不复有种，今人不得而用之矣。 \n时珍曰∶梨树高二、三丈，尖叶光腻有细齿，二月开白花如雪六出。上巳无风则结实必 \n佳。故古语云∶上巳有风梨有蠹，中秋无月蚌无胎。贾思勰言∶梨核每颗有十余子，种之惟 \n一、二子生梨，余皆生杜，此亦一异也。杜，即棠梨也。梨品甚多，必须棠梨、桑树接过者 \n，则结子早而佳。梨有青、黄、红、紫四色。乳梨，即悉尼；鹅梨，即绵梨；消梨，即香水 \n梨也。俱为上品，可以治病。御儿梨，即玉乳梨之讹。或云御儿一作语儿，地名也，在苏州 \n嘉兴县，见《汉书注》。 \n其他青皮、早谷、半斤、沙糜诸梨，皆粗涩不堪，只可蒸煮及切烘为脯尔。一种醋梨， \n易水煮熟，则甜美不损人也。昔人言梨，皆以常山真定、山阳钜野、梁国睢阳、齐国临淄、 \n巨鹿、弘农、京兆、邺都、洛阳为称。盖好梨多产于北土，南方惟宣城者为胜。故司马迁《 \n史记》云∶淮北、荥南、河济之间，千株梨其人与千户侯等也。又魏文帝诏云∶真定御梨大 \n如拳，甘如蜜，脆如菱，可以解烦释 。辛氏《三秦记》云∶含消梨大如五升器，坠地则破 \n，须以囊承取之。汉武帝尝种于上苑。此又梨之奇品也。《物类相感志》言∶梨与萝卜相间 \n收藏，或削梨 \n\\x实\\x \n【气味】甘、微酸，寒，无毒。多食令人寒中萎困。金疮、乳妇、血虚者，尤 \n不可 \n志曰∶《别本》云∶梨，甘寒，多食成冷痢。桑梨∶生食冷中，不益人。 \n【主治】热嗽，止渴。切片贴烫火伤，止痛不烂（苏恭）。治客热，中风不语，治伤寒 \n热 \n发，解丹石热气、惊邪，利大小便（《开宝》）。除贼风，止心烦气喘热狂。作浆，吐风痰（ \n大明）。猝喑风不语者，生捣汁频服。胸中痞塞热结者，宜多食之（孟诜）。润肺凉心，消痰 \n降火，解疮毒、酒毒（时珍）。 \n【发明】宗 曰∶梨，多食动脾，少则不及病，用梨者当斟酌之。惟病酒烦渴人食之甚 \n佳，终不能却疾。 \n慎微曰∶孙光宪《北梦琐言》云∶有一朝士见奉御梁新诊之，曰∶风疾已深，请速归去 \n。复见 州马医赵鄂诊之，言与梁同，但请多吃消梨，咀 不及，绞汁而饮。到家旬日，唯 \n吃消梨，顿爽也。 \n时珍曰∶《别录》着梨，只言其害，不着其功。陶隐居言梨不入药。盖古人论病多主风 \n寒，用药皆是桂、附，故不知梨有治风热、润肺凉心、消痰降火、解毒之功也。今人痰病、 \n火病，十居六、七。梨之有益，盖不为少，但不宜过食尔。按∶《类编》云∶一士人状若有 \n疾，厌厌无聊，往谒杨吉老诊之。杨曰∶君热症已极，气血消铄，此去三年，当以疽死。士 \n人不乐而去。闻茅山有道士医术通神，而不欲自鸣。乃衣仆衣，诣山拜之，愿执薪水之役。 \n道士留置弟子中。久之以实白道士。道士诊之，笑曰∶汝便下山，但日日吃好梨一颗。如生 \n梨已尽，则取干者泡汤，食滓饮汁，疾自当平。士人如其戒，经一岁复见吉老。见其颜貌腴 \n泽，脉息和平，惊曰∶君必遇异人，不然岂有痊理？士人备告吉老。吉老具衣冠望茅山设拜 \n，自咎其学之未至。此与琐言之说仿佛。观夫二条，则梨之功岂小补哉？然惟乳梨、鹅梨、 \n消梨可食，余梨则亦不能去病也。 \n【附方】旧八，新四。 \n消渴饮水∶用香水梨、或鹅梨、或江南悉尼皆可，取汁以蜜汤熬成瓶收。无时以热水或 \n冷水调服，愈乃止。（《普济方》） \n猝得咳嗽∶颂曰∶崔元亮《海上方》∶用好梨去核，捣汁一碗，入椒四十粒，煎一沸去 \n滓，纳黑饧一大两，消讫，细细含咽立定。诜曰∶用梨一颗，刺五十孔，每孔纳椒一粒，面 \n裹灰火煨熟，停冷去椒食之。又方∶去核纳酥、蜜，面裹烧熟，冷食。又方∶切片，酥煎食 \n之。又方∶捣汁一升，入酥、蜜各一两，地黄汁一升，煎成含咽。凡治嗽，须喘急定时冷食 \n之。若热食反伤肺，令嗽更剧，不可救也。若反，可作羊肉汤饼饱食之，便卧少时，即佳。 \n痰喘气急∶梨剜空，纳小黑豆令满，留盖合住系定，糠火煨熟，捣作饼。每日食之，至 \n效。（《摘玄》） \n喑风失音∶生梨，捣汁一盏饮之，日再服。（《食疗本草》） \n小儿风热，昏懵躁闷，不能食∶用消梨三枚切破，以水二升，煮取汁一升，入粳米一合， \n煮粥食之。（《圣惠方》） \n赤目弩肉，日夜痛者∶取好梨一颗捣绞汁，以绵裹黄连片一钱浸汁。仰卧点之。（ \n赤眼肿痛∶鹅梨一枚捣汁，黄连末半两，腻粉一字，和匀绵裹浸梨汁中，日日点之。（ \n《圣惠》） \n反胃转食，药物不下∶用大悉尼一个，以丁香十五粒刺入梨内，湿纸包四、五重，煨熟 \n食 \n\\x花\\x \n【主治】去面黑粉滓（时珍。方见李花下）。 \n\\x叶\\x \n【主治】霍乱吐利不止，煮汁服。作煎，治风（苏恭）。治小儿寒疝（苏颂）。捣汁服， \n解中菌毒（吴瑞）。 \n【附方】旧三，新一。 \n小儿寒疝腹痛，大汗出∶用梨叶，浓煎七合，分作数服，饮之大良。此徐玉经验方也。 \n（《图经本草》） \n中水毒病初起，头痛恶寒，拘急心烦∶用梨叶一把捣烂，以酒一盏搅饮。（《箧中方》） \n蠼 尿疮出黄水∶用梨叶汁涂之，干即易。（《箧中方》） \n食梨过伤∶梨叶煎汁，解之。（黄记） \n\\x木皮\\x \n【主治】解伤寒时气（时珍）。 \n【附方】新四。 \n伤寒温疫已发未发。用梨木皮、大甘草各一两，黄秫谷一合（为末），锅底煤一钱。每 \n服三钱，白汤下，日二服，取愈。此蔡医博方也。（黎居士《简易方》） \n霍乱吐利∶梨枝，煮汁饮。（《圣惠》） \n气积郁冒，人有气从脐左右起上冲，胸满气促，郁冒厥者。用梨木灰、伏出鸡卵壳中白 \n皮、紫菀、麻黄（去节），等分为末，糊丸梧桐子大。每服十丸，酒下。亦可为末服方寸匕， \n或煮汤服。（《总录》） \n结气咳逆三十年者，服之亦瘥。方同上。 \n\n\n\n<目录>果部第三十卷\\果之二\n\n<篇名>鹿梨\n\n内容：（《图经》） \n【校正】原附梨下，今分出。 \n【释名】鼠梨（《诗疏》）、山梨（《毛诗》）、杨 （《尔雅》）、罗。 \n时珍曰∶《尔雅》云∶ ，罗也。其木有纹如罗，故名。《诗》云∶隰有树 。毛苌注 \n云∶ ，一名赤罗，一名山梨，一名树梨。今人谓之杨 。陆机《诗疏》云∶ ，即鹿梨也 \n，一名鼠梨。 \n【集解】颂曰∶江宁府信州一种小梨，名鹿梨，叶如茶，根如小拇指。彼人取皮治疮， \n八月采之。近处亦有，但采实作干，不知入药也。 \n时珍曰∶山梨，野梨也，处处有之。梨大如杏，可食。其木纹细密，赤者纹急，白者纹 \n缓。按∶陆机云∶鹿梨，齐郡尧山、鲁国、河内皆有，人亦种之。实似梨而酢，亦有美脆者 \n。 \n\\x实\\x \n【气味】酸，涩，寒，无毒。 \n【主治】煨食治痢（苏颂）。 \n\\x根皮\\x \n【气味】同实。 \n【主治】疮疥，煎汁洗之（苏颂）。 \n【附方】新二。 \n一切疮∶鹿梨散∶用鹿梨根、蛇床子各半斤，真剪草四两，硫黄三钱，轻粉一钱。为末。 \n麻油调敷之。小儿涂于绢衣上着之，七日不解，自愈。（《仁存方》） \n一切癣∶鹿梨根，刮皮捣烂，醋和麻布包擦之。干者为末，以水和捣。（唐瑶《经验方》） \n\n\n\n<目录>果部第三十卷\\果之二\n\n<篇名>棠梨\n\n内容：（《纲目》） \n【释名】甘棠。 \n时珍曰∶《尔雅》云∶杜，甘棠也。赤者杜，白者棠。或云∶牝曰杜，牡曰棠。或云∶ \n涩者杜，甘者棠。杜者涩也，棠者糖也。三说俱通，末说近是。 \n【集解】时珍曰∶棠梨，野梨也。处处山林有之。树似梨而小。叶似苍术叶，亦有团者 \n，三叉者，叶边皆有锯齿，色颇黪白。二月开白花，结实如小楝子大，霜后可食。其树接梨 \n甚嘉。有甘酢、赤白二种。按∶陆机《诗疏》云∶白棠，甘棠也，子多酸美而滑。赤棠子涩 \n而酢，木理亦赤，可作弓材。《救荒本草》云∶其叶味微苦，嫩时炸熟，水浸淘净，油、盐 \n调食，或蒸晒代茶。其花亦可炸食，或晒干磨面，作烧饼食，以济饥。又杨慎《丹铅录》 \n言∶尹伯奇采 花以济饥。注者言∶ ，即山梨，乃今棠梨也。未知是否？ \n\\x实\\x \n【气味】酸、甘，涩，寒，无毒。 \n【主治】烧食，止滑痢（时珍）。 \n\\x枝叶\\x \n【气味】同实。 \n【主治】霍乱吐泻不止，转筋腹痛，取一握，同木瓜二两煎汁，细呷之（时珍。《圣惠 \n方》）。 \n【附方】新一。 \n反胃吐食∶棠梨叶，油炒，去刺，为末。每旦酒服一钱。（《山居四要》） \n\n\n\n<目录>果部第三十卷\\果之二\n\n<篇名>海红\n\n内容：（《纲目》） \n【释名】海棠梨。 \n时珍曰∶按∶李德裕《草木记》云∶凡花木名海者，皆从海外来，如海棠之类是也。又 \n李白诗注云∶海红乃花名，出新罗国甚多。则海棠之自海外有据矣。 \n【集解】时珍曰∶《饮膳正要》果类有海红，不知出处，此即海棠梨之实也。状如木瓜 \n而小，二月开红花，实至八月乃熟。郑樵《通志》云∶海棠子名海红，即《尔雅》赤棠也。 \n沈立《海棠记》云∶棠有甘棠、沙棠、棠梨，皆非海棠也。海棠盛于蜀中。其出江南者 \n名南海棠，大抵相类，而花差小。棠性多类梨。其核生者长慢，十数年乃花。以枝接梨及木 \n瓜者易茂，其根色黄而盘劲，其木坚而多节，外白中赤。其枝叶密而条畅。其叶类杜，大者 \n缥绿色，小者浅紫色。 \n二月开花五出，初如胭脂点点然，开则渐成缬晕，落则有若素妆淡粉。其蒂长寸余，淡 \n紫色，或三萼、五萼成丛。其蕊如金粟，中有紫须。其实状如梨，大如樱桃，至秋可食，味 \n甘酸。大抵海棠花以紫绵色者为正，余皆棠梨耳。海棠花不香，惟蜀之嘉州者有香而木大。 \n有黄海棠，花黄。贴干海棠，花小而鲜。垂丝海棠，花粉红向下。皆无子，非真海棠也。 \n\\x子\\x \n【气味】酸、甘，平，无毒。 \n【主治】泄痢（时珍。出《正要》）。 \n\n\n\n<目录>果部第三十卷\\果之二\n\n<篇名>木瓜\n\n内容：（《别录》中品） \n【释名】 （音茂）。 \n时珍曰∶按∶《尔雅》云∶ ，木瓜。郭璞注云∶木实如小瓜，酢而可食。则木瓜之名 \n取此义也。或云∶木瓜味酸，得木之正气故名。亦通。 从林、矛，谐声也。 \n【集解】弘景曰∶木瓜，山阴兰亭尤多，彼人以为良果。又有 楂，大而黄。有楂子， \n小而涩。《礼》云∶楂、梨钻之。古亦以楂为果，今则不也。 \n保升曰∶其树枝状如柰，花作房生子，形似栝蒌，火干甚香。楂子似梨而酢，江外常为 \n果食。 \n颂曰∶木瓜，处处有之，而宣城者为佳。木状如柰，春末开花，深红色。其实大者如瓜 \n，小者如拳，上黄似着粉。宣人种莳尤谨，遍满山谷。始实成则镞纸花粘于上，夜露日烘， \n渐变红，花文如生。本州以充土贡，故有宣城花木瓜之称。 楂酷类木瓜，但看蒂间别有重 \n蒂如乳者为木瓜，无者为 楂也。 \n曰∶真木瓜皮薄，色赤黄，香而甘酸不涩，其向里子头尖，一面方，食之益人。有和 \n圆子，色微黄，蒂粗，其子小圆，味涩微咸，能伤人气。有蔓子，颗小，味绝涩，不堪用。 \n有土伏子，味绝苦涩不堪，子如大样油麻，饵之令人目涩、目赤筋痛也。 \n宗 曰∶西洛大木瓜，其味和美，至熟只青白色，入药绝有功，胜宣州者，味淡。 \n时珍曰∶木瓜可种可接，可以枝压。其叶光而浓，其实如小瓜而有鼻，津润味不木者， \n为木瓜；圆小于木瓜，味木而酢涩者，为木桃；似木瓜而无鼻，大于木桃，味涩者，为木李 \n，亦曰木梨，即 楂及和圆子也。鼻乃花脱处，非脐蒂也。木瓜性脆，可蜜渍之为果。去子 \n蒸烂，捣泥入蜜与姜作煎，冬月饮尤佳。木桃、木李性坚，可蜜煎及作糕食之。木瓜烧灰散 \n池中，可以毒鱼，说出《淮南万毕术》。又《广志》云∶木瓜枝，一尺有百二十节，可为杖 \n\\x实\\x \n【修治】 曰∶凡使木瓜，勿犯铁器，以铜刀削去硬皮并子，切片晒干，以黄 \n牛乳 \n时珍曰∶今人但切片晒干入药尔。按∶《大明会典》∶宣州岁贡乌烂虫蛀木瓜入御药局 \n。亦取其陈久无木气，如栗子去木气之义尔。 \n【气味】酸，温，无毒。 \n思邈曰∶酸、咸，温，涩。诜曰∶不可多食，损齿及骨。 \n【主治】湿痹邪气，霍乱大吐下，转筋不止（《别录》）。治香港脚冲心，取嫩者一颗，去 \n子，煎服，佳。强筋骨，下冷气，止呕逆，心膈痰唾，消食，止水利后渴不止，作饮服之（ \n《藏器》）。止吐泻奔豚，及水肿冷热痢，心腹痛（大明）。调营卫，助谷气（雷 ）。去湿和 \n胃，滋脾益肺，治腹胀善噫，心下烦痞（好古）。 \n【发明】杲曰∶木瓜，入手、足太阴血分，气脱能收，气滞能和。 \n弘景曰∶木瓜最疗转筋。如转筋时，但呼其名及书上作木瓜字，皆愈。此理亦不可解。 \n俗人拄木瓜杖，云利筋胫也。 \n宗 曰∶木瓜得木之正，酸能入肝，故益筋与血。病腰肾脚膝无力，皆不可缺也。人以 \n铅霜或胡粉涂之，则失酢味，且无渣，盖受金之制也。 \n时珍曰∶木瓜所主霍乱、吐利、转筋、香港脚，皆脾胃病，非肝病也。肝虽主筋，而转筋 \n则由湿热、寒湿之邪袭伤脾胃所致，故筋转必起于足腓。腓及宗筋皆属阳明。木瓜治转筋， \n非益筋也，理脾而伐肝也。土病则金衰而木盛，故用酸温以收脾肺之耗散，而借其走筋以平 \n肝邪，乃土中泻木以助金也。木平则土得令而金受荫矣。《素问》云∶酸走筋。筋病无多食 \n酸。孟诜云∶多食木瓜，损齿及骨。皆伐肝之明验，而木瓜入手、足太阴，为脾、肺药，非 \n肝药，益可征矣。又《针经》云∶多食酸，令人癃。酸入于胃，其气涩以收，上之两焦 \n出入，流入胃中，下去膀胱，胞薄以软，得酸则缩卷，约而不通，故水道不利而癃涩也。罗 \n天益《宝鉴》云∶太保刘仲海日食蜜煎木瓜三、五枚，同伴数人皆病淋疾，以问天益。天益 \n曰∶此食酸所致也，但夺食则已。阴之所生，本在五味；阴之所营，伤在五味。五味太过， \n皆能伤人，不独酸也。又陆佃《埤雅》云∶俗言梨百损一益， 百益一损。故《诗》云∶投 \n我以木瓜。取其有益也。 \n【附方】旧二，新十。 \n项强筋急不可转侧，肝、肾二脏受风也∶用宣州木瓜二个（取盖去瓤），没药二两，乳 \n香 \n二钱半。二味入木瓜内缚定，饭上蒸三、四次，烂研成膏。每用三钱，入生地黄汁半盏，无 \n灰酒二盏，暖化温服。许叔微云∶有人患此，自午后发，黄昏时定。予谓此必先从足起。足 \n少阴之筋自足至项。筋者肝之合。今日中至黄昏，阳中之阴，肺也。自离至兑，阴旺阳弱之 \n时。故《灵宝毕法》云∶离至干，肾气绝而肝气弱。肝、肾二脏受邪，故发于此时。予授此 \n及都梁丸，服之而愈。（《本事方》） \n香港脚肿急∶用木瓜切片，囊盛踏之。广德顾安中，患香港脚筋急腿肿。因附舟，以足阁一 \n袋 \n医录》） \n脚筋挛痛∶用木瓜数枚，以酒、水各半，煮烂捣膏，乘热贴于痛处，以帛裹之。冷即换， \n日三、五度。（《食疗本草》） \n脐下绞痛∶木瓜三片，桑叶七片，大枣三枚。水三升，煮半升，顿服即愈。（《食疗》） \n小儿洞痢，木瓜捣汁，服之。（《千金方》） \n霍乱转筋∶木瓜一两，酒一升，煎服。不饮酒者，煎汤服。仍煎汤，浸青布裹其足。（《 \n圣惠》） \n霍乱腹痛∶木瓜五钱，桑叶三片，枣肉一枚。水煎服。（《圣惠方》） \n四蒸木瓜丸治肝、肾、脾三经气虚，为风寒暑湿相搏，流注经络。凡遇六气更变，七情 \n不和，必至发动，或肿满，或顽痹，憎寒壮热，呕吐自汗，霍乱吐利。用宣州大木瓜四个， \n切盖剜空听用∶一个入黄 、续断末各半两于内；一个入苍术、橘皮末各半两于内；一个入 \n乌药、黄松节末各半两于内（黄松节即茯神中心木也）；一个入威灵仙、苦葶苈末各半两于 \n内。 \n以原盖簪定，用酒浸透，入甑内蒸熟、晒，三浸、三蒸、三晒，捣末，以榆皮末、水和，糊 \n丸如梧桐子大。每服五十丸，温酒、盐汤任下。（《御药院方》） \n肾脏虚冷，气攻腹胁，胀满疼痛。用大木瓜三十枚，去皮、核，剜空，以甘菊花末、青 \n盐末各一斤填满，置笼内蒸熟，捣成膏，入新艾茸二斤搜和，丸如梧桐子大。每米饮下三十 \n丸，日二。（《圣济总录》） \n发槁不泽∶木瓜浸油，梳头。（《圣惠方》） \n反花痔疮∶木瓜为末，以鳝鱼身上涎调，贴之，以纸护住。（《医林集要》） \n辟除壁虱∶以木瓜切片，铺于席下。（ 仙《神隐》） \n\\x木瓜核\\x \n【主治】霍乱烦躁气急，每嚼七粒，温水咽之（时珍。出《圣惠》）。 \n\\x枝、叶、皮、根\\x \n【气味】并酸、涩，温，无毒。 \n【主治】煮汁饮，并止霍乱、吐下、转筋，疗香港脚（《别录》）。枝，作杖，利筋脉。根 \n、叶，煮汤淋足胫，可以已蹶。木材作桶濯足，甚益人（苏颂）。枝、叶煮汁饮，治热痢（时 \n珍。出《千金》）。 \n\\x花\\x \n【主治】面黑粉滓（方见李花）。 \n\n\n\n<目录>果部第三十卷\\果之二\n\n<篇名>楂子\n\n内容：（音渣。《食疗》） \n【校正】原附木瓜下，今分出。 \n【释名】木桃（《埤雅》）、和圆子。 \n时珍曰∶木瓜酸香而性脆。木桃酢涩而多渣，故谓之楂，《雷公炮炙论》和圆子即此也 \n【集解】《藏器》曰∶楂子生中都，似 而小，江外常为果食，北土无之。 \n颂曰∶处处有之，孟州特多。 \n弘景曰∶《礼》云∶楂梨钻之。谓钻去核也。郑玄不识，以为梨之不臧者。郭璞以为似 \n梨而酢涩。古以为果，今不入例矣。 \n时珍曰∶楂子乃木瓜之酢涩者，小于木瓜，色微黄，蒂、核皆粗，核中之子小圆也。按 \n∶王祯《农书》云∶楂似小梨，西川、唐、邓间多种之。味劣于梨与木瓜，而入蜜煮汤， \n则香美过之。《庄子》云∶楂、梨、橘、柚皆可于口。《淮南子》云∶树楂、梨、橘，食之 \n则美，嗅之则香。皆指此也。 \n【气味】酸，涩，平，无毒。 \n诜曰∶多食伤气，损齿及筋。 \n【主治】断痢（弘景）。去恶心咽酸，止酒痰黄水（藏器）。煮汁饮，治霍乱转筋，功与 \n木瓜相近（孟诜）。 \n\n\n\n<目录>果部第三十卷\\果之二\n\n<篇名>楂\n\n内容：（音冥渣。宋《图经》） \n【校正】原附木瓜下，今分出。 \n【释名】蛮楂（《通志》）、瘙楂（《拾遗》）、木李（《诗经》）、木梨（《埤雅》）。 \n时珍曰∶木李生于吴越，故郑樵《通志》谓之蛮楂。云俗呼为木梨，则 楂盖蛮楂之讹 \n也。 \n【集解】颂曰∶ 楂木、叶、花、实酷类木瓜，但比木瓜大而黄色。辨之惟看蒂间别有 \n重蒂如乳者为木瓜，无此则 楂也。可以进酒去痰。道家生压取汁，和甘松、玄参末作湿香 \n，云甚爽神也。 \n诜曰∶ 楂气辛香，置衣箱中杀蠹虫。 \n时珍曰∶ 楂，乃木瓜之大而黄色无重蒂者也；楂子，乃木瓜之短小而味酢涩者也； \n，则楂类之生于北土者也。三物与木瓜皆是一类各种，故其形状功用不甚相远，但木瓜得 \n木之正气，为可贵耳。 \n【气味】酸，平，无毒。 \n【主治】解酒去痰（弘景）。食之去恶心，止心中酸水（藏器）。煨食，止痢。浸油梳头， \n治发白、发赤（大明）。煮汁服，治霍乱转筋（吴瑞）。 \n\n\n\n<目录>果部第三十卷\n\n<篇名>果之二\n\n内容：（音温孛。宋《开宝》） \n【释名】时珍曰∶ ，性温而气 ，故名。 （音孛），香气也。 \n【集解】志曰∶ 生北土，似楂子而小。 \n颂曰∶今关陕有之，沙苑出者更佳。其实大抵类楂，但肤慢而多毛，味尤甘。其气芬馥 \n，置衣笥中亦香。 \n藏器曰∶树如林檎，花白绿色。 \n宗 曰∶食之须净去浮毛，不尔损人肺。花白色，亦香。最多生虫，少有不蛀者。 \n时珍曰∶ ，盖 楂之类生于北土者，故其形状功用皆相仿佛。李 《南海药录》言 \n∶关中谓林檎为 。按∶《述征记》云∶林檎佳美。 微大而状丑有毛，其味香，关辅 \n乃有，江南甚希。观此则林檎、 ，盖相似而二物也。李氏误矣。 \n【气味】酸、甘，微温，无毒。 \n士良曰∶发毒热，秘大小肠，聚胸中痰，壅涩血脉，不宜多食。 \n瑞曰∶同车螯食，发疝气。 \n【主治】温中，下气消食，除心间酸水，去臭，辟衣鱼（《开宝》）。去胸膈积食，止渴 \n除烦。将卧时，啖一、两枚，生、熟皆宜（苏颂。宗 曰∶卧时啖此太多，亦痞塞胃脘也）。 \n主水泻肠虚烦热，散酒气，并宜生食（李 ）。 \n\\x木皮\\x \n【主治】捣末，敷疮（苏颂）。 \n\n\n\n<目录>果部第三十卷\\果之二\n\n<篇名>山楂\n\n内容：（音渣。《唐本草》） \n【校正】《唐本草》木部赤爪木，宋《 \n也。今并于一，但以山楂标题。 \n【释名】赤爪子（侧巧切，《唐本》）、鼠楂《唐本》、猴楂（危氏）、茅楂（《日用》）、 \n子（音求）、 梅（音计。并《尔雅》）、羊 （《唐本》）、棠 子（《图经》）、山里果（《 \n食鉴》）。 \n时珍曰∶山楂，味似楂子，故亦名楂。世俗皆作查字，误矣。查（音槎）乃水中浮木， \n与楂何关？郭璞注《尔雅》云∶ （音求）树如梅。其子大如指头，赤色似小柰，可食，此 \n即山 \n楂也。世俗作 字，亦误矣。 乃栎实，于 何关？楂、 之名，见于《尔雅》。自晋、宋 \n以来，不知其原，但用查、 耳。此物生于山原茅林中，猴、鼠喜食之，故又有诸名也。《 \n唐本草》赤爪木当作赤枣，盖枣、爪音讹也，楂状似赤枣故尔。范成大《虞衡志》有赤枣子 \n。王 《百一选方》云∶山里红果，俗名酸枣，又名鼻涕团。正合此义矣。 \n【集解】恭曰∶赤爪木，赤楂也。出山南、申、安、随诸州。小树高五、六尺，叶似香 \n。子似虎掌，大如小林檎，赤色。 \n藏器曰∶赤爪草，即鼠楂 也。生高原， 似小楂而赤，人食之。 \n颂曰∶棠 子生滁州。三月开白花，随便结实，采无时。彼人用治下痢及腰疼有效。他 \n处亦有，不入药用。 \n时珍曰∶赤爪、棠 、山楂，一物也。古方罕用，故《唐本》虽有赤爪，后人不知即此 \n也。自丹溪朱氏始着山楂之功，而后遂为要药。其类有二种，皆生山中。一种小者，山人呼 \n为棠 子、茅楂、猴楂，可入药用。树高数尺，叶有五尖。丫间有刺。三月开五出小白花。 \n实有赤、黄二色，肥者如小林檎，小者如指头，九月乃熟，小儿采而卖之。闽人取熟者去皮 \n核，捣和糖、蜜，作为楂糕，以充果物。其核状如牵牛子，黑色甚坚。一种大者，山人呼为 \n羊子。树高丈余，花叶皆同，但实稍大而色黄绿，皮涩肉虚为异尔。初甚酸涩，经霜乃可 \n食。功用相同，而采药者不收。 \n\\x实\\x \n【修治】时珍曰∶九月霜后取带熟者，去核曝干，或蒸熟去皮核，捣作饼子，日干 \n【气味】酸，冷，无毒。 \n时珍曰∶酸、甘，微温。生食多，令人嘈烦易饥，损齿，齿龋人尤不宜也。 \n【主治】煮汁服，止水痢。沐头洗身，治疮痒（《唐本》）。煮汁洗漆疮，多瘥（弘景）。 \n治腰痛有效（苏颂）。消食积，补脾，治小肠疝气，发小儿疮疹（吴瑞）。健胃，行结气。 \n治妇人产后儿枕痛，恶露不尽，煎汁入沙糖服之，立效（震亨）。化饮食，消肉积症瘕，痰 \n饮痞满吞酸，滞血痛胀（时珍）。化血块气块，活血（宁原）。 \n【发明】震亨曰∶山楂大能克化饮食。若胃中无食积，脾虚不能运化，不思食者，多服 \n之，则反克伐脾胃生发之气也。 \n时珍曰∶凡脾弱食物不克化，胸腹酸刺胀闷者，于每食后嚼二、三枚，绝佳。但不可多 \n用，恐反克伐也。按∶《物类相感志》言∶煮老鸡、硬肉，入山楂数颗即易烂。则其消肉积 \n之功，盖可推矣。珍邻家一小儿，因食积黄肿，腹胀如鼓。偶往羊 树下，取食之至饱。归 \n而大吐痰水，其病遂愈。羊 乃山楂同类，医家不用而有此效，则其功应相同矣。 \n【附方】新七。 \n偏坠疝气∶山棠 肉、茴香（炒）各一两，为末，糊丸梧桐子大。每服一百丸，空心白 \n汤下。 \n老人腰痛及腿痛∶用棠 子、鹿茸（炙）等分，为末，蜜丸梧桐子大。每服百丸，日二 \n服。肠风下血，用寒药、热药及脾弱药俱不效者∶独用山里果（俗名酸枣，又名鼻涕团）干 \n者， \n痘疹不快∶干山楂为末，汤点服之，立出红活。又法∶猴楂五个，酒煎入水，温服即出。 \n痘疮干黑危困者∶用棠 子为末，紫草煎酒，调服一钱。（《全幼心鉴》） \n食肉不消∶山楂肉四两，水煮食之，并饮其汁。（《简便方》） \n\\x核\\x \n【主治】吞之，化食磨积，治 疝（时珍）。 \n【附方】新一。 \n难产∶山楂核七七粒，百草霜为衣，酒吞下。（《海上方》） \n阴肾 肿∶方见橄榄。 \n\n\n\n<目录>果部第三十卷\\果之二\n\n<篇名>赤爪木\n\n内容：【气味】苦，寒，无毒。 \n【主治】水痢，头风身痒（《唐本》）。 \n\\x根\\x \n【主治】消积，治反胃（时珍）。 \n\\x茎、叶\\x \n【主治】煮汁，洗漆疮（时珍。出《肘后》）。 \n\n\n\n<目录>果部第三十卷\\果之二\n\n<篇名>庵罗果\n\n内容：（宋《开宝》） \n【释名】庵摩罗迦果（出佛书）、香盖。 \n时珍曰∶庵罗，梵音二合者也。庵摩罗，梵音三合者也。华言清净是也。 \n【集解】志曰∶庵罗果，树生，若林檎而极大。 \n宗 曰∶西洛甚多，梨之类也。其状似梨，先诸梨熟，七夕前后已堪啖。色黄如鹅梨， \n才熟便松软，入药亦希。 \n时珍曰∶按∶《一统志》云∶庵罗果俗名香盖，乃果中极品。种出西域，亦柰类也。叶 \n似茶叶，实似北梨，五、六月熟，多食亦无害。今安南诸地亦有之。 \n【气味】甘，温，无毒。士良曰∶酸，微寒。 \n志曰∶动风疾。凡天行病及食饱后，俱不可食。同大蒜、辛物食，令人患黄病。 \n【主治】食之止渴（《开宝》）。主妇人经脉不通，丈夫营卫中血脉不行。久食，令人不 \n饥（士良）。 \n\\x叶\\x \n【主治】渴疾，煎汤饮（士良）。 \n\n\n\n<目录>果部第三十卷\\果之二\n\n<篇名>柰\n\n内容：（《别录》下品） \n【释名】频婆（音波）。 \n时珍曰∶篆文柰字，象子缀于木之形。梵言谓之频婆，今北人亦呼之，犹云端好也。 \n【集解】弘景曰∶柰，江南虽有，而北国最丰。作脯食之，不宜人。林檎相似而小，俱 \n不益人。 \n士良曰∶此有三种∶大而长者为柰，圆者为林檎，皆夏熟；小者味涩为 ，秋熟， \n一名楸子。 \n时珍曰∶柰与林檎，一类二种也。树、实皆似林檎而大，西土最多，可栽可压。有白、 \n赤、青三色。白者为素柰，赤者为丹柰，亦曰朱柰，青者为绿柰，皆夏熟。凉州有冬柰，冬 \n熟，子带碧色。孔氏《六帖》言∶凉州白柰，大如兔头。《西京杂记》言∶上林苑紫柰，大 \n如升，核紫花青。其汁如漆，着衣不可浣，名脂衣柰。此皆异种也。郭义恭《广志》云∶西 \n方例多柰，家家收切，曝干为脯，数十百斛，以为蓄积，谓之频婆粮。亦取柰汁为豉用。其 \n法∶取熟柰纳瓮中，勿令蝇入；六、七日待烂，以酒腌，痛拌令如粥状，下水更拌，滤去皮 \n子；良久，去清汁，倾布上，以灰在下引汁尽，划开，晒干，为末，调物甘酸得所也。刘熙 \n《释名》载∶柰油，以柰捣汁涂缯上，曝燥取下，色如油也。今关西人以赤柰、楸子取汁涂 \n器中，曝干，名果单是矣。味甘酸，可以馈远。杜恕《笃论》云∶日给之花似柰，柰实而日 \n给零落，虚伪与真实相似也。则日给乃柰之不实者。而《王羲之帖》云∶来禽、日给，皆囊 \n盛为佳果。则又似指柰为日给矣。木槿花亦名日及，或同名耳。 \n\\x实\\x \n【气味】苦，寒，有小毒。多食令人肺壅、胪胀，有病患尤甚（《别录》）。 \n思邈曰∶酸、苦，寒，涩，无毒。 \n时珍曰∶案∶《正要》云∶频婆∶甘，无毒。 \n【主治】补中焦诸不足气，和脾。治猝食饱气壅不通者，捣汁服（孟诜）。益心气，耐 \n饥 \n\n\n\n<目录>果部第三十卷\\果之二\n\n<篇名>林檎\n\n内容：（宋《开宝》） \n【校正】并入《拾遗》文林郎果。 \n【释名】来禽（《法帖》）、文林郎果。 \n《藏器》曰∶文林郎生渤海间。云其树从河中浮来，有文林郎拾得种之，因以为名。 \n曰∶文林郎，南人呼为 是矣。 \n时珍曰∶案∶洪玉父云∶此果味甘，能来众禽于林，故有林禽、来禽之名。又唐高宗时 \n，纪王李谨得五色林檎似朱柰以贡。帝大悦，赐谨为文林郎。人因呼林檎为文林郎果。又《 \n述征记》云∶林檎实佳美。其 微大而状丑，有毛而香，关辅乃有，江南甚希。据此，则 \n林檎是文林郎，非 也。 \n【集解】志曰∶林檎，在处有之。树似柰，皆二月开粉红花。子亦如柰而差圆，六月、 \n七月熟。 \n颂曰∶亦有甘、酢二种∶甘者，早熟而味脆美；酢者，差晚，须烂熟乃堪啖。今医家干 \n之入治伤寒药，谓之林檎散。 \n时珍曰∶林檎，即柰之小而圆者。其味酢者，即楸子也。其类有金林檎、红林檎、水林 \n檎、蜜林檎、黑林檎，皆以色味立名。黑者色似紫柰。有冬月再实者。林檎熟时，晒干研末 \n点汤服甚美，谓之林檎 。僧赞宁《物类相感志》云∶林檎树生毛虫，埋蚕蛾于下，或以洗 \n鱼水浇之即止。皆物性之妙也。 \n【气味】酸、甘，温，无毒。 \n思邈曰∶酸、苦，平，涩，无毒。多食令人百脉弱。 \n志曰∶多食发热及冷痰涩气，令人好唾，或生疮疖，闭百脉。其子食之，令人烦心。 \n【主治】下气消痰，治霍乱肚痛（大明）。消渴者，宜食之（苏颂）。疗水谷痢、泄精（孟 \n诜）。小儿闪癖（时珍）。 \n【附方】旧三。 \n水痢不止∶林檎（半熟者）十枚。水二升，煎一升，并林檎食之。（《食医心镜》） \n小儿下痢∶林檎、构子同杵汁，任意服之。（《子母秘录》） \n小儿闪癖，头发竖黄，瘰 瘦弱者∶干林檎脯研末，和醋敷之。（同上） \n\\x东行根\\x \n【主治】白虫、蛔虫，消渴好唾（孟诜）。 \n\n\n\n<目录>果部第三十卷\\果之二\n\n<篇名>柿\n\n内容：（音士。《别录》中品） \n【释名】时珍曰∶ 从KT ，音滓，谐声也。俗作 ，非矣。 （音肺），削木片也。 \n胡名镇头 \n【集解】颂曰∶柿南北皆有之，其种亦多。红柿所在皆有。黄柿生汴、洛诸州。朱柿出 \n华山，似红柿而圆小，皮薄可爱，味更甘珍。 柿色青，可生啖。诸柿食之皆美而益人。又 \n有一种小柿，谓之软枣，俗呼为牛奶柿。世传柿有七绝∶一多寿，二多阴，三无鸟巢，四无 \n虫蠹，五霜叶可玩，六嘉宾，七落叶肥滑，可以临书也。 \n宗 曰∶柿有数种∶着盖柿，于蒂下别有一重。又有牛心柿，状如牛心。蒸饼柿，状如 \n市卖蒸饼。华州朱柿，小而深红。塔柿，大于诸柿，去皮挂木上，风晒干之佳。火干者，味 \n不甚佳。其生者，可以温水养去涩味也。 \n时珍曰∶柿高树大叶，圆而光泽。四月开小花，黄白色。结实青绿色，八、九月乃熟。 \n生柿置器中自红者谓之烘柿，晒干者谓之白柿，火干者谓之乌柿，水浸藏者谓之 柿。其核 \n形扁，状如木鳖子仁而硬坚。其根甚固，谓之柿盘。案《事类合璧》云∶柿，朱果也。大者 \n如碟，八棱稍扁；其次如拳；小或如鸡子、鸭子、牛心、鹿心之状。一种小而如拆二钱者， \n谓之猴枣。皆以核少者为佳。 \n烘柿∶时珍曰∶烘柿，非谓火烘也。即青绿之柿，收置器中，自然红熟如烘成，涩味尽 \n去，其甘如蜜。欧阳修《归田录》言∶襄、邓人以 楂或 或橘叶于中则熟，亦不必。 \n【气味】甘，寒，涩，无毒。 \n弘景曰∶生柿性冷，鹿心柿尤不可食，令人腹痛。 \n宗 曰∶凡柿皆凉，不至大寒。食之引痰，为其味甘也。晒干者，食多动风。 \n颂曰∶凡柿同蟹食，令人腹痛作泻，二物俱寒也。 \n时珍曰∶按∶王 《百一选方》云∶一人食蟹，多食红柿，至夜大吐，继之以血，昏不 \n省人。一道者云∶惟木香可解。乃磨汁灌之，即渐苏醒而愈也。 \n【主治】通耳鼻气，治肠 不足。解酒毒，压胃间热，止口干（《别录》）。续经脉气（ \n诜）。 \n【发明】藏器曰∶饮酒食红柿，令人易醉或心痛欲死。《别录》言解酒毒，失之矣 \n\\x白柿、柿霜\\x \n【修治】时珍曰∶白柿即干柿生霜者。其法用大柿去皮捻扁，日晒夜露至干，内瓮中， \n待生白霜乃取出。今人谓之柿饼，亦曰柿花。其霜谓之柿霜。 \n【气味】甘，平，涩，无毒。 \n弘景曰∶晒干者性冷，生柿弥冷。火熏者性热。 \n【主治】补虚劳不足，消腹中宿血，涩中浓肠，健脾胃气（诜）。开胃涩肠，消痰止渴， \n治吐血，润心肺，疗肺痿心热咳嗽，润声喉，杀虫（大明）。温补。多食，去面 （藏器）。 \n治反胃咯血，血淋肠 ，痔漏下血（时珍）。霜∶清上焦心肺热，生津止渴，化痰宁嗽，治 \n咽喉 \n【发明】震亨曰∶干柿属金而有土，属阴而有收意。故止血治咳，亦可为助也。 \n时珍曰∶柿乃脾、肺血分之果也。其味甘而气平，性涩而能收，故有健脾涩肠、治嗽止 \n血之功。盖大肠者，肺之合而胃之子也。真正柿霜，乃其精液，入肺病上焦药尤佳。按∶方 \n勺《泊宅编》云∶外兄刘掾云∶病脏毒下血，凡半月，自分必死。得一方，只以干柿烧灰， \n饮服二钱，遂愈。又王 《百一方》云∶曾通判子病下血十年，亦用此方一服而愈。为散 \n、为丸皆可，与本草治肠 、消宿血、解热毒之义相合。则柿为太阴血分之药，益可证矣。 \n又《经验方》云∶有人三世死于反胃病，至孙得一方∶用干柿饼同干饭日日食之，绝不用水 \n饮，如法食之，其病遂愈。此又一证也。 \n【附方】旧四，新十二。 \n肠风脏毒∶方说见上。 \n小便血淋∶叶氏∶用干柿三枚（烧存性），研末。陈米饮服。《经验方》∶用白柿、乌豆、 \n盐花煎汤，入墨汁服之。 \n热淋涩痛∶干柿、灯心等分。水煎日饮（《朱氏方》） \n小儿秋痢∶以粳米煮粥，熟时入干柿末，再煮三、两沸食之，奶母亦食之。（《食疗》） \n反胃吐食∶干柿三枚，连蒂捣烂，酒服甚效。切勿以他药杂之。 \n腹薄食减，凡男女脾虚腹薄，食不消化，面上黑点者∶用干柿三斤，酥一斤，蜜半斤。 \n以酥、蜜煎匀，下柿煮十余沸，用不津器贮之。每日空腹食三、五枚，甚良。（孟诜《食疗》） \n痰嗽带血∶青州大柿饼，饭上蒸熟批开。每用一枚，掺真青黛一钱，卧时食之，薄荷汤下 \n。（《丹溪纂要》） \n产后咳逆，气乱心烦。用干柿切碎，水煮汁呷。（《产宝》） \n妇人蒜发∶干柿五枚，以茅香（煮熟）、枸杞子（酒浸，焙研）各等分。捣丸梧桐子大。 \n每服五十丸，茅香汤下，日三。（《普济》） \n面生 ∶干柿，日日食之。（《普济方》） \n鼻窒不通∶干柿同粳米煮粥，日食。（《圣济》） \n耳聋鼻塞∶干柿三枚细切，以粳米三合，豆豉少许煮粥，日日空心食之。（《圣惠》） \n痘疮入目∶白柿，日日食之，良。 \n胫烂疮∶用柿霜、柿蒂等分烧研，敷之甚效。（笔峰《杂兴》） \n解桐油毒∶干柿饼食之。（《普济》） \n\\x乌柿\\x（火熏干者） \n【气味】甘，温，无毒。 \n【主治】杀虫，疗金疮、火疮，生肉止痛（《别录》）。治狗啮疮，断下痢（弘景）。服药 \n口苦及呕逆者，食少许即止（藏器）。 \n\\x 柿\\x（音览） \n【修治】瑞曰∶水藏者性冷，盐藏者有毒。 \n时珍曰∶ ，藏柿也。水收、盐浸之外，又有以熟柿用灰汁澡三、四度，令汁尽着器中 \n，经十余日即可食，治病非宜。 \n【主治】涩下焦，健脾胃，消宿血（诜）。 \n\\x柿糕\\x \n【修治】时珍曰∶案∶李氏《食经》云∶用糯米（洗净）一斗，大干柿五十个，同 \n捣粉蒸食，如干，入煮枣泥和拌之。 \n【主治】作饼及糕与小儿食，治秋痢（诜）。黄柿和米粉作糗蒸，与小儿食，止下痢、 \n下血有效（《藏器》）。 \n\\x柿蒂\\x \n【气味】涩，平，无毒。 \n【主治】咳逆哕气，煮汁服（诜）。 \n【发明】震亨曰∶人之阴气，依胃为养。土伤则木挟相火，直冲清道而上作咳逆。古人 \n以 \n时珍曰∶咳逆者，气自脐下冲脉直上至咽膈，作呃忒蹇逆之声也。朱肱《南阳书》以哕 \n为咳逆，王履《溯洄集》以咳嗽为咳逆，皆误矣。哕者，干呕有声也。咳逆有伤寒吐下后， \n及久病产后，老人虚人，阴气大亏，阳气暴逆，自下焦逆至上焦而不能出者；有伤寒失下， \n及平人痰气抑遏而然者。当视其虚实阴阳，或温或补，或泄热，或降气，或吐或下可也。古 \n方单用柿蒂煮汁饮之，取其苦温能降逆气也。《济生》柿蒂散，加以丁香、生姜之辛热，以 \n开痰散郁，盖从治之法，而昔人亦常用之收效矣。至易水张氏又益以人参，治病后虚人咳逆 \n，亦有功绩。丹溪朱氏但执以寒治热之理，而不及从治之法，矫枉之过矣。若陈氏《三因》 \n又加以良姜之类，是真以为胃寒而助其邪火者也。 \n【附方】新一。 \n咳逆不止∶《济生》柿蒂散∶治咳逆胸满。用柿蒂、丁香各二钱，生姜五片。水煎服。 \n或 \n》加青皮、陈皮。王氏《易简》加半夏、生姜。 \n\\x木皮\\x \n【主治】下血。晒焙研末，米饮服二钱，两服可止（颂）。汤火疮，烧灰，油调敷 \n（时珍）。 \n\\x根\\x \n【主治】血崩，血痢，下血（时珍）。 \n\n\n\n<目录>果部第三十卷\\果之二\n\n<篇名>柿\n\n内容：（音卑士。宋《开宝》） \n【释名】漆柿（《日华》）、绿柿（《日用》）、青 （《广志》）、乌 （《开宝》）、花 \n（《日用》）、赤棠 。 \n时珍曰∶ 乃柿之小而卑者，故谓之 。他柿至熟则黄赤，惟此虽熟亦青黑色。捣碎浸 \n汁谓之柿漆，可以染罾、扇诸物，故有漆柿之名。 \n【集解】志曰∶ 柿生江淮以南，似柿而青黑。潘岳《闲居赋》所谓“梁侯乌 之柿” \n是也。 \n颂曰∶ 柿出宣歙、荆襄、闽广诸州。柿大如杏，惟堪生啖，不可为干也。 \n【气味】甘，寒，涩，无毒。 \n弘景曰∶ 生啖性冷，服石家宜之，不入药用。不可与蟹同食。 \n【主治】压丹石药发热，利水，解酒毒，去胃中热。久食，令人寒中（《开宝》）。止烦 \n渴，润心肺，除腹脏冷热（《日华》）。 \n\n\n\n<目录>果部第三十卷\\果之二\n\n<篇名>君迁子\n\n内容：（《拾遗》） \n【释名】KT 枣（《千金》作软枣）、 枣（《广志》。音逞）、牛奶柿（《名苑》）、丁香 \n柿 \n时珍曰∶君迁之名，始见于左思《吴都赋》，而着其状于刘欣期《交州记》，名义莫详 \n。KT 枣，其形似枣而软也。司马光《名苑》云∶君迁子似马奶，即今牛奶柿也，以形得 \n名。崔豹《古今注》云∶牛奶柿即KT 枣，叶如柿，子亦如柿而小。唐宋诸家，不知君迁、 \nKT枣 \n【集解】藏器曰∶君迁子生海南，树高丈余，子中有汁，如乳汁甜美。《吴都赋》 \n平仲君迁是也。 \n时珍曰∶君迁即KT 枣，其木类柿而叶长。但结实小而长，状如牛奶，干熟则紫黑色。 \n一种小圆如指顶大者，名丁香柿，味尤美。《救荒本草》以为羊矢枣，误矣。其树接大柿最 \n佳。《广志》云∶KT 枣，小柿也。肌细而浓，少核，可以供御。即此。 \n【气味】甘、涩，平，无毒。 \n【主治】止消渴，去烦热，令人润泽（《藏器》）。镇心。久服，悦人颜色，令人轻健（ \n）。 \n\n\n\n<目录>果部第三十卷\\果之二\n\n<篇名>安石榴\n\n内容：（《别录》下品） \n【释名】若榴（《广雅》）、丹若（《古今注》）、金罂。 \n时珍曰∶榴者，瘤也，丹实垂垂如赘瘤也。《博物志》云∶汉张骞出使西域，得涂林安 \n石国榴种以归，故名安石榴。又按∶《齐民要术》云∶凡植榴者须安僵石枯骨于根下，即花 \n实繁茂。则安石之名义或取此也。若木乃扶桑之名，榴花丹 似之，故亦有丹若之称。傅玄 \n《榴赋》所谓“灼若旭日栖扶桑”者是矣。《笔衡》云∶五代吴越王钱 改榴为金罂。《酉阳 \n杂 \n俎》言∶榴甜者名天浆。道家书谓榴为三尸酒，言三尸虫得此果则醉也。故范成大诗云∶玉 \n池咽清肥，三彭迹如扫。 \n【集解】弘景曰∶石榴花赤可爱，故人多植之，尤为外国所重。有甜、酢二种，医家惟 \n用酢者之根、壳。榴子乃服食者所忌。 \n颂曰∶安石榴，本生西域，今处处有之。木不甚高硕，枝柯附干，自地便生作丛。种极 \n易息，折其条盘土中便生也。花有黄、赤二色。实有甘、酢二种，甘者可食，酢者入药。又 \n一种山石榴，形颇相类而绝小，不作房生，青、齐间甚多，不入药，但蜜渍以当果甚美。 \n宗曰∶石榴有酸、淡二种。旋开单叶花，旋结实，实中子红，孙枝甚多，秋后经霜则自 \n坼裂。一种子白，莹澈如水晶者，味亦甘，谓之水晶石榴。惟酸石榴入药，须老木所结，收 \n留陈久者乃佳。 \n时珍曰∶榴五月开花，有红、黄、白三色。单叶者结实。千叶者不结实，或结亦无子也 \n。实有甜、酸、苦三种。《抱朴子》言∶苦者出积石山。或云即山石榴也。《酉阳杂俎》言 \n∶南诏石榴皮薄如纸。《琐碎录》言∶河阴石榴名三十八者，其中只有三十八子也。又南中 \n有四季榴，四时开花，秋月结实，实方绽，随复开花。有火石榴赤色如火。海石榴高一、二 \n尺即结实。皆异种也。案∶《事类合璧》云∶榴大如杯，赤色有黑斑点，皮中如蜂窠，有黄 \n膜隔之，子形如人齿，淡红色，亦有洁白如雪者。潘岳赋云∶榴者，天下之奇树，九州之名 \n果。千房同膜，千子如一。御饥疗渴，解酲止醉。 \n\\x甘石榴\\x \n【气味】甘、酸，温，涩，无毒。多食损人肺（《别录》）。 \n诜曰∶多食损齿令黑。凡服食药物人忌食之。 \n震亨曰∶榴者，留也。其汁酸性滞，粘膈成痰。 \n【主治】咽喉燥渴（《别录》）。能理乳石毒（段成式）。制三尸虫（时珍）。 \n\\x酸石榴\\x \n【气味】酸，温，涩，无毒。 \n【主治】赤白痢腹痛，连子捣汁，顿服一枚（孟诜）。止泻痢崩中带下（时珍）。 \n【发明】时珍曰∶榴受少阳之气，而荣于四月，盛于五月，实于盛夏，熟于深秋。丹花 \n赤实，其味甘酸，其气温涩，具木火之象。故多食损肺、齿而生痰涎。酸者则兼收敛之气， \n故入断下、崩中之药。或云∶白榴皮治白痢，红榴皮治红痢，亦通。 \n【附方】新五。 \n肠滑久痢∶黑神散∶用酸石榴一个。 烟尽，出火毒一夜，研末。仍以酸榴一块，煎汤 \n服 \n久泻不止∶方同上。（并《普济方》） \n痢血五色或脓或水，冷热不调∶酸石榴五枚（连子）。捣汁二升，每服五合，神妙。（《 \n圣济》） \n小便不禁∶酸石榴烧存性（无则用枝烧灰代之）。每服二钱，用柏白皮（切，焙）四钱， \n煎汤 \n捻须令黑∶酸石榴结成时，就东南枝上拣大者一个，顶上开一孔，内水银半两于中，原 \n皮 \n（《普济》） \n\\x酸榴皮\\x \n【修治】 曰∶凡使榴皮、叶、根，勿犯铁，并不计干湿，皆以浆水浸一夜，取出用， \n其水如墨汁也。 \n【气味】同实。 \n【主治】止下痢漏精（《别录》）。治筋骨风，腰脚不遂，行步挛急疼痛，涩肠。取汁点 \n目，止泪下（权）。煎服，下蛔虫（《藏器》）。止泻痢，下血脱肛，崩中带下（时珍）。 \n【附方】旧六，新四。 \n赤白痢下腹痛，食不消化者∶《食疗本草》∶用醋榴皮，炙黄为末，枣肉或粟米饭和丸 \n梧桐子大。每空腹米饮服三十丸，日三服，以知为度。如寒滑，加附子、赤石脂各一倍。《 \n肘后方》∶用皮烧存性，为末。每米饮服方寸匕，日三服，效乃止。 \n粪前有血，令人面黄∶用酢石榴皮（炙），研末。每服二钱，用茄子枝煎汤服。（孙真人 \n方） \n肠滑久痢，神妙无比方也∶用石榴一个劈破，炭火簇烧存性，出火毒，为末。每服一钱， \n别以酸石榴一瓣，水一盏，煎汤调服。（《经验方》） \n久痢久泻∶陈石榴皮酢者，焙研细末。每服二钱，米饮下。患二、三年或二、三月，百 \n方 \n小儿风痫∶大生石榴一枚，割去顶，剜空，入全蝎五枚，黄泥固济， 存性，为末。每 \n服 \n猝病耳聋∶八、九月间，取石榴一个，上作孔如球子大，内米醋令满，以原皮盖之，水 \n和面裹煨熟，取起去盖，入少黑李子、仙沼子末，取水滴耳中，勿动。脑中若痛，勿惊。如 \n此三夜，再作必通。案∶唐慎微《本草》收采此方，云出孙真人。而黑李子不知为何物也， \n其仙沼子即预知子。 \n食榴损齿∶石榴黑皮，炙黄，研末，枣肉和丸梧桐子大。每日空腹三丸，白汤下，日二 \n服 \n疔肿恶毒∶以针刺四畔，用榴皮着疮上，以面围四畔，灸之，以痛为度。仍纳榴末敷上 \n急 \n脚肚生疮初起如粟，搔之渐开，黄水浸淫，痒痛溃烂，遂致绕胫而成痼疾∶用酸榴皮煎 \n汤，冷定，日日扫之，取愈乃止。（《医学正宗》） \n\\x酸榴东行根\\x \n【气味】同皮。 \n【主治】蛔虫、寸白（《别录》）。青者，入染须用（权）。治口齿病（颂）。止涩泻痢、 \n带 \n【附方】旧三，新二。 \n金蚕蛊毒，吮白矾味甘，嚼黑豆不腥者，即是中蛊也∶石榴根皮，煎浓汁服，即吐出活 \n蛊 \n寸白蛔虫∶酢石榴东引根一握。洗锉，用水三升，煎取半碗，五更温服尽，至明取下虫 \n一 \n女子经闭不通∶用酢榴根（东生者）一握（炙干）。水二大盏，浓煎一盏，空心服之。 \n未通 \n再服。（《斗门》） \n赤白下痢∶方同上。 \n\\x榴花\\x \n【主治】阴干为末，和铁丹服，一年变白发如漆（藏器。铁丹，飞铁为丹也，亦 \n铁粉之属）。千叶者，治心热吐血。又研末吹鼻，止衄血，立效。亦敷金疮出血（苏颂）。 \n【附方】旧一，新二。 \n金疮出血∶榴花半斤，锻石一升。捣和阴干。每用少许敷之，立止。（崔元亮方） \n鼻出衄血∶酢榴花二钱半，黄蜀葵花一钱。为末。每服一钱，水一盏，煎服，效乃止。 \n（ \n九窍出血∶石榴花（揉）塞之取效。叶亦可。 \n\n\n\n<目录>果部第三十卷\\果之二\n\n<篇名>橘\n\n内容：（《本经》上品） \n【校正】志曰∶自木部移入此。 \n【释名】时珍曰∶橘，从 音鹬，谐声也。又云五色为庆，二色为 。 云外赤内黄 \n、非烟非雾、郁郁纷纷之象。橘实外赤内黄，剖之香雾纷郁，有似乎 云。橘之从 ，又取 \n此意也。 \n【集解】《别录》曰∶橘、柚，生江南及山南山谷，十月采。 \n恭曰∶柚之皮浓味甘，不似橘皮味辛苦。其肉亦如橘，有甘有酸。酸者名胡柑。今俗谓 \n橙为柚，非矣。案∶郭璞云∶柚似橙而实酢，大于橘。孔安国云∶小曰橘，大曰柚，皆为柑 \n也。 \n颂曰∶橘、柚，今江浙、荆襄、湖岭皆有之。木高一、二丈，叶与枳无辨，刺出茎间。 \n夏初生白花，六、七月成实，至冬黄熟。旧说小为橘，大为柚。今医家乃用黄橘、青橘，不 \n言柚。岂青橘是柚之类乎？ \n宗 曰∶橘、柚自是两种。《本草》云∶一名橘皮。后人误加柚字，妄生分别。且青橘 \n、黄橘治疗尚殊，况柚为别种乎？惟郭璞所言，乃真识橘、柚者。若不如此分别，误以柚皮 \n为橘皮，是贻无穷之患矣。 \n时珍曰∶橘、柚，苏恭所说甚是。苏颂不知青橘即橘之未黄者，乃以为柚，误矣。夫橘 \n、柚、柑三者相类而不同。橘实小，其瓣味微酢，其皮薄而红，味辛而苦。柑大于橘，其瓣 \n味甘，其皮稍浓而黄，味辛而甘。柚大小皆如橙，其瓣味酢，其皮最浓而黄，味甘而不甚辛 \n。如此分之，即不误矣。按∶《事类合璧》云∶橘树高丈许，枝多生刺。其叶两头尖，绿色 \n光面，大寸余，长二寸许。四月着小白花，甚香。结实至冬黄熟，大者如杯，包中有瓣，瓣 \n中有核也。宋韩彦直着《橘谱》三卷甚详，其略云∶柑橘出苏州、台州，西出荆州，南出闽 \n、广、抚州，皆不如温州者为上也。柑品有八，橘品十有四，多是接成。惟种成者，气味尤 \n胜。黄橘，扁小而多香雾，乃橘之上品也；朱橘，小而色赤如火；绿橘，绀碧可爱，不待霜 \n后，色味已佳，隆冬采之，生意如新；乳橘，状似乳柑，皮坚瓤多，味绝酸芳；塌橘，状大 \n而扁，外绿心红，瓣巨多液，经春乃甘美；包橘，外薄内盈，其脉瓣隔皮可数；绵橘，微小， \n极软美可受，而不多结；沙橘，细小甘美；油橘，皮似油饰，中坚外黑，乃橘之下品也；早 \n黄橘，秋半已丹；冻橘，八月开花，冬结春采；穿心橘，实大皮光，而心虚可穿；荔枝橘，"}, {"n": 27, "text": "卷二十七\n\n出衡阳，肤理皱密如荔子也。俗传橘下埋鼠，则结实加倍。故《物类相感志》曰∶橘见尸而 \n实繁。《涅 经》云∶如橘见鼠，其果实多。《周礼》言∶橘逾淮而北∶变为枳，地气然也。 \n余见柑下。 \n\\x橘实\\x \n【气味】甘、酸，温，无毒 \n弘景曰∶食之多痰，恐非益也。 \n原曰∶多食粘膈生痰，滞肺气。 \n瑞曰∶同螃蟹食，令人患软痈。 \n【主治】甘者润肺，酸者聚痰（藏器）。止消渴，开胃，除胸中膈气（大明）。 \n【发明】时珍曰∶橘皮，下气消痰，其肉生痰聚饮，表里之异如此，凡物皆然。今人以 \n蜜煎橘充果食甚佳，亦可酱菹也。 \n\\x黄橘皮\\x \n【释名】红皮（《汤液》）、陈皮（《食疗》）。 \n弘景曰∶橘皮疗气大胜。以东橘为好，西江者不如。须陈久者为良。 \n好古曰∶橘皮以色红日久者为佳，故曰红皮、陈皮。去白者曰橘红也。 \n【修治】 曰∶凡使勿用柚皮、皱子皮，二件用不得。凡修事，须去白膜一重，锉细 \n，以鲤鱼皮裹一宿，至明取用。 \n宗 曰∶《本草》橘、柚作一条，盖传误也。后世不知，以柚皮为橘皮，是贻无穷之患 \n矣。此乃六陈之一，天下日用所须。今人又多以乳柑皮乱之，不可不择也。柑皮不甚苦，橘 \n皮极苦，至熟亦苦。或以皮之紧慢分别，又因方土不同，亦互有紧慢也。 \n时珍曰∶橘皮，纹细色红而薄，内多筋脉，其味苦辛；柑皮，纹粗色黄而浓，内多白膜 \n，其味辛甘；柚皮，最浓而虚，纹更粗，色黄，内多膜无筋，其味甘多辛少。但以此别之， \n即不差矣。橘皮性温，柑、柚皮性冷，不可不知。今天下多以广中来者为胜，江西者次之。 \n然亦多以柑皮杂之。柑皮犹可用，柚皮则悬绝矣。凡橘皮，入和中理胃药则留白，入下气消 \n痰药则去白，其说出于《圣济经》。去白者，以白汤入盐洗润透，刮去筋膜，晒干用。亦有 \n煮焙者，各随本方。 \n【气味】苦、辛，温，无毒。 \n【主治】胸中瘕热逆气，利水谷。久服去臭，下气通神（《本经》）。下气，止呕咳，治 \n气冲胸中，吐逆霍乱，疗脾不能消谷，止泄，除膀胱留热停水，五淋，利小便，去寸白虫（ \n《别录》）。清痰涎，治上气咳嗽，开胃，主气痢，破症瘕 癖（甄权）。疗呕哕反胃嘈杂， \n时吐清水，痰痞 疟，大肠秘塞，妇人乳痈。入食料，解鱼腥毒（时珍）。 \n【发明】杲曰∶橘皮，气薄味浓，阳中之阴也。可升可降，为脾、肺二经气分药。留白 \n则补脾胃，去白则理肺气；同白术则补脾胃，同甘草则补肺，独用则泻肺损脾。其体轻浮， \n一能导胸中寒邪，二破滞气，三益脾胃。加青皮减半用之，去滞气，推陈致新。但多用久服 \n，能损元气也。 \n原曰∶橘皮，能散、能泻、能温、能补、能和，化痰治嗽，顺气理中，调脾快膈，通五 \n淋，疗酒病，其功当在诸药之上。 \n时珍曰∶橘皮，苦能泄、能燥，辛能散，温能和。其治百病，总是取其理气燥湿之功。 \n同补药则补，同泻药则泻，同升药则升，同降药则降。脾乃元气之母，肺乃摄气之 ，故橘 \n皮为二经气分之药，但随所配而补泻升降也。洁古张氏云∶陈皮、枳壳利其气而痰自下，盖 \n此义也。同杏仁治大肠气秘，同桃仁治大肠血秘，皆取其通滞也。详见杏仁下。按方勺《泊 \n宅编》云∶橘皮宽膈降气，消痰饮，极有殊功。他药贵新，惟此贵陈。外舅莫强中令丰城时 \n得疾，凡食已辄胸满不下，百方不效。偶家人合橘红汤，因取尝之，似相宜，连日饮之。一 \n日忽觉胸中有物坠下，大惊目瞪，自汗如雨。须臾腹痛，下数块如铁弹子，臭不可闻。自此 \n胸次廓然，其疾顿愈，盖脾之冷积也。其方∶用橘皮（去穣）一斤，甘草、盐花各四两。水五 \n碗，慢火煮干，焙研为末，白汤点服。名二贤散，治一切痰气特验。世医徒知半夏、南星之 \n属，何足以语此哉？珍按∶二贤散，丹溪变之为润下丸，用治痰气有效。惟气实人服之相宜， \n气不足者不宜用之也。 \n【附方】旧八，新二十。 \n润下丸∶治湿痰，因火泛上，停滞胸膈，咳唾稠粘。陈橘皮半斤（入砂锅内，下盐五钱， \n化水淹过，煮干），粉甘草二两（去皮，蜜炙）。各取净末，蒸饼和丸梧桐子大。每服百丸， \n白汤下。（丹溪方） \n宽中丸∶治脾气不和，冷气客于中，壅遏不通，是为胀满。用橘皮四两，白术二两。为 \n末 \n橘皮汤∶治男女伤寒并一切杂病呕哕，手足逆冷者。用橘皮四两，生姜一两。水二升， \n煎 \n嘈杂吐水∶真橘皮去白为末，五更安五分于掌心舐之，即睡，三日必效。皮不真则不验。 \n（《怪证奇方》） \n霍乱吐泻∶不拘男女，但有一点胃气存者，服之再生。广陈皮（去白）五钱，真藿香五 \n钱。水二盏，煎一盏，时时温服。出《百一选方》。《圣惠》∶用陈橘皮末二钱，汤点服（不 \n省 \n反胃吐食∶真橘皮，以日照西壁土炒香，为末。每服二钱，生姜三片，枣肉一枚，水二 \n钟 \n猝然食噎∶橘皮一两。汤浸去瓤，焙为末。以水一大盏，煎半盏，热服。（《食医心镜》） \n诸气呃噫∶橘皮二两。去瓤，水一升，煎五合，顿服。或加枳壳尤良。（孙尚药方） \n痰膈气胀∶陈皮三钱。水煎热服。（杨氏《简便方》） \n猝然失声∶橘皮半两，水煎，徐呷。（《肘后方》） \n经年气嗽∶橘皮、神曲、生姜（焙干）等分。为末，蒸饼和丸梧桐子大。每服三、五十 \n丸，食 \n化食消痰，胸中热气∶用橘皮半两。微熬，为末。水煎代茶，细呷。（《心镜》） \n下焦冷气∶干陈橘皮一斤。为末，蜜丸梧桐子大。每食前温酒下三十丸。（《食疗本草》） \n香港脚冲心或心下结硬，腹中虚冷∶陈皮一斤，和杏仁五两（去皮尖）熬，少加蜜，捣和 \n丸 \n老人气秘∶方同上。（《济生》） \n大肠秘塞∶陈皮连白，酒煮，焙，研末。每温酒服二钱，一方米饮下。（《普济》） \n途中心痛∶橘皮去白，煎汤饮之，甚良。（谈野翁方） \n食鱼蟹毒∶方同上。（《肘后》） \n风痰麻木，凡手及十指麻木，大风麻木，皆是湿痰死血∶用橘红一斤，逆流水五碗，煮 \n烂 \n脾寒诸疟不拘老少孕妇，只两服便止∶真橘皮（去白，切），生姜自然汁浸过一指，银 \n器 \n内重汤煮，焙干，研末。每服三钱，用隔年青州枣十个，水一盏，煎半盏，发前服，以枣下 \n之。（《适用方》） \n小儿疳瘦，久服消食和气，长肌肉∶用陈橘皮一两，黄连（以米泔水浸一日）一两半。 \n研 \n末，入麝三分，用猪胆盛药，以浆水煮熟取出，用粟米饭和丸绿豆大。每服一、二十丸，米 \n饮下。（钱氏《小儿方》） \n产后尿秘不通者∶陈皮一两，去白为末。每空心温酒服二钱，一服即通。此张不愚方也 \n。（《妇人良方》） \n产后吹奶∶陈皮一两，甘草一钱。水煎服，即散。 \n妇人乳痈，未成者即散，已成者即溃，痛不可忍者即不疼，神验不可云喻也∶用真陈橘 \n皮，汤浸去白晒，面炒微黄，为末。每服二钱，麝香调酒下。初发者一服见效。名橘香散。 \n（ \n耳出汁∶陈皮（烧研）一钱，麝香少许。为末。日掺。名立效散。 \n鱼骨鲠咽∶橘皮，常含，咽汁即下。（《圣惠方》） \n嵌甲作痛不能行履者∶浓煎陈皮，汤浸良久，甲肉自离，轻手剪去，以虎骨末敷之即安 \n。（《医林集要》） \n\\x青橘皮\\x \n【修治】时珍曰∶青橘皮乃橘之未黄而青色者，薄而光，其气芳烈。今人多以 \n小柑、小柚、小橙伪为之，不可不慎辨之。入药以汤浸去瓤，切片醋拌，瓦炒过用。 \n【气味】苦、辛，温，无毒。 \n【主治】气滞，下食，破积结及膈气（颂）。破坚癖，散滞气，去下焦诸湿，治左胁肝 \n经积气（元素）。治胸膈气逆，胁痛，小腹疝痛，消乳肿，疏肝胆，泻肺气（时珍）。 \n【发明】元素曰∶青橘皮气味俱浓，沉而降，阴也。入厥阴、少阳经，治肝胆之病。 \n杲曰∶青皮，乃足厥阴引经之药，能引食入太阴之仓，破滞削坚，皆治在下之病。有滞 \n气则破滞气，无滞气则损真气。 \n好古曰∶陈皮治高，青皮治低，与枳壳治胸膈、枳实治心下同意。 \n震亨曰∶青皮，乃肝胆二经气分药。故人多怒有滞气，胁下有郁积，或小腹疝疼，用之 \n以疏通二经，行其气也。若二经实者，当先补而后用之。又云∶疏肝气加青皮，炒黑则入血 \n分也。 \n时珍曰∶青橘皮，古无用者，至宋时医家始用之。其色青气烈，味苦而辛，治之以醋， \n所谓肝欲散，急食辛以散之，以酸泄之，以苦降之也。陈皮浮而升，入脾、肺气分。青皮沉 \n而降，入肝、胆气分。一体二用，物理自然也。小儿消积多用青皮，最能发汗，有汗者不可 \n用。说出杨仁斋《直指方》，人罕知之。 \n嘉谟曰∶久疟热甚，必结癖块，宜多服清脾汤。内有青皮疏利肝邪，则癖自不结也。 \n【附方】旧二，新七。 \n快膈汤治冷膈气及酒食后饱满∶用青橘皮一斤，作四分∶四两用盐汤浸，四两用百沸汤 \n浸，四两用醋浸，四两用酒浸。各三日取出，去白切丝，以盐一两炒微焦，研末。每用二钱 \n，以茶末五分，水煎温服。亦可点服。《经验后方》 \n理脾快气∶青橘皮一斤（晒干焙研末），甘草末一两，檀香末半两。和匀收之。每用一、 \n二 \n法制青皮∶常服安神调气，消食解酒益胃，不拘老人小儿。宋仁宗每食后咀数片，乃邢 \n和璞真人所献，名万年草，刘 改名延年草，仁宗以赐吕丞相。用青皮一斤（浸去苦味，去 \n瓤，炼净），白盐花五两，炙甘草六两，舶茴香四两。甜水一斗，煮之，不住搅，勿令着底， \n候水尽，慢火焙干，勿令焦，去甘草、茴香，只取青皮，密收用。（王氏《易简方》） \n疟疾寒热∶青皮一两。烧存性，研末。发前，温酒服一钱，临时再服。（《圣惠方》） \n伤寒呃逆，声闻四邻∶四花青皮全者，研末。每服二钱，白汤下。（《医林集要》） \n产后气逆∶青橘皮为末。葱白、童子小便煎二钱，服。（《经验后方》） \n妇人乳癌∶因久积忧郁，乳房内有核如指头，不痛不痒，五、七年成痈，名乳癌，不可 \n治 \n耳出汁∶青皮烧研末，绵包塞之。 \n唇燥生疮∶青皮，烧研，猪脂调涂。 \n\\x橘瓤上筋膜\\x \n【主治】口渴、吐酒。炒熟，煎汤饮，甚效（大明）。 \n\\x橘核\\x \n【修治】时珍曰∶凡用，须以新瓦焙香，去壳取仁，研碎入药。 \n【气味】苦，平， \n【主治】肾疰腰痛，膀胱气痛，肾冷。炒研，每温酒服一钱，或酒煎服之（大明）。治 \n酒风、鼻赤。炒研，每服一钱，胡桃肉一个，擂酒服，以知为度（宗 ）。小肠疝气及阴 \n核肿 \n【发明】时珍曰∶橘核入足厥阴，与青皮同功，故治腰痛 疝在下之病，不独取象于核 \n也。《和剂局方》治诸疝痛及内 ，卵肿偏坠，或硬如石，或肿至溃，有橘核丸，用之有效 \n。品味颇多，详见本方。 \n【附方】新一。 \n腰痛∶橘核、杜仲各二两（炒）。研末。每服二钱，盐酒下。（《简便方》） \n\\x叶\\x \n【气味】苦，平，无毒。 \n【主治】导胸膈逆气，入厥阴，行肝气，消肿散毒，乳痈胁痛，用之行经（震亨）。 \n【附方】新一。 \n肺痈∶绿橘叶，洗，捣绞汁一盏，服之。吐出脓血即愈。（《经验良方》） \n\n\n\n<目录>果部第三十卷\\果之二\n\n<篇名>柑\n\n内容：（宋《开宝》） \n【释名】木奴。 \n志曰∶柑，未经霜时犹酸，霜后甚甜，故名柑子。 \n时珍曰∶汉李衡种柑于武陵洲上，号为木奴焉。 \n【集解】炳曰∶乳柑出西戎者佳。 \n志曰∶柑生岭南及江南，树似橘，实亦似橘而圆大，皮色生青熟黄赤。惟乳柑皮入药， \n山 \n藏器曰∶柑有朱柑、黄柑、乳柑、石柑、沙柑。橘有朱橘、乳橘、塌橘、山橘、黄淡子 \n。此辈皮皆去气调中，实俱堪食，就中以乳柑为上也。 \n时珍曰∶柑，南方果也，而闽、广、温、台、苏、抚、荆州为盛，川蜀虽有不及之。其 \n树无异于橘，但刺少耳。柑皮比橘色黄而稍浓，理稍粗而味不苦。橘可久留，柑易腐败。柑 \n树畏冰雪，橘树略可。此柑、橘之异也。柑、橘皮，今人多混用，不可不辨，详见橘下。案 \n∶韩彦直《橘谱》云∶乳柑，出温州诸邑，惟泥山者为最，以其味似乳酪故名。彼人呼为真 \n柑，似以它柑为假矣。其木婆娑，其叶纤长，其花香韵，其实圆正，肤理如泽蜡，其大六、 \n七寸，其皮薄而味珍，脉不粘瓣，食不留滓，一颗仅二、三核，亦有全无者，擘之香雾 人 \n，为柑中绝品也。生枝柑，形不圆，色青肤粗，味带微酸，留之枝间，可耐久也，俟味变甘 \n，乃带叶折，故名。海红柑，树小而颗极大，有围及尺者，皮浓色红，可久藏，今狮头柑亦 \n是其类也。洞庭柑，种出洞庭山，皮细味美，其熟最早也。甜柑，类洞庭而大，每颗必八瓣 \n，不待霜而黄也。木柑，类洞庭，肤粗顽，瓣大而少液，故谓之木也。朱柑，类洞庭而大， \n色绝嫣红，其味酸，人不重之。馒头柑，近蒂起如馒头尖，味香美也。 \n【气味】甘，大寒，无毒。颂曰∶冷。 \n志曰∶多食令人肺冷生痰，脾冷发痼癖，大肠泻利，发阴汗。 \n【主治】利肠胃中热毒，解丹石，止暴渴，利小便（《开宝》）。 \n【附方】新一。 \n难产∶柑橘瓤，阴干，烧存性，研末。温酒服二钱。（《集效》） \n\\x皮\\x \n【气味】辛、甘，寒，无毒。 \n时珍曰∶橘皮苦辛温，柑皮辛甘寒。外形虽似，而气味不同。 \n诜曰∶多食令肺燥。 \n【主治】下气调中（藏器）。解酒毒及酒渴，去白，焙研末，点汤入盐饮之（大明）。治 \n产后肌浮，为末酒服（藏器）。伤寒饮食劳复者，浓煎汁服（时珍）。山柑皮∶治咽喉痛，效 \n（《 \n\\x核\\x \n【主治】作涂面药（《苏颂》）。 \n\\x叶\\x \n【主治】 耳流水或脓血。取嫩头七个，入水数滴，杵取汁滴之，即愈（蔺氏）。 \n\n\n\n<目录>果部第三十卷\\果之二\n\n<篇名>橙\n\n内容：（宋《开宝》） \n【释名】金球、鹄壳。 \n时珍曰∶案∶陆佃《埤雅》云∶橙，柚属也。可登而成之，故字从登。又谐声也。 \n【集解】志曰∶橙，树似橘而叶大，其形圆，大于橘而香，皮浓而皱，八月熟。 \n时珍曰∶橙产南土，其实似柚而香，叶有两刻，缺如两段，亦有一种气臭者。柚乃柑属 \n之大者，早黄难留；橙乃橘属之大者，晚熟耐久，皆有大小二种。案∶《事类合璧》云∶橙 \n树高枝，叶不甚类橘，亦有刺。其实大者如碗，颇似朱栾，经霜早熟，色黄皮浓，蹙衄如沸 \n，香气馥郁。其皮可以熏衣，可以 鲜，可以和菹醢，可以为酱齑，可以蜜煎，可以糖制为 \n橙丁，可以蜜制为橙膏。嗅之则香，食之则美，诚佳果也。 \n宗 曰∶橙皮，今只以为果，或合汤待宾，未见入药。宿酒未解者，食之速醒。 \n【气味】酸，寒，无毒。 \n士良曰∶暖。多食伤肝气，发虚热。与 肉同食，发头旋恶心。 \n时珍曰∶ 乃水獭之属也。诸家本草皆作槟榔，误矣。 \n【主治】洗去酸汁，切和盐、蜜，煎成贮食，止恶心，能去胃中浮风恶气（《开宝》）。 \n行风气，疗瘿气，发瘰 ，杀鱼、蟹毒（士良）。 \n\\x皮\\x \n【气味】苦、辛，温，无毒。 \n【主治】作酱、醋香美，散肠胃恶气，消食下气，去胃中浮风气（《开宝》）。和盐贮食 \n，止恶心，解酒病（孟诜）。糖作橙丁，甘美，消痰下气，利膈宽中，解酒（时珍）。 \n【附方】新二。 \n香橙汤∶宽中快气，消酒。用橙皮二斤（切片），生姜五两（切，焙，擂烂），入炙甘草 \n末一 \n痔疮肿痛∶隔年风干橙子，桶内烧烟熏之，神效。（《医方摘要》） \n\\x核\\x \n【主治】面 粉刺，湿研，夜夜涂之（时珍）。 \n【附方】新一。 \n闪挫腰痛∶橙子核，炒研，酒服三钱，即愈。（《摄生方》） \n\n\n\n<目录>果部第三十卷\\果之二\n\n<篇名>柚\n\n内容：（音又。《日华》） \n【释名】 （与柚同）、条（《尔雅》）、壶柑（《唐本》）、臭橙（《食性》）、朱栾。 \n时珍曰∶柚，色油然，其状如卣，故名。壶亦象形。今人呼其黄而小者为蜜筒，正此意 \n也。其大者谓之朱栾，亦取团栾之象。最大者谓之香栾。《尔雅》谓之 （音废），又曰 （ \n音贾）。《广雅》谓之镭柚，镭亦壶也。《桂海志》谓之臭柚，皆一物。但以大小、古今方 \n言称呼不同耳。 \n【集解】恭曰∶柚皮浓味甘，不似橘皮薄味辛而苦。其肉亦如橘，有甘有酸，酸者名壶 \n柑。今俗人谓橙为柚，非矣。案∶《吕氏春秋》云∶果之美者，江浦之橘，云梦之柚。郭璞 \n云∶柚出江南，似橙而实酢，大如橘。禹贡云∶扬州厥包橘、柚。孔安国云∶小曰橘，大曰 \n柚，皆为柑也。 \n颂曰∶闽中、岭外、江南皆有柚，比橘黄，白色而大。襄、唐间柚，色青黄而实小。其 \n味皆酢，皮浓，不堪入药。 \n时珍曰∶柚，树、叶皆似橙。其实有大、小二种∶小者如柑、如橙；大者如瓜、如升， \n有围及尺余者，亦橙之类也。今人呼为朱栾，形色圆正，都类柑、橙。但皮浓而粗，其味甘 \n，其气臭，其瓣坚而酸恶不可食，其花甚香。南人种其核，长成以接柑、橘，云甚良也。盖 \n橙乃橘属，故其皮皱浓而香，味苦而辛；柚乃柑属，故其皮粗浓而臭，味甘而辛。如此分， \n柚与橙、橘自明矣。郭璞云∶ ，大柚也。实大如盏，皮浓二、三寸，子似枳，食之少味。 \n范成大云∶广南臭柚大如瓜，可食，其皮甚浓，染墨打碑，可代毡刷，且不损纸也。《列子 \n》云∶吴越之间有木焉，其名为 。碧树而冬青，实丹而味酸。食其皮汁，已愤厥之疾。渡 \n淮而北，化而为枳。此言地气之不同如此。 \n【气味】酸，寒，无毒。 \n【主治】消食，解酒毒，治饮酒人口气，去肠胃中恶气，疗妊妇不思食、口淡（大明）。 \n\\x皮\\x \n【气味】甘、辛，平，无毒。 \n【正误】时珍曰∶案∶沈括《笔谈》云∶《本草》言橘皮苦，柚皮甘，误矣。柚皮极苦， \n不 \n【主治】下气。宜食，不入药（弘景）。消食快膈，散愤懑之气，化痰（时珍）。 \n【附方】新一。 \n痰气咳嗽∶用香栾，去核，切，砂瓶内浸酒，封固一夜，煮烂，蜜拌匀，时时含咽。 \n\\x叶\\x \n【主治】头风痛，同葱白捣，贴太阳穴（时珍）。 \n\\x花\\x \n【主治】蒸麻油作香泽面脂，长发润燥（时珍）。 \n\n\n\n<目录>果部第三十卷\\果之二\n\n<篇名>枸橼\n\n内容：（音矩员。宋《图经》） \n【校正】原附豆蔻下，今分出。 \n【释名】香橼（俗作圆）、佛手柑。 \n时珍曰∶义未详。佛手，取象也。 \n【集解】藏器曰∶枸橼生岭南，柑、橘之属也。其叶大，其实大如盏，味辛酸。 \n颂曰∶今闽广、江南皆有之，彼人呼为香橼子。形长如小瓜状，其皮若橙而光泽可爱， \n肉甚浓，白如萝卜而松虚。虽味短而香芬大胜，置衣笥中，则数日香不歇。寄至北方，人甚 \n贵重。古作五和糁用之。 \n时珍曰∶枸橼产闽广间。木似朱栾而叶尖长，枝间有刺。植之近水乃生。其实状如人手 \n，有指，俗呼为佛手柑。有长一尺四、五寸者。皮如橙柚而浓，皱而光泽。其色如瓜，生绿 \n熟黄。其核细。其味不甚佳而清香袭人。南人雕镂花鸟，作蜜煎果食。置之几案，可供玩 \n。若安芋片于蒂而以湿纸围护，经久不瘪。或捣蒜罨其蒂上，则香更充溢。《异物志》云∶ \n浸汁浣葛 ，胜似酸浆也！ \n\\x皮瓤\\x \n【气味】辛、酸，无毒。弘景曰∶性温。恭曰∶性冷。陶说误矣。藏器曰∶性温 \n【主治】下气，除心头痰水（藏器）。煮酒饮，治痰气咳嗽。煎汤，治心下气痛（时珍）。 \n\\x根、叶\\x \n【主治】同皮（《橘谱》）。 \n\n\n\n<目录>果部第三十卷\\果之二\n\n<篇名>金橘\n\n内容：（《纲目》） \n【释名】金柑（《橘谱》）、卢橘（《汉书》）、夏橘（《广州记》）、山橘（《北户录》）、 \n给客橙（《魏王花木志》）。 \n时珍曰∶此橘生时青卢色，黄熟则如金，故有金橘、卢橘之名。卢，黑色也。或云卢， \n酒器之名，其形肖之故也。注《文选》者以枇杷为卢橘，误矣。案∶司马相如《上林赋》云 \n∶卢橘夏熟，枇杷 柿。以二物并列，则非一物明矣。此橘夏冬相继，故云夏熟，而裴渊《 \n广州记》谓之夏橘。给客橙者，其芳香如橙，可供给客也。 \n【集解】时珍曰∶金橘，生吴粤、江浙、川广间。或言出营道者为冠，而江浙者皮甘肉 \n酸，次之。其树似橘，不甚高硕。五月开白花结实，秋冬黄熟，大者径寸，小者如指头，形 \n长而皮坚，肌理细莹，生则深绿色，熟乃黄如金。其味酸甘，而芳香可爱，糖造、蜜煎皆佳 \n。案∶《魏王花木志》云∶蜀之成都、临邛、江源诸处，有给客橙，一名卢橘。似橘而非， \n若柚而香。夏冬花实常相继，或如弹丸，或如樱桃，通岁食之。又刘恂《岭表录异》云∶山 \n橘子大如土瓜，次如弹丸，小树绿叶，夏结冬熟，金色薄皮而味酸，偏能破气。容、广人连 \n枝藏之，入脍醋尤加香美。韩彦直《橘谱》云∶金柑出江西，北人不识。景 中始至汴都， \n因温成皇后嗜之，价遂贵重。藏绿豆中可经时不变，盖橘性热、豆性凉也。又有山金柑，一 \n名山金橘，俗名金豆。木高尺许，实如樱桃，内只一核。俱可蜜渍，香味清美。以上诸说， \n皆指今之金橘，但有一类数种之异耳。 \n【气味】酸、甘，温，无毒。 \n【主治】下气快膈，止渴解酲，辟臭。皮尤佳（时珍）。 \n\n\n\n<目录>果部第三十卷\\果之二\n\n<篇名>枇杷\n\n内容：（《别录》中品） \n【释名】宗 曰∶其叶形似琵琶，故名。 \n【集解】颂曰∶枇杷，旧不着所出州土，今襄、汉、吴、蜀、闽、岭、江西南、湖南北 \n皆有之。木高丈余，肥枝长叶，大如驴耳，背有黄毛，阴密婆娑可爱，四时不凋。盛冬开白 \n花，至三、四月成实作 ，生大如弹丸，熟时色如黄杏，微有毛，皮肉甚薄，核大如茅栗， \n黄褐色。四月采叶，曝干用。 \n时珍曰∶案∶郭义恭《广志》云∶枇杷易种，叶微似栗，冬花春实。其子簇结有毛，四 \n月熟，大者如鸡子，小者如龙眼，白者为上，黄者次之。无核者名焦子，出广州。又杨万里 \n诗云∶大叶耸长耳，一枝堪满盘。荔枝分与核，金橘却无酸。颇尽其状。注《文选》者以枇 \n杷为卢橘，误矣。详金橘。 \n\\x实\\x \n【气味】甘、酸，平，无毒。 \n志曰∶寒。诜曰∶温。多食发痰热，伤脾。同炙肉及热面食，令人患热毒黄疾。 \n【主治】止渴下气，利肺气，止吐逆，主上焦热，润五脏（大明）。 \n\\x叶\\x \n【修治】恭曰∶凡用须火炙，以布拭去毛。不尔射人肺，令咳不已。或以粟秆 \n作刷 \n曰∶凡采得，秤湿叶重一两，干者三叶重一两，乃为气足，堪用。粗布拭去毛，以甘 \n草汤洗一遍，用绵再拭干。每一两，以酥二钱半涂上，炙过用。 \n时珍曰∶治胃病，以姜汁涂炙；治肺病，以蜜水涂炙，乃良。 \n【气味】苦，平，无毒。 \n权曰∶甘、微辛。弘景曰∶煮汁饮之，则小冷。 \n【主治】猝 不止，下气，煮汁服（《别录》）。弘景曰∶若不暇煮，但嚼汁咽，亦瘥） \n。治呕哕不止，妇人产后口干（大明）。煮汁饮，主渴疾，治肺气热嗽，及肺风疮，胸面上 \n疮 \n【发明】时珍曰∶枇杷叶，气薄味浓，阳中之阴。治肺胃之病，大都取其下气之功耳。 \n气下则火降痰顺，而逆者不逆，呕者不呕，渴者不渴，咳者不咳矣。 \n宗 曰∶治肺热嗽甚有功。一妇人患肺热久嗽，身如火炙，肌瘦将成痨。以枇杷叶、木 \n通、款冬花、紫菀、杏仁、桑白皮各等分，大黄减半。如常治讫，为末，蜜丸樱桃大。食后 \n、夜卧各含化一丸，未终剂而愈矣。 \n【附方】新七。 \n温病发哕因饮水多者∶枇杷叶（去毛，炙香）、茅根各半斤。水四升，煎二升，稍稍饮 \n之 \n反胃呕哕∶枇杷叶（去毛，炙）、丁香各一两，人参二两。为末，每服三钱，水一盏， \n姜三片 \n衄血不止∶枇杷叶（去毛），焙研末。茶服一、二钱，日二。（同上） \n酒 赤鼻∶枇杷叶、栀子仁等分。为末。每服二钱，温酒调下。日三服。（《本事》） \n面上风疮∶方同上。 \n痔疮肿痛∶枇杷叶（蜜灸）、乌梅肉（焙）。为末。先以乌梅汤洗，贴之。（《集要》） \n痘疮溃烂∶枇杷叶，煎汤洗之。（《摘玄》） \n\\x花\\x \n【主治】头风，鼻流清涕。辛夷等分，研末，酒服二钱，日二服（时珍）。 \n\\x木白皮\\x \n【主治】生嚼咽汁，止吐逆不下食，煮汁冷服，尤佳（思邈）。 \n\n\n\n<目录>果部第三十卷\\果之二\n\n<篇名>杨梅\n\n内容：（宋《开宝》） \n【释名】 子（音求）。 \n时珍曰∶其形如水杨子而味似梅，故名。段氏《北户录》名 子。扬州人呼白杨梅为圣 \n僧。 \n【集解】志曰∶杨梅，生江南、岭南山谷。树若荔枝树，而叶细阴青。子形似水杨子， \n而生青熟红，肉在核上，无皮壳。四月、五月采之。南人腌藏为果，寄至北方。 \n时珍曰∶杨梅树叶如龙眼及紫瑞香，冬月不凋。二月开花结实，形如楮实子，五月熟， \n有红、白、紫三种，红胜于白，紫胜于红，颗大而核细，盐藏、蜜渍、糖收皆佳。东方朔《 \n林邑记》云∶邑有杨梅，其大如杯碗，青时极酸，熟则如蜜。用以酿酒，号为梅香酎，甚珍 \n重之。赞宁《物类相感志》云∶桑上接杨梅则不酸。杨梅树生癞，以甘草钉钉之则无。皆物 \n理之妙也。 \n藏器曰∶张华《博物志》言地瘴处多生杨梅，验之信然。 \n\\x实\\x \n【气味】酸、甘，温，无毒。 \n诜曰∶热，微毒。久食令人发热，损齿及筋。忌生葱同食。 \n瑞曰∶发疮致痰。 \n【主治】盐藏食，去痰止呕哕，消食下酒。干作屑，临饮酒时服方寸匕，止吐酒（《开 \n宝》）。止渴，和五脏，能涤肠胃，除烦愦恶气。烧灰服，断下痢，甚验。盐者常含一枚， \n咽汁，利五脏下气（诜）。 \n【附方】旧一，新三。 \n下痢不止∶杨梅烧研，每米饮服二钱，日二服。（《普济》） \n头痛不止∶杨梅为末，以少许 鼻取嚏，妙。 \n头风作痛∶杨梅为末，每食后薄荷茶服二钱。或以消风散同煎服。或同捣末，以白梅肉 \n和 \n一切损伤，止血生肌，令无瘢痕∶用盐藏杨梅和核捣如泥，做成挺子，以竹筒收之。凡 \n遇 \n\\x核仁\\x \n【主治】香港脚。 \n时珍曰∶案，王明清《挥尘录》云∶会稽杨梅为天下冠。童贯苦香港脚，或云杨梅仁可治 \n之。郡守王嶷馈五十石，贯用之而愈。取仁法∶以柿漆拌核曝之，则自裂出也。 \n\\x树皮及根\\x \n【主治】煎汤，洗恶疮疥癣（大明）。煎水，漱牙痛。服之，解砒毒。 \n烧灰油 \n【附方】新三。 \n中砒毒∶心腹绞痛，欲吐不吐，面青肢冷。用杨梅树皮，煎汤二、三碗，服之即愈。（王 \n硕《易简方》） \n风虫牙痛∶《普济方》∶用杨梅根（皮浓者），焙一两，川芎 五钱，麝香少许。研末。 \n每 \n用半钱，鼻内 之，口中含水，涎出痛止。《摘要方》∶用杨梅根皮、韭菜根、厨案上油泥 \n等分。捣匀，贴于两腮上半时辰，其虫从眼角出也。屡用有效之方。 \n\n\n\n<目录>果部第三十卷\\果之二\n\n<篇名>樱桃\n\n内容：（《别录》上品） \n【释名】莺桃（《礼注》）、含桃（《月令》）、荆桃。 \n宗 曰∶孟诜《本草》言∶此乃樱，非桃也。虽非桃类，以其形肖桃，故曰樱桃，又何 \n疑焉？如沐猴梨、胡桃之类，皆取其形相似耳。《礼记》∶仲春，天子以含桃荐宗庙，即此 \n。故王维诗云∶才是寝园春荐后，非干御苑鸟衔残。药中不甚用。 \n时珍曰∶其颗如璎珠，故谓之樱。而许慎作莺桃，云莺所含食，故又曰含桃，亦通。案 \n∶《尔雅》云∶楔（音戛），荆桃也。孙炎注云∶即今樱桃。最大而甘者，谓之崖蜜。 \n【集解】颂曰∶樱桃，处处有之，而洛中者最胜。其木多阴，先百果熟，故古人多贵之 \n。其实熟时深红色者，谓之朱樱。紫色，皮里有细黄点者，谓之紫樱，味最珍重。又有正黄 \n明者，谓之蜡樱。小而红者，谓之樱珠，味皆不及。极大者，有若弹丸，核细而肉浓，尤难 \n得。 \n时珍曰∶樱桃树不甚高。春初开白花，繁英如雪。叶团，有尖及细齿。结子一枝数十颗 \n，三月熟时须守护，否则鸟食无遗也。盐藏、蜜煎皆可，或同蜜捣作糕食，唐人以酪荐食之 \n。林洪《山家清供》云∶樱桃经雨则虫自内生，人莫之见。用水浸良久，则虫皆出，乃可食 \n也。试之果然。 \n【气味】甘，热，涩，无毒。大明曰∶平，微毒。多食令人吐。 \n诜曰∶食多无损，但发虚热耳。有暗风人不可食，食之立发。 \n李鹏飞曰∶伤筋骨，败血气。有寒热病患不可食。 \n【主治】调中，益脾气，令人好颜色，美志（《别录》）。止泄精、水谷痢（孟诜）。 \n【发明】宗 曰∶小儿食之过多，无不作热。此果三月末、四月初熟，得正阳之气，先 \n诸果熟，故性热也。 \n震亨曰∶樱桃属火而有土，性大热而发湿。旧有热病及喘嗽者，得之立病，且有死者也。 \n时珍曰∶案∶张子和《儒门事亲》云∶舞水一富家有二子，好食紫樱，每日啖一、二升 \n。半月后，长者发肺痿，幼者发肺痈，相继而死。呜呼！百果之生，所以养人，非欲害人。 \n富贵之家，纵其嗜欲取死，是何？天耶？命耶？邵尧夫诗云∶爽口物多终作疾。真格言哉！ \n观此 \n，则寇、朱二氏之言，益可证矣。王维诗云∶饱食不须愁内热，大官还有蔗浆寒。盖谓寒物 \n同食，犹可解其热也。 \n\\x叶\\x \n【气味】甘，平，无毒。煮老鹅，易软熟。 \n【主治】蛇咬，捣汁饮，并敷之（颂）。 \n\\x东行根\\x \n【主治】煮汁服，立下寸白、蛔虫（颂）。 \n\\x枝\\x \n【主治】雀卵斑 ，同紫萍、牙皂、白梅肉研和，日用洗面（时珍）。 \n\\x花\\x \n【主治】面黑粉滓（方见李花）。 \n\n\n\n<目录>果部第三十卷\\果之二\n\n<篇名>山婴桃\n\n内容：（《别录》上品） \n【校正】《唐本》退入有名未用，今移入此。 \n【释名】朱桃（《别录》）、麦樱（《吴普》）、英豆（《别录》）、李桃。 \n诜曰∶此婴桃俗名李桃，又名柰桃。前樱桃名樱，非桃也。 \n【集解】《别录》曰∶婴桃实大如麦，多毛。四月采，阴干。 \n弘景曰∶樱桃即今朱樱，可煮食者。婴桃形相似而实乖异，山间时有之，方药不用。 \n时珍曰∶树如朱婴，但叶长尖不团。子小而尖，生青熟黄赤，亦不光泽，而味恶不堪食 \n\\x实\\x \n【气味】辛，平，无毒。 \n【主治】止泄、肠 ，除热，调中益脾气，令人好颜色，美志（《别录》）。止泄精（孟 \n诜）。 \n\n\n\n<目录>果部第三十卷\\果之二\n\n<篇名>银杏\n\n内容：（《日用》） \n【释名】白果（《日用》）、鸭脚子。 \n时珍曰∶原生江南，叶似鸭掌，因名鸭脚。宋初始入贡，改呼银杏，因其形似小杏而核 \n色白也。今名白果。梅尧臣诗∶鸭脚类绿李，其名因叶高。欧阳修诗∶绛囊初入贡，银杏贵 \n中州。是矣。 \n【集解】时珍曰∶银杏生江南，以宣城者为胜。树高二、三丈。叶薄纵理，俨如鸭掌形 \n，有刻缺，面绿背淡。二月开花成簇，青白色，二更开花，随即卸落，人罕见之。一枝结子 \n百十，状如楝子，经霜乃熟烂。去肉取核为果，其核两头尖，三棱为雄，二棱为雌。其仁嫩 \n时绿色，久则黄。须雌雄同种，其树相望，乃结实；或雌树临水亦可；或凿一孔，内雄木一 \n块，泥之，亦结。阴阳相感之妙如此。其树耐久，肌理白腻。术家取刻符印，云能召使也。 \n《文选·吴都赋》注∶平仲果，其实如银。未知即此果否？ \n\\x核仁\\x \n【气味】甘、苦，平，涩，无毒。 \n时珍曰∶熟食，小苦微甘，性温有小毒。多食令人胪胀。 \n瑞曰∶多食壅气动风。小儿食多昏霍，发惊引疳。同鳗鲡鱼食，患软风。 \n【主治】生食，引疳解酒，熟食益人（李鹏飞）。熟食，温肺益气，定喘嗽，缩小便， \n止 \n白浊。生食，降痰，消毒杀虫。嚼浆，涂鼻面手足，去 皴皱，及疥癣疳 阴虱（时 \n珍）。 \n【发明】时珍曰∶银杏，宋初始著名，而修本草者不收。近时方药亦时用之。其气薄味 \n浓，性涩而收，色白属金。故能入肺经，益肺气，定喘嗽，缩小便。生捣能浣油腻，则其去 \n痰浊之功，可类推矣。其花夜开，人不得见，盖阴毒之物，故又能杀虫消毒。然食多则收令 \n太过，令人气壅胪胀昏顿。故《物类相感志》言∶银杏能醉人。而《三元延寿书》言∶白果 \n食满千个者死。又云∶昔有饥者，同以白果代饭食饱，次日皆死也。 \n【附方】新十八。 \n寒嗽痰喘∶白果七个。煨熟，以熟艾作七丸，每果入艾一丸，纸包再煨香，去艾吃。（《 \n秘韫》方） \n哮喘痰嗽∶鸭掌散∶用银杏五个，麻黄二钱半，甘草（炙）二钱。水一钟半，煎八分， \n卧 \n十一个（炒黄），麻黄三钱，苏子二钱，款冬花、法制半夏、桑白皮（蜜炙）各二钱，杏仁 \n（去皮 \n（并《摄 \n咳嗽失声∶白果仁四两，白茯苓、桑白皮二两，乌豆半升（炒），蜜半斤。煮熟晒干为 \n末，以乳汁半碗拌湿，九蒸九晒，丸如绿豆大。每服三、五十丸，白汤下，神效。（余居士 \n方） \n小便频数∶白果十四枚，七生七煨，食之，取效，止。 \n小便白浊∶生白果仁十枚，擂水饮，日一服，取效，止。 \n赤白带下，下元虚惫∶白果、莲肉、江米各五钱，胡椒一钱半。为末。用乌骨鸡一只， \n去 \n肠风下血∶银杏煨熟，出火气，食之，米饮下。 \n肠风脏毒∶银杏四十九枚，去壳生研，入百药煎末和丸弹子大。每服二、三丸，空心细 \n嚼，米饮送下。（戴原礼《证治要诀》） \n牙齿虫 ∶生银杏，每食后嚼一、二个，良。（《永类钤方》） \n手足皴裂∶生白果嚼烂，夜夜涂之。 \n鼻面酒 ∶银杏、酒浮糟，同嚼烂，夜涂旦洗。（《医林集要》） \n头面癣疮∶生白果仁切断，频擦取效。（邵氏《经验方》） \n下部疳疮，生白果杵，涂之。（赵原阳） \n阴虱作痒∶阴毛际肉中生虫如虱，或红或白，痒不可忍者。白果仁，嚼细，频擦之，取 \n效 \n狗咬成疮∶白果仁，嚼细涂之。 \n乳痈溃烂∶银杏半斤，以四两研酒服之，以四两研敷之。（《救急易方》） \n水疔暗疔∶水疔色黄，麻木不痛；暗疔疮凸色红，使人昏狂。并先刺四畔，后用银杏去 \n壳 \n\n\n\n<目录>果部第三十卷\\果之二\n\n<篇名>胡桃\n\n内容：（宋《开宝》） \n【释名】羌桃（《名物志》）、核桃。 \n颂曰∶此果本出羌胡，汉时张骞使西域始得种还，植之秦中，渐及东土，故名之。 \n时珍曰∶此果外有青皮肉包之，其形如桃，胡桃乃其核也。羌音呼核如胡，名或以此。 \n或作核桃。《梵书》名播罗师。 \n【集解】颂曰∶胡桃生北土，今陕、洛间甚多。大株浓叶多阴，实亦有房，秋冬熟时采 \n之。出陈仓者，薄皮多肌；出阴平者，大而皮脆，急捉则碎。汴州虽有而实不佳，江表亦时 \n有之，南方则无。 \n时珍曰∶胡桃树高丈许，春初生叶，长四、五寸，微似大青叶，两两相对，颇作恶气。 \n三月开花如栗花，穗苍黄色。结实至秋如青桃状，熟时沤烂皮肉，取核为果。 \n人多以榉柳接之。案刘恂《岭表录异》云∶南方有山胡桃，底平如槟榔，皮浓而大坚， \n多肉少穣。其壳甚浓，须椎之方破。然则南方亦有，但不佳耳。 \n\\x核仁\\x \n【气味】甘，平、温，无毒。 \n颂曰∶性热，不可多食。 \n思邈曰∶甘冷滑。多食动痰饮，令人恶心、吐水、吐食物。 \n志曰∶多食动风，脱人眉。同酒食，多令人咯血。 \n颖曰∶多食生痰、动肾火。 \n【发明】震亨曰∶胡桃属土而有火，性热。本草云甘平，是无热矣。然又云动风、脱人 \n眉，非热何以伤肺耶？ \n时珍曰∶胡桃仁味甘气热，皮涩肉润。孙真人言其冷滑，误矣。近世医方用治痰气喘嗽 \n、醋心及疠风诸病，而酒家往往醉后嗜之。则食多吐水、吐食、脱眉，及酒同食咯血之说， \n亦未必尽然也。但胡桃性热，能入肾肺，惟虚寒者宜之。而痰火积热者，不宜多食耳。 \n【主治】食之令人肥健、润肌、黑须发。多食利小便、去五痔。捣和胡粉，拔白须发， \n内孔中，则生黑毛。烧存性，和松脂研，敷瘰 疮（《开宝》）。食之令人能食，通润血脉， \n骨肉细腻（诜，方见下）。治损伤、石淋。同破故纸蜜丸服，补下焦（颂）。补气养血，润燥 \n化 \n痰，益命门，利三焦，温肺润肠，治虚寒喘嗽，腰脚重痛，心腹疝痛，血痢肠风，散肿毒， \n发痘疮，制铜毒（时珍）。 \n\\x油胡桃\\x \n【气味】辛，热，有毒。 \n【主治】杀虫攻毒，治痈肿、疠风、疥癣、杨梅、白秃诸疮，润须发（时珍）。 \n【发明】韩 曰∶破故纸属火，能使心包与命门之火相通。胡桃属木，主润血养血。血 \n属阴，阴恶燥，故油以润之。佐破故纸，有木火相生之妙。故古有云∶黄柏无知母，破故纸 \n无胡桃，犹水母之无虾也。 \n时珍曰∶三焦者，元气之别使。命门者，三焦之本原。盖一原一委也。命门指所居之腑 \n而名，为藏精系胞之物。三焦指分治之部而名，为出纳腐熟之司。盖一以体名，一以用名。 \n其体非脂非肉，白膜裹之，在七节之旁，两肾之间。二系着脊，下通二肾，上通心肺，贯属 \n于脑。为生命之原，相火之主，精气之腑。人物皆有之，生人生物，皆由此出。《灵枢·本 \n脏论》已着其浓薄缓急直结之状。而扁鹊《难经》不知原委体用之分，以右肾为命门，谓三 \n焦有名无状。而高阳生伪撰《脉诀》，承其谬说，以误后人。至朱肱《南阳活人书》、陈言 \n因方论》、戴起宗《脉诀刊误》，始着说辟之，而知之者尚鲜。胡桃仁颇类其状，而外皮水 \n汁皆青黑。故能入北方，通命门，利三焦，益气养血，与破故纸同为补下焦肾命之药。夫命 \n门气与肾通，藏精血而恶燥。若肾、命不燥，精气内充，则饮食自健，肌肤光泽，肠腑润而 \n血脉通。此胡桃佐补药，有令人肥健能食，润肌黑发固精，治燥调血之功也。命门既通则三 \n焦利，故上通于肺而虚寒喘嗽者宜之，下通于肾而腰脚虚痛者宜之。内而心腹诸痛可止，外 \n而疮肿之毒可散矣。洪氏《夷坚志》只言胡桃治痰嗽能敛肺，盖不知其为命门三焦之药也。 \n油胡桃有毒，伤人咽肺，而疮科取之，用其毒也。胡桃制铜，此又物理之不可晓者。洪迈云 \n∶迈有痰疾，因晚对，上遣使谕令以胡桃肉三颗，生姜三片，卧时嚼服，即饮汤两、三呷， \n又再嚼桃、姜如前数，即静卧，必愈。迈还玉堂，如旨服之，及旦而痰消嗽止。又溧阳洪辑 \n幼子，病痰喘，凡五昼夜不乳食。医以危告。其妻夜梦观音授方，令服人参胡桃汤。辑急取 \n新罗人参寸许，胡桃肉一枚，煎汤一蚬壳许，灌之，喘即定。明日以汤剥去胡桃皮用之，喘 \n复作。仍连皮用，信宿而瘳。此方不载书册，盖人参定喘，胡桃连皮能敛肺故也。 \n【附方】旧五，新二十七。 \n服胡桃法∶诜曰∶凡服胡桃不得并食，须渐渐食之。初日服一颗，每五日加一颗，至二 \n十 \n青娥丸∶方见草部补骨脂。 \n胡桃丸∶益血补髓，强筋壮骨，延年明目，悦心润肌，能除百病。用胡桃仁四两，捣膏， \n入破故纸、杜仲、萆 末各四两。杵匀，丸梧桐子大。每空心温酒、盐汤任下五十丸。（《 \n御药院方》） \n消肾溢精∶胡桃丸∶治消肾病，因房欲无节及服丹石，或失志伤肾，遂致水弱火强，口 \n舌 \n附子一枚（去皮，切片）。姜汁、蛤粉同焙为末，蜜丸梧桐子大。每服三十丸，米饮下。（《 \n普济方》） \n小便频数∶胡桃煨熟，卧时嚼之，温酒下。 \n石淋痛楚，便中有石子者∶胡桃肉一升，细米煮浆粥一升，相和顿服，即瘥。（崔元亮 \n《 \n风寒无汗，发热头痛∶核桃肉、葱白、细茶、生姜等分。捣烂，水一钟，煎七分，热服。 \n覆衣取汗。（谈野翁方） \n痰喘咳嗽∶方见发明。 \n老人喘嗽气促，睡卧不得，服此立定∶胡桃肉（去皮）、杏仁（去皮尖）、生姜各一两。 \n研 \n产后气喘∶胡桃肉、人参各二钱。水一盏，煎七分，顿服。 \n久嗽不止∶核桃仁五十个（煮熟，去皮），人参五两，杏仁三百五十个（麸炒，汤浸， \n去皮） \n食物醋心∶胡桃烂嚼，以生姜汤下，立止。（《传信适用方》） \n食酸齿 ∶细嚼胡桃即解。（《日华子本草》） \n误吞铜钱∶多食胡桃，自化出也。胡桃与铜钱共食，即成粉，可证矣。（李楼方） \n揩齿乌须∶胡桃仁（烧过）、贝母各等分。为散，日用之。（《圣惠》） \n眼目暗昏∶四月内取风落小胡桃，每日午时食饱，以无根水吞下，偃卧，觉鼻孔中有泥 \n腥 \n赤痢不止∶胡桃仁、枳壳各七个，皂角（不蛀者）一挺。新瓦上烧存性，研为细末，分 \n作八 \n血崩不止∶胡桃肉十五枚。灯上烧存性，研作一服，空心温酒调下，神效。 \n急心气痛∶核桃一个，枣子一枚。去核夹桃，纸裹煨熟，以生姜汤一钟，细嚼送下。永 \n久 \n小肠气痛∶胡桃一枚，烧炭研末，热酒服之。（《奇效良方》） \n便毒初起∶子和《儒门事亲》∶用胡桃七个。烧研酒服，不过三服，见效。杨氏《经验》 \n∶用胡桃三枚，夹铜钱一个，食之即愈。 \n鱼口毒疮∶端午日午时，取树上青胡桃，筐内阴干，临时全烧为末，黄酒服。少行一、 \n二 \n一切痈肿，背痈、附骨疽，未成脓者∶胡桃十个（煨熟去壳），槐花一两。研末，杵匀， \n热 \n疔疮恶肿∶胡桃一个。平破，取仁嚼烂，安壳内，合在疮上，频换，甚效。（《普济》） \n痘疮倒陷∶胡桃肉一枚（烧存性），干胭脂半钱。研匀，胡荽煎，酒调服。（《儒门事亲》） \n小儿头疮久不愈∶胡桃和皮，灯上烧存性，碗盖出火毒，入轻粉少许，生油调涂，一、 \n二次愈。（《保幼大全》） \n酒 鼻赤∶方见橘核。 \n耳出汁∶胡桃仁烧研，狗胆汁和作挺子，绵裹塞之。（《普济方》） \n伤耳成疮∶出汁者。用胡桃杵取油纳入。（同上） \n火烧成疮∶胡桃仁烧黑，研敷。（《梅师方》） \n压扑伤损∶胡桃仁捣，和温酒顿服，便瘥。（《图经本草》） \n疥疮瘙痒∶油核桃一个，雄黄一钱，艾叶（杵熟）一钱。捣匀绵包，夜卧裹阴囊，立效。 \n勿 \n\\x胡桃青皮\\x \n【气味】苦，涩，无毒。 \n【主治】染髭及帛，皆黑。 \n志曰∶仙方取青皮压油，和詹糖香，涂毛发，色如漆也。 \n【附方】新五。 \n乌髭发∶胡桃皮、蝌蚪等分。捣泥涂之，一染即黑。《总录》∶用青胡桃三枚，和皮捣细 \n，入乳汁三盏，于银石器内调匀，搽须发三、五次，每日用胡桃油润之，良。 \n疡风∶青胡桃皮捣泥，入酱清少许、 砂少许合匀。先以泔洗，后敷之。（《外台》） \n白癜风∶青胡桃皮一个，硫黄一皂子大，研匀。日日掺之，取效。 \n嵌甲∶胡桃皮，烧灰贴。 \n\\x树皮\\x \n【主治】止水痢。春月斫皮汁，沐头至黑。煎水，可染褐（《开宝》）。 \n【附方】新一。 \n染须发∶胡桃根皮一秤，莲子草十斤。切，以瓮盛之，入水五斗，浸一月去滓，熬至五 \n升，入芸苔子油一斗，慢火煎取五升收之。凡用，先以炭灰汁洗，用油涂之，外以牛蒡叶包 \n住 \n\\x壳\\x \n【主治】烧存性，入下血、崩中药（时珍）。 \n\n\n\n<目录>果部第三十卷\\果之二\n\n<篇名>榛\n\n内容：（宋《开宝》） \n【释名】KT （古榛字）。 \n时珍曰∶案∶罗氏《尔雅翼》云∶《礼记》郑玄注云∶关中甚多此果。关中，秦地也。 \n榛之从秦，盖取此意。《左传》云∶女贽不过榛、栗、枣、 ，以告虔也。则榛有臻至之义 \n，以其名告己之虔也。古作KT ，从辛，从木。俗作莘，误矣。莘，音诜。 \n【集解】志曰∶榛生辽东山谷。树高丈许。子如小栗，军行食之当粮。中土亦有。郑玄 \n云∶关中 、坊甚多。 \n颂曰∶桂阳有KT 而丛生，实大如杏子中仁，皮子形色与栗无异，但小耳。 \n大明曰∶新罗榛子肥白，最良。 \n时珍曰∶榛树低小如荆，丛生。冬末开花如栎花，成条下垂，长二、三寸。二月生叶如 \n初生樱桃，叶多皱纹而有细齿及尖。其实作苞，三、五相粘，一苞一实。实如栎实，下壮上 \n锐，生青熟褐，其壳浓而坚，其仁白而圆，大如杏仁，亦有皮尖，然多空者，故谚云十榛九 \n空。按∶陆机《诗疏》云∶榛有两种∶一种大小、枝叶、皮树皆如栗，而子小，形如橡子， \n味亦如栗，枝茎可以为烛，《诗》所谓树之榛栗者也；一种高丈余，枝叶如木蓼，子作胡桃 \n味，辽、代、上党甚多 \n\\x仁\\x \n【气味】甘，平，无毒。 \n【主治】益气力，实肠胃，令人不饥、健行（《开宝》）。止饥，调中开胃，甚验（大明） \n\n\n\n<目录>果部第三十卷\\果之二\n\n<篇名>阿月浑子\n\n内容：（《拾遗》） \n【校正】自木部移入此，并入《海药》无名木皮。 \n【释名】胡榛子（《拾遗》）、无名子（《海药》）。 \n【集解】藏器曰∶阿月浑子生西国诸番，与胡榛子同树，一岁胡榛子，二岁阿月浑子也 \n曰∶按∶徐表《南州记》云∶无名木生岭南山谷，其实状若榛子，号无名子，波斯家 \n呼为阿月浑子也。 \n\\x仁\\x \n【气味】辛，温，涩，无毒。 \n【主治】诸痢，去冷气，令人肥健（藏器）。治腰冷，阴肾虚弱，房中术多用之，得木 \n香、山茱萸良（李 ）。 \n\\x无名木皮\\x（《海药》） \n【气味】辛，大温，无毒。 \n【主治】阴肾萎弱，囊下湿痒，并煎汁小浴，极妙（ ）。 \n\n\n\n<目录>果部第三十卷\\果之二\n\n<篇名>槠子\n\n内容：（《拾遗》） \n【校正】原附钩栗，今析出。 \n【集解】藏器曰∶槠子生江南。皮、树如栗，冬月不凋，子小于橡子。 \n颖曰∶槠子有苦、甜二种，治作粉食、糕食，褐色甚佳。 \n时珍曰∶槠子，处处山谷有之。其木大者数抱，高二、三丈。叶长大如栗，叶稍尖而浓 \n坚光泽，锯齿峭利，凌冬不凋。三、四月开白花成穗，如栗花。结实大如槲子，外有小苞， \n霜后苞裂子坠。子圆褐而有尖，大如菩提子。内仁如杏仁，生食苦涩，煮、炒乃带甘，亦可 \n磨粉。甜槠子粒小，木纹细白，俗名面槠。苦槠子粒大，木纹粗赤，俗名血槠。其色黑者名 \n铁槠。按∶《山海经》云∶前山有木，其名曰槠。郭璞注曰∶槠子似柞子，可食，冬月采之。 \n木作屋柱、棺材，难腐也。 \n\\x仁\\x \n【气味】苦、涩，平，无毒。 \n时珍曰∶案∶《正要》云∶酸、甘，微寒。不可多食。 \n【主治】食之不饥，令人健行，止泄痢，破恶血，止渴（藏器）。 \n\\x皮、叶\\x \n【主治】煮汁饮，止产妇血（藏器）。嫩叶∶贴 疮，一日三换，良（吴瑞）。 \n\n\n\n<目录>果部第三十卷\\果之二\n\n<篇名>钩栗\n\n内容：（《拾遗》） \n【释名】巢钩子（《拾遗》）、甜槠子。 \n瑞曰∶钩栗即甜槠子。 \n时珍曰∶钩、槠二字，方音相近。其状如栎，当作钩栎。 \n【集解】藏器曰∶钩栗生江南山谷。木大数围，冬月不凋，其子似栗而圆小。又有雀子 \n，相似而圆黑，久食不饥。详槠子下。 \n\\x仁\\x \n【气味】甘，平，无毒。 \n【主治】食之不饥，浓肠胃，令人肥健（藏器）。 \n\n\n\n<目录>果部第三十卷\\果之二\n\n<篇名>橡实\n\n内容：（音象。《唐本草》） \n【校正】自木部移入。 \n【释名】橡斗（《说文》）、皂斗（同）、栎 （音历求）、柞子（音作）、 （杼同。序、 \n暑 \n禹锡曰∶案∶《尔雅》云∶栩，杼也。又曰∶栎，其实 。孙炎注云∶栩，一名杼也。 \n栎，似樗之木也。 ，盛实之房也。其实名橡，有 自裹之。《诗·唐风》云∶集于苞栩 \n。《秦风》云∶山有苞栎。陆机注云∶即柞栎也。秦人谓之栎，徐人谓之杼，或谓之栩。其 \n子谓之皂，亦曰皂斗。其壳煮汁可染皂也。今京洛、河内亦谓之杼。盖五方通语，皆一物也。 \n时珍曰∶栎，柞木也。实名橡斗、皂斗，谓其斗 剜象斗，可以染皂也。南人呼皂如柞 \n，音相近也。 \n【集解】颂曰∶橡实，栎木子也。所在山谷皆有。木高二、三丈。三、四月开花黄色， \n八、九月结实。其实为皂斗，槲、栎皆有斗，而以栎为胜。 \n宗 曰∶栎叶如栗叶，所在有之。木坚而不堪充材，亦木之性也。为炭则他木皆不及。 \n其壳虽可染皂，若曾经雨水者，其色淡。槲亦有壳，但小而不及栎也。 \n时珍曰∶栎有二种∶一种不结实者，其名曰 ，其木心赤，《诗》云“瑟彼柞 ”是也； \n一种结实者，其名曰栩，其实为橡。二者树小则耸枝，大则偃蹇。其叶如槠叶，而纹理皆斜 \n勾。四、五月开花如栗花，黄色。结实如荔枝核而有尖。其蒂有斗，包其半截。其仁如老莲 \n肉，山人俭岁采以为饭，或捣浸取粉食，丰年可以肥猪。北人亦种之。其木高二、三丈，坚 \n实而重，有斑纹点点。大者可作柱栋，小者可为薪炭。《周礼·职方氏》“山林宜皂物，柞、 \n栗之属”即此也。其嫩叶可煎饮代茶。 \n\\x实\\x \n【修治】雷曰∶霜后收采，去壳蒸之，从巳至未，锉作五片，晒干用。 \n周定王曰∶取子换水，浸十五次，淘去涩味，蒸极熟食之，可以济饥。 \n【气味】苦，微温，无毒。 \n【主治】下痢，浓肠胃，肥健人（苏恭）。涩肠止泻。煮食，止饥，御歉岁（大明）。 \n【发明】思邈曰∶橡子，非果非谷而最益人，服食未能断谷，啖之尤佳。无气而受气， \n无味而受味，消食止痢，令人强健不极。 \n时珍曰∶木实为果，橡盖果也。俭岁，人皆取以御饥。昔挚虞入南山，饥甚，拾橡实而 \n食；唐杜甫客秦州，采橡、栗自给，是矣。 \n【附方】新五。 \n水谷下痢，日夜百余行者∶橡实二两，楮叶（炙）一两。为末。每服一钱，食前乌梅汤 \n调下 \n血痢不止∶上方加缩砂仁半两。 \n下痢脱肛∶橡斗子，烧存性。研末。猪脂和敷。（《直指方》） \n痔疮出血∶橡子粉、糯米粉各一升。炒黄，滚水调作果子，饭上蒸熟食之，不过四、五 \n次，效。（李楼《奇方》）石痈坚硬如石，不作脓∶用橡子一枚，以醋于青石上磨汁涂之。干 \n则易，不过十度即平 \n\\x斗壳\\x \n【修治】大明曰∶入药并宜捣细，炒焦或烧存性，研用。 \n【气味】涩，温，无毒。 \n【主治】为散及煮汁服，止下痢。并可染皂（恭）。止肠风、崩中、带下、冷热泻痢。 \n并 \n【附方】新五。 \n下痢脱肛∶橡斗壳烧存性，研末。猪脂和搽，并煎汁洗之。（《直指方》） \n肠风下血∶橡斗子壳，用白梅肉填满，两个合定，铁线札住， 存性，研末。每服二钱， \n米饮下。一方∶用硫黄填满， 研酒服。（余居士《选奇方》） \n走马牙疳∶橡斗壳，入盐填满，合定烧透，出火毒，研末，入麝香少许。先以米泔漱过， \n搽之。（《全幼心鉴》） \n风虫牙痛∶橡斗五个（入盐在内），皂荚一条（入盐在内）。同 过，研末。日擦三、五 \n次， \n\\x木皮、根皮（《拾遗》）\\x \n【气味】苦，平，无毒。 \n【主治】恶疮，因风犯露致肿者，煎汁日洗，令脓血尽乃止，亦治痢（藏器）。止水痢， \n消瘰 （大明）。 \n【附方】新一。 \n蚀烂痈肿及疣赘瘤痣∶柞栎木灰四斗，桑柴灰四斗，锻石一斗五升。以沸汤调湿，甑中 \n蒸一日，取釜中沸汤七斗，合甑灰淋之取汁，再熬至一升，投乱头发一鸡子大消尽，又剪五 \n色彩投入消尽，瓶盛密收。每以少许，挑破点之。煎时勿令鸡、犬、妇人、小儿见。（《普 \n济方》） \n\n\n\n<目录>果部第三十卷\\果之二\n\n<篇名>槲实\n\n内容：（音斛。《唐本草》） \n【校正】自木部移附此。 \n【释名】槲 （音速），朴 （并《尔雅》）、大叶栎（俗）、栎 子。 \n时珍曰∶槲 ，犹觳觫也。栗子绽悬，有颤栗之象，故谓之栗；槲叶摇动，有觳觫之态 \n，故曰槲 也。朴 者，婆娑、蓬然之貌。其树偃蹇，其叶 故也。俗称衣物不整者为朴 \n，本此。其实木强，故俗谓之栎 子。《史》言∶武后挂赦书于槲树，人遂呼为金鸡 \n树云。 \n【集解】颂曰∶槲，处处山林有之。木高丈余，与栎相类。亦有斗，但小不中用耳。不 \n拘时采。其皮、叶入药。 \n宗 曰∶槲亦有斗，木虽坚而不堪充材，只宜作柴，为炭不及栎木。 \n时珍曰∶槲有二种∶一种丛生小者名 （音孚，见《尔雅》）。一种高者名大叶栎。树、 \n叶俱似栗，长大粗浓，冬月凋落，三、四月开花亦如栗，八、九月结实似橡子而稍短小，其 \n蒂亦有斗。其实僵涩味恶，荒岁人亦食之。其木理粗不及橡木，所谓樗栎之材者指此。 \n\\x仁\\x \n【气味】苦，涩，平，无毒。 \n【主治】蒸煮作粉，涩肠止痢，功同橡子（时珍）。 \n\\x槲若\\x \n【修治】颂曰∶若即叶之名也。入药须微炙令焦。 \n【气味】甘、苦，平，无毒。 \n【主治】疗痔，止血及血痢，止渴（恭）。活血，利小便，除面上 赤（时珍）。 \n【附方】旧五，新三。 \n猝然吐血∶槲叶为末。每服二钱，水一盏，煎七分，和滓服。（《简要济众》） \n鼻衄不止∶槲叶。捣汁一小盏，顿服即止。（《圣惠方》） \n肠风血痔热多者尤佳∶槲叶（微炙，研末）一钱，槐花（炒，研末）一钱。米饮调服。 \n未止 \n冷淋茎痛∶槲叶，研末。每服三钱，水一盏，葱白七寸，煎六分，去滓，食前温服，日 \n二 \n孩子淋疾∶槲叶三片。煎汤服一鸡子壳，小便即时下也。（孙真人方） \n蝼蛄漏疾∶槲叶，烧存性，研。以米泔别浸槲叶，取汁洗疮后，乃纳灰少许于疮中。（《 \n圣惠方》）。 \n鼻上 出脓血者∶以泔水煮槲叶，取汁洗之，拭干，纳槲叶灰少许于中，良。（《圣 \n惠》） \n腋下胡臭∶槲若三升。切，水煮浓汁，洗毕，即以甘苦瓠壳烟熏之。后用辛夷、细辛、 \n杜 \n\\x木皮\\x（俗名赤龙皮） \n【气味】苦，涩，无毒。 \n【主治】煎服，除蛊及漏，甚效（恭）。煎汤，洗恶疮，良（权）。能吐瘰 ，涩五脏（大 \n明）。止赤白痢，肠风下血（时珍）。 \n【附方】旧四，新六。 \n赤龙皮汤∶治诸败烂疮、乳疮。用槲皮（切）三升。水一斗，煮五升，春夏冷用，秋冬 \n温用 \n附骨疽疮∶槲皮烧研，米饮每服方寸匕。（《千金方》） \n下部生疮∶槲皮、榉皮煮汁，熬如饴糖，以导下部。（《肘后方》） \n一切 疾∶《千金》∶用槲树北阴白皮三十斤（锉）。以水一石，煮一斗，去滓，煎如饴； \n又取通都厕上雄鼠屎、雌鼠屎各十四枚，烧汁尽研和之，纳温酒一升和匀。瘦人食五合，当 \n有虫出也。崔氏《纂要》∶用槲白皮（切）五升。水八升，煮令泣泣，去滓，再煎成膏。日 \n服 \n小儿瘰 ∶槲树皮，去粗皮，切，煎汤频洗之。（《圣惠方》） \n蛊毒下血∶槲木北阴白皮一大握（长五寸）。以水三升，煮取一升，空腹分服，即吐毒 \n出也。《千金及翼》 \n赤白久痢∶不拘大人、小儿。用新槲皮一斤。去黑皮切，以水一斗，煎取五升，去滓， \n煎 \n久痢不止∶槲白皮（姜汁炙五度）一两，干姜（炮）半两。为末。每服二钱，米饮调下。 \n（《 \n久疮不已∶槲木皮一尺，阔六寸，切，以水一斗，煮取五升，入白沙糖十挺，煎取一升， \n分三服，即吐而愈。（《肘后方》） \n\n\n\n<目录>果部第三十一卷\n\n<篇名>果之三\n\n内容：（夷果类三十一种） \n\n\n\n<目录>果部第三十一卷\\果之三\n\n<篇名>荔枝\n\n内容：（宋《开宝》） \n【释名】离枝（《纲目》）、丹荔。 \n颂曰∶按∶朱应《扶南记》云∶此木结实时，枝弱而蒂牢，不可摘取，必以刀斧 \n取其枝，故以为名。 （音利）与 同。 \n时珍曰∶司马相如《上林赋》作离支。按∶白居易云∶若离本枝，一日色变，三日味变 \n。则离支之名，又或取此义也。 \n【集解】颂曰∶荔枝生岭南及巴中。今闽之泉、福、漳州、兴化军，蜀之嘉、蜀、渝、 \n涪州，及二广州郡皆有之。其品以闽中为第一，蜀川次之，岭南为下。其木高二、三丈，自 \n径尺至于合抱，类桂木、冬青之属。绿叶蓬蓬然，四时荣茂不凋。其木性至坚劲，土人取其 \n根，作阮咸槽及弹棋局。其花青白，状若冠之蕤绥。其子喜双实，状如初生松球。壳有皱纹 \n如罗，初青渐红。肉色淡白如肪玉，味甘而多汁。夏至将中，则子翕然俱赤，乃可食也。大 \n树下子至百斛，五、六月盛熟时，彼方皆燕会其下以赏之，极量取啖，虽多亦不伤人，稍过 \n则饮蜜浆便解。荔枝始传于汉世，初惟出岭南，后出蜀中。故左思《蜀都赋》云∶旁挺龙目 \n，侧生荔枝。唐白居易《图序》论之详矣。今闽中四郡所出特奇，蔡襄《谱》其种类至三十 \n余品，肌肉甚浓，甘香莹白，非广、蜀之比也。福唐岁贡白曝荔枝、蜜煎荔枝肉，俱为上方 \n珍果。白曝须嘉实乃堪，其市货者，多用杂色荔枝入盐、梅曝成，皮色深红，味亦少酸，殊 \n失本真。经曝则可经岁，商贩流布，遍及华夏，味犹不歇，百果之盛，皆不及此。又有焦核 \n荔枝，核如鸡舌香，味更甜美。或云是木生背阳，结实不完就者。又有绿色、蜡色，皆其品 \n之奇者，本土亦自难得。其蜀、岭荔枝，初生小酢，肉薄核大，不堪白曝。花及根亦入药。 \n藏器曰∶顾微《广州记》云∶荔枝冬夏常青，其实大如鸡卵，壳朱肉白，核黄黑色，似 \n半熟莲子，精者核如鸡舌香，甘美多汁，极益人也。 \n时珍曰∶荔枝炎方之果，性最畏寒，易种而根浮。其木甚耐久，有经数百年犹结实者 \n。其实生时肉白，干时肉红。日晒火烘，卤浸蜜煎，皆可致远。成朵晒干者谓之荔锦。按∶ \n白居易《荔枝图序》云∶荔枝生巴、峡间。树形团团如帷盖，叶如冬青。花如橘而春荣，实 \n如丹而夏熟。朵如蒲桃，核如枇杷。壳如红缯，膜如紫绡。瓤肉洁白如冰雪，浆液甘酸如醴 \n酪。大略如彼，其实过之。若离本枝，一日而色变，二日而香变，三日而味变，四、五日外 \n，色香味尽去矣。又蔡襄《荔枝谱》云∶广、蜀所出，早熟而肉薄，味甘酸，不及闽中下等 \n者。闽中惟四郡有之，福州最多，兴化最奇，泉、漳次之。福州延亘原野，一家甚至万株。 \n兴化上品，大径寸余，香气清远，色紫壳薄，瓤浓膜红，核如丁香母。剥之如水精，食之如 \n绛雪。荔枝以甘为味，虽百千树莫有同者，过甘与淡，皆失于中。若夫浓皮尖刺，肌理黄色 \n，附核而赤，食之有渣，食已而涩，虽无酢味，亦自下等矣。最忌麝香触之，花、实尽落也 \n。又洪迈《夷坚志》云∶莆田荔枝，名品，皆出天成，虽以其核种之，亦失本体，形状百出 \n，不可以理求也。沈括《笔谈》谓焦核荔枝，乃土人去其大根，燔焦种成者，大不然也。 \n曰∶荔枝树似青木香。熟时人未采，则百虫不敢近。人才采之，乌鸟、蝙蝠之类，无 \n不伤残之也。故采荔枝者，必日中而众采之。一日色变，二日味变，三日色味俱变。故古诗 \n云∶色味不逾三日变也。 \n\\x实\\x \n【气味】甘，平，无毒。 \n曰∶甘、酸，热。多食令人发虚热。 \n李鹏飞曰∶生荔枝多食，发热烦渴，口干衄血。 \n颂曰∶多食不伤人。如稍过度，饮蜜浆一杯便解也。 \n时珍曰∶荔枝气味纯阳，其性畏热。鲜者食多，即龈肿口痛，或衄血也。病齿 及火病 \n人尤忌之。《开宝本草》言其性平，苏氏谓多食无伤，皆谬说也。按∶《物类相感志》云∶ \n食荔枝多则醉，以壳浸水饮之即解。此即食物不消，还以本物消之之意。 \n【主治】止渴，益人颜色（《开宝》）。食之止烦渴，头重心躁，背膊劳闷（李 ）。通神 \n，益智，健气（孟诜）。治瘰 瘤赘，赤肿疔肿，发小儿痘疮（时珍）。 \n【发明】震亨曰∶荔枝属阳，主散无形质之滞气，故消瘤赘赤肿者用之。苟不明此，虽 \n用之无应。 \n【附方】新六。 \n痘疮不发∶荔枝肉，浸酒饮，并食之。忌生冷。（闻人规《痘疹论》） \n疔疮恶肿∶《普济方》∶用荔枝五个或三个，不用双数，以狗粪中米淘净为末，与糯米粥 \n同研成膏，摊纸上贴之。留一孔出毒瓦斯。 \n《济生秘览》∶用荔枝肉、白梅各三个。捣作饼子。贴于疮上，根即出也。 \n风牙疼痛∶《普济》∶用荔枝连壳（烧存性），研末，擦牙即止。乃治诸药不效仙方也。 \n孙氏 \n呃逆不止∶荔枝七个，连皮核烧存性，为末。白汤调下，立止。（杨拱《医方摘要》） \n\\x核\\x \n【气味】甘，温，涩，无毒。 \n【主治】心痛、小肠气痛，以一枚煨存性，研末，新酒调服（宗 ）。治 疝气痛，妇 \n人 \n【发明】时珍曰∶荔枝核入厥阴，行散滞气，其实双结而核肖睾丸，故其治 疝卵肿， \n有述类象形之义。 \n【附方】新六。 \n脾痛不止∶荔枝核为末，醋服二钱。数服即愈。（《卫生易简方》） \n妇人血气刺痛∶用荔枝核（烧存性）半两，香附子（炒）一两，为末。每服二钱，盐汤 \n、米饮任下。名蠲痛散。（《妇人良方》） \n疝气 肿∶孙氏∶用荔枝核（炒黑色）、大茴香（炒）等分，为末。每服一钱，温酒下。 \n《皆 \n打面糊 \n阴肾肿痛∶荔枝核，烧研，酒服二钱。 \n肾肿如斗∶荔枝核、青橘皮、茴香等分，各炒研。酒服二钱，日三。 \n\\x壳\\x \n【主治】痘疮出不爽快，煎汤饮之。又解荔枝热，浸水饮（时珍）。 \n【附方】新一。 \n赤白痢∶荔枝壳、橡斗壳（炒）、石榴皮（炒）、甘草（炙）各等分。每以半两，水一盏 \n半，煎七分，温服，日二服。（《普济方》） \n\\x花及皮根\\x \n【主治】喉痹肿痛，用水煮汁，细细含咽，取瘥止（苏颂。出崔元亮《海上方》）。 \n\n\n\n<目录>果部第三十一卷\\果之三\n\n<篇名>龙眼\n\n内容：（《本经》中品） \n【校正】自木部移入此。 \n宗 曰∶龙眼专为果，未见入药。本草编入木部，非矣。 \n【释名】龙目（《吴普》）、圆眼（俗名）、益智（《本经》）、亚荔枝（《开宝》）、荔枝奴、 \n骊珠、燕卵、蜜脾、鲛泪、 \n时珍曰∶龙眼、龙目，象形也。《吴普本草》谓之龙目，又曰比目。曹宪《博雅》谓之 \n益智。 \n弘景曰∶广州有龙眼，非益智也，恐彼人别名耳。 \n志曰∶甘味归脾，能益人智，故名益智，非今之益智子也。 \n颂曰∶荔枝才过，龙眼即熟，故南人目为荔枝奴。又名木弹。晒干寄远，北人以为佳果 \n，目为亚荔枝。 \n【集解】《别录》曰∶龙眼生南海山谷。一名益智。其大者似槟榔。 \n恭曰∶龙眼树似荔枝，叶若林檎，花白色。子如槟榔，有鳞甲，大如雀卵。 \n颂曰∶今闽、广、蜀道出荔枝处皆有之。嵇含《南方草木状》云∶木高一、二丈，似荔 \n枝而枝叶微小，凌冬不凋。春末夏初，开细白花。七月实熟，壳青黄色，纹作鳞甲，形圆， \n大如弹丸，核若木 子而不坚，肉薄于荔枝，白而有浆，其甘如蜜。实极繁，每枝三、二十 \n颗，作穗如蒲桃。汉时南海常贡之，大为民害。临武长唐羌上书言状，和帝感其言，下诏止 \n之。 \n时珍曰∶龙眼正圆，《别录》、苏恭比之槟榔，殊不类也。其木性畏寒，白露后方可采 \n摘，晒焙令干，成朵干者名龙眼锦。按范成大《桂海志》有山龙眼，出广中，色青，肉如 \n龙眼，夏月实熟可啖，此亦龙眼之野生者欤？ \n\\x实\\x \n【气味】甘，平，无毒。恭曰∶甘、酸，温。李鹏飞曰∶生者沸汤瀹过食，不动脾 \n【主治】五脏邪气，安志厌食。除蛊毒，去三虫。久服强魂聪明，轻身不老，通神明（ \n《本经》）。开胃益脾，补虚长智（时珍）。 \n【发明】时珍曰∶食品以荔枝为贵，而资益则龙眼为良。盖荔枝性热，而龙眼性和平也 \n。严用和《济生方》，治思虑劳伤心脾有归脾汤，取甘味归脾、能益人智之义。 \n【附方】新一。 \n归脾汤∶治思虑过度，劳伤心脾，健忘怔忡，虚烦不眠，自汗惊悸。用龙眼肉、酸枣仁 \n（炒）、黄 （炙）、白术（焙）、茯神各一两，木香、人参各半两，炙甘草二钱半， 咀。 \n每服 \n\\x核\\x \n【主治】胡臭。六枚，同胡椒二、七枚研，遇汗出即擦之（时珍）。 \n\n\n\n<目录>果部第三十一卷\\果之三\n\n<篇名>龙荔\n\n内容：（《纲目》） \n【释名】见下。 \n【集解】时珍曰∶按范成大《桂海志》云∶龙荔出岭南。状如小荔枝，而肉味如龙眼 \n，其木之身、叶亦似二果，故名曰龙荔。三月开小白花，与荔枝同时熟，不可生啖，但可蒸 \n食。 \n\\x实\\x \n【主治】甘，热，有小毒。生食令人发痫，或见鬼物（时珍出《桂海志》）。 \n\n\n\n<目录>果部第三十一卷\\果之三\n\n<篇名>橄榄\n\n内容：（宋《开宝》） \n【释名】青果（《梅圣俞集》）、忠果（《记事珠》）、谏果（出《农书》）。 \n时珍曰∶橄榄名义未详。此果虽熟，其色亦青，故俗呼青果。其有色黄者不堪，病物 \n也。王祯云∶其味苦涩，久之方回甘味。王元之作诗，比之忠言逆耳，世乱乃思之，故人名 \n为谏果。 \n【集解】志曰∶橄榄生岭南。树似木 子树而高，端直可爱。结子形如生诃子，无棱 \n瓣，八月、九月采之。又有一种波斯橄榄，生邕州。色类相似，但核作两瓣，蜜渍食之。 \n诜曰∶其树大数围。实长寸许，先生者向下，后生者渐高。熟时生食味酢，蜜渍极甜。 \n曰∶按《南州异物志》云∶闽、广诸郡及缘海浦屿间皆有之。树高丈余，叶似榉柳 \n。二月开花，八月成实，状如长枣，两头尖，青色。核亦两头尖而有棱，核内有三窍，窍中 \n有仁，可食。 \n颂曰∶按∶刘恂《岭表录异》云∶橄榄树枝皆高耸。其子深秋方熟，南人重之，生咀 \n嚼之，味虽苦涩，而芬香胜于含鸡舌香也。有野生者，子繁而树峻，不可梯缘，但刻根下方 \n寸许，纳盐入内，一夕子皆自落，木亦无损。其枝节间有脂膏如桃胶，南人采取和皮、叶煎 \n汁，熬如黑饧，谓之榄糖，用泥船隙，牢如胶漆，着水益干也。 \n时珍曰∶橄榄树高，将熟时以木钉钉之，或纳盐少许于皮内，其实一夕自落，亦物理之 \n妙也。其子生食甚佳，蜜渍、盐藏皆可致远。其木脂状如黑胶者，土人采取， 之清烈，谓 \n之榄香。杂以牛皮胶者，即不佳矣。又有绿榄，色绿。乌榄，色青黑，肉烂而甘。取肉捶碎 \n干放，自有霜如白盐，谓之榄酱。青榄核内仁干小。惟乌榄仁最肥大，有文层叠如海螵蛸状 \n而味甘美，谓之榄仁。又有一种方榄，出广西两江峒中，似橄榄而有三角或四角，即是波斯 \n橄榄之类也。 \n\\x实\\x \n【气味】酸、甘，温，无毒。 \n宗 曰∶味涩，良久乃甘。 \n震亨曰∶味涩而甘，醉饱宜之。然性热，多食能致上壅。 \n时珍曰∶橄榄盐过则不苦涩，同栗子食甚香。按《延寿书》云∶凡食橄榄必去两头， \n其性热也。过白露摘食，庶不病 。 \n【主治】生食、煮饮，并消酒毒，解 鲐鱼毒（《开宝》）。嚼汁咽之，治鱼鲠（宗 ）。 \n生啖、煮汁，能解诸毒（苏颂）。开胃下气，止泻（大明）。生津液，止烦渴，治咽喉痛。咀 \n嚼 \n【发明】志曰∶ 鲐鱼，即河豚也。人误食其肝及子，必迷闷至死，惟橄榄及木煮汁能 \n解之。其木作舟楫，拨着鱼皆浮出，故知物有相畏如此者。 \n时珍曰∶按《名医录》云∶吴江一富人，食鳜鱼被鲠，横在胸中，不上不下，痛声动 \n邻里，半月余几死。忽遇渔人张九，令取橄榄与食。时无此果，以核研末，急流水调服，骨 \n遂下而愈。张九云∶我父老相传，橄榄木作取鱼棹篦，鱼触着即浮出，所以知鱼畏橄榄也。 \n今人煮河豚、团鱼，皆用橄榄，乃知橄榄能治一切鱼、鳖之毒也。 \n【附方】新四。 \n初生胎毒∶小儿落地时，用橄榄一个（烧研），朱砂末五分和匀，嚼生脂麻一口，吐唾 \n和 \n药，绢包如枣核大，安儿口中，待咂一个时顷，方可与乳。此药取下肠胃秽毒，令儿少疾， \n及出痘稀少也。（孙氏《集效方》） \n唇裂生疮∶橄榄炒研，猪脂和涂之。 \n牙齿风疳脓血有虫∶用橄榄烧研，入麝香少许，贴之。（《圣惠方》） \n下部疳疮∶橄榄烧存性，研末，油调敷之。或加孩儿茶等分。（《乾坤生意》） \n\\x榄仁\\x \n【气味】甘，平，无毒。 \n【主治】唇吻燥痛，研烂敷之（《开宝》）。 \n\\x核\\x \n【气味】甘，涩，温，无毒。 \n【主治】磨汁服，治诸鱼骨鲠，及食 成积，又治小儿痘疮倒 。烧研服之，治下 \n血（时珍）。 \n【附方】新三。 \n肠风下血∶橄榄核，灯上烧存性，研末。每服二钱，陈米饮调下。（《仁斋直指方》） \n阴肾 肿∶橄榄核、荔枝核、山楂核等分，（烧存性，）研末。每服二钱，空心茴香汤调 \n下。 \n耳足冻疮∶橄榄核烧研，油调涂之。（《乾坤生意》） \n\n\n\n<目录>果部第三十一卷\\果之三\n\n<篇名>木威子\n\n内容：（《拾遗》） \n【释名】未详。 \n【集解】藏器曰∶木威生岭南山谷。树高丈余，叶似楝叶。子如橄榄而坚，亦似枣，削 \n去皮可为粽食。 \n时珍曰∶木威子，橄榄之类也。陈氏说出顾微《广州记》中。而梁元帝《金楼子》云∶ \n橄榄树之南向者为橄榄，东向者为木威。此亦传闻谬说也。 \n\\x实\\x \n【气味】酸、辛，无毒。时珍曰∶按《广州记》云∶苦，涩。 \n【主治】心中恶水，水气（藏器）。 \n\n\n\n<目录>果部第三十一卷\\果之三\n\n<篇名>庵摩勒\n\n内容：（《唐本》） \n【校正】自木部移入此。 \n【释名】余甘子（《唐本》）、庵摩落迦果。 \n藏器曰∶《梵书》名庵摩勒，又名摩勒落迦果。其味初食苦涩，良久更甘，故曰余甘。 \n【集解】恭曰∶庵摩勒生岭南交、广、爱等州。树叶细似合昏。其花黄。实似李、柰， \n青黄色，核圆有棱，或六或七，其中仁亦入药用。 \n曰∶生西国者，大小如枳橘子状。 \n颂曰∶余甘子，今二广诸郡及西川、戎、泸、蛮界山谷皆有之。木高一、二丈，枝条甚 \n软。叶青细密，朝开暮敛如夜合，而叶微小，春生冬凋。三月有花，着条而生，如粟粒，微 \n黄。随即结实作莛，每条三、两子，至冬而熟，如李子状，青白色，连核作五、六瓣，干即 \n并核皆裂，俗作果子啖之。 \n时珍曰∶余甘，泉州山中亦有之。状如川楝子，味类橄榄，亦可蜜渍、盐藏。其木可制 \n器物。按陈祈畅《异物志》云∶余甘树叶如夜合及槐叶，其枝如柘，其花黄。其子圆，大 \n如弹丸，色微黄，有纹理如定陶瓜，核有五、六棱，初入口苦涩，良久饮水更甘，盐而蒸之 \n尤美。其说与两苏所言相合。而《临海异物志》云∶余甘子如梭形，大如梅子，其核两头锐 \n，与橄榄一物异名也。然橄榄形长尖，余甘形圆，稍有不同，叶形亦异，盖二物也。又苏恭 \n言其仁可入药，而未见主治何病，岂亦与果同功耶？ \n\\x实\\x \n【气味】甘，寒，无毒。 曰∶苦、酸、甘，微寒，涩。 \n【主治】风虚热气（《唐本》）。补益强气。合铁粉一斤用，变白不老。取子压汁，和油 \n涂头，生发去风痒，令发生如漆黑也（藏器）。主丹石伤肺，上气咳嗽。久服，轻身延年长 \n生。服乳石人，宜常食之（李 ）。为末点汤服，解金石毒（宗 ）。解硫黄毒（时珍。出《益 \n部 \n【发明】宗 曰∶黄金得余甘则体柔，亦物类相感相伏也，故能解金石之毒云。 \n\\x仁\\x \n\n\n\n<目录>果部第三十一卷\\果之三\n\n<篇名>毗梨勒\n\n内容：（《唐本草》） \n【校正】自木部移入此。 \n【释名】三果。 \n曰∶木似诃梨勒，而子亦相似，但圆而毗，故以名之。毗，即脐也。 \n【集解】恭曰∶毗梨勒出西域及南海诸国，岭南交、爱等州，戎人谓之三果。树似胡 \n桃，子形亦似胡桃。核似诃梨勒，而圆短无棱，用亦同法。番人以此作浆甚热。 \n\\x实\\x \n【气味】苦，寒，无毒。 \n曰∶味苦带涩，微温无毒。作浆性热。 \n【主治】风虚热气，功同庵摩勒（《唐本》）。暖肠腹，去一切冷气。作浆染须发，变黑 \n色（甄权）。下气，止泻痢。（大明）烧灰，干血有效（李 ）。 \n【发明】时珍曰∶毗梨勒古方罕用，惟《千金方》补肾鹿角丸用三果浆吞之，云无则以 \n酒代之。则此果亦余甘之类，而性稍温涩也。 \n【附方】新一。 \n大风发脱∶毗梨勒烧灰，频擦有效。（《圣惠方》） \n\\x没离梨\\x（《拾遗》） \n【集解】藏器曰∶没离梨生西南诸国。似毗梨勒，上有毛少许也。 \n\\x实\\x \n【气味】辛，平，无毒。 曰∶微温。 \n【主治】上气，下食（藏器）。主消食涩肠下气，及上气咳嗽。并宜入面药（李 ）。 \n\n\n\n<目录>果部第三十一卷\\果之三\n\n<篇名>五敛子\n\n内容：（《纲目》） \n【释名】五棱子（《桂海志》）、阳桃。 \n【时珍曰】按∶稽含《草木状》云∶南人呼棱为敛，故以为名。 \n【集解】时珍曰∶五敛子出岭南及闽中，闽人呼为阳桃。其大如拳，其色青黄润绿，形 \n甚诡异，状如田家碌碡，上有五棱如刻起，作剑脊形。皮肉脆软，其味初酸久甘，其核如柰 \n。五月熟，一树可得数石，十月再熟。以蜜渍之，甘酢而美，俗亦晒干以充果食。又有三廉 \n子，盖亦此类也。陈祈畅《异物志》云∶三廉出熙安诸郡。南人呼棱为廉，虽名三廉，或有 \n五、六棱者。食之多汁，味甘且酸，尤宜与众果参食。 \n\\x实\\x \n【气味】酸、甘、涩，平，无毒。 \n【主治】风热，生津止渴（时珍）。 \n\n\n\n<目录>果部第三十一卷\\果之三\n\n<篇名>五子实\n\n内容：（《纲目》） \n【集解】时珍曰∶五子树今潮州有之。按裴渊《广州记》云∶五子实，大如梨而内 \n有五核，故名。 \n\\x实\\x \n【气味】甘，温，无毒。 \n【主治】霍乱金疮，宜食之（时珍。《潮州志》）。 \n\n\n\n<目录>果部第三十一卷\\果之三\n\n<篇名>榧实\n\n内容：（《别录》下品） \n【校正】时珍曰∶《别录》木部有榧实，又有 华。《神农本草》鱼虫部有 子，宋《 \n开宝本草》退 子入有名未用。今据苏恭之说，合并于下。 \n【释名】 子（音彼。《神农》）、赤果（《日用》）、玉榧（《日用》）、玉山果。 \n时珍曰∶榧亦作 ，其木名文木，斐然章采，故谓之榧。信州玉山县者为佳。故苏东坡 \n诗云∶彼美玉山果，粲为金盘实。 子见下。 \n瑞曰∶土人呼为赤果，亦曰玉榧。 \n【集解】《别录》曰∶榧实生永昌。彼子生永昌山谷。 \n弘景曰∶彼子亦名罴子，从来无用者，古今诸医不复识之。榧实出东阳诸郡。 \n恭曰∶彼子当从木作 子，误入虫部也。《尔雅》 亦名 。其叶似杉，木如柏而微软 \n。子名榧子，宜入果部。又注榧实云∶即虫部彼子也。其木大连抱，高数仞，其叶似杉，其 \n木如柏，其理似松，肌细软，堪为器用。 \n宗 曰∶榧实大如橄榄，壳色紫褐而脆，其中子有一重黑粗衣，其仁黄白色，嚼久渐甘 \n美也。 \n藏器曰∶ 华即榧子之华也。 与榧同。榧树似杉，子如 \n虫部有彼子，陶氏复于木部出 \n榧实、 华，皆一物也。 \n颖曰∶榧有一种粗榧。其木与榧相似，但理粗色赤耳。其子稍肥大，仅圆不尖。《神农 \n本草》 子即粗榧也。 \n时珍曰∶榧生深山中，人呼为野杉。按∶罗愿《尔雅翼》云∶ 似杉而异于杉。彼有美 \n实而木有文采，其木似桐而叶似杉，绝难长。木有牝牡，牡者华而牝者实。冬月开黄圆花， \n结实大小如枣。其核长如橄榄核，有尖者、不尖者，无棱而壳薄，黄白色。其仁可生啖，亦 \n可焙收。以小而心实者为佳，一树不下数十斛。陶氏不识 子，惟苏恭能辨为一物也。 \n\\x榧实\\x（《别录》） \n【气味】甘，平，涩，无毒。 \n瑞曰∶性热，同鹅肉食，生断节风，又上壅人，忌火气。 \n时珍曰∶按∶《物类相感志》云∶榧煮素羹，味更甜美。猪脂炒榧，黑皮自脱。榧子同 \n甘蔗食，其渣自软。又云∶榧子皮反绿豆，能杀人也。 \n【主治】常食，治五痔，去三虫蛊毒，鬼疰恶毒（《别录》）。食之，疗寸白虫（弘景）。 \n消谷，助筋骨，行营卫，明目轻身，令人能食。多食一、二升，亦不发病（孟诜）。多食滑 \n肠，五痔人宜之（宗 ）。治咳嗽白浊，助阳道 \n\\x 子\\x（《本经》。旧作彼） \n【气味】甘，温，有 \n【主治】腹中邪气，去三虫，蛇螫蛊毒，鬼疰伏尸（《本经》）。 \n【发明】震亨曰∶榧子，肺家果也。火炒食之，香酥甘美。但多食则引火入肺，大肠受 \n伤尔。 \n原曰∶榧子杀腹间大小虫，小儿黄瘦有虫积者宜食之。苏东坡诗云∶驱除三彭虫，已 \n我心腹疾，是矣。 \n时珍曰∶榧实、 子治疗相同，当为一物无疑。但《本经》 子有毒，似有不同，亦因 \n其能杀虫蛊尔。汪颖以粗榧为 子，终是一类，不甚相远也。 \n【附方】旧一，新五。 \n寸白虫∶诜曰∶日食榧子七颗，满七日，虫皆化为水也。《外台秘要》∶用榧子一百枚， \n去皮火燃，啖之，经 \n好食茶叶面黄者∶每日食榧子七 \n令发不落∶榧子三个，胡桃二个，侧柏叶一两，捣浸雪水梳头，发永不落且润也。（《圣 \n惠方》） \n猝吐血出∶先食蒸饼两、三个，以榧子为末，白汤服三钱，日三服。（《圣济总录》） \n尸咽痛痒、语言不出∶榧实半两，芜荑一两，杏仁、桂各半两，为末，蜜丸弹子大，含咽。 \n（《圣济总 \n\\x 华\\x（《别录》） \n春月生采之。 \n藏器曰∶即榧子华也。 \n【气味】苦。 \n【主治】水气，去赤虫，令人好色，不可久服（《别录》）。 \n\n\n\n<目录>果部第三十一卷\\果之三\n\n<篇名>海松子\n\n内容：（宋《开宝》） \n【释名】新罗松子。 \n【集解】志曰∶海松子，状如小栗，三角。其中仁香美。东夷当果食之，亦代麻腐食之， \n与中国松子不同 \n炳曰∶五粒松一丛五叶如钗，道家服食绝粒，子如巴豆，新罗往往进之。 \n颂曰∶五粒字当作五鬣，音传讹也。五鬣为一丛，或有两鬣、七鬣者。松岁久则实繁。 \n中原虽有，小而不及塞上者佳好也。 \n瑞曰∶松子有南松、北松。华阴松形小壳薄，有斑极香；新罗者肉甚香美。 \n时珍曰∶海松子出辽东及云南，其树与中国松树同，惟五叶一丛者，球内结子，大如 \n巴豆而有三棱，一头尖尔，久收亦油。马志谓似小栗，殊失本体。中国松子大如柏子，亦可 \n入药，不堪果食，详见木部松下。按段成式《酉阳杂俎》云∶予种五鬣松二株，根大如碗， \n结实与新罗、南诏者无别。其三鬣者，俗呼孔雀松。亦有七鬣者。或云∶三针者为栝子松， \n五针者为松子松。 \n\\x仁\\x \n【气味】甘，小温，无毒。 \n曰∶新罗松子甘美大温，去皮食之甚香，与云南松子不同（云南松子似巴豆，其味不 \n及），与卑占国偏桃仁相似。多食发热毒。 \n时珍曰∶按∶《医说》云∶食胡羊肉不可食松子；而《物类相感志》云∶凡杂色羊肉入 \n松子则无毒。其说不同，何哉？ \n【主治】骨节风，头眩，去死肌，变白，散水气，润五脏，不饥（《开宝》）。逐风痹寒 \n气，虚羸少气，补不足，润皮肤，肥五脏（《大明》）。主诸风，温肠胃。久服，轻身延年不 \n老（李 \n【发明】时珍曰∶服食家用松子皆海松子。曰∶中国松子，肌细力薄，只可入药耳。按∶ \n《列仙传》云∶ 好食松实，体毛数寸，走及奔马。又犊子少在黑山食松子、茯苓，寿数 \n百岁。又赤松子好食松实、天门冬、石脂，齿落更生，发落更出，莫知所终。皆指此松子也。 \n【附方】旧一，新三。 \n服松子法∶七月取松实（过时即落难收也），去木皮，捣如膏收之。每服鸡子大，酒调 \n下， \n日三服。百日身轻，三百日行五百里，绝谷，久服神仙。渴即饮水。亦可以炼过松脂同服之。 \n（《圣惠方》） \n肺燥咳嗽∶苏游凤髓汤∶用松子仁一两，胡桃仁二两，研膏，和熟蜜半两收之。每服 \n二钱，食后沸汤点服。（《外台秘要》） \n小儿寒嗽或作壅喘∶用松子仁五个，百部（炒）、麻黄各三分，杏仁四十个（去皮尖， \n以少水略煮三、五沸，化白砂糖丸芡子大。每食后含化十丸，大妙。（钱乙《小儿方》） \n大便虚秘∶松子仁、柏子仁、麻子仁等分，研泥，溶白蜡和，丸梧桐子大。每服五十丸， \n黄汤下。（寇宗 ） \n\n\n\n<目录>果部第三十一卷\\果之三\n\n<篇名>槟榔\n\n内容：（《别录》中品） \n【校正】自木部移入此。 \n【释名】宾门（李当之《药对》）、仁频 \n时珍曰∶宾与郎皆贵客之称。稽含《南方草木状》言∶交广人凡贵胜族客，必先呈此果。 \n若邂逅不设，用相嫌恨。则槟榔名义，盖取于此。雷 《炮炙论》谓尖者为槟，圆者为榔， \n亦似强说。又颜师古注《上林赋》云∶仁频即槟榔也。 \n诜曰∶闽中呼为橄榄子。 \n【集解】《别录》曰∶槟榔生南海。 \n弘景曰∶此有三、四种∶出交州者，形小味甘。广州以南者，形大味涩；又有大者名猪 \n槟榔。皆可作药。小者名 子，俗呼为槟榔孙，亦可食。 \n恭曰∶生交州、爱州及昆仑。 \n颂曰∶今岭外州郡皆有之。木大如桄榔，而高五、七丈，正直无枝，皮似青桐，节似桂 \n枝。叶生木颠，大如盾头，又似芭蕉叶。其实作房，从叶中出，旁有刺若棘针，重叠其下。 \n一房数百实，如鸡子状，皆有皮壳。其实春生，至夏乃熟，肉满壳中，色正白。苏恭言其肉 \n极易烂，不经数日。今入北者，皆先以灰煮熟，焙熏令干，始可留久也。小而味甘者，名山 \n槟榔。大而味涩核亦大者，名猪槟榔；最小者名 子。雷氏言尖长而有紫纹者名槟，圆大而 \n矮者名榔，榔力大而槟力小。今医家亦不细分，但以作鸡心状、正稳心不虚、破之作锦纹者 \n为佳尔。岭南人啖之以当果食，言南方地湿，不食此无以祛瘴疠也。生食其味苦涩，得扶留 \n藤与瓦屋子灰同咀嚼之，则柔滑甘美也。刘恂《岭表录异》云∶真槟榔来自舶上，今交广生 \n者皆大腹子也，彼中悉呼为槟榔。或云∶槟榔难得真者，今贾人所货者，皆是大腹槟榔也， \n与槟榔相似，但茎、叶、干小异尔，连皮收之。 \n时珍曰∶槟榔树初生若笋竿积硬，引茎直上。茎干颇似桄榔、椰子而有节，旁无枝柯， \n条从心生。端顶有叶如甘蕉，条派开破，风至则如羽扇扫天之状。三月叶中肿起一房，因自 \n拆裂，出穗凡数百颗，大如桃李。又生刺重累于下，以护卫其实。五月成熟，剥去其皮，煮 \n其肉而干之。皮皆筋丝，与大腹皮同也。按∶汉喻益期与韩康伯笺云∶槟榔，子既非常，木 \n亦特异。大者三围，高者九丈。叶聚树端，房构叶下。华秀房中，子结房外。其擢穗似禾， \n其缀实似谷。其皮似桐而浓，其节似竹而概。其内空，其外劲。其屈如伏虹，其申如缒绳； \n本不大，末不小；上不倾，下不斜。调直亭亭，千百如一。步其林则寥朗，庇其阴则萧条。 \n信可长吟远想。但性不耐霜，不得北植。必当遐树海南，辽然万里。弗遇长者之目，令人恨 \n深也。又《竺法真罗山疏》云∶山槟榔一名 子，生日南，树似 榈而小，与槟榔同状。一 \n丛十余干，一干十余房，一房数百子。子长寸余，五月采之，味近苦甘。观此，则山槟榔即 \n子，猪槟榔即大腹子也。苏颂以味甘者为山槟榔，涩者为猪槟榔，似欠分明。 \n\\x槟榔子\\x \n【修治】 曰∶头圆矮毗者为榔，形尖紫纹者为槟。槟力小，榔力大。凡使用白槟及存 \n坐稳正、心坚有锦纹者为妙。半白半黑并心虚者，不入药用。以刀刮去底，细切之。勿令经 \n火，恐无力。若熟使，不如不用。 \n时珍曰∶近时方药亦有以火煨焙用者。然初生白槟榔，须本境可得。若他处者，必经煮 \n熏，安得生者耶？又槟榔生食，必以扶留藤、古贲灰为使，相合嚼之，吐去红水一口，乃滑 \n美不涩，下气消食。此三物相去甚远，为物各异，而相成相合如此，亦为异矣。俗谓“槟榔 \n为命赖扶留”以此。古贲灰即蛎蚌灰也。贲乃蚌字之讹。瓦屋子灰亦可用。 \n【气味】苦、辛，温，涩，无毒。甄权曰∶味甘，大寒。 \n大明曰∶味涩。 \n弘景曰∶交州者味甘，广州者味涩。 \n曰∶白者味甘，赤者味苦。 \n元素曰∶味辛而苦，纯阳也。无毒。 \n诜曰∶多食亦发热。 \n【主治】消谷逐水，除痰 ，杀三虫，伏尸，疗寸白（《别录》）。 \n治腹胀，生捣末服，利水谷道；敷疮，生肌肉止痛；烧灰，敷口吻白疮（苏 \n宣利五脏六腑壅滞，破胸中气，下水肿，治心痛积聚（甄权）。 \n除一切风，下一切气，通关节，利九窍，补五劳七伤，健脾调中，除烦，破症结（大明）。 \n主贲豚膀胱诸气，五膈气，风冷气，香港脚，宿食不消 \n古）。 \n【发明】元素曰∶槟榔味浓气轻，沉而降，阴中阳也。苦以破滞，辛以散邪，泄胸中至 \n高之气，使之下行，性如铁石之沉重，能坠诸药至于下极，故治诸气、后重如神也。 \n时珍曰∶按∶罗大经《鹤林玉露》云∶岭南人以槟榔代茶御瘴，其功有四∶一曰醒能使 \n之醉，盖食之久，则熏然颊赤，若饮酒然，苏东坡所谓“红潮登颊醉槟榔”也；二曰醉能使 \n之醒，盖酒后嚼之，则宽气下痰，余酲顿解，朱晦庵所谓“槟榔收得为祛痰”也。三曰饥能 \n使之 \n饱。四曰饱能使之饥。盖空腹食之，则充然气盛如饱；饱后食之，则饮食快然易消。又且赋 \n性疏通而不泄气，禀味严正而更有余甘，有是德故有是功也。又按∶吴兴章杰《瘴说》云∶ \n岭表之俗，多食槟榔，日至十数。夫瘴疠之作，率因饮食过度，气痞积结，而槟榔最能下气 \n消食去痰，故人狃于近利，而暗于远患也。夫峤南地热，四时出汗，人多黄瘠，食之则脏器 \n疏泄，一旦病瘴，不敢发散攻下，岂尽气候所致，槟榔盖亦为患，殆未思尔。又东阳卢和云∶ \n闽广人常服槟榔，云能祛瘴。有瘴服之可也，无瘴而服之，宁不损正气而有开门延寇之祸乎？ \n南人喜食此果，故备考诸说以见其功过焉。又朱晦庵《槟榔诗》云∶忆昔南游日，初尝面发 \n红。药囊知有用，茗碗讵能同？蠲疾收殊效，修真录异功。三彭如不避，糜烂七非中。亦与 \n其治疾杀虫之功， \n【附方】旧十一，新十五。 \n痰涎为害∶槟榔为末，白汤每服一钱。（《御药院方》） \n呕吐痰水∶白槟榔一颗（煨热），橘皮二钱半（炙）。为末。水一盏，煎半盏，温服。（《千 \n金》） \n醋心吐水∶槟榔四两，橘皮一两，为末。每服方寸匕，空心生蜜汤调下。（《梅师方》） \n伤寒痞满 \n汤下。（《宣明方》）伤寒结胸已经汗、下后者∶槟榔二两，酒二盏，煎一盏，分二服。（庞安 \n时《伤寒论》） \n蛔厥腹痛∶方同上。 \n心脾作痛∶鸡心槟榔、高良姜各一钱半，陈米百粒，同以水煎，服之。（《直指》） \n膀胱诸气∶槟榔二枚，一生一熟，为末。酒煎服之，良。此太医秦鸣鹤方也。（《海药 \n本草》） \n本脏气痛∶鸡心槟榔，以小便磨半个服。或用热酒调末一钱服之。（《斗门方》） \n腰重作痛∶槟榔为末，酒服一钱。（《斗 \n香港脚壅痛∶以沙牛尿一盏，磨槟榔一枚。空心暖服。（《梅师香港脚论》） \n香港脚冲心闷乱不识人∶用白槟榔十二分，为末，分二服，空心，暖小便五合调下，日二 \n服。或入姜汁、温酒同服。（《广利》） \n香港脚胀满非冷非热，或老人、弱人病此∶用槟榔仁为末，以槟榔壳煎汁或茶饮、苏汤或 \n豉汁调服二 \n干霍乱病，心腹胀痛，不吐不利，烦闷欲死∶用槟榔末五钱，童子小便半盏，水一盏， \n煎服。（《圣济总录》） \n大肠湿秘∶肠胃有湿，大便秘塞。大槟榔一枚。麦门冬煎汤磨汁温服。或以蜜汤调末二 \n钱 \n大小便 ∶槟榔为末。蜜汤调服二钱。或以童子小便、葱白，同煎服之，亦良。（《普 \n济方》） \n小便淋痛∶面煨槟榔、赤芍药各半两，为末。每服三钱，入灯心，水煎，空心服，日二 \n服。（《十便良方》） \n血淋作痛∶槟榔一枚。以麦门冬煎汤，细磨浓汁一盏，顿热空心服，日二服。 \n虫痔里急∶槟榔为末，每日空心以白汤调服二钱。 \n寸白虫病∶槟榔二七枚，为末。先以水二升半，煮槟榔皮，取一升，空心，调末方寸匕 \n服之，经日虫尽出。 \n诸虫在脏久不瘥者∶槟榔半两炮，为末。每服一钱至二钱，空心以葱、蜜煎汤调服。（《简 \n要济众》） \n金疮恶心∶白槟榔四两，橘皮一两，为末。每空心生蜜汤服二钱。（《圣惠方》） \n丹从脐起∶槟榔末，醋调敷之。（《本事方》） \n小儿头疮∶水磨槟榔，晒取粉，和生油涂之。（《圣惠方》） \n口吻生疮∶槟榔，烧研，入轻粉末，敷之良。（《圣惠方》） \n耳出脓∶槟榔末吹之。（鲍氏方） \n\n\n\n<目录>果部第三十一卷\\果之三\n\n<篇名>大腹子\n\n内容：（宋《开宝》） \n【校正】自木部移入此。 \n【释名】大腹槟榔（《图经》）、猪槟榔。 \n时珍曰∶大腹以形名，所以别鸡心槟榔也。 \n【集解】志曰∶大腹生南海诸国，所出与槟榔相似，茎、叶、根、干小异耳。 \n弘景曰∶向阳者为槟榔，向阴者为大腹。 \n时珍曰∶大腹子出岭表、滇南，即槟榔中一种腹大形扁而味涩者，不似槟榔尖长味良耳 \n，所谓猪槟榔者是矣。盖亦土产之异，今人不甚分别。陶氏分阴阳之说，亦是臆见。按∶刘 \n恂《岭表录异》云∶交广生者，非舶上槟榔，皆大腹子也，彼中悉呼为槟榔。自嫩及老，采 \n实啖之。以扶留藤、瓦屋灰同食之，以祛瘴疠。收其皮入药，皮外黑色，皮内皆筋丝如椰子 \n皮。又《云南记》云∶大腹槟榔每枝有三、二百颗，青时剖之，以一片蒌叶及蛤粉卷和食之， \n即减涩味。观此二说，则大腹子与槟榔皆可通用，但力比槟榔稍劣耳。 \n\\x大腹子\\x \n【气味】辛，涩，温，无毒。 \n【主治】与槟榔同功（时珍）。 \n\\x大腹皮\\x \n【修治】思邈曰∶鸩鸟多集槟榔树上。凡用槟榔皮，宜先以酒洗，后以大豆汁再洗过， \n晒干入灰火烧煨，切用。 \n【气味】辛，微温，无毒。 \n【主治】冷热气攻心腹、大肠壅毒，痰膈醋心。并以姜、盐同煎，入疏气药用之，良 \n（《开宝》）。下一切气，止霍乱，通大小肠，健脾开胃调中（大明）。降逆气，消肌肤中水气 \n浮肿，香港脚壅逆，瘴疟痞满，胎气恶阻 \n【附方】新二。 \n漏疮恶秽∶大腹皮煎汤洗之。（《直指》） \n乌癞风疮∶大腹子，生者或干者，连全皮勿伤动，以酒一升浸之，慢火熬干为末，腊猪 \n脂和敷。（《圣济总录》） \n\n\n\n<目录>果部第三十一卷\\果之三\n\n<篇名>椰子\n\n内容：（宋《开宝》） \n【校正】自木部移入此。 \n【释名】越王头（《纲目》）、胥余。 \n时珍曰∶按稽含《南方草木状》云∶相传林邑王与越王有怨，使刺客乘其醉，取其首， \n悬于树，化为椰子，其核犹有两眼，故俗谓之越王头，而其浆犹如酒也。此说虽谬，而俗传 \n以为口实。南人称其君长为爷，则椰名盖取于爷义也。相如《上林赋》作胥余，或作胥耶。 \n【集解】志曰∶椰子生安南，树如棕榈，子中有浆，饮之得醉。 \n颂曰∶椰子，岭南州郡皆有之。郭义恭《广志》云∶木似桄榔无枝条，高数丈。叶在木 \n末如束蒲。其实大如瓠，垂于枝间，如挂物然。实外有粗皮，如棕包。皮内有坚壳，圆而微 \n长。壳内有肤，白如猪肪，浓半寸许，味如胡桃。肤内裹浆四、五合如乳，饮之冷而动气醺 \n人。壳可 \n曰∶按∶刘欣期《交州记》云∶椰树状若海棕。实大如碗，外有粗皮，如大腹子、豆 \n寇之类。内有浆似酒，饮之不醉。生云南者亦好。 \n宗 曰∶椰子开之，有汁白色如乳，如酒极香，别是一种气味，强名为酒。中有白瓤 \n，形圆如栝蒌，上起细 ，亦白色而微虚，其纹若妇人裙褶，味亦如汁。与着壳一重白肉， \n皆可糖煎为果。其壳可为酒器，如酒中有毒，则酒沸起或裂破。今人漆其里，即失用椰子之 \n意。 \n时珍曰∶椰子乃果中之大者。其树初栽时，用盐置根下则易发。木至斗大方结实，大者 \n三、四围，高五、六丈，木似桄榔、槟榔之属，通身无枝。其叶在木顶，长四、五尺，直耸 \n指天，状如棕榈，势如凤尾。二月着花成穗，出于叶间，长二、三尺，大如五斗器。仍连着 \n实，一穗数枚，小者如栝蒌，大者如寒瓜，长七、八寸，径四、五寸，悬着树端。六七月熟， \n有粗皮包之。 \n皮内有核，圆而黑润，甚坚硬，浓二三分。壳内有白肉瓤如凝雪，味甘美如牛乳。瓤肉 \n空处，有浆数合，钻蒂倾出，清美如酒。若久者，则混浊不佳矣。其壳磨光，有斑缬点纹， \n横破之可作壶爵，纵破之可作瓢杓也。又《唐史》言∶番人以其花造酒，饮之亦醉也。《类 \n书》有青田 \n【附录】青田核 崔豹《古今注》云∶乌孙国有青田核，状如桃核，不知其树。核大如 \n数斗，剖之盛水，则变酒味，甚醇美。饮尽随即注水，随尽随成。但不可久，久则苦涩尔。 \n谓之青田酒，汉末蜀王刘璋曾得之。 \n\\x树头酒\\x \n《一统志》云∶缅甸在滇南，有树类棕，高五、六丈，结实如椰子。土人以罐盛曲，悬 \n于实下，划其实，汁流于罐中以成酒，名树头酒。或不用曲，惟取汁熬为白糖。其树即贝树 \n也，缅人取其叶写书。 \n\\x严树酒\\x \n《一统志》云∶琼州有严树，捣其皮叶，浸以清水，和以粳酿，或入石榴花叶，数日成 \n酒，能醉人。又《梁书》云∶顿逊国有酒树，似安石榴，取花汁贮杯中，数日成酒。盖此类 \n也。又有文章草，可以成酒。 \n\\x椰子瓤\\x \n【气味】甘，平，无毒。 \n【主治】益气（《开宝》）。治风（汪颖）。食之不饥，令人面泽（时珍。出《异 \n\\x椰子浆\\x \n【气味】甘，温，无毒。 \n曰∶多食，冷而动气。 \n时珍曰∶其性热，故饮之者多昏如醉状。《异物志》云∶食其肉则不饥，饮其浆则增渴 \n【主治】止消渴。涂头，益发令黑（《开宝》）。治吐血水肿 \n【发明】震亨曰∶椰子生海南极热之地，土人赖此解夏月毒渴，天之生物，各因其材也 \n\\x椰子皮\\x \n【修治】颂曰∶不拘时月采其根皮，入药炙用。一云∶其实皮亦可用。 \n【气味】苦，平，无毒。 \n【主治】止血，疗鼻衄，吐逆霍乱，煮汁饮之（《开宝》）。治猝心痛，烧存性，研，以 \n新汲 \n\\x壳\\x \n【主治】杨梅疮筋骨痛。烧存性，临时炒热，以滚酒泡服二、三钱，暖覆取汗，其痛即 \n止，神验（时珍）。 \n\n\n\n<目录>果部第三十一卷\\果之三\n\n<篇名>无漏子\n\n内容：（《拾遗》） \n【释名】千年枣（《开宝》）、万年枣（《一统志》）、海枣（《草木状》）、波斯枣（《拾 \n遗》）、 \n时珍曰∶无漏名义未详。千年、万岁，言其树性耐久也。曰海，曰波斯，曰番，言其种 \n自外国来也。金果，贵之也。曰棕、曰蕉，象其干、叶之形也。番人名其木曰窟莽，名其实 \n曰苦鲁麻枣。苦麻、窟莽，皆番音相近也。 \n【集解】藏器曰∶无漏子即波斯枣，生波斯国，状如枣。 \n曰∶树若栗木。其实若橡子，有三角。 \n颂曰∶按∶刘恂《岭表录异》云∶广州有一种波斯枣，木无旁枝，直耸三四丈，至巅四 \n向，共生十余枝，叶如棕榈，彼土人呼为海棕木。三五年一着子，每朵约三、二十颗，都类 \n北方青枣，但小尔。舶商亦有携本国者至中国，色类沙糖，皮肉软烂，味极甘，似北地天蒸 \n枣，而其核全别，两头不尖，双卷而圆，如小块紫矿，种之不生，盖蒸熟者也。 \n时珍曰∶千年枣虽有枣名，别是一物，南番诸国皆有之，即杜甫所赋海棕也。按段成 \n式《酉阳杂俎》云∶波斯枣生波斯国，彼人呼为窟莽。树长三、四丈，围五、六尺。叶似土 \n藤，不凋。二月生花，状如蕉花。有两甲，渐渐开罅，中有十余房。子长二寸，黄白色，状 \n如楝子，有核。六、七月熟则紫黑，状类干枣，食之味甘如饴也。又陶九成《辍耕录》云∶ \n四川成都有金果树六株，相传汉时物也。高五、六十丈，围三、四寻，挺直如矢，木无枝柯。 \n顶上有叶如棕榈，皮如龙鳞，叶如凤尾，实如枣而大。每岁仲冬，有司具祭收采，令医工以 \n刀剥去青皮，锻石汤瀹过，入冷熟蜜浸换四次，瓶封进献。不如此法，则生涩不可食。番人 \n名为苦鲁麻枣，盖凤尾蕉也。一名万岁枣，泉州有万年枣，即此物也。又稽含《草木状》云∶ \n海枣大如杯碗，以比安期海上如瓜之枣，似未得其详也。巴旦杏亦名忽鹿麻，另是一物也。 \n\\x实\\x \n【气味】甘，温，无毒。 \n【主治】补中益气，除痰嗽，补虚损，好颜色，令人肥健（藏器）。 \n消食止咳，治虚羸，悦人。久服无损（李 ）。 \n\n\n\n<目录>果部第三十一卷\\果之三\n\n<篇名>桄榔子\n\n内容：（宋《开宝》） \n【校正】自木部移入此。 \n【释名】木名姑榔木（《临海异物志》）、面木（《伽蓝记》）、董棕（杨慎《卮言》）、铁木。 \n时珍曰∶其木似槟榔而光利，故名桄榔。姑榔，其音讹也。面，言其粉也，铁言其坚也。 \n【集解】颂曰∶桄榔木，岭南二广州郡皆有之，人家亦植之庭院间。 \n其木似 榈而坚硬，斫其内取面，大者至数石，食之不饥。其皮至柔，坚韧可以作绠。 \n其子作穗生木端，不拘时月采之。按∶刘恂《岭表录异》云∶桄榔木枝叶并蕃茂，与槟榔小 \n异。然叶下有须如粗马尾，广人采之以织巾子；得咸水浸，即粗胀而韧，彼人以缚海舶，不 \n用钉线。木性如竹，紫黑色，有纹理而坚，工人解之，以制博弈局。其树皮中有屑如面，可 \n作饼食。 \n藏器曰∶按∶《临海异物志》云∶姑榔木生 山谷。外皮有毛如棕榈而散生。其木刚 \n利如铁，可作钐锄，中湿更利，惟中焦则易败尔，物之相伏如此。皮中有白粉，似稻米粉及 \n麦面，可作饼饵 \n时珍曰∶桄榔，二广、交、蜀皆有之。按∶郭义恭《广志》云∶木大者四、五围，高五 \n、六丈，拱直无旁枝。巅顶生叶数十，破似棕叶，其木肌坚，斫入数寸，得粉赤黄色，可食。 \n又顾 《海槎录》云∶桄榔木身直如杉，又如棕榈、椰子、槟榔、波斯枣、古散诸树而稍异， \n有节似大竹。树杪挺出数枝，开花成穗，绿色。结子如青珠，每条不下百颗，一树近百余条， \n团团悬挂若伞，极可爱。其木最重，色类花梨而多纹，番舶用代铁枪，锋 甚利。古散亦木 \n名，可为杖，又名虎散。 \n\\x子\\x \n【气味】苦，平，无毒。 \n【主治】破宿血（《开宝》）。 \n\\x面\\x \n【气味】甘，平，无毒。 \n【主治】作饼炙食腴美，令人不饥，补益虚羸损乏，腰脚无力。久服轻身辟谷（李 ）。 \n\n\n\n<目录>果部第三十一卷\\果之三\n\n<篇名>木面\n\n内容：（ 音梭，《海药》） \n【校正】自木部移入此。 \n【释名】 木（音襄）。 \n时珍曰∶ 字韵书不载，惟孙 《唐韵》莎字注云∶树似桄榔。则 字当作莎衣之莎。 \n其叶离披如莎衣之状，故谓之莎也。张勃《吴录·地理志》言，交趾 木，皮中有白粉如米 \n屑，干之捣末，以水淋过似面，可作饼食者，即此木也。后人讹 为莎，音相近尔。杨慎《卮 \n言》乃谓 木即桄榔，误矣。按左思《吴都赋》云∶面有桄榔。又曰∶文、 、桢、 ，既 \n是一物，不应两用矣。 \n【集解】 曰∶按∶《蜀记》 \n云∶ 木生南中八郡。树高十许丈，阔四、五围。峰头生叶，两边行列如飞鸟翼。皮中 \n有白面石许，捣筛作饼，或磨屑作饭食之，彼人呼为 面，轻滑美好，胜于桄榔面也。 \n藏器曰∶ 木生岭南山谷。大者木皮内出面数斛，色黄白。 \n时珍曰∶按∶刘欣期《交州记》云∶都勾树似棕榈，木中出屑如桄榔面，可作饼饵。恐 \n此即 木也。 \n\\x 面\\x \n【气味】甘，平、温，无毒。 \n【主治】补益虚冷，消食（李 ）。 \n温补。久食不饥，长生（藏器）。 \n\n\n\n<目录>果部第三十一卷\\果之三\n\n<篇名>波罗蜜\n\n内容：（《纲目》） \n【释名】曩伽结。 \n时珍曰∶波罗蜜，梵语也。因此果味甘，故借名之。安南人名曩枷结，波斯人名婆那娑， \n拂林人名阿萨 ，皆一物也。 \n【集解】时珍曰∶波罗蜜生交趾、南邦诸国，今岭南、滇南亦有之。 \n树高五、六丈，树类冬青而黑润倍之。叶极光净，冬夏不凋。树至斗大方结实，不花而 \n实，出于枝间，多者十数枚，少者五、六枚，大如冬瓜，外有浓皮裹之，若栗球，上有软刺 \n。五、六月熟时，颗重五、六斤，剥去外皮壳，内肉层叠如橘囊，食之味至甜美如蜜， \n香气满室。一实凡数百核，核大如枣。其中仁如栗黄，煮炒食之甚佳。果中之大者，惟此与 \n椰子而已。 \n\\x瓤\\x \n【气味】甘、香、微酸，平，无毒。 \n【主治】止渴解烦，醒酒益气，令人悦泽（时珍）。 \n\\x核中仁\\x \n【气味】同瓤。 \n【主治】补中益气，令人不饥轻健（时珍）。 \n\n\n\n<目录>果部第三十一卷\\果之三\n\n<篇名>无花果\n\n内容：（《食物》） \n【释名】映日果（《便民图纂》）、优昙钵 \n时珍曰∶无花果凡数种，此乃映日果也。 \n即广中所谓 \n【集解】时珍曰∶无花果出扬州及云南，今吴、楚、闽、越人家， \n枝柯如枇杷树，三月发叶如花构叶。五月内不花而实，实出枝间，状如木馒头，其内虚 \n软。采以盐渍，压实令扁，晒干充果食。熟则紫色，软烂甘味如柿而无核也。按∶《方舆志》 \n云∶广西优昙钵不花而实，状如枇杷。又段成式《酉阳杂俎》云∶阿驵出波斯、拂林人呼为 \n底珍树。长丈余，枝叶繁茂，叶有五丫如蓖麻，无花而实，色赤类 柿，一月而熟，味亦如 \n柿。二书所说，皆即此果也。又有文光果、天仙果、古度 \n【附录】文光果 出景州。形如无花果，肉味如栗，五月成熟。 \n\\x天仙果\\x \n出四川。树高八、九尺，叶似荔枝而小，无花而实，子如樱桃，累累缀枝间，六、七月 \n熟，其味至甘。宋祁《方物赞》云∶有子孙枝，不花而实。薄言采之，味埒蜂蜜。 \n\\x古度子\\x \n出交、广诸州。树叶如栗，不花而实，枝柯间生子，大如石榴及楂子而色赤，味醋，煮 \n以为粽食之。若数日不煮，则化作飞蚁，穿皮飞去也。 \n\\x实\\x \n【气味】甘，平，无毒。 \n【主治】开胃，止泄痢（汪颖）。 \n治五痔，咽喉痛（时珍）。 \n\\x叶\\x \n【气味】甘、微辛，平，有小毒。 \n【主治】五痔肿痛，煎汤频熏洗之，取效（震亨）。 \n\n\n\n<目录>果部第三十一卷\\果之三\n\n<篇名>阿勒勃\n\n内容：（《拾遗》） \n【校正】自木部移入此。 \n【释名】婆罗门皂荚（《拾遗》）、波斯皂荚。 \n时珍曰∶婆罗门，西域国名；波斯，西南国名也。 \n【集解】藏器曰∶阿勒勃生拂林国。状似皂荚而圆长，味甘好 \n时珍曰∶此即波斯皂荚也。按段成式《酉阳杂俎》云∶波斯皂荚，彼人呼为忽野檐， \n拂林人呼为阿梨去伐。树长三、四丈，围四、五尺。叶似枸橼而短小，经寒不凋。不花而 \n实，荚长二尺，中有隔。 \n隔内各有一子，大如指头，赤色至坚硬，中黑如墨，味甘如饴可食，亦入药也。 \n\\x子\\x \n【气味】苦，大寒，无毒。 \n【主治】心膈间热风，心黄，骨蒸寒热，杀三虫（藏器）。 \n炙黄入药，治热病，下痰，通经络，疗小儿疳气（李 ）。 \n【附录】罗望子 时珍曰∶按∶《桂海志》云∶出广西。壳长数寸，如肥皂及刀豆，色 \n正丹，内有二、三子，煨食甘美。 \n\n\n\n<目录>果部第三十一卷\\果之三\n\n<篇名>沙棠果\n\n内容：（《纲目》） \n【集解】时珍曰∶按∶《吕氏春秋》云∶果之美者，沙棠之实。今岭外宁乡、泷水、罗 \n浮山中皆有之。木状如棠，黄花赤实，其味如李而无核。 \n\\x实\\x \n【气味】甘，平，无毒。 \n【主治】食之，却水病（时珍。《山海经》）。 \n\n\n\n<目录>果部第三十一卷\\果之三\n\n<篇名>子\n\n内容：（音蟾。《拾遗》） \n【集解】藏器曰∶ 子似梨，生江南，左思《 \n时珍曰∶ 、留，二果名。按薛莹《荆阳以南异物志》云∶ 子树，南越、丹阳诸郡 \n山中皆有之。其实如梨，冬熟味酢。刘子树生交广、武平、兴古诸郡山中。三月着花，结实 \n如梨，七、八月熟 \n\\x实\\x \n【气味】甘，涩，平，无毒。 \n【主治】生食之，止水痢。熟和蜜食之，去嗽（藏器）。 \n\n\n\n<目录>果部第三十一卷\\果之三\n\n<篇名>麂目\n\n内容：（《拾遗》） \n【校正】自木部移入此。 \n【释名】鬼目。藏器曰∶此出岭南，状如麂目，故名。陶氏注豆蔻引麂目小冷，即此也。 \n后人讹为鬼目。 \n【集解】时珍曰∶鬼目有草木三种∶此乃木生者，其草鬼目别见草部白英下，又羊蹄菜 \n亦名鬼目，并物异名同。按∶刘欣期《交州记》云∶鬼目出交趾、九真、武平、兴古诸处。 \n树高硕似棠梨，叶似楮而皮白，二月生花，仍连着子，大者如木瓜，小者如梅李，而小斜不 \n周正。七、八月熟，色黄味酸，以蜜浸食之佳。 \n【气味】酸、甘，小冷，无毒。多食，发冷痰（藏器）。 \n\n\n\n<目录>果部第三十一卷\\果之三\n\n<篇名>都桷子\n\n内容：（《拾遗》） \n【释名】构子。 \n时珍曰∶桷音角。《太平御览》作桶子（音同上声），盖传写之讹也。亦与楮构之构，名 \n同实异。陈祈畅《异物志赞》云∶构子之树，枝叶四布。名同种异，实味甜酢。果而无核， \n里面如素。析酒止酲，更为遗赂。 \n【解集】 曰∶按徐表《南州记》云∶都桷子生广南山谷。树高丈余，二月开花，连着 \n实，大如鸡卵，七月熟。 \n时珍曰∶按∶魏王《花木志》云∶都桷树出九真、交趾，野生。二、三月开花，赤色。 \n子似木瓜，八、九月熟，俚民取食之，味酢，以盐、酸沤食，或蜜藏皆可。一云状如青梅。 \n\\x实\\x \n【气味】酸、涩，平，无毒。 \n【主治】久食，益气止泄（藏器）。安神温肠，治痔。久服无损（李 ）。解酒，止烦渴 \n（时珍） \n\n\n\n<目录>果部第三十一卷\\果之三\n\n<篇名>都念子\n\n内容：（《拾遗》） \n【释名】倒捻子（详下文）。 \n【集解】藏器曰∶杜宝《拾遗录》云∶都念子生岭南。隋炀帝时 \n高丈余，叶如白杨，枝柯长细。花心金色，花赤如蜀葵而大。子如小枣，蜜渍食之，甘美益 \n人。 \n时珍曰∶按∶刘恂《岭表录异》云∶倒捻子窠丛不大，叶如苦李。花似蜀葵，小而深紫 \n，南中妇女多用染色。子如软柿，外紫内赤，无核，头上有四叶如柿蒂。食之必捻其蒂。故 \n谓之倒捻子，讹而为都念子也。味甚甘软。 \n\\x实\\x \n【气味】甘、酸，小温，无毒。 \n【主治】痰嗽哕气（藏器）。暖腹脏，益肌肉（时珍。《岭表录异》）。 \n\n\n\n<目录>果部第三十一卷\\果之三\n\n<篇名>都咸子\n\n内容：（《拾遗》） \n【校正】自木部移入此。 \n【集解】藏器曰∶都咸子生广南山谷。按∶徐表《南州记》云∶其树如李，子大如指。 \n取子及皮、叶曝干，作饮极香美也。 \n时珍曰∶按∶嵇含《南方草木状》云∶都咸树出日南。三月生花，仍连着实，大如指， \n长三寸，七、八月熟，其色正黑。 \n\\x子及皮、叶\\x \n【气味】甘，平，无毒。 \n【主治】火干作饮，止渴润肺，去烦除痰（藏器）。 \n去伤 \n\n\n\n<目录>果部第三十一卷\\果之三\n\n<篇名>摩厨子\n\n内容：（《拾遗》） \n【集解】藏器曰∶摩厨子生西域及南海并斯调国。子如瓜，可为茹。其汁香美，如中国 \n用油。陈祈畅《异物志赞》云∶木有摩厨，生自斯调。厥汁肥润，其泽如膏。馨香馥郁，可 \n以煎熬。彼州之人，以为嘉肴。 \n曰∶摩厨二月开花，四、五月结实，如瓜状。 \n时珍曰∶又有齐墩果、德庆果，亦其类也。今附于下。 \n【附录】齐墩果 《酉阳杂俎》云∶齐墩树生波斯及拂林国。 \n高二、三丈，皮青白，花似柚极香。子似杨桃，五月熟，西域人压为油以煎饼果，如中 \n国之 \n\\x德庆果\\x \n《一统志》云∶广之德庆州出之。其树冬荣，子大如杯，炙而食之，味如猪肉也。 \n\\x实\\x \n【气味】甘，香，平，无毒。 \n【主治】益气，润五脏。久服令人肥健（藏器）。安神养血生肌，久服轻健（李 ）。 \n\n\n\n<目录>果部第三十一卷\\果之三\n\n<篇名>韶子\n\n内容：（《拾遗》） \n【集解】藏器曰∶韶子生岭南。按∶裴渊《广州记》云∶韶叶如栗， \n子大如栗，有棘刺。破其皮，内有肉如猪肪，着核不离，味甘酢，核如荔枝。 \n时珍曰∶按∶范成大《虞衡志》云∶广南有山韶子，夏熟，色红，肉如荔枝。又有藤韶 \n子，秋熟，大如凫卵柿也。 \n\\x实\\x \n【气味】甘，温，无毒。 \n【主治】暴痢，心腹冷气（藏器）。 \n\n\n\n<目录>果部第三十一卷\\果之三\n\n<篇名>马槟榔\n\n内容：（《会编》） \n【释名】马金囊（《云南志》）、马金南 \n【集解】时珍曰∶马槟榔生滇南金齿、沅江诸夷地，蔓生。结实大如葡萄，紫色味甘。 \n内有核，颇似大风子而壳稍薄，团长斜扁不等。核内有仁，亦甜。 \n\\x实\\x \n【气味】甘，寒，无毒。 \n\\x核仁\\x \n【气味】苦、甘，寒，无毒 \n机曰∶凡嚼之者，以冷水一口送下，其甜如蜜，亦不伤人也。 \n【主治】产难，临时细嚼数枚，井华水送下，须臾立产。再以四枚去壳，两手各握二枚， \n恶水自下也。欲断产者，常嚼二枚，水下。久则子宫冷，自不孕矣（汪机）。伤寒热病，食 \n数枚，冷水下。又治恶疮 \n\n\n\n<目录>果部第三十一卷\\果之三\n\n<篇名>枳\n\n内容：（音止矩。《唐本草》） \n【校正】自木部移入此，并入《拾遗》木蜜。 \n【释名】蜜枳 （音止矩）、蜜屈律（《广记》）、木蜜（《拾遗》）、木饧（同上）、木珊瑚 \n（《广志》）、鸡距子（苏文）、鸡爪子（俗名），木名白石木（《唐注》）、金钩木（《地志》）、 \nKT （音 \n时珍曰∶枳 徐锴注《说文》作枳 ，又作枳枸，皆屈曲不伸之意。此树多枝而曲，其 \n子亦卷曲，故以名之。曰蜜、曰饧，因其味也。曰珊瑚、曰鸡距、曰鸡爪，象其形也。曰交 \n加、曰KT ，言其实之纽屈也。KT ，枋梁之名。按∶《雷公炮炙》序云∶弊箅淡卤， \n如酒沾交。注云∶交加枝，即蜜枳 也。又《诗话》云∶子生枝端，横折歧出，状若KT \n，故土人谓之KT 也。珍谓∶KT 及俗称鸡矩，蜀人之称桔枸、棘枸，滇人之称鸡 \n橘子，巴人之称金钩，广人之称结留子，散见书记者，皆枳 、鸡距之字，方音转异尔。俗 \n又讹鸡爪为曹公爪，或谓之梨枣树，或谓之癞汉指头，崔豹《古今注》一名树蜜，一名木石， \n皆一物也。 \n【集解】恭曰∶枳 子其树径尺，木名白石，叶如桑柘。其子作房似珊瑚，核在其端， \n人皆食之。 \n颂曰∶此《诗·小雅》所谓南山有枸也。陆机《疏义》云∶枳枸树高硕如白杨，所在皆 \n有，枝柯不直。子着枝端，啖之甘美如饴，八、九月熟，江南特美之，谓之木蜜。能败酒味， \n若以其木为 \n诜曰∶昔有南人修舍用此木，误落一片入酒瓮中，酒化为水也。 \n藏器曰∶木蜜树生南方，人呼白石木，枝、叶俱甜。嫩叶可生啖，味如蜜。老枝细破， \n煎汁成蜜，倍甜，止渴解烦也。 \n时珍曰∶枳 木高三、四丈，叶圆大如桑柘，夏月开花。枝头结实，如鸡爪形，长寸许， \n纽曲，开作二、三歧，俨若鸡之足距。嫩时青色，经霜乃黄，嚼之味甘如蜜。每开歧尽处， \n结一、二小子，状如蔓荆子，内有扁核赤色，如酸枣仁形。飞鸟喜巢其上，故宋玉赋云∶枳 \n枸来巢。《曲礼》云∶妇人之贽， 、榛、 \n\\x实\\x \n【气味】甘，平，无毒。 \n诜曰∶多食发蛔虫。 \n【主治】头风，小腹拘急（《唐本》）。止渴除烦，去膈上热，润五脏，利大小便，功用 \n同蜂蜜。枝、叶煎膏亦同（藏器）。止呕逆，解酒毒 \n【发明】震亨曰∶一男子年三十余，因饮酒发热，又兼房劳虚乏。乃服补气血之药，加 \n葛根以解酒毒。微汗出，人反懈怠，热如故。此乃气血虚，不禁葛根之散也。必须鸡距子解 \n其毒，遂煎药中加而服之，乃愈。 \n时珍曰∶枳 ，本草只言木能败酒，而丹溪朱氏治酒病往往用其实，其功当亦同也。按∶ \n《苏东坡集》云∶眉山揭颖臣病消渴，日饮水数斗，饭亦倍常，小便频数。服消渴药逾年， \n疾日甚，自度必死。予令延蜀医张肱诊之。笑曰∶君几误死。乃取麝香当门子以酒濡湿，作 \n十许丸，用棘枸子煎汤吞之，遂愈。问其故。肱曰∶消渴消中皆脾弱肾败、土不制水而成疾。 \n今颖臣脾脉极热而肾气不衰，当由果实、酒物过度，积热在脾，所以食多而饮水。水饮既多， \n溺不得不多，非消非渴也。麝香能制酒果花木，棘枸亦胜酒（屋外有此木，屋内酿酒多不佳）。 \n故以此二物为药，以去其酒果之毒也。棘枸实如鸡距，故俗谓之鸡距，亦曰癞汉指头。食之 \n如牛乳，本草名枳 ，小儿喜食之。吁！古人重格物， \n\\x木汁\\x \n【气味】同枳 。 \n【附方】新一。 \n腋下狐气∶用桔枸树凿孔，取汁一、二碗，用青木香、东桃、西柳、七姓妇人乳，一处 \n煎一、二沸。就热，于五月五日鸡叫时洗了，将水放在十字路口，速回勿顾，即愈。只是他 \n人先遇者，必带去也。桔枸树即 \n\\x木皮\\x \n【气味】甘，温，无毒。 \n【主治】五痔，和五脏（《唐本》）。 \n\n\n\n<目录>果部第三十二卷\n\n<篇名>果之四\n\n内容：（味类一十三种） \n\n\n\n<目录>果部第三十二卷\\果之四\n\n<篇名>秦椒\n\n内容：（《本经》中品） \n【校正】自木部移入此。 \n【释名】大椒（《尔雅》）、 \n【集解】《别录》曰∶秦椒生泰山山谷及秦岭上，或琅琊。八月、 \n弘景曰∶今从西来。形似椒而大，色黄黑，味亦颇有椒气。或云即今 树子。 \n乃猪椒，恐谬。 \n恭曰∶秦椒树、叶及茎、子都似蜀椒，但味短实细尔。蓝田、秦岭间大有之。 \n颂曰∶今秦、凤、明、越、金、商州皆有之。初秋生花，秋末结实，九月、十月采之。 \n《尔雅》云∶ ，大椒。郭璞注云∶椒丛生，实大者为 也。 \n《诗·唐风》云∶椒聊之实，繁衍盈升。陆机《疏义》云∶椒树似茱萸，有针刺。茎叶 \n坚而滑泽，味亦辛香。蜀人作茶，吴人作茗，皆以其叶合煮为香。今成皋诸山有竹叶椒，其 \n木亦如蜀椒，小毒热，不中合药也，可入饮食中及蒸鸡、豚用。东海诸岛上亦有椒，枝、叶 \n皆相似。子长而不圆，甚香，其味似橘皮。岛上獐、鹿食其叶，其肉自然作椒、橘香。今南 \n北所生一种椒，其实大于蜀椒，与陶氏及郭、陆之说正相合，当以实大者为秦椒也。 \n宗 曰∶此秦地所产者，故言秦椒。大率椒株皆相似，但秦椒叶差大，粒亦大而纹低， \n不若蜀椒皱纹高为异也。然秦地亦有蜀椒种。 \n时珍曰∶秦椒，花椒也。始产于秦，今处处可种，最易蕃衍。其叶对生，尖而有刺。四 \n月生细花。 \n五月结实，生青熟红，大于蜀椒，其目亦不及蜀椒目光黑也。《范子计然》云∶蜀椒出 \n武都 \n【修治】同蜀椒。 \n\\x椒红\\x \n【气味】辛，温，有毒。《别录》曰∶生温、熟寒，有毒 \n之才曰∶恶栝蒌、防葵，畏雌黄。 \n【主治】除风邪气，温中，去寒痹，坚齿发，明目。久服，轻身好颜色，耐老增年通神 \n（《本经》）。疗喉痹吐逆疝瘕，去老血，产后余疾腹痛，出汗，利五脏（《别录》）。上气 \n咳嗽，久风湿痹（孟诜）。 \n治恶风遍身，四肢 痹，口齿浮肿摇动，女人月闭不通，产后恶血痢，多年痢，疗腹中 \n冷痛， \n【附方】旧六。 \n膏瘅尿多，其人饮少∶用秦椒一分（出汗），瓜蒂二分，为末。水服方寸匕，日三服。（《伤 \n寒类要》） \n乃风也∶椒、盐末等分，醋和敷之，良。（《肘后方》） \n损疮中风∶以面作馄饨，包秦椒，于灰中烧之令热，断使开口，封于疮上，冷即易之。 \n（孟 \n久患口疮∶大椒，去闭口者，水洗面拌，煮作粥，空腹吞之，以饭压下。重者可再服， \n以瘥为度。（《食疗本草》） \n牙齿风痛∶秦椒煎醋含漱。（孟诜《食疗》） \n百虫入耳∶椒末一钱，醋半盏，浸良久，稍稍滴入，自出。（《续十全方》） \n\n\n\n<目录>果部第三十二卷\\果之四\n\n<篇名>蜀椒\n\n内容：（《本经》下品） \n【校正】自木部移入此。 \n【释名】巴椒（《别录》）、汉椒（《日华》）、 \n（唐毅）、点椒。 \n时珍曰∶蜀，古国名。汉，水名。今川西成都、广汉、潼川诸处是矣。巴亦国名，又水 \n名。今川东重庆、夔州、顺庆、阆中诸处是矣。川则巴蜀之总称，因岷、沱、黑、白四大水， \n分东、西、南、北为四川也。 \n【集解】《别录》曰∶蜀椒生武都山谷及巴郡。八月采实，阴干。 \n弘景曰∶蜀郡北部人家种之。皮肉浓，腹里白，气味浓。江阳、晋康及建平间亦有而 \n细赤，辛而不香，力势不如巴郡者。 \n恭曰∶今出金州西城者最佳。 \n颂曰∶今归陕及蜀川、陕洛间人家，多作园圃种之。木高四、五尺，似茱萸而小，有针 \n刺。叶坚而滑，可煮饮食。四月结子无花，但生于枝叶间，颗如小豆而圆，皮紫赤色，八月 \n采实 \n时珍曰∶蜀椒肉浓皮皱，其子光黑，如人之瞳仁，故谓之椒目。他椒子虽光黑，亦不似 \n之。若土椒，则子无光彩矣。 \n【修治】 曰∶凡使南椒须去目及闭口者，以酒拌湿蒸，从巳至午，放冷密盖，无气后 \n取出，便入瓷器中，勿令伤风也。 \n宗 曰∶凡用秦椒、蜀椒，并微炒使出汗，乘热入竹筒中，以梗捣去里面黄壳，取红用 \n，未尽再捣。或只炒热，隔纸铺地上，以碗覆，待冷碾取红用。 \n\\x椒红\\x \n【气味】辛，温，有毒。 \n《别录》曰∶大热。多食，令人乏气喘促。口闭者杀人。 \n诜曰∶十月食椒，损气伤心，令人多忘。 \n李鹏飞曰∶久食，令人失明，伤血脉。 \n之才曰∶杏仁为之使，得盐味佳，畏款冬花、防风、附子、雄黄。可收水银。中其毒者 \n，凉水、麻仁浆解之。 \n【主治】邪气咳逆，温中，逐骨节皮肤死肌，寒湿痹痛，下气。久服头不白，轻身增年 \n（《本经》）。除六腑寒冷，伤寒温疟大风汗不出，心腹留饮宿食，肠 下痢，泄精，女子 \n字乳余疾，散风邪瘕结，水肿黄胆，鬼疰蛊毒，杀虫、鱼毒。久服开腠理，通血脉，坚齿发， \n明目，调关节，耐寒暑，可作膏药（《别录》）。治头风下泪，腰脚不遂，虚损留结，破血， \n下诸石水，治咳嗽，腹内冷痛，除齿痛（甄权）。破症结开胸，治天行时气，产后宿血，壮 \n阳，疗阴汗，暖腰膝，缩小便，止呕逆（大明）。通神去老，益血，利五脏，下乳汁，灭瘢， \n生毛发（孟诜）。散寒除湿，解郁结，消宿食，通三焦，温脾胃，补右肾命门，杀蛔虫，止 \n泄泻（时珍）。 \n【发明】颂曰∶服食方∶单服椒红补下，宜用蜀椒乃佳。段成式言椒气下达，饵之益下， \n不上冲也 \n时珍曰∶椒纯阳之物，乃手足太阴、右肾命门气分之药。其味辛而麻，其气温以热。 \n禀南方之阳，受西方之阴。故能入肺散寒，治咳嗽；入脾除湿，治风寒湿痹，水肿泻痢；入 \n右肾补火，治阳衰溲数，足弱久痢诸证。一妇年七十余，病泻五年，百药不效。予以感应丸 \n五十丸投之，大便二日不行。再以平胃散加椒红、茴香，枣肉为丸与服，遂瘳。每因怒食举 \n发，服之即止。此除湿消食，温脾补肾之验也。按∶《岁时记》言∶岁旦饮椒柏酒以辟疫疠。 \n椒乃玉衡星精，服之令人体健耐老；柏乃百木之精，为仙药，能伏邪鬼故也。吴猛真人《服 \n椒诀》云∶椒禀五行之气而生，叶青、皮红、花黄、膜白、子黑。其气馨香，其性下行，能 \n使火热下达，不致上薰，芳草之中，功皆不及（其方见下）。时珍窃谓椒红丸虽云补肾，不 \n分 \n水火，未免误人。大抵此方惟脾胃及命门虚寒有湿郁者相宜。若肺胃素热者，大宜远之。故 \n丹溪朱氏云∶椒属火，有下达之能。服之既久，则火自水中生。故世人服椒者，无不被其毒 \n也。又《上清诀》云∶凡人吃饭伤饱，觉气上冲，心胸痞闷者，以水吞生椒一、二十颗即散。 \n取其能通三焦，引正气，下恶气，消宿食也。又戴原礼云∶凡人呕吐，服药不纳者，必有蛔 \n在膈间。蛔闻药则动，动则药出而蛔不出。但于呕吐药中，加炒川椒十粒良，盖蛔见椒则头 \n伏也。观此，则张仲景治蛔厥乌梅丸中用蜀椒，亦此义也。许叔微云∶大凡肾气上逆，须以 \n川椒引之归经则安。 \n【附方】旧十二，新二十三。 \n椒红丸∶治元脏伤惫，目暗耳聋。服此百日，觉身轻少睡，足有力，是其效也。服及三 \n年，心智爽悟，目明倍常，面色红悦，髭发光黑。用蜀椒去目及合口者，炒出汗，曝干，捣 \n取红一斤。以生地黄捣自然汁，入铜器中煎至一升，候稀稠得所，和椒末丸梧桐子大。每空 \n心暖酒下三十丸。合药时勿令妇人、鸡、犬见。诗云∶其椒应五行，其仁通六义。欲知先有 \n功，夜间无梦寐。四时去烦劳，五脏调元气。明目腰不痛，身轻心健记。别更有异能，三年 \n精自秘。回老返婴童，康强不思睡。九虫顿消亡，三尸自逃避。若能久饵之，神仙应可冀。 \n补益心肾∶《仙方》椒苓丸∶补益心肾，明目驻颜，顺气祛风延年。真川椒一斤（炒去 \n汗）， \n白茯苓十两（去皮）。为末，炼蜜丸梧桐子大。每服五十丸，空心盐汤下。忌铁器。（邵真人 \n《经验方》） \n虚冷短气∶川椒三两，去目并合口者，以生绢袋盛，浸无灰酒五升中三日，随性饮之。 \n腹内虚冷∶用生椒择去不拆者，用四十粒，以浆水浸一宿，令合口，空心新汲水吞下。 \n久服暖脏腑，驻颜黑发、明目，令人思饮食。（《斗门方》） \n心腹冷痛∶以布裹椒安痛处，用熨斗熨令椒出汗，即止。（孙真人方） \n冷虫心痛∶川椒四两，炒出汗，酒一碗淋之，服酒。（《寿域神方》） \n阴冷入腹∶有人阴冷，渐渐冷气入阴囊肿满，日夜疼闷欲死。以布裹椒包囊下，热气大 \n通，日再易之，以消为度。（《千金》） \n呃噫不止∶川椒四两，炒研，面糊丸梧桐子大。每服十丸，醋汤下，神效。（邵以正《经 \n验方》） \n传尸劳疰∶最杀劳虫。用真川椒红色者，去子及合口，以黄草纸二重隔之，炒出汗，取 \n放地上，以砂盆盖定，以火灰密遮四旁，约一时许，为细末，去壳，以老酒浸白糕和，丸梧 \n子大。每服四十丸，食前盐汤下。服至二斤，其疾自愈。此药兼治诸痹，用肉桂煎汤下；腰 \n痛，用茴香汤下；肾冷，用盐汤下。昔有一人病此，遇异人授是方，服至二斤，吐出一虫如 \n蛇而安，遂名神授丸。（陈言《三因方》） \n历节风痛∶白虎历节风，痛甚，肉理枯虚，生虫游走痒痛，兼治痹疾，半身不遂。即上 \n治劳疰神授丸方。（《世医得效方》） \n寒湿香港脚∶川椒二、三升，稀布囊盛之，日以踏脚。贵人所用。（ \n诸疮中风∶生蜀椒一升，以少面和溲裹椒，勿令漏气，分作两裹，于 灰火中烧熟，刺 \n头作孔，当疮上罨之，使椒气射入疮中，冷即易之。须臾疮中出水，及遍体出冷汗，即瘥也。 \n（ \n疮肿作痛∶生椒末、釜下土、荞麦粉等分研，醋和敷之。（《外台秘要》） \n囊疮痛痒∶红椒七粒，葱头七个，煮水洗之。一人途中苦此，湘山寺僧授此方，数日愈。 \n名 \n手足皴裂∶椒四合，以水煮之，去渣渍之，半食顷，出令燥，须臾再浸，候干，涂猪羊 \n脑髓，极妙。（《深师方》） \n漆疮作痒∶谭氏方∶用汉椒煎汤洗之。《相感志》云∶凡至漆所，嚼川椒涂鼻上，不生 \n漆疮。 \n夏月湿泻∶川椒（炒取红）、肉豆蔻（煨）各一两，为末，粳米饭丸梧桐子大。每量人 \n米饮服百 \n飧泻不化及久痢∶小椒一两（炒），苍术二两（土炒），碾末，醋糊丸梧桐子大。每米饮 \n服 \n久冷下痢或不痢，腰腹苦冷∶用蜀椒三升。酢渍一宿，曲三升，同椒一升，拌作粥食， \n不过 \n老小泄泻∶小儿水泻、及人年五十以上患泻。用椒二两，醋二升，煮醋尽，慢火焙干， \n碾末 \n水泻奶疳∶椒一分，去目碾末，酥调，稍稍涂脑上，日三度。（姚和仲《延龄方》） \n食茶面黄∶川椒红，炒碾末，糊丸梧桐子大。每服十丸，茶汤下。（《胜金方》） \n伤寒齿衄∶伤寒呕血，继而齿缝出血不止。用开口川椒四十九粒。入醋一盏，同煎熟， \n入白 \n风虫牙痛∶《总录》∶用川椒红末，水和白面丸皂子大，烧热咬之，数度愈。一方∶花椒 \n四钱，牙皂七七个，醋一碗，煎漱之。 \n头上白秃∶花椒末，猪脂调敷，三、五度便愈。（《普济方》） \n妇人秃鬓∶汉椒四两，酒浸，密室内日日搽之，自然长也。（《圣惠方》） \n蝎螫作痛∶川椒嚼细涂之，微麻即止。（《杏林摘要》） \n百虫入耳∶川椒碾细，浸醋灌之，自出。（危氏方） \n毒蛇咬螫∶以闭口椒及叶，捣封之，良。（《肘后方》） \n蛇入人口∶因熟取凉，卧地下，有蛇入口，不得出者。用刀破蛇尾，纳生椒二、三粒， \n裹定，须臾即自退出也。（《圣惠方》） \n小儿暴惊，啼哭绝死∶蜀椒、左顾牡蛎各六铢，以酢浆水一升，煮五合。每灌一合。（《千 \n金方 \n舌謇语吃∶川椒，以生面包丸。每服十粒，醋汤送下。（《救急方》） \n痔漏脱肛∶每日空心嚼川椒一钱，凉水送下，三、五次即收。（同上） \n肾风囊痒∶川椒、杏仁研膏，涂掌心，合阴囊而卧，甚效。（《直指方》 \n\\x椒目\\x \n【气味】苦，寒，无毒。权曰∶苦、辛，有小毒。 \n【主治】水腹胀满，利小便（苏恭）。治十二种水气，及肾虚耳猝鸣聋，膀胱急（甄权）。 \n止气喘（震亨）。 \n【发明】权曰∶椒气下达，故椒目能治肾虚耳鸣。用巴豆、菖蒲同碾细，以松脂、黄蜡 \n溶和为挺，纳耳中抽之。治肾气虚，耳中如风水鸣，或如打钟磬之声，猝暴聋者。一日一易， \n神验。 \n宗 曰∶椒目治盗汗有功。将目微炒碾细，用半钱，以生猪上唇煎汤一合，睡时调服， \n无不效。盖椒目能行水，又治水蛊也。 \n震亨曰∶诸喘不止，用椒目炒碾二钱，白汤调服二、三服以上劫之，后乃随痰、火用药 \n时珍曰∶椒目下达，能行渗道，不行谷道，所以能下水燥湿、定喘消蛊也 \n【附方】新六。 \n水气肿满∶椒目炒，捣如膏，每酒服方寸匕。（《千金方》） \n留饮腹痛∶椒目二两，巴豆一两（去皮心）。熬捣，以枣膏和丸麻子大。每服二丸，吞 \n下其痛即止。又方∶椒目十四枚，巴豆一枚，豉十六枚，合捣为二丸。服之，取吐利。（《肘 \n后方》） \n痔漏肿痛∶椒目一撮，碾细。空心水服三钱，如神。（《海上方》） \n崩中带下∶椒目炒碾细，每温酒服一勺。（《金匮钩玄》） \n眼生黑花∶年久不可治者。椒目（炒）一两，苍术（炒）一两。为末，醋糊丸梧桐子大。 \n每服二十丸，醋汤下。（《本事方》） \n\\x叶\\x \n【气味】辛，热，无毒。 \n【主治】奔豚、伏梁气，及内外肾钓，并霍乱转筋，和艾及葱碾，以醋拌罨之（大明）。 \n杀虫，洗香港脚 \n\\x根\\x \n【气味】辛，热，微毒。 \n【主治】肾与膀胱虚冷，血淋色瘀者，煎汤细饮。色鲜者勿服（时珍。出《证治要诀》）。 \n\n\n\n<目录>果部第三十二卷\\果之四\n\n<篇名>崖椒\n\n内容：（宋《图经》） \n【释名】野椒。 \n【集解】颂曰∶施州一种崖椒，叶大于蜀椒，彼土人四季采皮入药。 \n时珍曰∶此即俗名野椒也。不甚香，而子灰色不黑，无光。野人用炒鸡、鸭食。 \n\\x椒红\\x \n【气味】辛，热，无毒。忌盐。时珍曰∶有毒。 \n【主治】肺气上喘，兼咳嗽。并野姜为末，酒服一钱匕（苏颂） \n\n\n\n<目录>果部第三十二卷\\果之四\n\n<篇名>蔓椒\n\n内容：（《本经》下品） \n【校正】自木部移入此。 \n【释名】猪椒（《别录》）、豕椒（《本经》）、彘椒（《别录》）、 椒（弘景）、狗椒（《别 \n录》）、金椒（《图经》）。 \n时珍曰∶此椒蔓生，气臭如狗、彘，故得诸名。 \n【集解】《别录》曰∶蔓椒生云中川谷及丘冢间。采茎根，煮酿酒。 \n弘景曰∶山野处处有之，俗呼为 子。似椒、 \n时珍曰∶蔓椒野生林箐间，枝软如蔓，子、叶皆似椒，山人亦食之。《尔雅》云∶椒 \n丑，谓其子丛生也。陶氏所谓 子，当作 子，诸椒之通 \n\\x实、根、茎\\x \n【气味】苦，温，无毒。 \n【主治】风寒湿痹，历节疼，除四肢厥气，膝痛，煎汤蒸浴，取汗（《本经》）。根主 \n痔，烧末服，并煮汁浸之（藏器）。 \n贼风挛急（孟诜）。通身水肿，用枝叶煎汁，熬如饧状，每空心服一匙，日三服（时珍。 \n出《千金》）。 \n\n\n\n<目录>果部第三十二卷\\果之四\n\n<篇名>地椒\n\n内容：（宋《嘉 》） \n【校正】自草部移入此。 \n【集解】禹锡曰∶地椒出上党郡。其苗覆地蔓生，茎、叶甚细，花作小朵，色紫白，因 \n旧茎而生。 \n时珍曰∶地椒出北地，即蔓椒之小者。贴地生叶，形小，味微辛。土人以煮羊肉食，香 \n美。 \n\\x实\\x \n【气味】辛，温，有小毒。"}, {"n": 28, "text": "卷二十八\n\n【主治】淋渫肿痛。可作杀蛀虫药（《嘉 》）。 \n【附方】新一。 \n牙痛∶地花椒、川芎 尖等分。为末，擦之。（《海上名方》） \n\n\n\n<目录>果部第三十二卷\\果之四\n\n<篇名>胡椒\n\n内容：（《唐本草》） \n【校正】自木部移入此。 \n【释名】昧履支。 \n时珍曰∶胡椒，因其辛辣似椒，故得椒名，实非椒也。 \n【集解】恭曰∶胡椒生西戎。形如鼠李子，调食用之，味甚辛辣。 \n慎微曰∶按∶段成式《酉阳杂俎》云∶胡椒出摩伽陀国，呼为昧履支。其苗蔓生，茎极 \n柔弱，叶长寸半。有细条与叶齐，条条结子，两两相对。其叶晨开暮合，合则裹其子于叶中。 \n形似汉椒，至辛辣，六月采，今食料用之。 \n时珍曰∶胡椒，今南番诸国及交趾、滇南、海南诸地皆有之。蔓生附树及作棚引之。 \n叶如扁豆、山药辈。正月开黄白花，结椒累累，缠藤而生，状如梧桐子，亦无核，生青熟红， \n青 \n\\x实\\x \n【气味】辛，大温，无毒。 \n时珍曰∶辛热纯阳，走气助火，昏目发疮。 \n曰∶多食损肺，令人吐血。 \n【主治】下气温中去痰，除脏腑中风冷（《唐本》）。 \n去胃口虚冷气，宿食不消，霍乱气逆，心腹猝痛，冷气上冲（李 ）。调五脏，壮肾气， \n治冷痢，杀一切鱼、肉、鳖、蕈毒（大明）。去胃寒吐水，大肠寒滑（宗 ）。暖肠胃，除寒 \n湿，反 \n【发明】宗 曰∶胡椒去胃中寒痰，食已则吐水甚验。大肠寒滑亦可用，须以他药佐之， \n过剂则走气也。 \n震亨曰∶胡椒，属火而性燥，食之快膈，喜之者众，积久则脾胃肺气大伤。凡病气疾人 \n，益大其祸也。牙齿痛必用胡椒、荜茇者，散其中浮热也。 \n时珍曰∶胡椒大辛热，纯阳之物，肠胃寒湿者宜之。热病患食之，动火伤气，阴受其害 \n。时珍自少嗜之，岁岁病目，而不疑及也。后渐知其弊，遂痛绝之，目病亦止。才食一、二 \n粒，即便昏涩。此乃昔人所未试者。盖辛走气，热助火，此物气味俱浓故也。病咽喉口齿者， \n亦宜忌之。 \n近医每以绿豆同用，治病有效。盖豆寒椒热，阴阳配合得宜，且以豆制椒毒也。按∶张 \n从正《儒门事亲》云∶噎膈之病，或因酒得，或因气得，或因胃火。医氏不察，火里烧姜， \n汤中煮桂；丁香未已，豆蔻继之；荜茇未已，胡椒继之。虽曰和胃，胃本不寒；虽曰补胃， \n胃本不虚。况三阳既结，食必上潮，只宜汤丸小小润之可也。时珍窃谓此说虽是，然亦有食 \n入反出、无火之证，又有痰气郁结、得辛热暂开之证，不可执一也。 \n【附方】旧二，新二十二。 \n心腹冷痛∶胡椒三七枚，清酒吞之。或云一岁一粒。（孟诜《食疗》） \n心下大痛∶《寿域方》∶用椒四十九粒，乳香一钱，研匀。男用生姜、女用当归酒下。又 \n方∶用椒五分，没药三钱，研细。分二服，温酒下。又方∶胡椒、绿豆各四十九粒研烂，酒 \n下神效。 \n霍乱吐泻∶孙真人∶用胡椒三十粒，以饮吞之。《直指方》∶用胡椒四十九粒，绿豆一 \n百四十九粒。研匀，木瓜汤服一钱。 \n反胃吐食∶戴原礼方∶用胡椒醋浸，晒干，如此七次，为末，酒糊丸梧桐子大。每服三、 \n四十丸，醋汤下。《圣惠方》∶用胡椒七钱半，煨姜一两，水煎，分二服。《是斋百一方》∶用 \n胡椒、半夏（汤泡）等分，为末， \n夏月冷泻及霍乱∶用胡椒碾末，饭丸梧桐子大。每米饮下四十丸。（《卫生易简方》） \n赤白下痢∶胡椒、绿豆各一岁一粒，为末，糊丸梧桐子大。红用生姜、白用米汤下。（《集 \n简方》） \n大小便闭，关格不通，胀闷二、三日则杀人∶胡椒二十一粒，打碎，水一盏，煎六分， \n去滓，入芒硝半两，煎化服。（《总录》） \n小儿虚胀∶塌气丸∶用胡椒一两，蝎尾半两。为末，面糊丸粟米大。每服五七丸，陈米 \n饮下。一加莱菔子半两。（钱乙方）虚寒积癖在背膜之外，流于两胁，气逆喘急，久则营卫 \n凝 \n滞，溃为痈疽，多致不救∶用胡椒二百五十粒，蝎尾四个，生木香二钱半，为末，粟米饭丸 \n绿豆大。每服二十丸，橘皮汤下。名磨积丸。（《济生方》） \n房劳阴毒∶胡椒七粒，葱心二寸半，麝香一分，捣烂，以黄蜡溶和，做成条子，插入阴 \n内，少顷汗出即愈。（孙氏《集效方》） \n惊风内钓∶胡椒、木鳖子仁等分。为末，醋调黑豆末，和杵，丸绿豆大。每服三、四十 \n丸，荆芥汤下。（《圣惠》） \n发散寒邪∶胡椒、丁香各七粒。碾碎，以葱白捣膏，和涂两手心，合掌握定，夹于大腿 \n内侧，温覆取汗则愈。（《伤寒蕴要》） \n伤寒咳逆，日夜不止，寒气攻胃也∶胡椒三十粒（打碎），麝香半钱，酒一钟，煎半钟， \n热服。（《圣惠方》） \n风虫牙痛∶《卫生易简方》∶用胡椒、荜茇等分，为末，蜡丸麻子大。每用一丸，塞蛀孔 \n中。《韩氏医通》∶治风、虫、客寒，三般牙痛，呻吟不止。用胡椒九粒，绿豆十一粒，布裹 \n捶碎，以丝绵包作一粒，患处咬定，涎出吐去，立愈。《普济方》∶用胡椒一钱半，以羊脂拌 \n打四十丸，擦之追涎。 \n阿伽陀丸∶治妇人血崩。用胡椒、紫檀香、郁金、茜根、小柏皮等分。为末，水丸梧桐 \n子大。每服二十丸，阿胶汤下。时珍曰∶按《酉阳杂俎》∶胡椒出摩伽陀国。此方之名，因 \n此而讹者也。 \n沙石淋痛∶胡椒、朴硝等分。为末。每服用二钱，白汤下，日二。名二拗散。（《普济 \n方》） \n蜈蚣咬伤∶胡椒，嚼封之，即不痛。（《多能鄙事》） \n\n\n\n<目录>果部第三十二卷\\果之四\n\n<篇名>毕澄茄\n\n内容：（宋《开宝》） \n【校正】自草部移入此。 \n【释名】毗陵茄子。 \n时珍曰∶皆番语也。 \n【集解】藏器曰∶毕澄茄生佛誓国。状似梧桐子及蔓荆子而微大。 \n曰∶胡椒生南海诸国。向阴者为澄茄，向阳者为胡椒。按∶顾微《广州志》云∶澄茄 \n生诸海国，乃嫩胡椒也。青时就树采摘，柄粗而蒂圆。 \n颂曰∶今广州亦有之。春夏生叶，青滑可爱。结实似梧桐子，微大。八月、九月采之。 \n时珍曰∶海南诸番皆有之。蔓生，春开白花，夏结黑实，与胡椒一类二种，正如大腹之 \n与槟榔相近耳。 \n【修治】 曰∶凡采得，去柄及皱皮了，用酒浸蒸之，从巳至酉，杵细晒干，入药用。 \n\\x实\\x \n【气味】辛，温，无毒。 曰∶辛、苦，微温。 \n【主治】下气消食，去皮肤风，心腹间气胀，令人能食，疗鬼气。能染发及香身（藏器）。 \n治一切冷气痰 ，并霍乱吐泻，肚腹痛，肾气膀胱冷 \n【附方】旧一，新五。 \n脾胃虚弱，胸膈不快，不进饮食∶用荜澄茄为末，姜汁打神曲糊，丸梧桐子大。每姜汤 \n下七十丸，日二服。《济生方》 \n噎食不纳∶荜澄茄、白豆蔻等分。为末。干舐之。（《寿域神方》）反胃吐食，吐出黑汁， \n治不愈者∶用荜澄茄为末，米糊丸梧桐子大。每姜汤下三、四十丸，日一服。愈后服平胃散 \n三百帖。（《永类钤方》） \n伤寒咳逆呃噫，日夜不定者∶用荜澄茄、高良姜各等分，为末。每服二钱，水六分，煎 \n十沸，入酢少许，服之。（苏颂《图经》）痘疮入目，羞明生翳∶荜澄茄末，吹少许入鼻中， \n三、五次效。（《飞鸿集》） \n鼻塞不通，肺气上攻而致者∶荜澄茄丸∶用荜澄茄半两，薄荷叶三钱，荆芥穗一钱半， \n为末，蜜丸芡子大。时时含咽。（《御药院方》） \n【附录】山胡椒（《唐本草》） \n恭曰∶所在有之。似胡椒，色黑 \n滞气，俗用有效。 \n\n\n\n<目录>果部第三十二卷\\果之四\n\n<篇名>吴茱萸\n\n内容：（《本经》中品） \n【校正】自木部移入此。 \n【释名】藏器曰∶茱萸南北总有，入药以吴地者为好，所以有吴之名也。 \n时珍曰∶茱萸二字义未详。萸有俞、由二音。 \n【集解】《别录》曰∶吴茱萸生上谷川谷及冤句。九月九日采，阴 \n颂曰∶今处处有之，江浙、蜀汉尤多。木高丈余，皮青绿色。叶似椿而阔浓，紫色。三 \n月开红紫细花。七月、八月结实似椒子，嫩时微黄，至熟则深紫。或云∶颗粒紧小，经久色 \n青绿者，是吴茱萸；颗粒大，经久色黄黑者，是食茱萸。恐亦不然。按∶《周处风土记》云∶ \n俗尚九月九日谓之上九，茱萸到此日气烈熟色赤，可折其房以插头，云辟恶气御冬。又《续 \n齐谐记》云∶汝南桓景随费长房学道。长房谓曰∶九月九日汝家有灾厄，宜令急去，各作绛 \n囊盛茱萸以系臂上，登高饮菊花酒，此祸可消。景如其言，举家登高山，夕还见鸡、犬、牛、 \n羊一时暴死。长房闻之曰∶此代之矣。故人至此日登高饮酒，戴茱萸囊，由此尔。 \n时珍曰∶茱萸枝柔而肥，叶长而皱，其实结于梢头，累累成簇而无核，与椒不同。一种 \n粒大，一种粒小，小者入药为胜。《淮南万毕术》云∶井上宜种茱萸，叶落井中，人饮其水， \n无瘟疫。 \n【修治】 曰∶凡使去叶梗，每十两以盐二两投东流水四斗中，分作一百度洗之，自然 \n无涎，晒干入丸散用之。若用醋煮者，每十两用醋一镒，煮三十沸后，入茱萸熬干用。 \n宗 曰∶凡用吴茱萸，须深汤中浸去苦烈汁七次，始可焙用。 \n【气味】辛，温，有小毒。权曰∶辛、苦，大热，有毒。 \n好古曰∶辛、苦，热。气味俱浓，阳中阴也。半浮半沉，入足太阴经血分，少阴、厥阴 \n经气分。 \n思邈曰∶陈久者良，闭口者有毒。多食伤神，令人起伏气，咽喉不通。 \n时珍曰∶辛热，走气动火，昏目发疮。 \n之才曰∶蓼实为之使。恶丹参、硝石、白垩，畏紫石英。 \n【主治】温中下气，止痛，除湿血痹，逐风邪，开腠理，咳逆寒热（《本经》）。利五脏， \n去痰冷逆气，饮食不消，心腹诸冷绞痛，中恶，心腹痛（《别录》）。霍乱转筋，胃冷吐泻腹 \n痛，产后心痛，治遍身 痹刺痛，腰脚软弱，利大肠壅气，肠风痔疾，杀三虫（甄权）。杀 \n恶 \n虫毒，牙齿虫 ，鬼魅疰气（藏器）。下产后余血，治肾气、香港脚水肿，通关节，起阳健脾 \n（大明）。主痢，止泻，浓肠胃，肥健人（孟诜）。治痞满塞胸，咽膈不通，润肝燥脾（好古）。 \n开郁化滞，治吞酸，厥阴痰涎头痛，阴 \n【发明】颂曰∶段成式言椒气好下，茱萸气好上。言其冲膈，不可为服食之药，故多食 \n冲眼又脱发也。 \n宗 曰∶此物下气最速，肠虚人服之愈甚。 \n元素曰∶气味俱浓，浮而降，阳中阴也。其用有三∶去胸中逆气满塞，止心腹感寒， \n痛，消宿酒，为白豆蔻之使也。 \n杲曰∶浊阴不降，厥气上逆，咽膈不通，食则令人口开目瞪，阴寒隔塞，气不得上下。 \n此病不已，令人寒中，腹满膨胀下利。宜以吴茱萸之苦热，泄其逆气，用之如神，诸药不可 \n代也。不宜多用，恐损元气。 \n好古曰∶冲脉为病，逆气里急，宜此主之。震、坤合见，其色绿。故仲景吴茱萸汤、当 \n归四逆汤方，治厥阴病及温脾胃，皆用此也。 \n时珍曰∶茱萸辛热，能散能温；苦热，能燥能坚。故其所治之症，皆取其散寒温中、燥 \n湿解郁之功而已。案∶《朱氏集验方》云∶中丞常子正苦痰饮，每食饱或阴晴节变率同，十 \n日一发，头疼背寒，呕吐酸汁，即数日伏枕不食，服药罔效。宣和初为顺昌司禄，于太守蔡 \n达道席上，得吴仙丹方服之，遂不再作。每遇饮食过多腹满，服五、七十丸便已。少顷小便 \n作茱萸气，酒饮皆随小水而去。前后痰药甚众，无及此者。用吴茱萸（汤泡七次）、茯苓等 \n分， \n为末，炼蜜丸梧桐子大。每熟水下五十丸。梅杨卿方∶只用茱萸酒浸三宿，以茯苓末拌之， \n晒干。每吞百粒，温酒下。又咽喉口舌生疮者，以茱萸末醋调贴两足心，移夜便愈。其性虽 \n热，而能引热下行，盖亦从治之义；而谓茱萸之性上行不下者，似不然也。有人治小儿痘疮 \n口噤者，啮茱萸一、二粒，抹之即开，亦取其辛散耳。 \n【附方】旧二十四，新二十二。 \n风 痒痹∶茱萸一升，酒五升，煮取一升半，温洗之，立止。（孟诜《食疗》）贼风口偏， \n不能语者∶茱萸一升，姜豉三升，清酒五升，和煎五沸，待冷服半升，一日三服，得少汗即 \n瘥。（同上） \n冬月感寒∶吴茱萸五钱。煎汤服之，取汗。 \n头风作痛∶茱萸煎浓汤，以绵染，频拭发根良。（《千金翼方》） \n呕涎头痛∶吴茱萸汤∶用茱萸一升，枣二十枚，生姜一大两，人参一两，以水五升，煎 \n取三升，每服七合，日三服。（仲景方） \n呕而胸满∶方同上。 \n香港脚冲心∶吴茱萸、生姜擂汁饮，甚良。（孟诜方） \n肾气上哕∶肾气自腹中起，上筑于咽喉，逆气连属而不能出，或至数十声，上下不得喘 \n息。此由寒伤胃脘，肾虚气逆，上乘于胃，与气相并。《难经》谓之哕。《素问》云∶病深者， \n其声哕。宜服此方。如不止，灸期门、关元、肾俞穴。用吴茱萸（醋炒热）、橘皮、附子（去 \n皮）各一两，为末，面糊丸梧桐子大。每姜汤下七十丸。（孙氏《仁存方》） \n阴毒伤寒，四肢逆冷∶用茱萸一升，酒拌湿，绢袋二个，包蒸极热，更互熨足心。候气 \n透， \n中恶心痛∶吴茱萸五合。酒三升，煮沸，分三服。（ \n心腹冷痛∶方同上。（《千金》） \n冷气腹痛∶吴茱萸二钱擂烂，以酒一钟调之。用香油一杯，入锅煎热，倾茱萸酒入锅， \n煎一滚，取服立止。（唐瑶《经验方》） \n脾元气痛，发歇不可忍∶用茱萸一两，桃仁一两。和炒茱萸焦，去茱萸，取桃仁去皮尖， \n研细，葱白三茎，煨熟，酒浸温服。（《经验 \n寒疝往来∶吴茱萸一两，生姜半两，清酒一升，煎温分服。（《肘后方 \n小肠疝气∶夺命丹∶治远年近日，小肠疝气，偏坠掣疼，脐下撮痛，以致闷乱，及外肾 \n肿硬，日渐滋长，及阴间湿痒成疮。用吴茱萸（去梗）一斤，分作四分∶四两酒浸，四两醋 \n浸， \n四两汤浸，四两童子小便浸一宿，同焙干，泽泻二两，为末，酒糊丸梧桐子大。每服五十丸， \n空心盐汤或酒吞下。《如宜方》名星斗丸。（《和剂局方》） \n小儿肾缩乃初生受寒所致∶用吴茱萸、硫黄各半两。同大蒜研，涂其腹；仍以蛇床子烟 \n熏之。 \n妇人阴寒十年无子者∶用吴茱萸、川椒各一升。为末，炼蜜丸弹子大。绵裹纳阴中，日 \n再易之。但子宫开，即有子也。（《经心录》） \n子肠脱出∶茱萸三升，酒五升，煎二升，分三服。（《兵部手集》） \n醋心上攻如浓醋∶用茱萸一合，水三盏，煎七分，顿服。近有人心如蜇破，服此，二十 \n年不发也。累用有效。（同上） \n食已吞酸，胃气虚冷者∶吴茱萸（汤泡七次焙）、干姜（炮）等分。为末，汤服一钱。（《圣 \n惠方》） \n转筋入腹∶茱萸（炒）二两，酒二盏，煎一盏，分二服。得下即安。（《圣济录》） \n霍乱干呕不止∶吴 \n多年脾泄∶老人多此，谓之水土同化。吴茱萸三钱泡过，入水煎汁，入盐少许，通口服。 \n盖茱萸能暖膀胱，水道 \n脏寒泄泻，倦怠减食∶吴茱萸（汤泡过，炒），猪脏半条，去脂洗净，装满扎定，文火 \n煮熟， \n滑痢不止∶方同上。 \n下痢水泄∶吴茱萸（泡，炒）、黄连（炒）各二钱，水煎服。未止再服。（《圣 \n赤白下痢∶《和剂局方》戊己丸∶治脾胃受湿，下痢腹痛，米谷不化。用吴茱萸、黄连、 \n白芍药各一两，同炒为末，蒸饼丸梧桐子大。每服二、三十丸，米饮下。《百一选方》变通 \n丸∶治赤白痢日夜无度，及肠风下血。用川黄连二两，吴茱萸二两（汤泡七次），同炒香， \n拣 \n出各自为末，粟米饭丸梧桐子大，另收。每服三十丸。赤痢，甘草汤下黄连丸；白痢，干姜 \n汤下茱萸丸；赤白痢，各用十五丸，米汤下。此乃浙西河山纯老以传苏韬光者，救人甚效。 \n邓笔峰《杂兴方》二色丸∶治痢及水泄肠风。用吴茱萸二两，黄连二两，同炒香，各自为末。 \n以百草霜末二两，同黄连作丸；以白芍药末二两，同茱萸作丸。各用饭丸梧桐子大，各收。 \n每服五十丸∶赤痢，乌梅汤下连霜；白痢，米饮下茱芍丸；赤白痢，各半服之。 \n赤痢脐痛∶茱萸合黑豆汤吞之。（《千金方》）肠痔常血，下部痒痛如虫咬者∶掘地作坑 \n烧赤，以酒沃之，捣茱萸二升入坑，乘热坐有孔板熏之，冷乃下。不过三、四度愈。（《肘 \n后方》） \n腹中症块∶茱萸三升捣，和酒煮熟，布裹熨症上。冷更炒热，更番熨之。症移走，逐熨 \n之 \n产后盗汗，啬啬恶寒∶茱萸一鸡子大。酒三升，渍半日，煮服。（《千金翼》） \n口疮口疳∶茱萸末，醋调涂足心，一夕愈。（《集简方》） \n咽喉作痛∶方同上。 \n牙齿疼痛∶茱萸煎酒，含漱之。（孟诜《本草》） \n小儿头疮∶吴茱萸，炒焦，为末，入汞粉少许，猪脂、醋调涂之。（《圣惠方》） \n小儿瘭疮∶一名火灼疮，一名火烂疮。茱萸煎酒，拭之良。（《兵部手集》） \n老小风疹∶方同上。（《千金》） \n痈疽发背及发乳诸毒∶用吴茱萸一升，捣为末。用苦酒调涂帛上，贴之。（《外台秘 \n要》） \n阴下湿痒∶吴茱萸煎汤，频洗取效。（同上） \n骨在肉中不出者∶咀茱萸封之，骨当腐出。（孟诜《食疗》） \n鱼骨入腹，刺痛不得出者∶吴茱萸水煮一盏，温服，其骨必软出。未出再服。（同上） \n蛇咬毒疮∶用吴茱萸一两为末。冷水和，作三服，立安。（《胜金方》） \n肩疽白秃∶并用吴茱萸盐淹过，炒研，醋和涂之。（《活幼口议》） \n寒热怪病∶寒热不止，数日四肢坚如石，击之似钟磬声，日渐瘦恶。用茱萸、木香 \n等分，煎汤饮之愈。（夏子益方） \n\\x叶\\x \n【气味】辛、苦，热，无毒。 \n【主治】霍乱下气，止心腹痛冷气。内外肾钓痛，盐碾罨之，神验，干即易。转筋者同 \n艾捣，以醋和罨之（大明）。治大寒犯脑，头痛，以酒拌叶，袋盛蒸熟，更互枕熨之，痛止 \n为度（时珍） \n\\x枝\\x \n【主治】大小便卒关格不通，取南行枝，如手第二指中节，含之立下（苏颂。出姚僧坦 \n《集验方》）。 \n\\x根及白皮\\x \n【气味】同叶。 \n【主治】杀三虫（《本经》）。蛲虫。治喉痹咳逆，止泄注，食不消，女子经产余血，疗 \n白癣（《别录》）。杀牙齿虫，止痛（藏器）。治中恶 \n【附方】旧二，新二。 \n寸白虫∶茱萸东北阴细根（大如指者勿用，洗去土）四两，切，以水、酒各一升渍一宿， \n平旦分再服，当取虫下。（《千金方》） \n肝劳生虫，眼中赤脉∶吴茱萸根（为末）一两半，粳米半合，鸡子白三个，化蜡一两半。 \n和丸小豆大。每米汤下三十丸，当取虫下。 \n脾劳发热，有虫在脾中为病，令人好呕者∶取东行茱萸根（大者）一尺，大麻子八升， \n橘 \n皮二两，三物 咀，以酒一斗，浸一宿，微火薄暖之，绞去滓，平旦空腹服一升，取虫下， \n或死或半烂，或下黄汁。凡作药时，切忌言语。（《删繁方》） \n肾热肢肿拘急∶茱萸根一合半，桑白皮三合，酒二升，煮一升，日二 \n\n\n\n<目录>果部第三十二卷\\果之四\n\n<篇名>食茱萸\n\n内容：（《唐本草》） \n【校正】自木部移入此，并入《拾遗》 子。 \n【释名】KT （音杀）、 （音毅）、艾子 \n辣子。 \n弘景曰∶《礼记》名 ，而俗中呼为KT 子，当是不识 字也。 \n恭曰∶《尔雅》云∶椒KT 丑 。陆机《诗疏》云∶椒，KT 属也。并有KT 名，陶 \n说误矣。 \n时珍曰∶此即 子也。蜀人呼为艾子，楚人呼为辣子，古人谓之 及KT 子。因其辛 \n辣，蜇口惨腹，使人有杀毅党然之状，故有诸名。苏恭谓茱萸之开口者为食茱萸。孟诜谓茱 \n萸之闭口者为 子。马志谓粒大、色黄黑者为食茱萸，粒紧小、色青绿者为吴茱萸。陈藏器 \n谓吴、食二茱萸是一物，入药以吴地者为良，不当重出此条，只可言汉与吴，不可言食与不 \n食。时珍窃谓数说皆因茱萸二字相混致误耳。不知吴茱、食茱乃一类二种。茱萸取吴地者入 \n药，故名吴茱萸。 子则形味似茱萸，惟可食用，故名食茱萸也。陈藏器不知食茱萸即 子， \n重出 子一条，正自误矣。按∶曹宪《博雅》云∶ 子、越椒，茱萸也。郑樵《通志》云∶ \n子，一名食 \n【集解】颂曰∶ 子出闽中、江东。其木高硕似樗，茎间有刺。其子辛辣如椒，南人淹 \n藏作果品，或以寄远。《吴越春秋》云 \n又曰∶食茱萸，南北皆有之。其木亦甚高硕，有长及百尺者。枝茎青黄，上有小白点。 \n叶类油麻，其花黄色。蜀人呼为艾子，《礼记》所谓 者是也。 、艾，声相近也。宜入食 \n羹中，能发辛香。 \n时珍曰∶食茱萸、 子、辣子，一物也。高木长叶，黄花绿子，丛簇枝上。 \n味辛而苦，土人八月采，捣滤取汁，入锻石搅成，名曰艾油，亦曰辣米油，始辛辣蜇口， \n入 \n\\x实\\x \n【气味】辛、苦，大热，无毒。时珍曰∶有小毒，动脾火，病目者忌之。 \n颖曰∶发疮痔、浮肿、虚恚。 \n之才曰∶畏紫石英。 \n【主治】功同吴茱萸，力稍劣尔。疗水气用之佳（苏恭）。 \n心腹冷气痛，中恶，除咳逆，去脏腑冷，温中，甚良（孟诜）。 \n疗蛊毒飞尸着喉口者，刺破，以子揩之，令血出，当下涎沫。煮汁服之，去暴冷腹痛， \n食不消，杀腥物（藏器）。治冷痢带下，暖胃燥湿（时珍）。 \n【附方】新二。 \n赤白带下∶ 子、石菖蒲等分，为末。每旦盐、酒温服二钱。（《经验方》） \n久泻虚痢腹痛者∶ 子丸治之。 子、肉豆蔻各一两，陈米一两半。以米一分同二味炒 \n黄为末；一分生碾为末，粟米粥丸梧桐子大。每陈米饮下五十丸，日三服。（《 \n\n\n\n<目录>果部第三十二卷\\果之四\n\n<篇名>盐麸子\n\n内容：（《开宝》） \n【校正】自木部移入此。 \n【释名】五 （音倍）、盐肤子（《纲目》）、盐梅子（同）、盐 子（同）、木盐（《通志》）、 \n天盐（《灵草篇》）、叛奴盐（ \n藏器曰∶蜀人谓之酸桶，亦曰酢桶。吴人谓之盐麸。戎人谓之木盐。 \n时珍曰∶其味酸、咸，故有诸名。《山海经》云∶橐山多 木。郭璞注云∶ 木出蜀中， \n七、八月吐穗，成时如有盐粉，可以酢羹。即此也。后人 \n【集解】藏器曰∶盐麸子生吴、蜀山谷。树状如椿。七月子成穗，粒如小豆。上有盐似 \n雪，可为羹用。岭南人取子为末食之，酸咸止渴，将以防瘴。 \n时珍曰∶肤木即 木，东南山原甚多。 \n木状如椿。其叶两两对生，长而有齿，面青背白，有细毛，味酸。正叶之下，节节两边， \n有直叶贴茎，如箭羽状。五、六月开花，青黄色成穗，一枝累累。七月结子，大如细豆而扁， \n生青，熟微紫色。其核淡绿，状如肾形。核外薄皮上有薄盐，小儿食之，滇、蜀人采为木盐。 \n叶上有虫，结成五倍子，八月取之。详见虫部。《后魏书》云∶勿吉国，水气咸凝，盐生树 \n上。即此物也。别有咸平树、咸草、酸角，皆其类也。附见于下∶ \n【附录】咸平树 真腊国人，不能为酸，但用咸平树叶 \n\\x酸角\\x \n云南、临安诸处有之。状如猪牙皂荚，浸水和羹，酸美如醋。 \n\\x咸草\\x \n扶桑东有女国，产咸草。叶似邪蒿，而气香味咸，彼人食之。 \n\\x子\\x \n【气味】酸、咸，微寒，无毒。盐霜制汞、硫。 \n【主治】除痰饮瘴疟，喉中热结喉痹，止渴，解酒毒黄胆，飞尸蛊毒，天行寒热，痰 \n嗽，变白，生毛发，去头上白屑，捣末服之（藏器）。生津，降火化痰，润肺滋肾，消毒止 \n痢收汗，治风湿眼病（时珍）。 \n【发明】时珍曰∶盐麸子气寒味酸而咸，阴中之阴也。咸能软而润，故降火化痰消毒； \n酸能收而涩，故生津润肺止痢。肾主五液∶入肺为痰，入脾为涎，入心为汗，入肝为泪，自 \n入为唾，其本皆水也。盐麸、五倍先走肾、肝，有救水之功。所以痰涎、盗汗、风湿、下泪、 \n涕唾之证，皆宜用之。 \n\\x树白皮\\x \n【主治】破血止血，蛊毒血痢，杀蛔虫，并煎服之（《开 \n\\x根白皮\\x \n【主治】酒疸，捣碎，米泔浸一宿，平旦空腹温服一、二升（《开宝》）。诸骨鲠，以醋 \n煎浓汁，时呷之（时珍）。 \n【发明】时珍曰∶按∶《本草集议》云∶盐麸子根能软鸡骨。岑公云∶有人被鸡骨鲠， \n项肿可畏。用此根煎醋，啜至三碗，便吐出也。又彭医官治骨鲠，以此根捣烂，入盐少许， \n绵裹，以线系定吞之，牵引上下，亦钓出骨也。 \n\n\n\n<目录>果部第三十二卷\\果之四\n\n<篇名>醋林子\n\n内容：（《图经》） \n【校正】自外类移入此。 \n【释名】时珍曰∶以味得名。 \n【集解】颂曰∶醋林子，生四川邛州山野林箐中。木高丈余，枝叶繁茂。三月开白花， \n四出。九月、十月子熟，累累数十枚成朵，生青熟赤，略类樱桃而蒂短。熟时采之阴干，连 \n核用。土人以盐、醋收藏，充果食。其叶味酸，夷獠人采得，入盐和鱼 \n\\x实\\x \n【气味】酸，温，无毒。 \n【主治】久痢不瘥，及痔漏下血，蛔咬心痛，小儿疳蛔，心腹胀满黄瘦，下寸白虫 \n，单捣为末，酒调一钱匕服之甚效。盐、醋藏者，食之生津液，醒酒止渴。多食，令人口 \n舌粗拆也（苏颂）。 \n\n\n\n<目录>果部第三十二卷\\果之四\n\n<篇名>茗\n\n内容：（《唐本草》） \n【校正】自木部移入此。 \n【释名】苦KT （搽、 \n颂曰∶郭璞云∶早采为荼，晚采为茗，一名 ，蜀人谓之苦荼。 \n陆羽云∶其名有五∶一荼，二 ，三 ，四茗 \n时珍曰∶杨慎《丹铅录》云∶荼，即古茶字（音途）。《诗》云“谁谓荼苦，其甘如荠” \n是也。颜师古云∶汉时荼陵，始转途音为宅加切，或言六经无茶字，未深考耳。 \n【集解】《神农食经》曰∶荼茗生益州及山陵道旁。凌冬不死，三 \n恭曰∶茗生山南。汉中山谷。《尔雅》云∶ ，苦荼。郭璞注云∶树小似栀子。冬生叶， \n可 \n颂曰∶今闽、浙、蜀荆、江湖、淮南山中皆有之，通谓之荼。春中始生嫩叶，蒸焙去苦 \n水，末之乃可饮。与古所食，殊不同也。陆羽《茶经》云∶茶者，南方嘉木。自一尺、二尺 \n至数十尺，其巴川峡山有两人合抱者，伐而掇之。木如瓜芦，叶如栀子，花如白蔷薇，实如 \n榈，蒂如丁香，根如胡桃。其上者生烂石，中者生砾壤，下者生黄土。艺法如种瓜，三岁 \n可采。阳崖阴林。紫者上，绿者次；笋者上，芽者次；叶卷者上，舒者次。在二月、三月、 \n四月之间，茶之笋者，生于烂石之间，长四五寸，若蕨之始抽，凌露采之。茶之芽者，发于 \n丛薄之上，有三枝、四枝、五枝，于枝颠采之。采得蒸焙封干，有千类万状也。略而言之∶ \n如胡人靴者蹙缩然，如 牛臆者廉 然，浮云出山者轮 然，飙风拂水者涵澹然，皆茶之精 \n好者也。如竹箨，如霜荷，皆茶之瘠老者也。其别者，有石楠芽、枸杞芽、枇杷芽，皆治风 \n疾。又有皂荚芽、槐芽、柳芽，乃上春摘其芽和茶作之。故今南人输官茶，往往杂以众叶。 \n惟茅芦竹箬之类不可入，自余山中草木芽叶，皆可和合，椿、柿尤奇。真茶性冷，惟雅州蒙 \n山出者温而主疾。毛文锡《茶谱》云∶蒙山有五顶，上有茶园，其中顶曰上清峰。昔有僧人 \n病冷且久，遇一老父谓曰∶蒙之中顶茶，当以春分之先后，多构人力，俟雷发声，并手采择， \n三日而止。若获一两，以本处水煎服，即能祛宿疾；二两当眼前无疾，三两能固肌骨，四两 \n即为地仙矣。其僧如说，获一两余服之，未尽而疾瘳。其四顶茶园，采摘不废。惟中峰草木 \n繁密，云雾蔽亏，鸷兽时出，故人迹不到矣。近岁稍贵此品，制作亦精于他处。 \n陈承曰∶近世蔡襄述闽茶极备。惟建州北苑数处产者，性味与诸方略不同。今亦独名蜡 \n茶，上供御用。碾治作饼，日晒得火愈良。其他者或为芽，或为末收贮，若微见火便硬，不 \n可久收，色味俱败。惟鼎州一种芽茶，性味略类建茶，今汴中及河北、京西等处磨为末，亦 \n冒腊茶者，是也。 \n宗 曰∶苦荼即今茶也。陆羽有《茶经》，丁谓有《北苑茶录》，毛文锡有《茶谱》，蔡 \n宗颜有《茶对》，皆甚详。 \n然古人谓茶为雀舌、麦颗，言其至嫩也。又有新芽一发，便长寸余，其粗如针，最为上 \n品，其根干、水土力皆有余故也。雀舌、麦颗又在下品，前人未知尔。 \n时珍曰∶茶有野生、种生，种者用子。其子大如指顶，正圆黑色。其仁入口，初甘后苦 \n，最戟人喉，而闽人以榨油食用。二月下种，一坎须百颗乃生一株，盖空壳者多故也。畏水 \n与日，最宜坡地荫处。清明前采者上，谷雨前者次之，此后皆老茗尔。采、蒸、揉、焙、修 \n造皆有法，详见《茶谱》。茶之税始于唐德宗，盛于宋、元，及于我朝，乃与西番互市易马。 \n夫茶一木尔，下为民生日用之资，上为朝廷赋税之助，其利博哉。昔贤所称，大约谓唐人尚 \n茶，茶品益众。有雅州之蒙顶、石花、露芽、谷芽为第一，建宁之北苑龙凤团为上供。蜀之 \n茶，则有东川之神泉兽目，硖州之碧涧明月，夔州之真香，邛州之火井，思安黔阳之都濡， \n嘉定之峨眉，泸州之纳溪，玉垒之沙坪。楚之茶，则有荆州之仙人掌，湖南之白露，长沙之 \n铁色，蕲州蕲门之团面，寿州霍山之黄芽，庐州之六安英山，武昌之樊山，岳州之巴陵，辰 \n州之溆浦，湖南之宝庆、茶陵。吴越之茶，则有湖州顾渚之紫笋，福州方山之生芽，洪州之 \n白露，双井之白毛，庐山之云雾，常州之阳羡，池州之九华，丫山之阳坡，袁州之界桥，睦 \n州之鸠坑，宣州之阳坑，金华之举岩，会稽之日铸。皆产茶有名者。其他犹多，而猥杂更甚。 \n按∶陶隐居注苦菜云∶酉阳、武昌、庐江、晋陵皆有好茗，饮之宜人。凡所饮物，有茗及木 \n叶、天门冬苗、菝 叶，皆益人。余物并冷利。又巴东县有真茶，火焙作卷结，为饮亦令人 \n不眠。俗中多煮檀叶及大皂李叶作茶饮，并冷利。南方有瓜芦木，亦似茗也。今人采槠、栎、 \n山矾、南烛、乌药诸叶，皆可为饮，以乱茶云。 \n\\x叶\\x \n【气味】苦、甘，微寒，无毒 \n藏器曰∶苦寒，久食，令人瘦，去人脂，使人不睡。饮之宜热，冷则聚痰。 \n胡洽曰∶与榧同食，令人身重。 \n李鹏飞曰∶大渴及酒后饮茶，水入肾经，令人腰、脚、膀胱冷痛，兼患水肿、挛痹诸疾 \n。大抵饮茶宜热、宜少，不饮尤佳，空腹最忌之。 \n时珍曰∶服威灵仙、土茯苓者，忌饮茶。 \n【主治】 疮，利小便，去痰热，止渴，令人少睡，有力悦志（《神农食经》）。下气消 \n食。作饮，加茱萸 \n清头目，治中风昏愦，多睡不醒（好古）。治伤暑。合醋，治泄痢，甚效（陈承）。炒煎 \n饮，治热毒赤白痢。同芎 、葱白煎饮，止头痛 \n【发明】好古曰∶茗茶气寒味苦，入手、足厥阴经。治阴证汤药内入此，去格拒之寒， \n及治伏阳，大意相 \n机曰∶头目不清，热熏上也。以苦泄其热，则上清矣。且茶体轻浮，采摘之时，芽 初 \n萌，正得春升之气，味虽苦而气则薄，乃阴中之阳，可升可降。利头目，盖本诸此。 \n汪颖曰∶一人好烧鹅炙爆，日常不缺。人咸防其生痈疽，后卒不病。访知其人每夜必啜 \n凉茶一碗，乃知茶能解炙爆之毒也。 \n杨士瀛曰∶姜茶治痢。姜助阳，茶助阴，并能消暑、解酒食毒。且一寒一热，调平阴阳 \n，不问赤、白、冷、热，用之皆良。生姜细切，与真茶等分，新水浓煎服之。苏东坡以此治 \n文潞公有效。 \n时珍曰∶茶苦而寒，阴中之阴，沉也，降也，最能降火。火为百病，火降则上清矣。然 \n火有五，火有虚实。若少壮胃健之人，心肺脾胃之火多盛，故与茶相宜。温饮则火因寒气而 \n下降，热饮则茶借火气而升散，又兼解酒食之毒，使人神思 爽，不昏不睡，此茶之功也。 \n若虚寒及血弱之人，饮之既久，则脾胃恶寒，元气暗损，土不制水，精血潜虚；成痰饮，成 \n痞胀，成痿痹，成黄瘦，成呕逆，成洞泻，成腹痛，成疝瘕，种种内伤，此茶之害也。民生 \n日用，蹈其弊者，往往皆是，而妇妪受害更多，习俗移人，自不觉尔。况真茶既少，杂茶更 \n多，其为患也，又可胜言哉？人有嗜茶成癖者，时时咀啜不止，久而伤营伤精，血不华色， \n黄瘁痿弱，抱病不悔，尤可叹惋。晋干宝《搜神记》载∶武官因时病后，啜茗一斛二升乃止。 \n才减升合，便为不足。有客令更进五升，忽吐一物，状如牛脾而有口。浇之以茗，尽一斛二 \n升。再浇五升，即溢出矣。人遂谓之斛茗瘕。嗜茶者观此可以戒矣。陶隐居《杂录》言∶丹 \n丘子、黄山君服茶轻身换骨，《壶公食忌》言∶苦茶久食羽化者，皆方士谬言误世者也。按∶ \n唐右补阙母炅代茶饮序云∶释滞消拥，一日之利暂佳；瘠气侵精，终身之累斯大。获益则功 \n归茶力，贻患则不谓茶灾。岂非福近易知，祸远难见乎？又宋学士苏轼《茶说》云∶除烦去 \n腻，世故不可无茶，然暗中损人不少。空心饮茶入盐，直入肾经，且冷脾胃，乃引贼入室也。 \n惟饮食后浓茶漱口，既去烦腻，而脾胃不知，且苦能坚齿消蠹，深得饮茶之妙。古人呼茗为 \n酪奴，亦贱之也。时珍早年气盛，每饮新茗必至数碗，轻汗发而肌骨清，颇觉痛快。中年胃 \n气稍损，饮之即觉为害，不痞闷呕恶，即腹冷洞泄。故备述诸说，以警同好焉。又浓茶能令 \n人吐，乃酸苦涌泄为阴之义，非其性能升也。 \n【附方】旧六，新十四。 \n气虚头痛∶用上春茶末调成膏，置瓦盏内覆转，以巴豆四十粒，作二次烧烟熏之，晒干 \n乳细。每服一字，别入好茶末，食后煎服，立效。（《医方大成》） \n热毒下痢∶《食医心镜》∶赤白下痢。 \n以好茶一斤，炙捣末，浓煎一、二盏服。久患痢者，亦宜服之。《直指》∶用蜡茶，赤痢 \n以蜜水煎服，白痢以连皮自然姜汁同水煎服。二、三服即愈。《经验良方》∶用蜡茶二钱， \n汤点七分，入麻油一蚬壳和服，须臾腹痛大下即止。一少年用之有效。一方∶蜡茶末，以白 \n梅肉和丸。赤痢甘草汤下白痢乌梅汤下，各百丸。一方∶建茶合醋煎，热服，即止。 \n大便下血∶营卫气虚，或受风邪，或食生冷，或啖炙爆，或饮食过度，积热肠间，使脾 \n胃受伤，糟粕不聚，大便下利清血，脐腹作痛，里急后重，及酒毒一切下血，并皆治之。用 \n细茶半斤（碾末），川百药煎五个（烧存性）。每服二钱，米饮下，日二服。（《 \n产后秘塞∶以葱涎调蜡茶末，丸百丸，茶服自通。不可用大黄利药，利者百无一生。（郭 \n稽中《妇人方》）久年心痛十年、五年者∶煎湖茶，以头醋和匀，服之良 \n腰痛难转∶煎茶五合，投醋二合，顿服。（《食医心镜》） \n嗜茶成癖∶一人病此，一方士令以新鞋盛茶令满，任意食尽，再盛一鞋，如此三度，自 \n不吃也。男用女鞋，女用男鞋，用之果愈也。（ \n解诸中毒∶芽茶、白矾等分，碾末，冷水调下。（《简便方》） \n痘疮作痒∶房中宜烧茶烟恒熏之。 \n阴囊生疮∶用蜡面茶，为末。先以甘草汤洗，后贴之妙。（《经验方》） \n脚丫湿烂∶茶叶嚼烂敷之，有效。（《摄生方》） \n蠼 尿疮∶初如糁粟，渐大如豆，更大如火烙浆 ，疼痛至甚者。速以草茶，并蜡茶俱 \n可，以生油调敷。药至，痛立止。（《胜金 \n风痰颠疾∶茶芽、栀子各一两。煎浓汁一碗服。良久探吐。（ \n霍乱烦闷∶茶末一钱煎水，调干姜末一钱，服之即安。（《圣济总录》） \n月水不通∶茶清一瓶，入沙糖少许，露一夜服。虽三个月胎亦通，不可轻视。（鲍氏） \n痰喘咳嗽，不能睡卧∶好末茶一两，白僵蚕一两，为末，放碗内盖定，倾沸汤一小盏。 \n临卧，再添汤点服。（《瑞竹堂方》） \n\\x茶子\\x \n【气味】苦，寒，有毒。 \n【主治】喘急咳嗽，去痰垢。捣仁洗衣，除油腻（时珍）。 \n【附方】新三。 \n上气喘急，时有咳嗽∶茶子、百合等分。为末，蜜丸梧桐子大。每服七丸，新汲水下。 \n（《 \n喘嗽 ，不拘大人、小儿∶用糯米泔少许磨茶子，滴入鼻中，令吸入口服之。口咬竹 \n筒，少顷涎出如线。不过二、三次绝根，屡验。（《经验良方》）头脑鸣响，状如虫蛀，名大 \n白蚁∶以茶子为末，吹入鼻中，取效。（杨拱《医方摘要》） \n\n\n\n<目录>果部第三十二卷\\果之四\n\n<篇名>皋芦\n\n内容：（《拾遗》） \n【校正】自木部移入此。 \n【释名】瓜芦（弘景）、苦 。 \n藏器曰∶《南越志》云∶龙川县有皋芦，一名瓜芦，叶似茗。土人谓之过罗，或曰物罗， \n皆夷语也。 \n【集解】弘景《苦菜注》曰∶南方有瓜芦，亦似茗。若摘取其叶，作屑煮饮，即通夜不 \n睡。煮盐人惟资此饮，而交、广最所重，客来先设，乃加以香 之 \n李 曰∶按∶此木即皋芦也。生南海诸山中，叶似茗而大，味苦涩，出新平县。南人取 \n作茗饮，极重之，如蜀人饮茶也。 \n时珍曰∶皋芦叶状如茗，而大如手掌。 碎泡饮，最苦而色浊，风味比茶不及远矣。今 \n广人用之，名曰苦 。 \n\\x叶\\x \n【气味】苦，平，无毒。 \n时珍曰∶寒。胃冷者不可用。 \n【主治】煮饮，止渴明目除烦，令人不睡，消痰利水（藏器）。 \n通小肠，治淋，止头痛烦热（李 ）。噙 \n\n\n\n<目录>果部第三十三卷\n\n<篇名>果之五\n\n内容：（ 类九种） \n\n\n\n<目录>果部第三十三卷\\果之五\n\n<篇名>甜瓜\n\n内容：（宋《嘉 》） \n【校正】自菜部移入此。并入《本经》瓜蒂。 \n【释名】甘瓜（《唐本》）、果瓜。 \n时珍曰∶瓜字篆文，象瓜在须蔓间之形。甜瓜之味甜于诸瓜，故独得甘、甜之称。旧列 \n菜部，误矣。按∶王祯云∶瓜类不同，其用有二∶供果者为果瓜，甜瓜、西瓜是也；供菜者 \n为菜瓜，胡瓜、越瓜是也。在木曰果，在地曰 。大曰瓜，小曰瓞。其子曰KT ，其肉曰 \n瓤。其跗曰环，谓脱花处也；其蒂曰 ，谓系蔓处也。《礼记》为天子削瓜及瓜祭，皆指果 \n瓜也。本草瓜蒂 \n【集解】《别录》曰∶瓜蒂生嵩高平泽，七月七日采，阴干。 \n颂曰∶瓜蒂即甜瓜蒂也，处处有之。园圃所莳，有青、白二种，子色皆黄。入药当用早 \n青瓜蒂为良。 \n时珍曰∶甜瓜，北土、中州种莳甚多。二、三月下种，延蔓而生，叶大数寸，五、六月 \n花开黄色，六、七月瓜熟。其类甚繁∶有团有长，有尖有扁；大或径尺，小或一捻；其棱或 \n有或无；其色或青或绿，或黄斑、糁斑，或白路、黄路；其瓤或白或红，其子或黄或赤，或 \n白或黑。按∶王祯《农书》云∶瓜品甚多，不可枚举。以状得名，则有龙肝、虎掌、兔头、 \n狸首、羊髓、蜜筒之称；以色得名，则有乌瓜、白团、黄 、白 、小青、大斑之别。然其 \n味，不出乎甘香而已。《广志》惟以辽东、敦煌、庐江之瓜为胜。然瓜州之大瓜，阳城之御 \n瓜，西蜀之温瓜，永嘉之寒瓜，未可以优劣论也。甘肃甜瓜，皮、瓤皆甘胜糖蜜，其皮曝干 \n犹美。浙中一种阴瓜，种于阴处，熟则色黄如金，肤皮稍浓，藏之至春，食之如新。此皆种 \n之功，不必拘于土地也。甜瓜子曝裂取仁，可充果食。凡瓜最畏麝气，触之甚至一蒂不收。 \n\\x瓜瓤\\x \n【气味】甘，寒，滑，有小毒。 \n大明曰∶无毒。 \n思邈曰∶多食，发黄胆，令人虚羸多忘，解药力。病后食多，或反胃。香港脚人食之，患 \n永不除也。 \n诜曰∶多食，令人阴下湿痒生疮，动宿冷症癖病，破腹，发虚热，令人 气弱，脚手 \n无力。少食则可。《龙鱼河图》云∶凡瓜有两鼻、两蒂者，杀人。五月瓜沉水者，食之得冷 \n病，终身不瘥。九月被霜者，食之冬病寒热。与油饼同食，发病。多食瓜作胀者，食盐花即 \n化。 \n弘景曰∶食瓜多，即入水自渍，便消。 \n时珍曰∶张华《博物志》言∶人以冷水渍至膝，可顿啖瓜至数十枚；渍至项，其啖转多， \n水皆作瓜气也。则水浸消瓜，亦物性也。瓜最忌麝与酒，凡食瓜过多，但饮酒及水服麝香， \n尤胜于食盐、渍水也。 \n【主治】止渴，除烦热，利小便，通三焦间壅塞气，治口鼻疮（《嘉 》）。暑月食之， \n永不中 \n【发明】宗 曰∶甜瓜虽解暑气，而性冷，消损阳气，多食未有不下利者。贫下多食， \n深秋作痢，最为难治。惟以皮蜜浸收之良，皮亦可作羹食。 \n弘景曰∶凡瓜皆冷利，早青者尤甚。熟瓜除瓤食之，不害人。 \n时珍曰∶瓜性最寒，曝而食之尤冷。故《稽圣赋》云∶瓜寒于曝，油冷于煎，此物性之 \n异也。王冀《洛都赋》云∶瓜则消暑荡 ，解渴疗饥。又《奇效良方》云∶昔有男子病脓血 \n恶痢，痛不可忍。以水浸甜瓜食数枚，即愈。此亦消暑之验也。 \n\\x瓜子仁\\x \n【修治】 曰∶凡收得曝干杵细，马尾筛筛过成粉，以纸三重裹压去油用。不去油，其 \n力短也。西瓜子仁同。 \n【气味】甘，寒，无毒。 \n【主治】腹内结聚，破溃脓血，最为肠胃脾内壅要药（《别录》）。止月经太过，研末去 \n油，水调服（藏器。《炮炙论序》曰∶血泛经过，饮调瓜子）。炒食，补中宜人（孟诜）。清 \n肺润肠，和中止渴（时珍）。 \n【附方】旧一，新二。 \n口臭∶用甜瓜子杵末，蜜和为丸。每旦漱口后含一丸。亦可贴齿。（《千金》） \n腰腿疼痛∶甜瓜子三两，酒浸十日，为末。每服三钱，空心酒下，日三。（《寿域神方》） \n肠痈已成∶小腹肿痛，小便似淋，或大便难涩下脓。用甜瓜子一合，当归（炒）一两， \n蛇蜕皮一条， 咀。每服四钱，水一盏半，煎一盏，食前服，利下恶物为 \n\n\n\n<目录>果部第三十三卷\\果之五\n\n<篇名>瓜蒂\n\n内容：（《本经》上品） \n【释名】瓜丁（《千金》）、苦丁香（象形）。 \n【修治】 曰∶凡使勿用白瓜蒂，要取青绿色瓜，气足时，其蒂自然落在蔓上。采得， \n系屋东有风处，吹干用。 \n宗 曰∶此甜瓜蒂也。去瓜皮用蒂，约半寸许，曝极干，临时研用。 \n时珍曰∶按唐瑶云∶甜瓜蒂以团而短瓜、团瓜者良。若香甜瓜及长如瓠子者，皆供菜之 \n瓜，其蒂不可用也。 \n【气味】苦，寒，有毒。大明曰∶无毒。 \n【主治】大水，身面四肢浮肿，下水杀蛊毒，咳逆上气，及食诸果，病在胸腹中，皆吐 \n下之（《本经》）。去鼻中息肉，疗黄胆（《别录》）。治脑塞热 ，眼昏吐痰（《大明》）。吐 \n风热痰涎，治风眩头痛，癫痫喉痹，头目有湿气（时珍）。得麝香、细辛，治鼻不闻香臭（好 \n古）。 \n【发明】张机曰∶病如桂枝证，头不痛，项不强，寸脉微浮，胸中痞硬，气上冲咽喉， \n不得息者，此为胸中有寒也，当吐之；太阳中 ，身热疼重而脉微弱，此夏月伤冷水，水行 \n皮中也，宜吐之；少阳病，头痛发寒热，脉紧不大，是膈上有痰也，宜吐之；病胸上诸实， \n郁郁而痛，不能食，欲人按之，而反有浊唾，下利日十余行，寸口脉微弦者，当吐之；懊 \n烦躁不得眠，未经汗下者，谓之实烦，当吐之；宿食在上管者，当吐之，并宜以瓜蒂散主之。 \n惟诸亡血虚家，不可与瓜蒂散也。 \n成无己曰∶高者越之，在上者涌之。故越以瓜蒂、香豉之苦，涌以赤小豆之酸，酸苦涌 \n泄为阴也。 \n杲曰∶《难经》云∶上部有脉，下部无脉，其人当吐不吐者，死。此饮食内伤，填塞胸 \n中，食伤太阴，风木生发之气伏于下，宜瓜蒂散吐之，《素问》所谓木郁则达之也。吐去上 \n焦有形之物，则木得舒畅，天地交而万物通矣。若尺脉绝者，不宜用此，恐损真元，令人胃 \n气不复也。 \n宗 曰∶此物吐涎，甚不损人，全胜石绿、 砂辈也。 \n震亨曰∶瓜蒂性急，能损胃气，胃弱者宜以他药代之。病后、产后，尤宜深戒。 \n时珍曰∶瓜蒂乃阳明经除湿热之药，故能引去胸脘痰涎，头目湿气，皮肤水气，黄胆湿 \n热诸证，凡胃弱人及病后、产后用吐药，皆宜加慎，何独瓜蒂为然。 \n【附方】旧七，新十五。 \n瓜蒂散∶治证见上。其方用瓜蒂二钱半（熬黄），赤小豆二钱半，为末。每用一钱，以 \n香 \n豉一合，热汤七合，煮糜去滓，和服。稍稍加之，快吐乃止。（仲景《伤寒论》） \n太阳中 ∶身热头痛而脉微弱，此夏月伤冷水，水行皮中所致。瓜蒂二七个，水一升， \n煮五合，顿服取吐。（《金匮要略》） \n风涎暴作，气塞倒仆∶用瓜蒂为末。每用一、二钱，腻粉一钱匕，以水半合调灌，良久 \n涎自出。不出，含沙糖一块，下咽即涎出也。（寇氏《衍义》） \n诸风诸痫∶诸风膈痰，诸痫涎涌。用瓜蒂炒黄为末，量人以酸齑水一盏，调下取吐。风 \n痫，加蝎梢半钱。湿气肿满，加赤小豆末一钱；有虫，加狗油五、七点，雄黄一钱，甚则加 \n芫花半钱，立吐虫出。（东垣《活法机要》） \n风痫喉风∶咳嗽，及遍身风疹，急中涎潮等症，不拘大人、小儿。此药不大吐逆，只出 \n涎水。瓜蒂为末，壮年服一字，老少半字，早晨井华水下。一食顷，含沙糖一块。良久涎如 \n水出，年深者出墨涎，有块布水上也。涎尽食粥一、两日。如吐多，人困甚，即以麝香泡汤 \n一盏饮之，即止。（《经验后方》） \n急黄喘息，心上坚硬，欲得水吃者∶瓜蒂二小合，赤小豆一合，研末。暖浆水五合，服 \n方寸匕。一炊久当吐，不吐再服。吹鼻取水亦可。（《伤 \n遍身如金∶瓜蒂四十九枚，丁香四十九枚，甘锅内烧存性，为末。每用一字，吹鼻取出 \n黄水。亦可揩牙追涎。（《经验方》） \n热病发黄∶瓜蒂为末，以大豆许吹鼻中。轻则半日，重则一日，流取黄水乃愈。（《千 \n金翼》） \n黄胆 黄∶并取瓜蒂、丁香、赤小豆各七枚，为末。吹豆许入鼻，少时黄水流出。隔日 \n一用，瘥乃止。（孟诜《食疗》） \n身面浮肿∶方同上。十种蛊气∶苦丁香为末，枣肉和，丸梧桐子大。每服三十丸，枣汤 \n下，甚效。（《瑞竹堂方》） \n湿家头痛∶瓜蒂末一字， 入鼻中，口含冷水，取出黄水愈。（《活人书》） \n疟疾寒热∶瓜蒂二枚，水半盏，浸一宿，顿服，取吐愈。（《千金》） \n发狂欲走∶瓜蒂末，井水服一钱，取吐即愈。（《圣惠方》） \n大便不通∶瓜蒂七枚，研末，绵裹，塞入下部即通。（《必效方》） \n鼻中息肉∶《圣惠》∶用陈瓜蒂末，吹之，日三次，瘥乃已。又方∶瓜蒂末、白矾末各半 \n钱，绵裹塞之，或以猪脂和挺子塞之。日一换。又方∶青甜瓜蒂二枚，雄黄、麝香半分，为 \n末。先抓破，后贴之，日三次。《汤液》∶用瓜蒂十四个，丁香一个，黍米四十九粒，研末。 \n口 \n风热牙痛∶瓜蒂七枚（炒研），麝香少许和之，绵裹咬定，流涎。（《圣济总录》） \n鸡屎白秃∶甜瓜蔓连蒂不拘多少，以水浸一夜，砂锅熬取苦汁，去滓再熬如饧盛收。每 \n剃去痂 ，洗净，以膏一盏，加半夏末二钱，姜汁一匙，狗胆汁一枚，和匀涂之，不过三上。 \n忌食动风之物。（《儒门事亲》） \n喘痰气∶苦丁香三个，为末。水调服，吐痰即止。（《朱氏集验方》） \n\\x蔓\\x（阴干） \n【主治】女人月经断绝，同使君子各半两， \n\\x花\\x \n【主治】心痛咳逆（《别录》）。 \n\\x叶\\x \n【主治】人无发，捣汁涂之即生（《嘉 》）。补中，治小儿疳，及打伤损折， \n为末酒服，去瘀血（孟诜）。 \n【附方】新一。 \n面上 子∶七月七日午时，取生瓜叶七枚，直入北堂中，向南立，逐枚拭靥，即灭去也。 \n（ \n\n\n\n<目录>果部第三十三卷\\果之五\n\n<篇名>西瓜\n\n内容：（《日用》） \n【释名】寒瓜（见下）。 \n【集解】瑞曰∶契丹破回纥，始得此种，以牛粪覆而种之。结实如斗大，而圆如匏，色 \n如青玉，子如金色，或黑麻色。北地多有之。 \n时珍曰∶按∶胡峤《陷虏记》言∶峤征回纥，得此种归，名曰西瓜。则西瓜自五代时始 \n入中国，今则南北皆有，而南方者味稍不及，亦甜瓜之类也。二月下种，蔓生，花、叶皆如 \n甜瓜。七、八月实熟，有围及径尺者，长至二尺者。其棱或有或无，其色或青或绿，其瓤或 \n白或红，红者味尤胜。其子或黄或红，或黑或白，白者味更劣。其味有甘、有淡、有酸，酸 \n者为下。陶弘景注瓜蒂言，永嘉有寒瓜甚大，可藏至春者，即此也。盖五代之先，瓜种已入 \n浙东，但无西瓜之名，未遍中国尔。其瓜子曝裂取仁，生食、炒熟俱佳。皮不堪啖，亦可蜜 \n煎、酱藏。 \n颂曰∶一种杨溪瓜，秋生冬熟，形略长扁而大，瓤色如胭脂，味胜。可留至次年，云是 \n异人所遗之种也。 \n\\x瓜瓤\\x \n【气味】甘、淡，寒，无毒。 \n瑞曰∶有小毒。多食作吐利，胃弱者不可食。同油饼食，损脾。 \n时珍曰∶按《延寿书》云∶北人禀浓，食之犹惯；南人禀薄，多食易至霍乱，冷病 \n终身也。又按∶《相感志》云∶食西瓜后食其子，即不噫瓜气。以瓜划破，曝日中，少顷食， \n即冷如水也。得酒气、近糯米，即易烂。猫踏之，即易沙。 \n【主治】消烦止渴，解暑热（吴瑞）。疗喉痹（汪颖）。宽中下气，利小水，治血痢，解 \n酒毒（宁原）。含汁，治口疮（震享）。 \n【发明】颖曰∶西瓜性寒解热，有天生白虎汤之号。然亦不宜多食。 \n时珍曰∶西瓜、甜瓜皆属生冷。世俗以为醍醐灌顶，甘露洒心，取其一时之快，不知其 \n伤脾助湿之害也。《真西山卫生歌》云∶“瓜桃生冷宜少飧，免致秋来成疟痢。”是矣。又李 \n鹏飞《延寿书》云∶防州太守陈逢原，避暑食瓜过多，至秋忽腰腿痛，不能举动。遇商助教 \n疗之，乃愈。此皆食瓜之患也，故集书于此，以为鉴戒云。又洪忠宣《松漠纪闻》言∶有人 \n苦目病。或令以西瓜切片曝干，日日服之，遂愈。由其性冷降火故也。 \n\\x皮\\x \n【气味】甘，凉，无毒。 \n【主治】口、舌、唇内生疮，烧研噙之（震亨）。 \n【附方】新二。 \n闲挫腰痛∶西瓜青皮，阴干为末，盐酒调服三钱。（《摄生众妙方》） \n食瓜过伤∶瓜皮煎汤解之。诸瓜皆同。（《事林广记》） \n\\x瓜子仁\\x \n【气味】甘，寒，无毒。 \n【主治】与甜瓜仁同（时珍）。 \n\n\n\n<目录>果部第三十三卷\\果之五\n\n<篇名>葡萄\n\n内容：（《本经》上品） \n【释名】蒲桃（古字）、草龙珠。 \n时珍曰∶葡萄，《汉书》作蒲桃，可以造酒，人 饮之，则 然而醉，故有是名。其圆 \n者名草龙珠，长者名马乳葡萄，白者名水晶葡萄，黑者名紫葡萄。《汉书》言∶张骞使西域 \n还，始得此种，而《神农本草》已有葡萄，则汉前陇西旧有，但未入关耳。 \n【集解】《别录》曰∶葡萄生陇西、五原、敦煌山谷。 \n弘景曰∶魏国使人多 来南方。状如五味子而甘美，可作酒，云用藤汁殊美。北人多肥 \n健耐寒，盖食斯乎？不植淮南，亦如橘之变于河北也。人说即是此间 ，恐亦如枳之与橘 \n耶？ \n恭曰∶ 即山葡萄，苗、叶相似，亦堪作酒。葡萄取子汁酿酒，陶云用藤汁，谬矣。 \n颂曰∶今河东及近汴州郡皆有之。苗作藤蔓而极长，太盛者一、二本绵被山谷间。花极 \n细而黄白色。其实有紫、白二色，有圆如珠者，有长似马乳者，有无核者，皆七月、八月熟， \n取汁可酿酒。按《史记》云∶大宛以葡萄酿酒，富人藏酒万余石，久者十数年不败。张骞使 \n西域，得其种还，中国始有。盖北果之最珍者，今太原尚作此酒寄远也。其根、茎中空相通， \n暮溉其根，而晨朝水浸子中矣。故俗呼其苗为木通，以利小肠。江东出一种，实细而酸者， \n名 子。 \n宗 曰∶段成式言∶葡萄有黄、白、黑三种。《唐书》言∶波斯所出者，大如鸡卵。此 \n物最难干，不干不可收。不问土地，但收皆可酿酒。 \n时珍曰∶葡萄，折藤压之最易生。春月萌苞生叶，颇似栝蒌叶而有五尖。生须延蔓，引 \n数十丈。三月开小花成穗，黄白色。仍连着实，星编珠聚，七、八月熟，有紫、白二色。西 \n人及太原、平阳皆作葡萄干，货之四方。蜀中有绿葡萄，熟时色绿。云南所出者，大如枣， \n味尤长。西边有琐琐葡萄，大如五味子而无核。按∶《物类相感志》云∶甘草作钉，针葡萄， \n立死。以麝香入葡萄皮内，则葡萄尽作香气。其爱憎异于他草如此。又言∶其藤穿过枣树， \n则实味更美也。《 \n\\x实\\x \n【气味】甘，平，涩，无毒。 \n诜曰∶甘、酸，温。多食，令人猝烦闷、眼暗。 \n【主治】筋骨湿痹，益气倍力强志，令人肥健，耐饥忍风寒。久食，轻身不老延年。可 \n作酒（《本经》）。逐水，利小便（《别录》）。除肠间水，调中治淋（甄权）。时气痘疮不出， \n食之，或研酒饮，甚效（苏颂）。 \n【发明】颂曰∶按∶魏文帝诏群臣曰∶蒲桃当夏末涉秋，尚有余暑，醉酒宿酲，掩露而 \n食。甘而不饴，酸而不酢，冷而不寒，味长汁多，除烦解渴。又酿为酒，甘于曲 ，善醉而 \n易醒。他方之果，宁有匹之者乎？ \n震亨曰∶葡萄属土，有水与木火。东南人食之多病热，西北人食之无恙。盖能下走渗道， \n西北人禀气浓故耳。 \n【附方】新三。 \n除烦止渴∶生葡萄捣滤取汁，以瓦器熬稠，入熟蜜少许同收。点汤饮甚良。（《居家必 \n用》） \n热淋涩痛∶葡萄（捣取自然汁）、生藕（捣取自然汁）、生地黄（捣取自然汁）、白沙蜜 \n各五合 \n胎上冲心∶葡萄，煎汤饮之，即下。（《圣惠方》） \n\\x根及藤、叶\\x \n【气味】同实。 \n【主治】煮浓汁细饮，止呕哕及霍乱后恶心，孕妇子上冲心，饮之即下，胎安（孟诜）。 \n治腰脚肢腿痛，煎汤淋洗之良。又饮其汁，利小便，通小肠，消肿满（时珍）。 \n【附方】新一。 \n水肿∶葡萄嫩心十四个，蝼蛄七个（去头尾），同研，露七日，曝干为末。每服半钱， \n淡酒调下。暑月尤佳。（洁古《保命集 \n\n\n\n<目录>果部第三十三卷\n\n<篇名>果之五\n\n内容：（音婴郁。《纲目》） \n【校正】原附葡萄下，今分出。 \n【释名】燕 （《毛诗》）、 \n龙。 \n时珍曰∶名义未详。 \n【集解】恭曰∶ 蔓生。苗、叶与葡萄相似而小，亦有茎大如碗者。冬月惟叶凋而藤 \n不死。藤汁味甘，子味甘酸，即千岁 \n颂曰∶ 子生江东，实似葡萄，细而味酸，亦 \n时珍曰∶ 野生林墅间，亦可插植。蔓、叶、花、实，与葡萄无异。其实小而圆，色 \n不甚紫也。《诗》云“六月食 ”即此。其茎吹之，气出有汁，如 \n【正误】藏器曰∶苏恭注千岁 即是 ，妄言也。千岁 藤如葛，而叶背白，子赤可 \n食。 藤斫 \n时珍曰∶苏恭所说 ，形状甚是，但以为千岁 则非矣。 \n\\x实\\x \n【气味】甘、酸，平、无毒。 \n【主治】止渴，悦色益气（苏恭）。 \n\\x藤\\x \n【气味】甘，平，无毒。 \n【主治】哕逆，伤寒后呕哕，捣汁饮之良（苏恭）。止渴，利小便（时珍）。 \n【附方】新三。 \n呕 厥逆∶ 藤煎汁，呷之。（《肘后方》） \n目中障翳∶ 藤，以水浸过，吹气取汁，滴入目中，去热翳，赤、白障。（《拾遗本 \n草》） \n五淋血淋∶木龙汤∶用木龙（即野葡萄藤也）、竹园荽、淡竹叶、麦门冬（连根苗）、红 \n枣肉、灯心草、乌梅、当归各等分，煎汤代茶饮。（《百一 \n\\x根\\x \n【气味】同藤。 \n【主治】下焦热痛淋秘，消肿毒（时珍）。 \n【附方】新四。 \n男妇热淋∶野葡萄根七钱，葛根三钱，水一钟，煎七分，入童子小便三分，空心 \n温服。（《乾坤秘韫》） \n女人腹痛∶方同上。 \n一切肿毒∶赤龙散∶用野葡萄根，晒研为末，水调涂之，即消也。（《儒门事亲》方） \n赤游风肿∶忽然肿痒，不治则杀人。用野葡萄根捣如泥，涂之即消。（《通变要法》） \n\n\n\n<目录>果部第三十三卷\\果之五\n\n<篇名>猕猴桃\n\n内容：（宋《开宝》） \n【释名】猕猴梨（《开宝》）、藤梨（同上）、 \n时珍曰∶其形如梨，其色如桃，而猕猴喜食，故有诸名。闽人呼为阳桃。 \n【集解】志曰∶生山谷中。藤着树生，叶圆有毛。其实形似鸡卵大，其皮褐色，经霜始 \n甘美可食。皮堪作纸。 \n宗 曰∶今陕西永兴军南山甚多。枝条柔弱，高二、三丈，多附木而生。 \n其子十月烂熟，色淡绿，生则极酸。子繁细，其色如芥子。浅山傍道则有存者，深山则 \n多为猴所食矣。 \n\\x实\\x \n【气味】酸、甘，寒，无毒。 \n藏器曰∶咸、酸，无毒。多食冷脾胃，动泄 。 \n宗 曰∶有实热者宜食之。太过，则令人脏寒作泄。 \n【主治】止暴渴，解烦热，压丹石，下石淋（《开宝》。诜曰∶并宜取瓤和蜜作煎食）。 \n调中下气，主骨节风，瘫缓不随，长年白发，野鸡内痔病（藏器）。 \n\\x藤中汁\\x \n【气味】甘，滑，寒，无毒。 \n【主治】热壅反胃，和生姜汁服之。又下石淋（藏器）。 \n\\x枝、叶\\x \n【主治】杀虫。煮汁饲狗，疗 疥（《 \n\n\n\n<目录>果部第三十三卷\\果之五\n\n<篇名>甘蔗\n\n内容：（音柘，《别录》中品） \n【释名】竿蔗（《草木状》）、薯（音遮）。 \n时珍曰∶按∶《野史》云∶吕惠卿言∶凡草皆正生嫡出，惟蔗侧种，根上庶出，故字从 \n庶也。嵇含作竿蔗，谓其茎如竹竿也。《离骚》、《汉书》皆作柘字，通用也。薯字出许慎《说 \n文》，盖蔗音之转也。 \n【集解】弘景曰∶蔗出江东为胜，庐陵亦有好者。广州一种，数年生皆大如竹，长丈余， \n取汁为沙糖，甚益人。又有荻蔗，节疏而细，亦可啖也。 \n颂曰∶今江浙、闽广、湖南、蜀川所生，大者亦高丈许。有二种∶荻蔗其叶似荻，茎细 \n短而节疏，但堪生啖，亦可煎稀糖；竹蔗茎粗而长，可榨汁为沙糖，泉、福、吉、广诸州多 \n作之。炼沙糖和牛乳为乳糖，惟蜀川作之。南人贩至北地者，荻蔗多而竹蔗少也。 \n诜曰∶蔗有赤色者名昆仑蔗；白色者名荻蔗。竹蔗以蜀及岭南者为胜，江东虽有而劣于 \n蜀产。会稽所作乳糖，殆胜于蜀。 \n时珍曰∶蔗皆畦种，丛生，最困地力。茎似竹而内实，大者围数寸，长六、七尺，根下 \n节密，以渐而疏。抽叶如芦叶而大，长三、四尺，扶疏四垂。八、九月收茎，可留过春充果 \n食。按王灼《糖霜谱》云∶蔗有四色∶曰杜蔗，即竹蔗也，绿嫩薄皮，味极醇浓，专用作霜； \n曰西蔗，作霜色浅；曰 蔗，亦名蜡蔗，即荻蔗也，亦可作沙糖；曰红蔗，亦名紫蔗，即昆 \n仓蔗也，止可生啖，不堪作糖。凡蔗榨 \n\\x蔗\\x \n【气味】甘，平，涩，无毒。 \n大明曰∶冷。 \n诜曰∶共酒食，发痰。 \n瑞曰∶多食，发虚热，动衄血。 \n【主治】下气和中，助脾气，利大肠（《别录》）。利大小肠，消痰止渴，除心胸烦热， \n解酒毒 \n【发明】时珍曰∶蔗，脾之果也。其浆甘寒，能泻火热，《素问》所谓甘温除大热之意。 \n煎炼成糖，则甘温而助湿热，所谓积温成热也。蔗浆消渴解酒，自古称之。故《汉书·郊祀 \n歌》云∶百末旨酒布兰生，泰尊柘浆析朝酲。唐王维《樱桃诗》云∶饱食不须愁内热，大官 \n还有蔗浆寒。是矣。而孟诜乃谓共酒食发痰者，岂不知其有解酒除热之功耶？日华子大明又 \n谓沙糖能解酒毒，则不知既经煎炼，便能助酒为热，与生浆之性异矣。按∶晁氏《客话》云∶ \n甘草遇火则热，麻油遇火则冷，甘蔗煎饴则热，水成汤则冷。此物性之异，医者可不知乎？ \n又《野史》云∶卢绛中病 疾疲瘵，忽梦白衣妇人云∶食蔗可愈。及旦买蔗数挺食之，翌日 \n疾愈。此亦助脾和中之验欤？ \n【附方】旧三，新四。 \n发热口干，小便赤涩∶取甘蔗去皮，嚼汁咽之。饮浆亦可。（《外台秘要》） \n痰喘气急∶方见山药。 \n反胃吐食，朝食暮吐，暮食朝吐，旋旋吐者。用甘蔗汁七升，生姜汁一升，和匀，日日 \n细呷之。（《梅师方》） \n干呕不息∶蔗汁，温服半升，日三次。入姜汁更佳。（《肘后方》） \n疟疲瘵∶见前。眼暴赤肿，碜涩疼痛∶甘蔗汁二合，黄连半两，入铜器内慢火养浓， \n去滓，点之。（《普济》） \n虚热咳嗽，口干涕唾∶用甘蔗汁一升半，青粱米四合，煮粥，日食二次，极润心肺。（董 \n氏方） \n小儿口疳∶蔗皮烧研，掺之。（《简便方》） \n\\x滓\\x \n【主治】烧存性，研末，乌 油调，涂小儿头疮白秃，频涂取瘥。烧烟勿令入人目，能 \n使暗明（时珍）。 \n\n\n\n<目录>果部第三十三卷\\果之五\n\n<篇名>沙糖\n\n内容：（《唐本草》） \n【集解】恭曰∶沙糖，蜀地、西戎、江东并有之。榨甘蔗汁煎成，紫色。瑞曰∶稀者为 \n蔗糖，干者为沙糖，球者为球糖，饼者为糖饼。沙糖中凝结如石，破之如沙，透明白者，为 \n糖霜。 \n时珍曰∶此紫沙糖也。法出西域，唐太宗始遣人传其法入中国。以蔗汁过樟木槽，取而 \n煎成。清者为蔗糖，凝结有沙者为沙糖。漆瓮造成，如石、如霜、如冰者，为石蜜、为糖霜、 \n为冰糖也。紫糖亦可煎化，印成鸟兽果物之状，以充席献。今之货者，又多杂以米饧诸物， \n不可不知。 \n【气味】甘，寒，无毒。 \n恭曰∶冷利过于石蜜。 \n诜曰∶性温不冷。多食令人心痛，生长虫，消肌肉，损齿，发疳 。与鲫鱼同食，成疳 \n虫；与葵同食，生流 ；与笋同食， \n【主治】心腹热胀，口干渴（《唐本》）。润心肺大小肠热，解酒毒。腊月瓶封窖粪坑中， \n患天行热狂者，绞汁服，甚良（大明）。和中助脾 \n【发明】宗 曰∶蔗汁清，故费煎炼致紫黑色。今医家治暴热，多用为先导；兼啖驼、 \n马，解热。小儿多食则损齿生虫者，土制水， 虫属土，得甘即生也。 \n震亨曰∶糖生胃火，乃湿土生热，故能损齿生虫，与食枣病龋同意，非土制水也。 \n时珍曰∶沙糖性温，殊于蔗浆，故不宜多食。与鱼、笋之类同食，皆不益人。今人每用 \n为调和，徒取其适口，而不知阴受其害也。但其性能和脾缓肝，故治脾胃及泻肝药用为先导。 \n本草言其性寒，苏恭谓其冷利，皆昧此理。 \n【附方】旧一，新五。 \n下痢禁口∶沙糖半斤，乌梅一个，水二碗，煎一碗，时时饮之。（《摘玄方》） \n腹中紧胀∶白糖以酒三升，煮服之。不过再服。（《子母秘录》） \n痘不落痂∶沙糖，调新汲水一杯服之（白汤调亦可），日二服。（刘提点方） \n虎伤人疮∶水化沙糖一碗服，并涂之。（《摘玄方》）上气喘嗽，烦热，食即吐逆∶用沙 \n糖、姜汁等分，相和，慢煎二十沸，每咽半匙，取效。 \n食韭口臭∶沙糖解之。（《摘要方》） \n\n\n\n<目录>果部第三十三卷\\果之五\n\n<篇名>石蜜\n\n内容：（《唐本草》） \n【释名】白沙糖。 \n恭曰∶石蜜即乳糖也，与虫部石蜜同名。 \n时珍曰∶按∶万震《凉州异物志》云∶石蜜非石类，假石之名也。实乃甘蔗汁煎而曝之， \n则凝如石而体甚轻，故谓之石蜜也。 \n【集解】志约曰∶石蜜出益州及西戎，煎炼沙糖为之，可作饼块，黄白色。 \n恭曰∶石蜜用水、牛乳、米粉和煎成块，作饼坚重。西戎来者佳，江左亦有，殆胜于蜀。 \n诜曰∶自蜀中、波斯来者良。东吴亦有，不及两处者。皆煎蔗汁、牛乳，则易细白耳。 \n宗 曰∶石蜜，川、浙者最佳，其味浓，他处皆次之，煎炼以型象物，达京师。至夏月 \n及久阴雨，多自消化。土人先以竹叶及纸裹包，外用石夹埋之，不得见风，遂可免。今人谓 \n之乳糖。其作饼黄白色者，谓之捻糖，易消化，入药至少。 \n时珍曰∶石蜜，即白沙糖也。凝结作饼块如石者为石蜜，轻白如霜者为糖霜，坚白如冰 \n者为冰糖，皆一物有精粗之异也。以白糖煎化，模印成人物狮象之形者为飨糖，《后汉书注》 \n所谓猊糖是也。以石蜜和诸果仁，及橙橘皮、缩砂、薄荷之类，作成饼块者，为糖缠。以石 \n蜜和牛乳、酥酪作成饼块者，为乳糖。皆一物数变也。《唐本草》明言石蜜煎沙糖为之，而 \n诸注皆以乳糖即为石蜜，殊欠分明。按∶王灼《糖霜谱》云∶古者惟饮蔗浆，其后煎为蔗饧， \n又曝为石蜜，唐初以蔗为酒。而糖霜则自大历间有邹和尚者，来住蜀之遂宁伞山，始传造法。 \n故甘蔗所在植之，独有福建、四明、番禺、广汉、遂宁有冰糖，他处皆颗碎、色浅、味薄。 \n惟竹蔗绿嫩味浓，作霜最佳，西蔗次之。凡霜一瓮，其中品色亦自不同。惟叠如假山者为上， \n团枝次之，瓮鉴次之，小颗块又次之，沙脚为下；紫色及如水晶色者为上，深琥珀色次之， \n浅黄又次之，浅白为下。 \n【气味】甘，寒，冷利，无毒。 \n【主治】心腹热胀，口干渴（《唐本》）。治目中热膜，明目。和枣肉、巨胜末为丸噙之， \n润肺气，助五脏，生津（孟诜）。润心肺燥热，治嗽消痰，解酒和中，助 \n珍）。 \n【发明】震亨曰∶石蜜甘喜入脾，食多则害必生于脾。西北地高多燥，得之有益；东北 \n地下多湿，得之未有不病者，亦兼气之浓薄不同耳。 \n时珍曰∶石蜜、糖霜、冰糖，比之紫沙糖性稍平，功用相同，入药胜之。然不冷利，若 \n久食则助热、损齿、生虫之害同也。 \n\n\n\n<目录>果部第三十三卷\\果之五\n\n<篇名>刺蜜\n\n内容：（《拾遗》） \n【校正】自草部移入此。 \n【释名】草蜜（《拾遗》）、给 罗。 \n【集解】藏器曰∶交河沙中有草，头上有毛，毛中生蜜。胡人名为给 罗。 \n时珍曰∶按李延寿《北史》云∶高昌有草名羊刺，其上生蜜，味甚甘美。又《梁四公子 \n记》云∶高昌贡刺蜜。杰公云∶南平城羊刺无叶，其蜜色白而味甘；盐城羊刺叶大，其蜜色 \n青而味薄也。高昌即交河，在西番，今为火州。又段成式《酉阳杂俎》云∶北天竺国有蜜草， \n蔓生大叶，秋冬不死，因受霜露，遂成蜜也。又《大明一统志》云∶西番撒马儿罕地，有小 \n草丛生，叶细如蓝，秋露凝其上，味甘如蜜，可熬为饧，土人呼为达即古宾，盖甘露也。按 \n此二说，皆草蜜也，但不知其草即羊刺否也？又有KT 齐树，亦出蜜，云可入药而不得其 \n详， \n今附于下。 \n【附录】KT 齐（音别） 按∶段成式云∶KT 齐出波斯国，拂林国亦有之，名KT \n勃 \n梨佗（KT 音夺）。树长丈余，皮色青薄光净。叶似阿魏，生于枝端，一枝三叶。八月伐之， \n蜡月更抽新条。七月断其枝，有黄汁如蜜，微香，可以入药疗病也。 \n【气味】甘，平，无毒。 \n【主治】骨蒸发热痰嗽，暴痢下血，开胃止渴除烦（藏器）。 \n\n\n\n<目录>果部第三十三卷\n\n<篇名>果之六\n\n内容：（水果类六种） \n\n\n\n<目录>果部第三十三卷\\果之六\n\n<篇名>莲藕\n\n内容：（《本经》上品） \n【释名】其根藕（《尔雅》），其实莲（同上），其茎叶荷。 \n韩保升曰∶藕生水中，其叶名荷。按∶《尔雅》云∶荷，芙蕖。其茎茄，其叶 ，其本 \n，其华菡萏，其实莲，其根藕，其中 ， 中薏。邢 注云∶芙蕖，总名也，别名芙蓉， \n江东人呼为荷。菡萏，莲花也。 ，莲实也。薏， 中青心也。郭璞注云∶ ，乃茎下白 \n在泥中者。莲，乃房也； ，乃子也；薏，乃中心苦薏也。江东人呼荷花为芙蓉，北人以藕 \n为荷，亦以莲为荷，蜀人以藕为茄，此皆习俗传误也。陆机《诗疏》云∶其茎为荷。其花未 \n发为菡萏，已发为芙蕖。其实莲，莲之皮青里白。其子 \n分，为苦薏也。 \n时珍曰∶《尔雅》以荷为根名，韩氏以荷为叶名，陆机以荷为茎名。按∶茎乃负叶者也， \n有负荷之义，当从陆说。 乃嫩 ，如竹之行鞭者。节生二茎，一为叶，一为花，尽处乃生 \n藕，为花、叶、根、实之本。显仁藏用，功成不居，可谓退藏于密矣，故谓之 。花叶常偶 \n生，不偶不生，故根曰藕。或云藕善耕泥，故字从耦，耦者耕也。茄音加，加于 上也。 \n音遐，远于密也。菡萏，函合未发之意。芙蓉，敷布容艳之意。莲者连也，花实相连而出也。 \n者的也，子在房中点点如的也。的乃凡物点注之名。薏，犹意也，含苦在内也。古诗云∶ \n食子心无弃，苦心生意存是矣。 \n【集解】《别录》曰∶藕实茎生汝南池泽。八月采。 \n当之曰∶所在池泽皆有，豫章、汝南者良。苗高五、六尺，叶团青大如扇，其花赤，子 \n黑如羊矢。 \n时珍曰∶莲藕，荆、扬、豫、益诸处湖泽陂池皆有之。以莲子种者生迟，藕芽种者最易 \n发。其芽穿泥成白 ，即 也。长者至丈余，五、六月嫩时，没水取之，可作蔬茹，俗呼藕 \n丝菜。节生二茎∶一为藕荷，其叶贴水，其下旁行生藕也；一为芰荷，其叶出水，其旁茎生 \n花也。其叶清明后生。六、七月开花，花有红、白、粉红三色。花心有黄须，蕊长寸余，须 \n内即莲也。花褪连房成 ， 在房如蜂子在窠之状。六、七月采嫩者，生食脆美。至秋房枯 \n子黑，其坚如石，谓之石莲子。八、九月收之，斫去黑壳，货之四方，谓之莲肉。冬月至春 \n掘藕食之，藕白有孔有丝，大者如肱臂，长六、七尺，凡五、六节。大抵野生及红花者，莲 \n多藕劣；种植及白花者，莲少藕佳也。其花白者香，红者艳，千叶者不结实。别有合欢（并 \n头者），有夜舒荷（夜布昼卷）、睡莲（花夜入水）、金莲（花黄）、碧莲（花碧）、绣莲（花 \n如绣），皆是异种，故不述。《相感志》云∶荷梗塞穴鼠自 \n\\x莲实\\x \n【释名】藕实（《本经》）、 （《尔雅》）、 （音吸，同上）、石莲子（《别录》）、 \n经》）、泽芝（《古今注》）。 \n【修治】弘景曰∶藕实即莲子，八、九月采黑坚如石者，干捣破之。 \n颂曰∶其 至秋黑而沉水，为石莲子，可磨为饭食。 \n时珍曰∶石莲剁去黑壳，谓之莲肉。以水浸去赤皮、青心，生食甚佳。入药须蒸熟去心， \n或晒或焙干用。亦有每一斤，用 猪肚一个盛贮，煮熟捣焙用者。今药肆一种石莲子，状如 \n土石而味苦，不知何物也？ \n【气味】甘， \n时珍曰∶嫩 性平，石莲性温。得茯苓、山药、白术、枸杞子良。 \n诜曰∶生食过多，微动冷气胀人。蒸食甚良。大便燥涩者，不可食。 \n【主治】补中养神，益气力，除百疾。久服，轻身耐老，不饥延年（ \n不足，伤中气绝，益十二经脉血气（孟诜）。 \n止渴去热，安心止痢，治腰痛及泄精。多食令人欢喜（大明）。交心肾，浓肠胃，固精 \n气，强筋骨，补虚损，利耳目，除寒湿，止脾泄久痢，赤白浊，女人带下崩中诸血病（时珍）。 \n捣 \n碎和米作粥饭食，轻身益气，令人强健 \n【发明】时珍曰∶莲产于淤泥而不为泥染；居于水中而不为水没。根茎花实，凡品难同； \n清净济用，群美兼得。自 而节节生茎，生叶，生花，生藕；由菡萏而生蕊，生莲，生 ， \n生薏。其莲 则始而黄，黄而青，青而绿，绿而黑，中含白肉，内隐青心。石莲坚刚，可历 \n永久。薏藏生意，藕复萌芽，展转生生，造化不息。故释氏用为引譬，妙理具存；医家取为 \n服食，百病可却。盖莲之味甘气温而性啬，禀清芳之气，得稼穑之味，乃脾之果也。脾者， \n黄宫，所以交媾水、火，会合木、金者也。土为元气之母，母气既和，津液相成，神乃自生， \n久视耐老，此其权舆也。昔人治心肾不交，劳伤白浊，有清心莲子饮；补心肾，益精血，有 \n瑞莲丸，皆得此理。 \n藏器曰∶经秋正黑，名石莲子，入水必沉，惟煎盐卤能浮之。此物居山海间，经百年不 \n坏，人得食之，令发黑不老。 \n诜曰∶诸鸟、猿猴取得不食，藏之石室内，人得三百年者，食之永不老也。又雁食之， \n粪于田野山岩之中，不逢阴雨，经久不坏。人得之，每旦空腹食十枚，身轻能登高涉远也。 \n【附方】旧四，新十。 \n服食不饥∶诜曰∶石莲肉蒸熟去心，为末，炼蜜丸梧桐子大。日服三十丸。此仙家方也。 \n清心宁神∶宗 曰∶用莲蓬中干石莲子肉，于砂盆中擦去赤皮，留心，同为末，入龙脑， \n点 \n补中强志，益耳目聪明∶用莲实半两去皮心，研末，水煮熟，以粳米三合作粥，入末搅 \n匀食。（《圣惠方》） \n补虚益损∶水芝丹∶用莲实半升。酒浸二宿，以牙猪肚一个洗净，入莲在内，缝定煮熟， \n取出晒干为末，酒煮米糊丸梧桐子大。每服五十 \n小便频数，下焦真气虚弱者∶用上方，醋糊丸，服。 \n白浊遗精∶石莲肉、龙骨、益智仁等分。为末。每服二钱，空心米饮下。《普济》∶用莲 \n肉、白茯苓等分，为末。白汤调服。 \n心虚赤浊∶莲子六一汤∶用石莲肉六两，炙甘草一两，为末。每服一钱，灯心汤下。（《直 \n指方》） \n久痢禁口∶石莲肉炒为末。每服二钱，陈仓米汤调下，便觉思食，甚妙。加入香连丸， \n尤妙。（《丹溪心法》） \n脾泄肠滑∶方同上。 \n哕逆不止∶石莲肉六枚，炒赤黄色，研末。冷熟水半盏和服，便止。（苏颂《图经》） \n产后咳逆、呕吐，心忡目晕∶用石莲子两半，白茯苓一两，丁香五钱。为末。每米饮服二钱 \n。（《良方补遗》） \n眼赤作痛∶莲实（去皮研末）一盏，粳米半升，以水煮粥，常食。（《普济方》） \n小儿热渴∶莲实二十枚（炒），浮萍二钱半，生姜少许，水煎，分三服。（《圣济总录》） \n反胃吐食∶石莲肉为末，入少肉豆寇末，米汤调服之。（《直指方》） \n\\x藕\\x \n【气味】甘，平，无毒。大明曰∶温。 \n时珍曰∶《相感志》云∶藕以盐水共食，则不损口；同油炸面米果食，则无渣。煮忌铁 \n器。 \n【主治】热渴，散留血，生肌。久服令人心欢（《别录》）。止怒止泄，消食解酒毒，及 \n病后干渴（藏器）。捣汁服，止闷除烦开胃，治霍乱，破产后血闷，捣膏， 金疮并伤折， \n止暴痛。蒸煮食之，大能开胃（大明）。生食，治霍乱后虚渴。蒸食，甚补五脏，实下焦。 \n同蜜食，令人腹脏肥，不生诸虫，亦可休粮（孟诜）。汁∶解射罔毒、蟹毒（徐之才）。捣浸 \n澄粉服食 \n【发明】弘景曰∶根入神仙家。宋时太官作血KT （音勘），庖人削藕皮误落血中，遂 \n散涣不凝。故医家用以破血多效也。KT 者，血羹也。 \n诜曰∶产后忌生冷物，独藕不同生冷者，为能破血也。 \n时珍曰∶白花藕大而孔扁者，生食味甘，煮食不美；红花及野藕，生食味涩，煮蒸则佳。 \n夫藕生于卑污，而洁白自若。质柔而穿坚，居下而有节。孔窍玲珑，丝纶内隐。生于嫩 ， \n而发为茎、叶、花、实，又复生芽，以续生生之脉。四时可食，令人心欢，可谓灵根矣。故 \n其所主者，皆心脾血分之疾，与莲之功稍不同云。 \n【附方】旧四，新八。 \n时气烦渴∶生藕汁一盏，生蜜一合，和匀，细服。（《圣惠》） \n伤寒口干∶生藕汁、生地黄汁、童子小便各半盏 \n霍乱烦渴∶藕汁一钟，姜汁半钟。和匀饮。（《圣济总录》） \n霍乱吐利∶生藕，捣汁服。（《圣惠》） \n上焦痰热∶藕汁、梨汁各半盏。和服。（《简便》） \n产后闷乱，血气上冲，口干腹痛∶《梅师方》∶用生藕汁三升，饮之。庞安时∶用藕汁、 \n生地黄汁、童子小便等分，煎服。 \n小便热淋∶生藕汁、生地黄汁、葡萄汁各等分。每服 盏，入蜜温服。 \n坠马血瘀，积在胸腹，唾血无数者∶干藕根为末。酒服方寸匕，日二次。（《千金方》） \n食蟹中毒∶生藕汁饮之。（《圣惠》） \n冻脚裂坼∶蒸熟藕，捣烂涂之。 \n尘芒入目∶大藕洗捣，绵裹，滴汁入目中，即出也。（《普济方》） \n\\x藕 \\x \n【释名】藕丝菜（五、六月嫩时，采为蔬 \n【气味】甘，平，无毒。 \n【主治】生食，主霍乱后虚渴烦闷不能食，解酒食毒（苏颂）。 \n功与藕同（时珍）。解烦毒，下瘀血（汪颖）。 \n\\x藕节\\x \n【气味】涩，平，无毒。 \n大明曰∶冷。伏硫黄。 \n【主治】捣汁饮，主吐血不止，及口鼻出血（甄权）。消瘀血，解热毒。产后血闷，和 \n地黄研汁 \n【发明】时珍曰∶一男子病血淋，痛胀祈死。予以藕汁调发灰，每服二钱，服三日而血 \n止痛除。按∶赵 《养 漫笔》云∶宋孝宗患痢，众医不效。高宗偶见一小药肆，召而问之。 \n其人问得病之由，乃食湖蟹所致。遂诊脉，曰∶此冷痢也。乃用新采藕节捣烂，热酒调下， \n数服即愈。高宗大喜，就以捣药金杵臼赐之，人遂称为金杵臼严防御家，可谓不世之遇也。 \n大抵藕能消瘀血，解热开胃，而又解蟹毒故也。 \n【附方】新五。 \n鼻衄不止∶藕节捣汁饮，并滴鼻中。 \n猝暴吐血∶双荷散∶用藕节、荷蒂各七个，以蜜少许擂烂，用水二钟，煎八分，去滓， \n温服。或为末丸服亦可。（《圣惠》） \n大便下血∶藕节晒干研末，人参、白蜜煎汤，调服二钱，日二服。（《全幼心鉴》） \n遗精白浊，心虚不宁∶金锁玉关丸∶用藕节、莲花须、莲子肉、芡实肉、山药、白茯苓、 \n白茯神各二两，为末。用金樱子二斤捶碎，以水一斗，熬八分，去滓，再熬成膏，入少面和 \n药，丸梧桐子大。每服七十丸，米饮下。 \n鼻渊脑泻∶藕节、芎 ，焙研为末。每服二钱，米饮下。（《普济》） \n\\x莲薏\\x（即莲子中青心也） \n【释名】苦薏。 \n【气味】苦，寒，无毒。 \n藏器曰∶食莲子不去心，令人作吐。 \n【主治】血渴，产后渴，生研末，米饮服二钱，立愈（士良）。止霍乱（大明）。清心去 \n热（时珍。出《统旨》）。 \n【附方】新二。 \n劳心吐血∶莲子心七个，糯米二十一粒，为末，酒服。此临安张上舍方也。（《是斋百 \n一方 \n小便遗精∶莲子心一撮。为末，入辰砂一分。每服一钱，白汤下，日二。（《医林集要》） \n\\x莲蕊须\\x \n【释名】佛座须（花开时采取，阴干，亦可充果食）。 \n【气味】甘，涩，温，无毒。 \n大明曰∶忌地黄、葱、蒜。 \n【主治】清心通肾，固精气，乌须发，悦颜色，益血，止血崩、吐血（时珍）。 \n【发明】时珍曰∶莲须本草不收，而《三因》诸方、固真丸、巨胜子丸各补益方中，往 \n往用之。其功大抵与莲子同也。 \n【附方】新一。 \n久近痔漏三十年者，三服除根。用莲花蕊、黑牵牛头末各一两半，当归五钱，为末。每 \n空心酒服二钱。忌热物。五日见效。（孙氏《集效方》） \n\\x莲花\\x \n【释名】芙蓉（《古今注》）、芙蕖（同 \n【气味】苦、甘，温，无毒。忌地黄、葱、蒜。 \n【主治】镇心益色。驻颜轻身（大明）。 \n弘景曰∶花入神仙家用，入香尤妙。 \n【附方】旧二，新二。 \n服食驻颜∶七月七日采莲花七分，八月八日采根八分，九月九日采实九分，阴干捣筛。 \n每服方寸匕，温酒调服。（《太清草木方》） \n天 湿疮∶荷花贴之。（《简便方》） \n难产催生∶莲花一瓣，书人字，吞之，即易产。（《肘后方》） \n坠损呕血∶坠跌积血心胃，呕血不止。用干荷花为末，每酒服方寸匕，其效如神。（杨 \n拱《医方摘要》） \n\\x莲房\\x \n【释名】莲蓬壳（陈久者良）。 \n【气味】苦，涩，温，无毒。 \n【主治】破血（孟诜）。治血胀腹痛，及产后胎衣不下，酒煮服之。水煮服之，解野菌 \n毒 \n【发明】时珍曰∶莲房入厥阴血分，消瘀散血，与荷叶同功，亦急则治标之意也。 \n【附方】新六。 \n经血不止∶瑞莲散∶用陈莲蓬壳烧存性，研末。每服二钱，热酒下。（《妇人经验方》） \n血崩不止，不拘冷热∶用莲蓬壳、荆芥穗各（烧存性） \n等分为末。每服二钱，米饮下。（《圣惠方》） \n产后血崩∶莲蓬壳五个，香附二两，各烧存性，为末。每服二钱，米饮下，日二。（《妇 \n人良方》） \n漏胎下血∶莲房烧研，面糊丸梧桐子大。每服百丸，汤、酒任下，日二。（《朱氏集验 \n方》） \n小便血淋∶莲房烧存性，为末，入麝香少许。每服二钱半，米饮调下，日二。（《经验 \n方》） \n天 湿疮∶莲蓬壳烧存性，研末，井泥调涂，神效。（《海上方》） \n\\x荷叶\\x \n【释名】嫩者荷钱（象形）。贴水者藕荷（生藕者）。出水者芰荷（生花者）。蒂名荷鼻。 \n【修治】大明曰∶入药并炙用。 \n【气味】苦，平，无毒。 \n时珍曰∶畏桐油。伏白银，伏硫黄。 \n【主治】止渴，落胞破血，治产后口干，心肺躁烦（大明）。治血胀腹痛，产后胎衣不 \n下，酒煮服之。荷鼻∶安胎，去恶血，留好血，止血痢，杀菌蕈毒，并煮水服（藏器）。生 \n发元气，裨助脾胃，涩精滑，散瘀血，消水肿痈肿，发痘疮，治吐血咯血衄血，下血溺血血 \n淋，崩中产后恶血，损伤败血（时珍）。 \n【发明】 \n杲曰∶洁古张先生口授枳术丸方，用荷叶烧饭为丸。当时未悟其理，老年味之始得。夫 \n震者动也，人感之生足少阳甲胆，是属风木，为生化万物之根蒂。人之饮食入胃，营气上行， \n即少阳甲胆之气，与手少阳三焦元气，同为生发之气。《素问》云∶履端于始，序则不愆。 \n荷叶生于水土之下，污秽之中，挺然独立。其色青，其形仰，其中空，象震卦之体。食药感 \n此气之化，胃气何由不升乎？用此为引，可谓远识合道矣。更以烧饭和药，与白术协力滋养， \n补令胃浓，不致内伤，其 \n时珍曰∶烧饭见谷部饭下。按∶《东垣试效方》云∶雷头风症，头面疙瘩肿痛，憎寒发 \n热，状如伤寒，病在三阳，不可过用寒药重剂，诛伐无过。一人病此，诸药不效，余处清震 \n汤治之而愈。用荷叶一枚，升麻五钱，苍术五钱，水煎温服。盖震为雷，而荷叶之形象震体， \n其色又青，乃涉类象形之义也。又案∶闻人规《痘疹八十一论》云∶痘疮已出，复为风寒外 \n袭，则窍闭血凝，其点不长，或变黑色，此为倒 ，必身痛，四肢微厥。但温肌散邪，则热 \n气复行，而斑自出也。宜紫背荷叶散治之。盖荷叶能升发阳气，散瘀血，留好血，僵蚕能解 \n结滞之气故也。此药易得，而活人甚多，胜于人牙、龙脑也。又戴原礼《证治要诀》云∶荷 \n叶服之，令人瘦劣，故单服可以消阳水浮肿之气。 \n【附方】 \n旧四，新二十三。 \n阳水浮肿∶败荷叶，烧存性，研末。每服二钱，米饮调下，日三服。（《证治要诀》） \n脚膝浮肿∶荷叶心、 本等分，煎汤，淋洗之。（《永类方》） \n痘疮倒 ∶紫背荷叶散，又名南金散∶治风寒外袭倒 势危者，万无一失。用霜后荷叶 \n（贴水紫背者，炙干）、白僵蚕直者炒去丝等分为末。每服半钱，用胡荽汤或温酒调下。（闻 \n人规《痘疹论》） \n诸般痈肿，拔毒止痛∶荷叶中心蒂如钱者，不拘多少，煎汤淋洗，拭干，以飞过寒水石， \n同腊猪脂涂之。又治痈肿，柞木饮方中亦用之。（《本事方》） \n打扑损伤，恶血攻心，闷乱疼痛者∶以干荷叶五片，烧存性，为末。每服三钱，童子热 \n尿一盏，食前调下，日三服，利下恶物为度。（《圣惠方》） \n产后心痛，恶血不尽也∶荷叶炒香为末。每服方寸匕，沸汤或童子小便调下。或烧灰、 \n或煎汁皆可。（《救急 \n胎衣不下∶方同上。伤寒产后，血晕欲死∶用荷叶、红花、姜黄等分，炒研末。童子小 \n便调服二钱。（庞安常《伤寒论》） \n孕妇伤寒∶大热烦渴，恐伤胎气。用嫩卷荷叶（焙）半两，蚌粉二钱半。 \n为末。每服三钱，新汲水入蜜调服，并涂腹上。名罩胎散。（郑氏方）妊娠胎动，已见 \n黄水者∶干荷蒂一枚炙，研为末。糯米淘汁一钟，调服即安。（唐氏《经 \n吐血不止∶嫩荷叶七个，擂水服之，甚佳。又方∶干荷叶、生蒲黄等分，为末。每服三 \n钱，桑白皮煎汤调下。《 \n吐血咯血∶《经验后方》∶荷叶焙干，为末。米汤调服二钱，一日二服，以知为度。《圣 \n济总录》∶用败荷叶、蒲黄各一两，为末。每服二 \n吐血衄血∶阳乘于阴，血热妄行，宜服四生丸。陈日华云∶屡用得效。用生荷叶、生艾 \n叶、生柏叶、生地黄等分，捣烂，丸鸡子大。每服一丸，水三盏，煎一盏，去滓服。（《济 \n生方》） \n崩中下血∶荷叶（烧研）半两，蒲黄、黄芩各一两，为末。每空心酒服三钱。 \n血痢不止∶荷叶蒂，水煮汁，服之。（《普济方》） \n下痢赤白∶荷叶烧研。每服二钱，红痢蜜；白痢沙糖汤下。 \n脱肛不收∶贴水荷叶焙研，酒服二钱，仍以荷叶盛末坐之。（《经验良方》）牙齿疼痛∶ \n青荷叶剪取钱蒂七个，以浓米醋一盏，煎半盏，去滓，熬成膏，时时抹之妙。（唐氏《经验 \n方》） \n赤游火丹∶新生荷叶，捣烂，入盐涂之。（《摘玄方》） \n漆疮作痒∶干荷叶，煎汤，洗之，良。（《集验方》） \n遍身风疠∶荷叶三十枚，锻石一斗。淋汁合煮，渍之，半日乃出。数日一作，良。（ \n《圣惠方》） \n偏头风痛∶升麻、苍术各一两，荷叶一个，水二钟，煎一钟，食后温服。或烧荷叶一个 \n，为末，以煎汁调服。（《简便方》） \n刀斧伤疮∶荷叶烧研，搽之。（《集简方》） \n阴肿痛痒∶荷叶、浮萍、蛇床等分。煎水，日洗之。（《医垒元戎》） \n\n\n\n<目录>果部第三十三卷\\果之六\n\n<篇名>红白莲花\n\n内容：（《拾遗》） \n【校正】自草部移入此。 \n【集解】藏器曰∶红莲花、白莲花，生西国，胡人将来也。 \n时珍曰∶此不知即莲花否？而功与莲同，以类相从，姑移入此。 \n【气味】甘，平，无毒。 \n【主治】久服，令人好颜色，变白却老（藏器）。 \n\n\n\n<目录>果部第三十三卷\\果之六\n\n<篇名>芰实\n\n内容：（音妓。《别录》上品） \n【释名】菱（《别录》）、水栗（风俗通） \n时珍曰∶其叶支散，故字从支。其角棱峭，故谓之菱，而俗呼为菱角也。昔人多不分别， \n惟伍安贫《武陵记》以三角、四角者为芰，两角者为菱。《左传》屈到嗜芰，即此物也。《尔 \n雅》谓之厥 （音眉）。又许慎《说文》云∶菱，楚谓之芰，秦谓之 。杨氏《丹铅录》 \n以 \n芰为鸡头，引《离骚》缉芰荷以为衣，言菱叶不可缉衣，皆误矣。案∶《尔雅》 乃决明 \n之名，非厥 也。又《埤雅》芰荷乃藕上出水生花之茎，非鸡头也。与菱同名异物。许、杨 \n二氏失于详考 \n【集解】弘景曰∶芰实，庐、江间最多，皆取火燔以为米充粮， \n颂曰∶菱，处处有之。叶浮水上，花黄白色，花落而实生，渐向水中乃熟。实有二种∶ \n一种四角，一种两角。两角中又有嫩皮而紫色者，谓之浮菱，食之尤美。江淮及山东人曝其 \n实以为米，代粮。 \n时珍曰∶芰菱有湖泺处则有之。菱落泥中，最易生发。有野菱、家菱，皆三月生蔓延引。 \n叶浮水上，扁而有尖，光面如镜。叶下之茎有股如虾股，一茎一叶，两两相差，如蝶翅状。 \n五、六月开小白花，背日而生，昼合宵炕，随月转移。其实有数种∶或三角、四角，或两角 \n、无角。野菱自生湖中，叶、实俱小。其角硬直刺人，其色嫩青老黑。嫩时剥食甘美，老则 \n蒸煮食之。野人曝干，剁米为饭为粥，为糕为果，皆可代粮。其茎亦可曝收，和米作饭，以 \n度荒歉，盖泽农有利之物也。家菱种于陂塘，叶、实俱大，角软而脆，亦有两角弯卷如弓形 \n者，其色有青、有红、有紫，嫩时剥食，皮脆肉美，盖佳果也。老则壳黑而硬，坠入江中， \n谓之乌菱。冬月取之，风干为果，生、熟皆佳。夏月以粪水浇其叶，则实更肥美。按段成式 \n《酉阳杂俎》云∶苏州折腰菱，多两角。荆州郢城菱，三角无刺，可以按莎。汉武帝昆明池 \n有浮根菱，亦曰青水菱，叶没水下，根出水上。或云∶玄都有鸡翔菱，碧色，状如鸡飞，仙 \n人凫伯子常食之。 \n【气味】甘，平，无毒。 \n诜曰∶生食，性冷利。多食，伤人脏腑，损阳气，痿茎，生蛲虫。水族中此物最不治病。 \n若过食腹胀者，可暖姜酒服之即消，亦可含吴茱萸咽津。 \n时珍曰∶《仇池笔记》言∶菱花开背日，芡花开向日，故菱寒而芡暖。《别录》言芰实性 \n平，岂 \n【主治】安中补五脏，不饥轻身（《别录》）。蒸曝，和蜜饵之，断谷长生（弘景）。解丹 \n石毒（苏颂）。鲜者， \n捣烂澄粉食，补中延年（ 仙）。 \n\\x芰花\\x \n【气味】涩。 \n【主治】入染须发方（时珍）。 \n\\x乌菱壳\\x \n【主治】入染须发方，亦止泄痢（时珍）。 \n\n\n\n<目录>果部第三十三卷\\果之六\n\n<篇名>芡实\n\n内容：（音俭。《本经》上品） \n【释名】鸡头（《本经》）、雁喙（同）、雁头（《古今注》）、鸿头（韩退之）、鸡雍（《庄 \n子》）、卯菱（《管子》）、 子（音唯）、水流黄。 \n弘景曰∶此即今 子也。茎上花似鸡冠，故名鸡头。 \n颂曰∶其苞形类鸡、雁头，故有诸名。 \n时珍曰∶芡可济俭歉，故谓之芡。鸡雍见《庄子·徐无鬼篇》。卯菱见《管子·五行篇》。 \n扬雄《方言》云∶南楚谓之鸡头，幽燕谓之雁头，徐、青、淮、泗谓之芡子。其茎谓之 ， \n亦曰 。郑樵《通志》以钩 为芡，误矣。钩 ，陆生草也，其茎可食。水流黄见下。 \n【集解】《别录》曰∶鸡头实生雷泽池泽。八月采之。 \n保升曰∶苗生水中，叶大如荷，皱而有刺。花子若拳大，形似鸡头。实若石榴，其皮青 \n黑，肉白如菱米也。 \n颂曰∶处处有之，生水泽中。其叶俗名鸡头盘，花下结实。其茎嫩者名 ，亦名 菜， \n人采为蔬茹。 \n宗 曰∶天下皆有之。临水居人，采子去皮，捣仁为粉，蒸炸作饼，可以代粮。 \n时珍曰∶芡茎三月生叶贴水，大于荷叶，皱纹如 ，蹙衄如沸，面青背紫，茎、叶皆有 \n刺。其茎长至丈余，中亦有孔有丝，嫩者剥皮可食。五六月生紫花，花开向日结苞，外有青 \n刺，如 刺及栗球之形。花在苞顶，亦如鸡喙及 喙。剥开内有斑驳软肉裹子，累累如珠玑。 \n壳内白米，状如鱼目。深秋老时，泽农广收，烂取芡子，藏至 石，以备歉荒。其根状如三 \n棱，煮食如芋。 \n【修治】诜曰∶凡用蒸熟，烈日晒裂取仁，亦可舂取粉用。 \n时珍曰∶新者煮食良。入涩精药，连壳用亦可。案∶刘 《暇日记》云∶芡实一斗，以 \n防风四两煎汤浸过用，且经久不坏。 \n【气味】甘，平，涩，无毒。 \n弘景曰∶小儿多食，令不长。 \n诜曰∶生食多，动风冷气。 \n宗 曰∶食多，不益脾胃，兼难消化。 \n【主治】湿痹，腰脊膝痛，补中，除暴疾，益精气，强志，令耳目聪明。久服，轻身不 \n饥，耐老神仙（《本经》）。开胃助气（《日华》）。止渴益肾，治小便不禁，遗精白浊带下（时 \n珍）。 \n【发明】弘景曰∶《仙方》取此合莲实饵之，甚益人。 \n恭曰∶作粉食，益人胜于菱也。 \n颂曰∶取其实及中子，捣烂曝干，再捣筛末，熬金樱子煎和丸服之，云补下益人，谓之 \n水陆丹。 \n时珍曰∶案孙升《谈圃》云∶芡本不益人，而俗谓之水流黄何也？盖人之食芡，必咀 \n之，终日嗫嗫。而芡味甘平，腴而不腻。食之者能使华液流通，转相灌溉，其功胜于乳石 \n也。《淮南子》云∶狸头愈 ，鸡头已 。注者云∶即芡实也。 \n【附方】旧一，新三。 \n鸡头粥∶益精气，强志意，利耳目。鸡头实三合（煮熟去壳），粳米一合煮粥，日日空 \n心食。（《经验后方》） \n玉锁丹∶治精气虚滑。用芡实、莲茎（方见藕节下）。 \n四精丸∶治思虑、色欲过度，损伤心气，小便数，遗精。用秋石、白茯苓、芡实、莲肉 \n各二两，为末，蒸枣和丸梧桐子大。每服三十丸，空心盐汤送下。（《永类方》） \n厘清丸∶治浊病。用芡实粉、白茯苓粉，黄蜡化蜜和，丸梧桐子大。每服百丸，盐汤下。 \n（《摘玄方 \n\\x鸡头菜即 菜\\x（芡茎也） \n【 \n【主治】止烦渴，除虚热，生熟皆宜（时珍）。 \n\\x根\\x \n【气味】同茎。 \n【主治】小腹结气痛，煮食之（士良）。 \n【附方】新一。 \n偏坠气块∶鸡头根切片煮熟，盐、醋食之。（《法天生意》） \n\n\n\n<目录>果部第三十三卷\\果之六\n\n<篇名>乌芋\n\n内容：（《别录》中品） \n【释名】凫茈（音疵）、凫茨（音瓷）、荸荠（《衍义》）、黑三棱（《博济方》）、芍（音晓）。 \n地栗（郑樵《通志》）。 \n时珍曰∶乌芋，其根如芋而色乌也。凫喜食之，故《尔雅》名凫茈，后遂讹为凫茨，又 \n讹为荸荠。盖切韵凫、荸同一字母，音相近也。三棱、地栗，皆形似也。 \n瑞曰∶小者名凫茈，大者名地栗。 \n【集解】颂曰∶乌芋，今凫茨也。苗似龙须而细，色正青。根如指头大，黑色，皮浓有 \n毛。又有一种皮薄无毛者，亦同。田中人并食之。 \n宗 曰∶皮浓色黑，肉硬而白者，谓之猪荸荠。皮薄泽，色淡紫，肉软而脆者，谓之羊 \n荸荠。正二月，人采食之。此二等药 \n时珍曰∶凫茈生浅水田中。其苗三、四月出土，一茎直上，无枝叶，状如龙须。肥田栽 \n者，粗近葱、蒲，高二、三尺。其根白 ，秋后结颗，大如山楂、栗子，而脐有聚毛，累累 \n下生入泥底。野生者，黑而小，食之多滓。种出者，紫而大，食之多毛。吴人以沃田种之， \n三月下种，霜后苗枯，冬春掘收为果，生食、煮食皆良。 \n【正误】《别录》曰∶乌芋，一名借姑。二月生叶如芋。三月三日采 \n弘景曰∶借姑生水田中。叶有丫，状如泽泻，不正似芋。其根黄，似芋子而小，疑有乌 \n者，根极相似，细而美。叶状如苋，草呼为凫茨，恐即此也。 \n恭曰∶乌芋一名槎丫，一名慈菇。 \n时珍曰∶乌芋、慈菇原是二物。慈菇有叶，其根散生。乌芋有茎无叶，其根下生。气味 \n不同，主治亦异。而《别录》误以借菇为乌芋，谓其叶如芋。陶、苏二氏因凫茨、慈菇字音 \n相近，遂致混注， \n\\x根\\x \n【气味】甘，微寒，滑，无毒。 \n诜曰∶性冷。先有冷气人不可食，令人腹胀气满。小儿秋月食多，脐下结痛也。 \n【主治】消渴痹热，温中益气（《别录》）。下丹石，消风毒，除胸中实热气。可作粉食， \n明耳目，消黄胆（孟诜）。开胃下食（大明）。作粉食，浓人肠胃，不饥，能解毒，服金石人 \n宜 \n之（苏颂）。疗五种膈气，消宿食，饭后宜食之。治误吞铜物（汪机）。主血痢下血血崩，辟 \n蛊毒（时珍）。 \n【发明】机曰∶乌芋善毁铜，合铜钱嚼之，则钱化，可见其为消坚削积之物。故能化五 \n种膈疾，而消宿食，治误吞铜也，时珍曰∶按∶王氏《博济方》∶治五积、冷气攻心、变为 \n五膈诸病，金锁丸中用黑三棱。注云∶即凫茈干者。则汪氏所谓消坚之说，盖本于此。又董 \n炳《集验方》云∶地栗晒干为末，白汤每服二钱，能辟蛊毒。传闻下蛊之家，知有此物，便 \n不敢下。此亦前人所未知者。 \n【附方】新五。 \n大便下血∶荸荠捣汁大半钟，好酒半钟，空心温服。三日见效。（《神秘方》）下痢赤白∶ \n午日午时取完好荸荠，洗净拭干，勿令损破，于瓶内入好烧酒浸之，黄泥密封收贮。遇有患 \n者，取二枚细嚼，空心用原酒送下。（唐瑶《经验方》）妇人血崩∶凫茈一岁一个，烧存性， \n研末，酒服之。（李氏方）小儿口疮∶用荸荠烧存性，研末，掺之。（杨起《简便方》）误吞 \n铜钱∶生凫茈，研汁，细细呷之，自然消化成水。（王 《百一选方》） \n\n\n\n<目录>果部第三十三卷\\果之六\n\n<篇名>慈菇\n\n内容：（《日华》） \n【校正】原混乌芋下，今分出。仍并入《图经》外类剪刀草。 \n【释名】借姑（《别录》）、水萍（《别录》）、河凫茈（《图经》）、白地栗（同上），苗名 \n剪刀草 \n根岁生十二子，如慈菇之乳诸子，故以名之。作茨菰者非矣。河凫茈、白地栗，所以别乌芋 \n之凫茈、地栗也。剪刀、箭搭、槎丫、燕 \n【集解】《别录》曰∶借姑，三月三日采根，曝干。 \n弘景曰∶借姑生水田中。叶有丫，状如泽泻。其根黄，似芋子而小，煮之可啖。 \n恭曰∶慈菇生水中。叶似 箭之镞，泽泻之类也。 \n颂曰∶剪刀草，生江湖及汴洛近水河沟沙碛中。叶如剪刀形。茎干似嫩蒲，又似三棱。 \n苗甚软，其色深青绿。每丛十余茎，内抽出一、两茎，上分枝，开小白花，四瓣，蕊深黄色。 \n根大者如杏，小者如栗，色白而莹滑。五、六、七月采叶，正、二月采根，即慈菇也。煮熟 \n味甘甜 \n时珍曰∶慈姑生浅水中，人亦种之。三月生苗，青茎中空，其外有棱。叶如燕尾，前尖 \n后歧。霜后叶枯，根乃练结，冬及春初，掘以为果，须灰汤煮熟，去皮食，乃不麻涩戟人咽 \n也。嫩茎亦可炸食。又取汁，可制粉霜、雌黄。又有山慈菇，名同实异，见草部。 \n\\x根\\x \n【气味】苦、甘，微寒，无毒。 \n大明曰∶冷，有毒。多食，发虚热，及肠风痔漏，崩中带下，疮疖。以生姜同煮佳。怀 \n孕人不可食。诜曰∶吴人常食之，令人发香港脚瘫缓风，损齿失颜色，皮肉干燥。猝食之，使 \n人干呕也。 \n【主治】百毒，产后血闷，攻心欲死，产难胞衣不出，捣汁服一升。又下石淋（苏恭）。 \n\\x叶\\x \n【主治】诸恶疮肿，小儿游瘤丹毒，捣烂涂之，即便消退，甚佳（苏颂）。治蛇、 \n虫咬，捣烂封之（大明）。调蚌粉， \n\n\n\n<目录>果部第三十三卷\\果之六\n\n<篇名>附录诸果\n\n内容：（《纲目》二十一种，《拾遗》一种） \n时珍曰∶方册所记诸果，名品甚多，不能详其性、味、状。既列于果，则养生者不可不 \n知，因略采附以俟。 \n津符子 时珍曰∶孙真人《千金方》云∶味苦，平，滑。多食 \n必思答 又曰∶忽思慧《饮膳正要》云∶味甘， \n甘剑子 又曰∶范成大《桂海志》云∶状似巴榄子，仁附肉，有白靥，不可食，发人病。 \n北人呼为海胡桃是也。 \n味甘无奇，色青黄，长四、五寸。 \n海梧子 又曰∶嵇含《南方草木状》云∶出林邑。树似梧桐，色白。叶似青桐。其子如 \n大栗，肥甘可食。 \n木竹子 又曰∶《桂海志》云∶皮色形状全似大枇杷，肉味甘美，秋 \n橹罟子 又曰∶《桂海志》云∶大如半升碗，数十房攒聚成球，每房有缝。冬生青，至 \n夏红。破其瓣食之，微甘。出广西。 \n罗晃子 又曰∶《桂海志》云∶状如橄榄，其皮七重。出广西。顾 《海槎录》云∶横 \n州出 \n子 又曰∶徐表《南州记》云∶出九真、交趾。树生子如桃实，长寸余。二月开花， \n连着子，五月熟，色黄。盐藏食之，味酸似梅。 \n夫编子 又曰∶《南州记》云∶树生交趾山谷。三月开花，仍连着子，五、六月熟。入 \n鸡、鱼、猪、鸭羹中，味美，亦可盐藏。 \n白缘子 又曰∶刘欣期《交州记》云∶出交趾。树高丈余，实味甘美如 \n系弥子 又曰∶郭义恭《广志》云∶状圆而细，赤如软枣。其味初苦后 \n人面子 又曰∶《草木状》云∶出南海。树似含桃。子如桃实，无味， \n其核正如人面，可玩。祝穆《方舆胜览》云∶出广中。大如梅李。春花、夏实、秋熟，蜜煎 \n甘酸可食 \n黄皮果 又曰∶《海槎录》云∶出广西横州。状如楝子及小枣而味酸。 \n四味果 又曰∶段成式《酉阳杂俎》云∶出祁连山。木生如枣。剖以竹刀则甘，铁刀则 \n苦，木刀则酸，芦刀则辛。行旅得之，能止饥渴。 \n千岁子 又曰∶《草木状》云∶出交趾。蔓生。子在根下，须绿色，交加如织。一苞恒 \n二百余颗，皮壳青黄色。壳中有肉如栗，味亦如之。干则壳肉相离，撼之有声。《桂海志》 \n云∶状似青黄李，味甘。 \n侯骚子 又曰∶《酉阳杂俎》云∶蔓生，子大如鸡卵，既甘且冷，消酒轻身。王太仆曾 \n献之。 \n酒杯藤子 又曰∶崔豹《古今注》云∶出西域。藤大如臂。花坚硬，可以酌酒，文章映 \n澈。实大如指，味如豆蔻，食之消酒。张骞得其种于大宛。 \n（音间）子 又曰∶贾思勰《齐民要术》云∶藤，生交趾、合浦。缘树木，正二、月 \n花， \n四、五月熟，实如梨，赤如鸡冠，核如鱼鳞。生食，味淡 \n山枣 又曰∶《寰宇志》云∶出广西肇庆府。叶似梅，果似荔枝，九月 \n隈支 又曰∶宋祁《益州方物图》云∶生邛州山谷中。树高丈余，枝修而弱。开白花。 \n实大若雀卵，状似荔枝，肉黄肤甘。 \n\\x灵床上果子\\x（《拾遗》） \n藏器云∶入夜谵语，食之即止。 \n\n\n\n<目录>果部第三十三卷\\果之六\n\n<篇名>诸果有毒\n\n内容：（《拾遗》） \n凡果未成核者，食之令人发痈疖及寒热。 \n凡果落地有恶虫缘过者，食之令人患九漏。 \n凡果双仁者，有毒杀人。 \n凡瓜双蒂者，有毒杀人；沉水者，杀人。 \n凡果忽有异常者，根下必有毒蛇，食之杀人。 \n互考楮实 梧桐子 枸杞子 金樱子 山茱萸 桑椹 木半夏 胡颓子 松花 桂花 \n栎实（已上木部） 黄 \n覆盆子（已上草部） \n\n\n\n<目录>\n\n<篇名>木部第三十四卷\n\n内容：李时珍曰∶木乃植物，五行之一。性有土宜，山谷原隰。肇由气化，爰受形质。乔条苞 \n灌，根叶华实。坚脆美恶，各具太极。色香气味，区辨品类。食备果蔬，材充药器。寒 \n温毒良，直有考汇。多识其名，奚止读诗。埤以本草，益启其知。乃肆搜猎，萃而类之。是 \n为木部，凡一百八十种，分为六类∶曰香，曰乔，曰灌，曰寓，曰苞，曰杂。旧本木部三品， \n共二百六十三种。今并入二十五种，移一十四种入草部，二十九种入蔓草，三十一种入果部， \n三种入菜部，一十六种入器用部，二种入虫部。自草部移入二种，外类有名未用移入十一种。 \n《神农本草经》四十四种（梁陶弘景注） 《名医别录》二十三种（梁陶弘景注） 《唐 \n本草》二十二种（唐苏恭） 《本草拾遗》 \n（唐李 ） 《蜀本草》一种（蜀韩保升） 《开宝本草》一十五种（宋马志） 《嘉 本 \n草》六种（宋掌禹锡） 《图经本草》一种（宋苏颂） 《日华本草》一种（宋人大明） 《证 \n类本草》一种（宋唐慎微） 《本草补遗》一种 \n李时珍） \n【附注】魏李当之《药录》 《吴普本草》 宋雷 《炮炙》 齐徐之才《药对》 唐 \n甄权《药性》 孙思邈《千金》 唐孟诜《食疗》 杨损之《删繁》 萧炳《四声》 南唐 \n陈士良《食性》 宋陈承《别说》 寇宗 《衍义》 金张元素《珍珠囊》 元李杲《法象》 \n王好古《汤液》 元吴瑞《日用》 明汪颖《食物》 汪机《会编》 周定 \n王纶《集要》 宁原《食鉴》 陈嘉谟《蒙筌》 \n\n\n\n<目录>木部第三十四卷\n\n<篇名>木之一\n\n内容：（香木类三十五种） \n\n\n\n<目录>木部第三十四卷\\木之一\n\n<篇名>柏\n\n内容：（《本经》上品） \n【释名】 （音菊）、侧柏。 \n李时珍曰∶按∶魏子才《六书精蕴》云∶万木皆向阳，而柏独西指，盖阴木而有贞德者， \n故字从白。白者，西方也。陆佃《埤雅》云∶柏之指西，犹针之指南也。柏有数种，入药惟 \n取叶扁而侧生者，故曰侧柏。 \n寇宗 曰∶予官陕西，登高望柏，千万株皆一一西指。盖此木至坚，不畏霜雪，得木之 \n正气，他木不及。所以受金之正气所制，一一西指也。 \n【集解】《别录》曰∶柏实生太山山谷，柏叶尤良。四时各依方面 \n陶弘景曰∶处处有柏，当以太山为佳尔。并忌取冢墓上者。其叶以秋夏采者良。 \n苏恭曰∶今太山无复采子，惟出陕州、宜州为胜。八月采之。 \n苏颂曰∶柏实以干州者为最。三月开花，九月结子成熟，取采蒸曝，舂擂取仁用。其叶 \n名侧柏，密州出者尤佳。虽与他柏相类，而其叶皆侧向而生，功效殊别。古柏叶尤奇，益州 \n诸葛孔明庙中有大柏木，相传是蜀世所植，故人多采以作药，其味甘香，异常柏也。雷 曰∶ \n柏叶有花柏叶、丛柏叶及有子圆叶。其有子圆叶成片，如大片云母，叶皆侧，叶上有微赤毛 \n者，宜入药用。花柏叶，其树浓叶成朵，无子；丛柏叶，其树绿色，并不入药。陈承曰∶陶 \n隐居说柏忌冢墓上者，而今干州者皆是乾陵所出，他处皆无大者，但取其州土所宜，子实气 \n味丰美可也。其柏异于他处，木之纹理，大者多为菩萨云气、人物鸟兽，状极分明可观。有 \n盗得一株径尺者，值万钱，宜其子实为贵也。时珍曰∶《史记》言∶松柏为百木之长。其树 \n耸直，其皮薄，其肌腻。其花细琐，其实成 ，状如小铃，霜后四裂，中有数子，大如麦粒， \n芬香可爱。柏叶松身者，桧也。其叶尖硬，亦谓之栝。今人名圆柏，以别侧柏。松叶柏身者， \n枞也。松桧相半者，桧柏也。峨眉山中一种竹叶柏身者，谓之竹柏。 \n\\x柏实\\x \n【修治】 曰∶凡使先以酒浸一宿，至明漉出，晒干，用黄精自然汁于日中煎之，缓火 \n煮成煎为度。每煎柏子仁三两，用酒五两浸。 \n时珍曰∶此法是服食家用者。寻常用，只蒸熟曝烈，舂簸取仁，炒研入药。 \n【气味】甘，平，无毒。 \n甄权曰∶甘、辛。畏菊花、羊蹄草。 \n徐之才曰∶见叶下。 \n【主治】惊悸益气，除风湿，安五脏。久服，令人润泽美色，耳目聪明，不饥不老，轻 \n身延年（《本经》）。疗恍惚，虚损吸吸，历节腰中重痛，益血止汗（《别录》）。治头风，腰 \n肾中冷，膀胱冷脓宿水，兴阳道，益寿，去百邪鬼魅，小儿惊痫（甄权）。润肝（好古）。养 \n心气，润肾燥，安魂定魄，益智宁神。烧沥，泽头发 \n【发明】王好古曰∶柏子仁，肝经气分药也。又润肾，古方十精丸用之。 \n时珍曰∶柏子仁性平而不寒不燥，味甘而补，辛而能润，其气清香，能透心肾，益脾 \n盖仙家上品药也，宜乎滋养之剂用之。《列仙传》云∶赤松子食柏实，齿落更生，行及 \n奔马。谅非虚语也。 \n【附方】旧二，新六。 \n服柏实法∶八月连房取实曝收，去壳研末。 \n每服二钱，温酒下，一日三服。渴即饮水，令人悦泽。一方∶加松子仁等分，以松脂和 \n丸。一方∶加菊花等分，蜜丸服。《奇效方》∶用柏子仁二斤（为末，酒浸为膏），枣肉三斤， \n白蜜、白术末、地黄末各一斤，捣匀，丸弹子大。每嚼一丸，一日三服。百日，百病愈；久 \n服，延年壮神。老人虚秘∶柏子仁、松子仁、大麻仁等分。同研，溶蜜蜡丸梧桐子大。以少 \n黄丹汤，食前调服二、三十丸，日二服。（寇宗 ）肠风下血∶柏子十四个。捶碎，囊贮浸 \n好 \n酒三盏，煎八分服，立止。（《普济方》）小儿 啼，惊痫腹满，大便青白色∶用柏子仁末， \n温水调服一钱。（《圣惠方》）黄水湿疮∶真地沥青二两，香油二两。熬稠搽之，如神。（陆氏 \n《积德 \n\\x柏叶\\x \n【修治】 曰∶凡用 去两畔并心枝丫，用糯泔浸七日，以酒拌蒸一伏时。每一斤，用 \n黄精自然汁十二两浸焙（又浸又焙），待汁干用之。 \n时珍曰∶此服食治法也。常用或生或炒，各从本方。 \n【气味】苦，微温，无毒。 \n权曰∶苦、辛，性涩。与酒相宜。 \n颂曰∶性寒。 \n之才曰∶瓜子、牡蛎、桂为之使。畏菊花、羊蹄、诸石及面曲。伏砒、硝。 \n弘景曰∶柏之叶、实，服饵所重。此云恶曲，而人以酿酒无妨。恐酒米相和，异单用也。 \n【主治】吐血、衄血，痢血、崩中、赤白，轻身益气，令人耐寒暑，去湿痹，止饥（《别 \n录》）。治冷风历节疼痛，止尿血（甄权）。 \n炙， 冻疮。烧取汁涂头，黑润鬓发（大明）。敷汤火伤，止痛灭瘢。服之，疗蛊痢。 \n作汤常服，杀五脏虫，益人（苏颂）。 \n【发明】震亨曰∶柏属阴与金，善守。故采其叶，随月建方，取其多得月令之气。此补 \n阴之要药，其性多燥，久得之大益脾土，以滋其肺。 \n时珍曰∶柏性后凋而耐久，禀坚凝之质，乃多寿之木，所以可入服食。道家以之点汤常 \n饮，元旦以之浸酒辟邪，皆有取于此。麝食之而体香，毛女食之而体轻，亦其证验矣。毛女 \n者，秦王宫人。关东贼至，惊走入山，饥无所食。有一老公教吃松柏叶，初时苦涩，久乃相 \n宜，遂不复饥，冬不寒，夏不热。至汉成帝时，猎者于终南山见一人，无衣服，身生黑毛， \n跳坑越涧如飞，乃密围获之，去秦时二百余载矣。事出葛洪《抱朴子》书中。 \n【附方】旧十，新十一。 \n服松柏法∶孙真人《枕中记》云∶尝以三月、四月采新生松叶，长三、四寸许，并花蕊 \n阴干；又于深山岩谷中，采当年新生柏叶，长二、三寸者，阴干，为末，白蜜丸如小豆大。 \n常以日未出时，烧香东向，手持八十一丸，以酒下。服一年，延十年命；服二年，延二十年 \n命。欲得长肌肉，加大麻、巨胜；欲心力壮健者，加茯苓、人参。此药除百病，益元气，滋 \n五脏六腑，清明耳目，强壮不衰老，延年益寿，神验。用七月七日露水丸之，更佳。服时仍 \n祝曰∶神仙真药，体合自然。服药入腹，天地同年。祝毕服药。断诸杂肉、五辛。神仙服饵∶ \n五月五日，采五方侧柏叶三斤，远志（去心）二斤，白茯苓（去皮）一斤，为末，炼蜜和丸 \n梧桐 \n子大。每以仙灵脾酒下三十丸，日再服。并无所忌。勿示非人。中风不省，涎潮口禁，语言 \n不出，手足 曳∶得病之日，便进此药，可使风退气和，不成废人。柏叶一握（去枝），葱 \n白 \n一握（连根研如泥），无灰酒一升，煎一、二十沸，温服。如不饮酒，分作四、五服，方进 \n他 \n药。（《杨氏家藏方》）时气瘴疫∶社中西南柏树东南枝，取曝干研末。每服一钱，新水调下， \n日三、四服。（《圣惠方》）霍乱转筋∶柏叶捣烂，裹脚上，及煎汁淋之。（《圣惠方》）吐血 \n不止∶张仲景柏叶汤∶用青柏叶一把，干姜二片，阿胶一挺（炙），三味，以水二升，煮一 \n升， \n去滓，别绞马通汁一升，合煎取一升，绵滤，一服尽之。《圣惠方》∶用柏叶，米饮服二钱。 \n或蜜丸、或水煎服，并良。 \n忧恚呕血，烦满少气，胸中疼痛∶柏叶为散，米饮调服二方寸匕。（《圣惠方》）衄血不 \n止∶柏叶、榴花研末，吹之。（《普济方》）小便尿血∶柏叶、黄连焙研，酒服三钱。（《济 \n急方》）大肠下血∶随四时方向，采侧柏叶，烧研。每米饮服二钱。王涣之舒州病此，陈宜 \n父大夫传方，二服愈。（《百一选方》）酒毒下血或下痢∶嫩柏叶（九蒸九晒）二两，陈槐花 \n（炒 \n焦）一两，为末，蜜丸梧桐子大。每空心温酒下四十丸。（《普济方》）蛊痢下血∶男子、妇 \n人、小儿大腹，下黑血茶脚色，或脓血如淀色。柏叶焙干为末，与黄连同煎为汁，服之。（《本 \n草图经》）小儿洞痢∶柏叶煮汁，代茶饮之。（《经验后方》）月水不断∶侧柏叶（炙）、芍药 \n等分。每用三钱，水、酒各半，煎服。室女用侧柏叶、木贼（炒微焦）等分，为末。每服二 \n钱， \n米饮下。（《圣济总录》）汤火烧灼∶柏叶生捣涂之，系定二、三日，止痛灭瘢。（《本草图 \n经》）鼠 核痛∶未成脓，以柏叶捣涂，熬盐熨之，令热气下即消。（姚僧坦《集验方》）大 \n风疠疾，眉发不生∶侧柏叶九蒸九晒，为末，炼蜜丸梧桐子大。每服五丸至十丸，日三、夜 \n一服。百日即生。（《圣惠方》）头发不生∶侧柏叶阴干，作末。和麻油涂之。（孙真人《食 \n忌》）头发黄赤∶生柏叶末一升，猪膏一斤。和丸弹子大。每以布裹一丸，纳泔汁中化开， \n沐之。一月，色黑而润矣。（《圣惠方》） \n\\x枝节\\x \n【主治】煮汁酿酒，去风痹、历节风。烧取 油，疗 疥及虫癞良（苏恭）。 \n【附方】 \n霍乱转筋∶以暖物裹脚，后以柏木片煮汤淋之。（《经验后方》） \n齿 肿痛∶柏枝烧热，拄孔中。须臾虫缘枝出。（《圣惠》） \n恶疮有虫∶久不愈者，以柏枝节烧沥取油，敷之。三、五次无不愈。亦治牛马疥。（陈 \n承 \n\\x脂\\x \n【主治】身面疣目，同松脂研匀涂之，数夕自失（《圣惠》）。 \n\\x根白皮\\x \n【气味】苦，平，无毒。 \n【主治】火灼烂疮，长毛发（《别录》）。 \n【附方】旧一。 \n热油灼伤∶柏白皮，以腊猪脂煎油，涂疮上。（《肘后方》） \n\n\n\n<目录>木部第三十四卷\\木之一\n\n<篇名>松\n\n内容：（《别录》上品） \n【释名】时珍曰∶按王安石《字说》云∶松柏为百木之长。松犹公也，柏犹伯也。故松 \n从公，柏从白。 \n【集解】《别录》曰∶松脂生太山山谷。六月采。 \n颂曰∶松处处有之。 \n其叶有两鬣、五鬣、七鬣。岁久则实繁。中原虽有，不及塞上者佳好也。松脂以通明如 \n薰陆香颗者为胜。 \n宗 曰∶松黄一如蒲黄，但味差淡。松子多海东来，今关右亦有，但细小味薄也。 \n时珍曰∶松树 修耸多节，其皮粗浓有鳞形，其叶后凋。二、三月抽蕤生花，长四、 \n五寸，采其花蕊为松黄。结实状如猪心，叠成鳞砌，秋老则子长鳞裂。然叶有二针、三针、 \n五针之别。三针者为栝子松，五针者为松子松。 \n其子大如柏子，惟辽海及云南者，子大如巴豆可食，谓之海松子，详见果部。孙思邈云∶ \n松脂以衡山者为良。衡山东五百里，满谷所出者，与天下不同。苏轼云∶镇定松脂亦良。《抱 \n朴子》云∶凡老松皮内自然聚脂为第一，胜于凿取及煮成者。其根下有伤处，不见日月者为 \n阴脂，尤佳。老松余气结为茯苓。千年松脂化为琥珀。《玉策记》云∶千年松树四边枝起， \n上杪不长如偃盖。其精化为青牛、青羊、青犬、青人、伏龟，其寿皆千岁。 \n\\x松脂\\x \n【别名】松膏（《本经》）、松肪（同）、 \n【修治】弘景曰∶采炼松脂法，并在服食方中。以桑灰汁或酒煮软， 纳寒水中数十过， \n白滑则可用。 \n颂曰∶凡用松脂，先须炼治。用大釜加水置甑，用白茅借甑底，又加黄砂于茅上，浓寸 \n许∶然后布松脂于上，炊以桑薪，汤减频添热水。候松脂尽入釜中，乃出之，投于冷水，既 \n凝又蒸，如此三过，其白如玉，然后入用。 \n【气味】苦、甘，温，无毒。权曰∶甘，平。 \n震亨曰∶松脂属阳金，伏汞。 \n【主治】痈疽恶疮，头疡白秃，疥瘙风气，安五脏，除热。 \n久服，轻身不老延年（《本经》）。除胃中伏热，咽干消渴，风痹死肌。炼之令白。其赤者， \n主恶痹（《别录》）。煎膏，生肌止痛，排脓抽风。贴诸疮脓血 烂。塞牙孔，杀虫（甄权）。 \n除邪下气，润心肺，治耳聋。古方多用辟谷（大明）。强筋骨，利耳目，治崩带（时珍）。 \n【发明】弘景曰∶松、柏皆有脂润，凌冬不凋 \n颂曰∶道人服饵，或合茯苓、松柏实、菊花作丸，亦可单服。 \n时珍曰∶松叶、松实，服饵所须；松节、松心，耐久不朽。松脂则又树之津液精华也。 \n在土不朽；流脂日久，变为琥珀，宜其可以辟谷延龄。葛洪《抱朴子》云∶上党赵瞿病癞历 \n年，垂死，其家弃之，送置山穴中。瞿怨泣经月，有仙人见而哀之，以一囊药与之。瞿服百 \n余日，其疮都愈，颜色丰悦，肌肤玉泽。仙人再过之，瞿谢活命之恩，乞求其方。仙人曰∶ \n此是松脂，山中便多。此物汝炼服之，可以长生不死。瞿乃归家长服，身体转轻，气力百倍， \n登危涉险，终日不困。年百余岁，齿不坠，发不白。夜卧忽见屋间有光，大如镜，久而一室 \n尽明如昼。又见面上有采女一人，戏于口鼻之间。后入抱犊山成地仙。于时人闻瞿服此脂， \n皆竞服之，车运驴负，积之盈室。不过一月，未觉大益，皆辄止焉。志之不坚如此。张杲《医 \n说》有服松丹之法。 \n【附方】旧七，新十七。 \n服食辟谷∶《千金方》∶用松脂十斤，以桑薪灰汁一石，煮五七沸，漉出，冷水中凝，复 \n煮之，凡十遍乃白，细研为散。每服一、二钱，粥饮调下，日三服。服至十两以上，不饥， \n饥再服之。一年以后，夜视目明。久服，延年益寿。又法∶百炼松脂治下筛，蜜和纳筒中， \n勿见风日。每服一团，一日三服。服至百日，耐寒暑；二百日，五脏补益；五年，即见西王 \n母。 \n伏虎禅师服法∶用松脂十斤，炼之五度，令苦味尽。每一斤，入茯苓末四两。每旦水服 \n一刀圭，能令不食，而复延龄，身轻清爽。强筋补益∶四圣不老丹∶用明松脂一斤，以无灰 \n酒沙锅内桑柴火煮数沸，竹枝搅稠，乃住火，倾入水内结块，复以酒煮九遍，其脂如玉，不 \n苦不涩乃止，为细末。用十二两，入白茯苓末半斤，黄菊花末半斤，柏子仁（去油取霜）半 \n斤， \n炼蜜丸如梧桐子大。每空心好酒送下七十二丸。须择吉日修合，勿令妇人、鸡、犬 \n松梅丸∶用松脂以长流水桑柴煮拔三次，再以桑灰滴汁煮七次扯拔，更以好酒煮二次， \n仍以长流水煮二次，色白不苦为度。每一斤，入九蒸地黄末十两，乌梅末六两，炼蜜丸梧桐 \n子大。每服七十丸，空心盐、米汤下。健阳补中，强筋润肌，大能益人。（白飞霞《方外奇 \n方》） \n揩齿固牙∶松脂（出镇定者佳），稀布盛，入沸汤煮，取浮水面者投冷水中（不出者不 \n用）， \n研末，入白茯苓末和匀。日用揩齿漱口，亦可咽之，固牙驻颜。（苏东坡《仇池笔记》）历节 \n诸风，百节酸痛不可忍∶松脂三十斤，炼五十遍。以炼酥三升，和松脂三升，搅令极稠。每 \n旦空心酒服方寸匕，日三服。数食面粥为佳，慎血腥、生冷、酢物、果子，一百日瘥。（《外 \n台秘要》） \n肝虚目泪∶炼成松脂一斤，酿米二斗。水七斗，曲二斗，造酒。频饮之。妇人白带∶松 \n香五两，酒二升，煮干，木臼杵细，酒糊丸如梧桐子大。每服百丸，温酒下。（《摘玄方》） \n小儿秃疮∶《简便方》∶用松香五钱，猪油一两熬，搽，一日数次，数日即愈。《卫生宝 \n鉴》∶用沥青二两，黄蜡 \n小儿紧唇∶松脂炙化，贴之。（《圣惠方》）风虫牙痛∶刮松上脂，滚水泡化，一漱即止， \n已试验。（《集简方》） \n龋齿有孔∶松脂 塞，须臾虫从脂出也。（《梅师方》） \n久聋不听∶炼松脂三两，巴豆一两。和捣成丸。薄绵裹塞，一日二度。（《梅师方》） \n一切 疮∶炼成松脂末，填令满，日三、四度。（《圣惠方》） \n一切肿毒∶松香八两，铜青二钱，蓖麻仁五钱。同捣作膏，摊贴甚妙。（李楼《奇方》） \n软疖频发∶翠玉膏∶用通明沥青八两，铜绿二两，麻油三钱，雄猪胆汁三个。先溶沥青， \n乃下油、胆，倾入水中扯拔，器盛。每用，绯帛摊贴，不须再换。小金丝膏∶治一切疮疖肿 \n毒。沥青、白胶香各二两，乳香二钱，没药一两，黄蜡三钱，又以香油三钱，同熬至滴下不 \n散，倾入水中，扯千遍收贮。每捻作饼，贴之。疥癣湿疮∶松胶香研细，稍入轻粉。先以油 \n涂疮，糁末在上，一日便干。顽者三、二度愈。（《刘涓子鬼遗方》） \n阴囊湿痒欲溃者∶用板儿松香为末，纸卷作筒。每根入花椒三粒，浸灯盏内三宿，取出 \n点烧，淋下油搽之。先以米泔洗过。（《简便方》） \n金疮出血∶沥青末，稍加生铜屑末，糁之，立愈。（唐瑶《经验方》） \n猪啮成疮∶松脂炼作饼，贴之。（《千金》） \n刺入肉中，百理不瘥∶松脂流出如乳头香者，敷上以帛裹。三、五日当有根出，不痛不 \n痒，不觉自安。（《兵部 \n\\x松节\\x \n【气味】苦，温，无毒。 \n【主治】百节久风，风虚脚痹疼痛（《别录》）。酿酒，主脚弱，骨节风（弘景）。炒焦， \n治筋骨间病，能燥血中之湿 \n【发明】时珍曰∶松节，松之骨也。质坚气劲，久亦不朽，故筋骨间风湿诸病宜之。 \n【附方】旧二，新五。历节风痛，四肢如解脱∶松节酒∶用二十斤，酒五斗，浸三、七 \n日。每服一合，日五、六服。（《外台》） \n转筋挛急∶松节一两（锉如米大），乳香一钱，银石器慢火炒焦，存一、二分性，出火 \n毒，研末。每服一、二钱，热木瓜酒调下。一应筋病皆治之。（孙用和《秘宝方》） \n风热牙痛∶《圣惠方》∶用油松节如枣大一块（碎切），胡椒七颗，入烧酒，须二、三盏， \n乘热入飞过白矾少许，噙漱三、五口，立瘥。又用松节二两，槐白皮、地骨皮各一两，浆水 \n煎汤。热漱冷吐，瘥乃止。反胃吐食∶松节煎酒，细饮之。（《百一方》） \n阴毒腹痛∶油松木七块炒焦，冲酒二钟，热服。（《集简方》） \n颠扑伤损∶松节煎酒服。（谈野翁方） \n【主治】疮疥及马牛疮（苏恭）。 \n\\x松叶\\x \n【别名】松毛。 \n【气味】苦，温，无毒。 \n【主治】风湿疮，生毛发，安五脏，守中，不饥延年（《别录》）。细切，以水及面饮服 \n之，或捣屑丸服，可断谷及治恶疾（弘景）。炙， 冻疮风湿疮，佳（大明）。去风痛脚痹， \n杀米虫（时珍）。 \n【附方】旧六，新三。 \n服食松叶∶松叶细切更研，每日食前以酒调下二钱，亦可煮汁作粥食。初服稍难，久则 \n自便矣。令人不老，身生绿毛，轻身益气。久服不已，绝谷不饥不渴。（《圣惠方》） \n天行温疫∶松叶，细切，酒服方寸匕，日三服。能辟五年瘟。（《伤寒类要》） \n中风口 ∶青松叶一斤捣汁，清酒一斗，浸二宿，近火一宿。初服半升，渐至一升，头 \n面汗出即止。（《千金方》） \n三年中风∶松叶一斤。细切，以酒一斗，煮取三升。顿服，汗出立瘥。（《千金方》） \n历节风痛∶松叶（捣汁）一升。以酒三升，浸七日。服一合，日三服。（《千金方》） \n香港脚风痹∶松叶酒∶治十二风痹不能行，服更生散数剂，及众疗不得力，服此一剂，便 \n能行远，不过两剂。松叶六十斤细锉，以水四石，煮取四斗九升，以米五斗，酿如常法。别 \n煮松叶汁以渍米并 饭，泥酿封头，七日发，澄饮之取醉。得此酒力者甚众。（《千金方》） \n风牙肿痛∶松叶一握，盐一合，酒二升煎漱。（《圣惠方》） \n大风恶疮∶猪鬃松叶二斤，麻黄（去节）五两。锉，以生绢袋盛，清酒二斗浸之，春夏 \n五日，秋冬七日。每温服一小盏，常令醺醺，以效为度。（《圣惠方》） \n阴囊湿痒∶松毛煎汤，频洗。（《简便方》） \n\\x松花\\x \n【别名】松黄。 \n【气味】甘，温，无毒。 \n震亨曰∶多食，发上焦热病。 \n【主治】润心肺，益气，除风止血。亦可酿酒（时珍）。 \n【发明】恭 \n颂曰∶花上黄粉，山人及时拂取，作汤点之甚佳。但不堪停久，故鲜用寄远。 \n时珍曰∶今人收黄和白沙糖印为饼膏，充果饼食之，且难久收，恐轻身疗病之功，未必 \n胜脂、叶也。 \n【附方】旧一，新一。 \n头旋脑肿∶三月收松花并苔（五、六寸如鼠尾者，蒸切）一升，以生绢囊贮，浸三升酒 \n中五日。空心暖饮五合。（《普济方》）产后壮热，头痛颊赤，口干唇焦，烦渴昏闷∶用松花、 \n蒲黄、川芎、当归、石膏等分，为末。每服二钱，水二合，红花二捻，同煎七分，细呷。（《本 \n草衍义》） \n\\x根白皮\\x \n【气味】苦，温，无毒。 \n【主治】辟谷不饥（《别录》）。补五劳，益气（大明）。 \n\\x木皮\\x \n【别名】赤龙皮。 \n【主治】痈疽疮口不合，生肌止血，治白秃、杖疮、汤火疮（时珍）。 \n【附方】新四。 \n肠风下血∶松木皮，去粗皮，取里白者，切、晒，焙研为末。每服一钱，腊茶汤 \n下。（《杨氏家藏方》） \n三十年痢∶赤松上苍皮一斗，为末。面粥和服一升，日三。不过一斗，救人。（《圣惠 \n方》） \n金疮杖疮∶赤龙鳞（即古松皮）， 存性，研末。搽之，最止痛。（《永类钤方》） \n小儿头疮浸湿，名胎风疮∶古松上自有赤浓皮，入豆豉少许，瓦上炒存性，研末，入轻 \n粉、香油调，涂之。（《经验良方》） \n松实 见果部。 \n艾纳 见草部苔类桑花下。 \n松蕈 见菜部香蕈下。 \n\n\n\n<目录>木部第三十四卷\\木之一\n\n<篇名>杉\n\n内容：（《别录》下品） \n【释名】 （音杉）、沙木 \n【集解】颂曰∶杉材旧不着所出州土，今南中深山多有之。木类松而劲直，叶附枝生， \n若刺针。郭璞注《尔雅》云∶ 似松，生江南。可以为船及棺材，作柱埋之不腐。又人家常 \n用作桶板，甚耐水。 \n宗 曰∶杉干端直，大抵如松，冬不凋，但叶阔成枝也。今处处有之，入药须用油杉及 \n臭者良。 \n时珍曰∶杉木叶硬，微扁如刺，结实如枫实。江南人以惊蛰前后取枝插种，出倭国者， \n谓 \n干燥。有斑纹如雉者，谓之野鸡斑，作棺尤贵。其木不生白蚁，烧灰最发火药。 \n\\x杉材\\x \n【气味】辛，微温，无毒。 \n【主治】漆疮，煮汤洗之，无不瘥（《别录》）。煮水，浸捋香港脚肿满。服之，治心腹胀 \n痛，去恶气（苏恭）。治风毒奔豚， \n【发明】震亨曰∶杉屑属金有火。其节煮汁浸捋香港脚肿满，尤效。 \n颂曰∶唐柳柳州纂《救三死方》云∶元和十二年二月得香港脚，夜半痞绝，胁有块，大如 \n石，且死，困不知人，搐搦上视，三日，家人号哭。荥阳郑洵美传杉木汤，服半食顷大下， \n三行气通块散。方用杉木节一大升，橘叶（切）一大升（无叶则以皮代之），大腹槟榔七枚 \n（连子碎之），童子小便三大升，共煮取一大升半，分为两服。若一服得快，即停后服。此 \n乃死病，会有教者，乃得不死。恐人不幸病此，故传之云。 \n【附方】新四。 \n肺壅痰滞，上焦不利，猝然咳嗽∶杉木屑一两，皂角（去皮酥炙）三两，为末，蜜丸梧 \n桐子大。每米饮下十丸，一日四服。（《圣惠方》）小儿阴肿赤痛，日夜啼叫，数日退皮，愈 \n而复作∶用老杉木烧灰，入腻粉，清油调敷，效。（危氏《得效方》）肺壅失音∶杉木烧炭入 \n碗中，以小碗覆之，用汤淋下，去碗饮水。不愈再作，音出乃止。（《集简方》） 疮黑烂∶ \n多年老杉木节，烧灰，麻油调，隔箬叶贴之，绢帛包定，数贴而愈。（《救急 \n\\x皮\\x \n【主治】金疮血出，及汤火伤灼，取老树皮烧存性，研敷之。或入鸡子清调敷。一、二 \n日愈（时珍）。 \n\\x叶\\x \n【主治】风、虫牙痛，同芎 、细辛煎酒含漱（时珍）。 \n\\x子\\x \n【主治】疝气痛，一岁一粒，烧研酒服（时珍）。 \n杉菌 见菜部。 \n【附录】丹桎木皮（桎，音直） 藏器曰∶生江南深山。似杉木，皮，主治 疡风。取 \n一握，去上黑，打碎，煎如糖，日日涂之。 \n\n\n\n<目录>木部第三十四卷\\木之一\n\n<篇名>桂\n\n内容：（《别录》上品）、牡桂（《本经》上品） \n【释名】 （音寝）。 \n时珍曰∶按∶范成大《桂海志》云∶凡木叶心皆一纵理，独桂有两道如圭形，故字从圭。 \n陆佃《埤雅》云∶桂犹圭也。宣导百药，为之先聘通使，如执圭之使也。《尔雅》谓之 者， \n能侵害他木也。故《吕氏春秋》云∶桂枝之下无杂木。《雷公炮炙论》云∶桂钉木根，其木 \n即死，是也。桂即牡桂之浓而辛烈者，牡桂即桂之薄而味淡者，《别录》不当重出。今并为 \n一 \n【集解】《别录》曰∶桂生桂阳，牡桂生南海山谷。二月、八月、 \n弘景曰∶南海即是广州。《神农本经》惟有牡桂、菌桂。俗用牡桂，扁广殊薄，皮黄， \n脂肉甚少，气如木兰，味亦类桂，不知是别树，是桂之老宿者？菌桂正圆如竹，三重者良， \n俗中不见，惟以嫩枝破卷成圆者用之，非真菌桂也，并宜研访。今俗又以半卷多脂者，单名 \n为桂，入药最多，是桂有三种矣。此桂广州出者好；交州、桂州者，形段小而多脂肉，亦好； \n湘州、始兴、桂阳县者，即是小桂，不如广州者。《经》云∶桂，叶如柏叶泽黑，皮黄心赤。 \n齐武帝时，湘州送树，植芳林苑中。今东山有桂皮，气粗相类，而叶乖异，亦能凌冬，恐是 \n牡桂。人多呼为丹桂，正谓皮赤尔。北方重此，每食辄须之，盖《礼》所云姜桂以为芬芳也。 \n恭曰∶桂惟有二种。陶氏引《经》云似柏叶，不知此言从何所出？又于《别录》剩出桂条， \n为深误也。单名桂者，即是牡桂，乃《尔雅》所谓“ ，木桂”也。叶长尺许，花、子皆与 \n菌 \n桂同。大小枝皮俱名牡桂。但大枝皮，肉理粗虚如木而肉少味薄，名曰木桂，亦云大桂；不 \n及小嫩枝皮，肉多而半卷，中必皱起，其味辛美，一名肉桂，亦名桂枝，一名桂心，出融州、 \n桂州、交州甚良。其菌桂，叶似柿叶，中有纵纹三道，表里无毛而光泽。肌理紧薄如竹，大 \n枝、小枝皮俱是筒。其大枝无肉，老皮坚板，不能重卷，味极淡薄，不入药用；小枝薄而卷 \n及二、三重者良。或名筒桂，陶云小桂是也。今惟出韶州。保升曰∶桂有三种∶菌桂，叶似 \n柿叶而尖狭光净。花白蕊黄，四月开。五月结实。树皮青黄，薄卷若筒，亦名筒桂。其浓硬 \n味薄者，名板桂，不入药用。牡桂，叶似枇杷叶，狭长于菌桂叶一、二倍。其嫩枝皮半卷多 \n紫，而肉中皱起，肌理虚软，谓之桂枝，又名肉桂。削去上皮，名曰桂心。其浓者名曰木桂。 \n药中以此为善。陶氏言半卷多脂者为桂。又引《仙经》云∶叶似柏叶。此则桂有三种明矣。 \n陶虽是梁武帝时人，实生于宋孝武建元三年，历齐为诸王侍读，曾见芳林苑所植之树。苏恭 \n只知有二种，指陶为误，何臆断之甚也。藏器曰∶菌桂、牡桂、桂心三色，同是一物。桂林 \n桂岭，因桂得名，今之所生，不离此郡。从岭以南际海尽有桂树，惟柳、象州最多。味既辛 \n烈，皮又浓坚。浓者必嫩，薄者必老。采者以老薄为一色，嫩浓为一色。嫩既辛烈，兼又筒 \n卷。老必味淡，自然板薄。薄者即牡桂，卷者即菌桂也。桂心即是削除皮上甲错，取其近里 \n而有味者。承曰∶诸家所说，几不可考。今广、交商人所贩，及医家见用，惟陈藏器一说最 \n近之。颂曰∶《尔雅》但言“ ，木桂”一种，本草载桂及牡桂、菌桂三种。今岭表所出， \n则"}, {"n": 29, "text": "卷二十九\n\n有筒桂、肉桂、桂心、官桂、板桂之名，而医家用之罕有分别。旧说菌桂正圆如竹，有二、 \n三重者，则今之筒桂也。牡桂皮薄色黄少脂肉者，则今之官桂也。桂是半卷多脂者，则今之 \n板桂也。而今观宾、宜、韶、钦诸州所图上者，种类亦各不同，然总谓之桂，无复别名。参 \n考旧注，谓菌桂，叶似柿，中有三道纹，肌理紧薄如竹，大小皆成筒，与今宾州所出者相类。 \n牡桂，叶狭于菌桂而长数倍，其嫩枝皮半卷多紫，与今宜州、韶州所出者相类。彼土人谓其 \n皮为木兰皮，肉为桂心。此又有黄、紫两色，益可验也。桂，叶如柏叶而泽黑，皮黄心赤； \n今钦州所出者，叶密而细，恐是其类，但不作柏叶形为异尔。苏恭以单桂、牡桂为一物，亦 \n未可据。其木俱高三、四丈，多生深山蛮洞中，人家园圃亦有种者。移植于岭北，则气味殊 \n少辛辣，不堪入药也。三月、四月生花，全类茱萸。九月结实，今人多以装缀花果作筵具。 \n其叶甚香，可用作饮尤佳。二月、八月采皮，九月采花，并阴干，不可近火。时珍曰∶桂有 \n数种，以今参访∶牡桂，叶长如枇杷叶，坚硬有毛及锯齿，其花白色，其皮多脂。菌桂，叶 \n如柿叶，而尖狭光净，有三纵纹而无锯齿，其花有黄有白，其皮薄而卷。今商人所货，皆此 \n二桂。但以卷者为菌桂，半卷及板者为牡桂，即自明白。苏恭所说，正合医家见今用者。陈 \n藏器、陈承断菌、牡为一物者，非矣。陶弘景复以单词桂为叶似柏者，亦非也。柏叶之桂， \n乃服食家所云，非此治病之桂也。苏颂所说稍明，亦不当以钦州者为单词之桂也。按∶《尸 \n子》云∶春花秋英曰桂。嵇含《南方草木状》云∶桂生合浦、交趾，生必高山之巅，冬夏常 \n青。其类自为林，更无杂树。有三种∶皮赤者为丹桂，叶似柿叶者为菌桂，叶似枇杷叶者为 \n牡桂。其说甚明，足破 \n∶暗河之桂，实大如枣。得而食之，后天而老。此又一种也。暗河不知在何处？ \n【正误】好古曰∶寇氏《衍义》言∶官桂不知缘何立名？予考《图经》，今观、宾、宜 \n诸 \n州出者佳。世人以观字画多，故写作官也。时珍曰∶此误。《图经今观》乃今视之意。岭南 \n无观州。曰官桂者，乃上等供官之桂也。桂（《别录》） 时珍曰∶此即肉桂也。浓而辛烈， \n去粗皮用。其去内 \n【气味】甘、辛，大热，有小毒。权曰∶桂心∶苦、辛，无毒。 \n元素曰∶肉桂∶气热，味大辛，纯阳也。杲曰∶桂，辛，热，有毒。阳中之阳，浮也。 \n气之薄者，桂枝也；气之浓者，桂肉也。气薄则发泄，桂枝上行而发表；气浓则发热，桂肉 \n下行而补肾。此天地亲上亲下之道也。好古曰∶桂枝入足太阳经，桂心入手少阴经血分，桂 \n肉入足少阴、太阴经血分。细薄者为枝为嫩，浓脂者为肉为老。去其皮与里，当其中者为桂 \n心。《别录》言∶有小毒，又云∶久服神仙不老。虽有小毒，亦从类化。与黄芩、黄连为使， \n小毒何施？与乌头、附子为使，全取其热性而已。与巴豆、 砂、干漆、穿山甲、水蛭等同 \n用，则小毒化为大毒。与人参、麦门冬、甘草同用，则调中益气，便可久服也。之才曰∶桂 \n得人参、甘草、麦门冬、大黄、黄芩，调中益气。得柴胡、紫石英、干地黄，疗吐逆。忌生 \n葱、石脂。 \n【主治】利肝肺气，心腹寒热冷疾，霍乱转筋，头痛腰痛出汗，止烦止唾，咳嗽鼻 ， \n堕胎，温中，坚筋骨，通血脉，理疏不足，宣导百药，无所畏。久服，神仙不老（《别录》）。 \n补下焦不足，治沉寒痼冷之病，渗泄止渴，去营卫中风寒，表虚自汗。春夏为禁药，秋冬下 \n部腹痛，非此不能止（元素）。补命门不足，益火消阴（好古）。治寒痹风喑，阴盛失血，泻 \n痢惊痫（时珍）。桂心（《药性论》） 曰∶用紫色浓者，去上粗皮并内薄皮，取心中味辛 \n者用。中土只有桂草，以煮丹阳木皮，伪充桂心也。时珍曰∶按∶《酉阳杂俎》云∶丹阳山 \n中有山桂，叶如麻，开细黄花。此即雷氏所谓丹 \n【气味】苦、辛，无毒。详前桂下。 \n【主治】九种心痛，腹内冷气痛不可忍，咳逆结气壅痹，脚痹不仁，止下痢，杀三虫， \n治鼻中息肉，破血，通利月闭，胞衣不下（甄权）。治一切风气，补五劳七伤，通九窍，利 \n关 \n节，益精明目，暖腰膝，治风痹骨节挛缩，续筋骨，生肌肉，消瘀血，破 癖症瘕，杀草木 \n毒（大明）。治风僻失音喉痹，阳虚失血，内托痈疽痘疮，能引血化汗、化脓，解蛇蝮毒（时 \n珍）。牡桂（《本经》） 时珍曰∶此即木桂也。薄而味淡，去粗皮用。其最薄者为桂枝，枝 \n之嫩小者为柳桂。 \n【气味】辛，温，无毒。权曰∶甘、辛。 \n元素曰∶桂枝味辛、甘，气微热，气味俱薄，体轻而上行，浮而升，阳也。余见前单桂 \n下。 \n【主治】上气咳逆结气，喉痹吐吸，利关节，补中益气。久服通神，轻身不老（《本经》）。 \n心痛胁痛胁风，温筋通脉，止烦出汗（《别录》）。去冷风疼痛（甄权）。去伤风头痛，开 \n腠理，解表发汗，去皮肤风湿（元素）。泄奔豚，散下焦 血，利肺气（成无己）。横行手臂， \n治痛风（震亨）。 \n【发明】宗 曰∶桂甘、辛，大热。《素问》云∶辛甘发散为阳。 \n故汉张仲景桂枝汤治伤寒表虚，皆须此药，正合辛甘发散之意。本草三种之桂，不用牡 \n桂、菌桂者，此二种性只于温，不可以治风寒之病也。然《本经》只言桂，仲景又言桂枝者， \n取枝上皮也。好古曰∶或问∶本草言桂能止烦出汗，而张仲景治伤寒有当发汗，凡数处，皆 \n用桂枝汤。又云无汗不得服桂枝。汗家不得重发汗，若用桂枝是重发其汗。汗多者用桂枝甘 \n草汤，此又用桂枝闭汗也。一药二用，与本草之义相通否乎？曰∶本草言桂辛甘大热，能宣 \n导百药，通血脉，止烦出汗，是调其血而汗自出也。仲景云∶太阳中风，阴弱者，汗自出。 \n卫实营虚，故发热汗出。又云太阳病发热汗出者，此为营弱卫强，阴虚阳必凑之，故皆用桂 \n枝发其汗。此乃调其营气，则卫气自和，风邪无所容，遂自汗而解。非桂枝能开腠理，发出 \n其汗也。汗多用桂枝者，以之调和营卫，则邪从汗出而汗自止，非桂枝能闭汗孔也。昧者不 \n知出汗、闭汗之意，遇伤寒无汗者亦用桂枝，误之甚矣。桂枝汤下发汗字，当认作出字，汗 \n自然发出，非若麻黄能开腠理，发出其汗也。其治虚汗，亦当逆察其意可也。成无己曰∶桂 \n枝本为解肌。若太阳中风，腠理致密，营卫邪实，津液禁固，其脉浮紧，发热汗不出者，不 \n可与此必也。皮肤疏泄，自汗，脉浮缓，风邪干于卫气者，乃可投之。发散以辛甘为主，桂 \n枝辛热，故以为君。而以芍药为臣、甘草为佐者，风淫所胜，平以辛苦，以甘缓之，以酸收 \n之也。以姜、枣为使者，辛甘能发散，而又用其行脾胃之津液而和营卫，不专于发散也。故 \n麻黄汤不用姜、枣，专于发汗，不待行其津液也。承曰∶凡桂之浓实气味重者，宜入治水脏 \n及下焦药；轻薄气味淡者，宜入治头目发散药。故《本经》以菌桂养精神，牡桂利关节。仲 \n景发汗用桂枝，乃枝条，非身干也，取其轻薄能发散。又有一种柳桂，乃桂之嫩小枝条，尤 \n宜入上焦药用。时珍曰∶麻黄遍彻皮毛，故专于发汗而寒邪散，肺主皮毛，辛走肺也。桂枝 \n透达营卫，故能解肌而风邪去，脾主营，肺主卫，甘走脾，辛走肺也。肉桂下行，益火之原， \n此东垣所谓肾苦燥，急食辛以润之，开腠理，致津液，通其气者也。《圣惠方》言∶桂心入 \n心，引血化汗化脓。盖手少阴君火、厥阴相火，与命门同气者也。《别录》云桂通血脉是矣。 \n曾世荣言∶小儿惊风及泄泻，并宜用五苓散以泻丙火，渗土湿。内有桂，能抑肝风而扶脾土。 \n又《医余录》云∶有人患赤眼肿痛，脾虚不能饮食，肝脉盛，脾脉弱。用凉药治肝则脾愈虚， \n用暖药治脾则肝愈盛。但于温平药中倍加肉桂，杀肝而益脾，故一治两得之。传云木得桂而 \n枯是也。此皆与《别录》桂利肝肺气，牡桂治胁痛胁风之义相符。人所不知者，今为拈出。 \n又桂性辛散，能通子宫而破血，故《别录》言其堕胎，庞安时乃云炒过则不损胎也。又丁香、 \n官桂治痘疮灰塌，能 \n【附方】旧二十，新十三。 \n阴痹熨法∶寒痹者，留而不去，时痛而皮不仁。刺布衣者，以火 之；刺大人者，以药 \n熨之。熨法∶用醇酒二十斤，蜀椒一斤，干姜一斤，桂心一斤。凡四物， 咀渍酒中。用棉 \n絮一斤，细白布四丈，并纳酒中，置马矢 中，封涂勿使泄气。五日五夜，出布、絮曝干， \n复渍以尽其汁；每渍必 其日，乃出干之。并用滓与絮复布为复巾，长六、七尺，为六、七 \n巾。每用一巾，生桑炭火炙巾，以熨寒痹所刺之处，令热入至病所。寒则复炙巾以熨之，三 \n十遍而止。汗出以巾拭身，亦三十遍而止。起步内中，无见风。每刺必熨，如此病已矣。（《灵 \n枢经》）足 筋急∶桂末，白酒和涂之，一日一上。（皇甫谧《甲乙经》）中风口 ，面目相 \n引，偏僻颊急，舌不可转∶桂心酒煮取汁，故布蘸拓病上，症即止。左 拓右，右 拓左。 \n常用大效。（《千金方》）中风逆冷，吐清水，宛转啼呼。桂一两，水一升半，煎半升，冷服。 \n（《肘后方》）中风失音∶桂着舌下，咽汁。又方∶桂末三钱，水二盏，煎一盏服，取汗。（《千 \n金方》）。喉痹不语∶方同上。偏正头风，天阴风雨即发∶桂心末一两，酒调如膏，涂敷额 \n角及顶上。（《圣惠方》）。暑月解毒∶桂苓丸∶用肉桂（去粗皮，不见火）、茯苓（去皮）等 \n分， \n为细末，炼蜜丸龙眼大。每新汲水化服一丸。（《和剂方》）。桂浆渴水∶夏月饮之，解烦渴， \n益气消痰。桂末一大两，白蜜一升，以水二斗，先煎取一斗，待冷，入新瓷瓶中，乃下二物， \n搅二、三百转。先以油纸一重复上，加七重封之。每日去纸一重，七日开之，气香味美，格 \n韵绝高 \n盏半，煎半盏饮，立效。《外台秘要》∶桂末，酒服方寸匕，须臾六、七次。心腹胀痛，气短 \n欲绝∶桂二两。水一升二合，煮八合，顿服之。（《肘后方》） \n寒疝心痛∶四肢逆冷，全不饮食。桂心研末一钱，热酒调下取效。（《圣惠方》）产后心痛∶ \n恶血冲心，气闷欲绝。桂心三两为末，狗胆汁丸芡子大。每热酒服一丸。（《圣惠》）产后瘕 \n痛∶桂末，酒服方寸匕，取效。（《肘后》）死胎不下∶桂末二钱，待痛紧时，童子小便温热 \n调下。名观音救生散，亦治难产横生。加麝香少许，酒下，比之水银等药，不损人。（何氏 \n方）血崩不止∶桂心不拘多少，砂锅内 存性，为末。每米饮空腹服一、二钱。名神应散。 \n（《妇 \n人良方》）反腰血痛∶桂末，和苦酒涂之，干再上。（《肘后方》）吐血下血∶《肘后》∶用桂 \n心为末，水服方寸匕。王 曰∶此阴乘阳之症也，不可服凉药。南阳赵宣德暴吐血，服二次 \n而止。其甥亦以二服而安。小儿久痢赤白∶用桂（去皮，以姜汁炙紫）、黄连（以茱萸炒过） \n等 \n分，为末。紫苏、木瓜煎汤服之。名金锁散。（《全幼心鉴》）小儿遗尿∶桂末、雄鸡肝等分。 \n捣丸小豆大。温水调下，日二服。（《外台》）婴儿脐肿∶多因伤湿。桂心炙热熨之，日四、 \n五次。（姚和众方）外肾偏肿∶桂末，水调方寸匕，涂之。（《梅师方》）食果腹胀，不拘老小∶ \n用桂末，饭和丸绿豆大。吞五、六丸，白汤下。未消再服。（《经验方》）打扑伤损，瘀血溷 \n闷，身体疼痛∶辣桂为末，酒服二钱。（《直指方》）乳痈肿痛∶桂心、甘草各二分，乌头一 \n分（炮）。为末，和苦酒涂之，纸覆住。脓化为水，神效。（《肘后方》）重舌鹅口∶桂末，和 \n姜汁涂之。（汤氏《宝书》）诸蛇伤毒∶桂心、栝蒌等分。为末，竹筒密塞。遇毒蛇伤，即敷 \n之。塞不密，即不中用也。闭口椒毒∶气欲绝，或出白沫，身体冷。急煎桂汁服之，多饮新 \n汲水一、二升。（《梅师方》） \n\\x叶\\x \n【主治】捣碎浸水，洗发，去垢除风（时珍）。 \n\n\n\n<目录>木部第三十四卷\\木之一\n\n<篇名>菌桂\n\n内容：（音窘。《本经》上品） \n【释名】筒桂（《唐本》）、小桂。 \n恭曰∶ 者，竹名。此桂嫩而易卷如筒，即古所用筒桂也。筒似 字，后人误书为 ， \n习而成俗， \n时珍曰∶今本草又作从草之菌，愈误矣。牡桂为大桂，故此称小桂。 \n【集解】《别录》曰∶ 桂生交趾、桂林山谷岩崖间。无骨，正圆如竹，立秋采之。 \n弘景曰∶交趾属交州，桂林属广州。《蜀都赋》云“ 桂临岩”是矣。 \n俗中不见正圆如竹者，惟嫩枝破卷成圆，犹依桂用，非真 桂也。《仙经》用 桂，云 \n三重者良，则明非今 \n时珍曰∶ 桂，叶似柿叶者是。详前桂下。《别录》所谓正圆如竹者，谓皮卷如竹筒。 \n陶氏误疑是木形如竹，反谓卷成圆者非真也。今人所栽岩桂，亦是 桂之类 \n似柿叶，亦有锯齿如枇杷叶而粗涩者，有无锯齿如栀子叶而光洁者。丛生岩岭间，谓之岩桂， \n俗呼为木犀。其花有白者名银桂，黄者名金桂，红者名丹桂。有秋花者，春花者，四季花者， \n逐月花者。其皮薄而不辣，不堪入药。惟花可收茗、浸酒、盐渍，及作香搽、发泽之类耳。 \n【发明】见前桂下。 \n时珍曰∶ 桂主治，与桂心、牡桂迥然不同。昔人所服食者，盖此类耳。 \n【正误】弘景曰∶《仙经》服食桂，以葱涕合和云母蒸化为水服之。 \n慎微曰∶《抱朴子》云∶桂可合竹沥饵之，亦可以龟脑和服之。七年能步行水上，长生 \n不死。赵佗子服桂二十年，足下生毛，日行五百里，力举千斤。《列仙传》云∶范蠡好食桂， \n饮水卖 \n时珍曰∶方士谬言，类多如此，唐氏收入本草，恐误后人，故详记。 \n\\x皮\\x（三月、七月采） \n【气味】辛，温，无毒。 \n【主治】百病，养精神，和颜色，为诸药先聘通使。久服轻身不老，面生光华，媚好常 \n如童子（《本经》）。 \n\\x木犀花\\x \n【气味】辛，温，无毒。 \n【主治】同百药煎、孩儿茶作膏饼噙，生津辟臭化痰，治风虫牙痛。同麻油蒸熟，润发， \n及作面脂（时珍）。 \n\n\n\n<目录>木部第三十四卷\\木之一\n\n<篇名>天竺桂\n\n内容：（《海药》） \n【集解】 曰∶天 \n宗 曰∶皮与牡桂相同，但薄耳。 \n时珍曰∶此即今闽、粤、浙中山桂也，而台州天竺最多，故名。大树繁花，结实如莲子 \n状。天竺僧人称为月桂是矣。详月桂下。 \n\\x皮\\x \n【气味】辛，温，无毒。 \n【主治】腹内诸冷，血气胀痛（藏器）。破产后恶血，治血痢肠风，补 \n心同，方家少用（ ）。 \n\n\n\n<目录>木部第三十四卷\\木之一\n\n<篇名>月桂\n\n内容：（《拾遗》） \n【集解】藏器曰∶今江东诸处，每至四、五月后晦，多于衢路间得月桂子，大于狸豆， \n破之辛香，古者相传是月中下也。余杭灵隐寺僧种得一株，近代诗人多所论述。《洞冥记》 \n云∶有远飞鸡，朝往夕还，常衔桂实归于南土。南土月路也，故北方无之。山桂犹堪为药， \n况 \n时珍曰∶吴刚伐月桂之说，起于隋唐小说。月桂落子之说，起于武后之时。相传有梵僧 \n自天竺鹫岭飞来，故八月常有桂子落于天竺。《唐书》亦云∶垂拱四年三月，有月桂子降于 \n台州，十余日乃止。宋仁宗天圣丁卯八月十五日夜，月明天净，杭州灵隐寺月桂子降，其繁 \n如雨，其大如豆，其圆如珠，其色有白者、黄者、黑者，壳如芡实，味辛。拾以进呈，寺僧 \n种之，得二十五株，慈云式公有序记之。张君房宿钱塘月轮寺，亦见桂子纷如烟雾，回旋成 \n穗，坠如牵牛子，黄白相间，咀之无味。据此，则月中真若有树矣。窃谓月乃阴魄，其中婆 \n娑者，山河之影尔。月既无桂，则空中所坠者何物耶？泛观群史，有雨尘沙土石，雨金铅钱 \n汞，雨絮帛谷粟，雨草木花药，雨毛血鱼肉之类甚众。则桂子之雨，亦妖怪所致，非月中有 \n桂也。桂生南方，故惟南方有之。《宋史》云∶元丰三年六月，饶州雨木子数亩，状类山芋 \n子，味辛而香， \n\\x子\\x \n【气味】辛，温，无毒。 \n【主治】小儿耳后月蚀疮，研碎敷之（藏器）。 \n\n\n\n<目录>木部第三十四卷\\木之一\n\n<篇名>木兰\n\n内容：（《本经》上品） \n【释名】杜兰（《别录》）、林兰（《本经》） \n时珍曰∶其香如兰，其花如莲，故名。其木心黄，故曰黄心。 \n【集解】《别录》曰∶木兰生零陵山谷及太山。皮似桂而香。十二 \n弘景曰∶零陵诸处皆有之。状如楠树，皮甚薄而味辛香。今益州者皮浓，状如浓朴，而 \n气味为胜。今东人皆以山桂皮当之，亦相类。道家用合香亦好。 \n保升曰∶所在皆有。树高数仞。叶似菌桂叶，有三道纵纹，其叶辛香不及桂也。皮如板 \n桂，有纵横纹。三月、四月采皮，阴干。 \n颂曰∶今湖、岭、蜀川诸州皆有之。此与桂全别，而韶州所上，乃云与桂同是一种。取 \n外皮为木兰，中肉为桂心。盖是桂中之一种尔。十一月、十二月采，阴干。任 《述异记》 \n云∶木兰川，在浔阳江中，多木兰。又七里洲中有鲁班刻木兰舟，至今在洲中。今诗家云木 \n兰舟，出于此。时珍曰∶木兰枝叶俱疏。其花内白外紫，亦有四季开者。深山生者尤大，可 \n以为舟。按∶《白乐天集》云∶木莲生巴峡山谷间，民呼为黄心树。大者高五、六丈，涉冬 \n不凋。身如青杨，有白纹。叶如桂而浓大，无脊。花如莲花，香色艳腻皆同，独房蕊有异。 \n四月初始开，二十日即谢，不结实。此说乃真木兰也。其花有红、黄、白数色。其木肌细而 \n心黄，梓人所重。苏颂所言韶州者，是牡桂，非木兰也。或云木兰树虽去皮，亦不死。罗愿 \n言其冬花、实如小柿甘美者，恐不然也。 \n\\x皮\\x \n【气味】苦，寒，无毒。 \n【主治】身大热在皮肤中，去面热赤 酒渣，恶风癫疾，阴下痒湿，明耳目（《本经》）。 \n疗中风伤寒，及痈疽水肿，去臭气 \n【附方】旧二，新二。 \n小儿重舌∶木兰皮一尺，广四寸，削去粗皮，入醋一升，渍汁噙之。（《子母秘录》） \n面上 ∶用木兰皮一斤细切，以三年酢浆渍之百日，晒干捣末。每浆水服方寸匕， \n日三服。《肘后》用酒渍之，栀子仁一斤。（《古今录验》方） \n皮一两，黄 二两，为末。酒服方寸匕，日三服。（《肘后方 \n\\x花\\x \n【主治】鱼哽骨哽，化铁丹用之（时珍）。 \n\n\n\n<目录>木部第三十四卷\\木之一\n\n<篇名>辛夷\n\n内容：（《本经》上品） \n【释名】辛雉（《本经》）、侯桃（同）、 \n时珍曰∶夷者荑也。其苞初生如荑而味辛也。扬雄《甘泉赋》云∶列辛雉于林薄。服虔 \n注云∶即辛夷。雉、夷声相近也。今 \n藏器曰∶辛夷花未发时，苞如小桃子，有毛，故名侯桃。初发如笔头，北人呼为木笔。 \n其花最早，南人呼为迎春。 \n【集解】《别录》曰∶辛夷生汉中、魏兴、梁州川谷。其树似杜仲，高丈余。子似冬桃 \n而小。九月采实，曝干，去心及外毛。毛射人肺，令人咳。 \n弘景曰∶今出丹阳近道。形如桃子，小时气味辛香。 \n恭曰∶此是树，花未开时收之。正月、二月好采。云九月采实者，恐误也。 \n保升曰∶其树大连合抱，高数仞。叶似柿叶而狭长。正月、二月花，似有毛小桃，色白 \n而带紫。花落而无子。夏杪复着花，如小笔。又有一种，花、叶皆同，但三月花开，四月花 \n落，子赤似相思子。二种所在山谷皆有。 \n禹锡曰∶今苑中有树，高三、四丈，其枝繁茂。正、二月花开，紫白色。花落乃生叶， \n夏初复生花。经秋历冬，叶花渐大，如有毛小桃，至来年正、二月始开。初是兴元府进来， \n树才三、四尺，有花无子，经二十余年方结实。盖年浅者无子，非有二种也。其花开早晚， \n各随方土节气尔。宗 曰∶辛夷，处处有之，人家园亭亦多种植。先花后叶，即木笔花也。 \n其花未开时，苞上有毛，尖长如笔，故取象而名。花有桃红、紫色二种，入药当用紫者，须 \n未开时收之，已开者不佳。时珍曰∶辛夷花，初出枝头，苞长半寸，而尖锐俨如笔头，重重 \n有青黄茸毛顺铺，长半分许。及开则似莲花而小如盏，紫苞红焰，作莲及兰花香。亦有白色 \n者，人呼为玉兰。又有千叶者。诸家言苞似小桃者，比类欠当。 \n\\x苞\\x \n【修治】 曰∶凡用辛夷，拭去赤肉毛了，以芭蕉水浸一宿，用浆水煮之，从巳至未， \n取出焙干用。若治眼目中患，即一时去皮，用向里实者。 \n大明曰∶入药微炙。 \n【气味】辛，温，无毒。 \n时珍曰∶气味俱薄，浮而散，阳也。入手太阴、足阳明经。 \n之才曰∶芎 为之使。恶五石脂，畏菖蒲、蒲黄、黄连、石膏、黄环。 \n【主治】五脏身体寒热，风头脑痛面 。久服下气，轻身明目，增年耐老（《本经》）。 \n温中解肌，利九窍，通鼻塞涕出，治面肿引齿痛，眩冒身兀兀如在车船之上者，生须发， \n去白虫（《别录》）。通关脉，治头痛憎寒，体噤瘙痒。入面脂，生光泽（大明）。鼻渊鼻鼽， \n鼻窒鼻疮，及痘后鼻疮，并用研末，入麝香少许，葱白蘸入数次，甚良 \n【发明】时珍曰∶鼻气通于天。天者，头也、肺也。肺开窍于鼻，而阳明胃脉环鼻而上 \n行。 \n脑为元神之府，而鼻为命门之窍。人之中气不足，清阳不升，则头为之倾，九窍为之不 \n利。辛夷之辛温走气而入肺，其体轻浮，能助胃中清阳上行通于天。所以能温中，治头面目 \n鼻 \n\n\n\n<目录>木部第三十四卷\\木之一\n\n<篇名>沉香\n\n内容：（《别录》上品） \n【释名】沉水香（《纲目》）、蜜香。 \n时珍曰∶木之心节置水则沉，故名沉水，亦曰水沉。半沉者为栈香，不沉者为黄熟香。 \n《南越志》言∶交州人称为蜜香，谓其气如蜜脾也。梵书名阿迦 香。 \n【集解】恭曰∶沉香、青桂、鸡骨、马蹄、煎香，同是一树，出天竺诸国。木似榉柳， \n树皮青色。叶似橘叶，经冬不凋。夏生花，白而圆。秋结实似槟榔，大如桑椹，紫而味辛。 \n藏器曰∶沉香，枝、叶并似椿。云似橘者，恐未是也。其枝节不朽，沉水者为沉香；其 \n肌理有黑脉，浮者为煎香。鸡骨、马蹄皆是煎香，并无别功，止可熏衣去臭。 \n颂曰∶沉香、青桂等香，出海南诸国及交、广、崖州。沈怀远《南越志》云∶交趾蜜香 \n树，彼人取之，先断其积年老木根，经年其外皮干俱朽烂，木心与枝节不坏，坚黑沉水者， \n即沉香也。半浮半沉与水面平者，为鸡骨香。细枝紧实未烂者，为青桂香。其干为栈香。其 \n根为黄熟香。其根节轻而大者，为马蹄香。此六物同出一树，有精粗之异尔，并采无时。刘 \n恂《岭表录异》云∶广管罗州多栈香树，身似柜柳，其花白而繁，其叶如橘。其皮堪作纸， \n名香皮纸，灰白色，有纹如鱼子，沾水即烂，不及楮纸，亦无香气。沉香、鸡骨、黄熟、栈 \n香虽是一树，而根、干、枝、节，各有分别也。又丁谓《天香传》云∶此香奇品最多。四香 \n凡四名十二状，出于一本。木体如白杨，叶如冬青而小。海北窦、化、高、雷皆出香之地， \n比海南者优劣不侔。既所禀不同，复售者多而取者速，其香不待稍成，乃趋利戕贼之深也。 \n非同琼管黎人，非时不妄剪伐，故木无夭札之患，得必异香焉。宗 曰∶岭南诸郡悉有，傍 \n海处尤多。交干连枝，冈岭相接，千里不绝。叶如冬青，大者数抱，木性虚柔。山民以构茅 \n庐，或为桥梁，为饭甑，为狗槽，有香者百无一、二。盖木得水方结，多在折枝枯干中，或 \n为沉，或为煎，或为黄熟。自枯死者，谓之水盘香。南恩、高、窦等州，惟产生结香。盖山 \n民入山，以刀斫曲干斜枝成坎，经年得雨水浸渍，遂结成香。乃锯取之，刮去白木，其香结 \n为斑点，名鹧鸪斑，燔之极清烈。香之良者，惟在琼、崖等州，俗谓之角沉、黄沉，乃枯木 \n得者，宜入药用。依木皮而结者，谓之青桂，气尤清。在土中岁久，不待 剔而成薄片者， \n谓之龙鳞。削之自卷，咀之柔韧者，谓之黄蜡沉，尤难得也。承曰∶诸品之外，又有龙鳞、 \n麻叶、竹叶之类，不止一、二十品。要之入药惟取中实沉水者。或沉水而有中心空者，则是 \n鸡骨。谓中有朽路，如鸡骨中血眼也。时珍曰∶沉香品类，诸说颇详。今考杨亿《谈苑》、 \n蔡绦《丛谈》、范成大《桂海志》、张师正《倦游录》、洪驹父《香谱》、叶廷 《香录》诸书， \n撮其未尽者补之云。香之等凡三∶曰沉，曰栈，曰黄熟是也。沉香入水即沉，其品凡四∶曰 \n熟结，乃膏脉凝结自朽出者；曰生结，乃刀斧伐仆，膏脉结聚者；曰脱落，乃因水朽而结者； \n曰虫漏，乃因蠹隙而结者。生结为上，熟脱次之。坚黑为上，黄色次之。角沉黑润，黄沉黄 \n润，蜡沉柔韧，革沉纹横，皆上品也。海岛所出，有如石杵，如肘如拳，如凤雀龟蛇，云气 \n人物。及海南马蹄、牛头、燕口、茧栗、竹叶、芝菌、梭子、附子等香，皆因形命名尔。其 \n栈香入水半浮半沉，即沉香之半结连木者，或作煎香，番名婆木香，亦曰弄水香。其类有 \n刺香、鸡骨香、叶子香，皆因形而名。有大如笠者，为蓬莱香。有如山石枯槎者，为光香。 \n入药皆次于沉香。其黄熟香，即香之轻虚者，俗讹为速香是矣。有生速，斫伐而取者。有熟 \n速，腐朽而取者。其大而可雕刻者，谓之水盘头。并不堪入药，但可焚 。叶廷 云∶出 \n渤泥、占城、真腊者，谓之番沉，亦曰舶沉，曰药沉，医家多用之，以真腊为上。蔡绦云∶ \n占城不若真腊，真腊不若海南黎峒。黎峒又以万安黎母山东峒者，冠绝天下，谓之海南沉， \n一片万钱。海北高、化诸州者，皆栈香尔。范成大云∶黎峒出者名土沉香，或曰崖香。虽薄 \n如纸者，入水亦沉。万安在岛东，钟朝阳之气，故香尤酝藉，土人亦自难得。舶沉香多腥烈， \n尾烟必焦。交趾海北之香，聚于钦州，谓之钦香，气尤酷烈。南人不甚重之，惟以入药。 \n【正误】时珍曰∶按∶李 《海药本草》谓沉者为沉香，浮者为檀香。梁元帝《金楼子》 \n谓一木五香∶根为檀，节为沉，花为鸡舌，胶为熏陆，叶为藿 \n并误也。五香各是一种。所谓五香一本者，即前苏恭所言，沉、栈、青桂、马蹄、鸡骨 \n者是矣。 \n【修治】 曰∶凡使沉香，须要不枯，如觜角硬重沉于水下者为上，半沉者次之。不可 \n见火。时珍曰∶欲入丸散，以纸裹置怀中，待燥研之。或入乳钵以水磨粉，晒干亦可。若入 \n煎 \n【气味】辛，微温，无毒。 曰∶苦，温。大明曰∶辛，热。元素曰∶阳也。有升有降。 \n时珍曰∶咀嚼香甜者性平，辛辣者性热。 \n【主治】风水毒肿，去恶气（《别录》）。主心腹痛，霍乱中恶，邪鬼疰气，清人神，并 \n宜酒煮服之。诸疮肿，宜入膏中（李 ）。调中，补五脏，益精壮阳，暖腰膝，止转筋、吐 \n泻冷气，破症癖，冷风麻痹，骨节不任，风湿皮肤瘙痒，气痢（大明）。补右肾命门（元素）。 \n补脾胃，及痰涎、血出于脾（李杲）。益气和神（刘完素）。治上热下寒，气逆喘急，大肠虚 \n闭，小 \n【附方】新七。 \n诸虚寒热，冷痰虚热∶冷香汤∶用沉香、附子（炮）等分，水一盏，煎七分，露一夜， \n空心温服。（王好古《医垒元戎》） \n胃冷久呃∶沉香、紫苏、白豆蔻仁各一钱。为末。每柿蒂汤服五、七分。（吴球《活人 \n心统》） \n心神不足，火不降，水不升，健忘惊悸∶朱雀丸∶用沉香五钱，茯神二两，为末，炼蜜 \n和丸小豆大。每食后人参汤服三十丸，日二服。（王 《百一选方》） \n肾虚目黑，暖水脏∶用沉香一两，蜀椒（去目，炒出汗）四两，为末，酒糊丸梧桐子大。 \n每服三十丸，空心，盐汤下。（《普济方》） \n胞转不通∶非小肠、膀胱、厥阴受病，乃强忍房事，或过忍小便所致，当治其气则愈， \n非利药可通也。沉香、木香各二钱，为末。白汤空腹服之，以通为度。（《医垒元戎》） \n大肠虚闭，因汗多，津液耗涸者∶沉香一两，肉苁蓉（酒浸焙）二两，各研末，以麻 \n仁研汁作糊，丸梧桐子大。每服一百丸，蜜汤下。（严子礼《济生方》） \n檀香、乳香等分， 于盆内。抱儿于上熏之，即起。（鲜于枢《钩玄》） \n\n\n\n<目录>木部第三十四卷\\木之一\n\n<篇名>蜜香\n\n内容：（《拾遗》） \n【释名】木蜜（《内典》）、没香（《纲目》）、 \n【集解】藏器曰∶蜜香生交州。大树，节如沉香。《法华经》注云∶木蜜，香蜜也。树 \n形似槐而香，伐之五、六年，乃取其香。《异物志》云∶其叶如椿。树生千岁，斫仆之，四、 \n五岁乃往看，已腐败，惟中节坚贞者是香。 曰∶生南海诸山中。种之五、六年便有香。《交 \n州记》云∶树似沉香无异也。时珍曰∶按∶《魏王花木志》云∶木蜜号千岁树，根本甚大， \n伐之四、五岁，取不腐者为香。观此，则陈藏器所谓生千岁乃斫者，盖误讹也。段成式《酉 \n阳杂俎》云∶没树出波斯国、拂林国人呼为阿KT 。树长丈余，皮青白色，叶似槐而长， \n花似橘花而大。子黑色，大如山茱萸，酸甜可食。《广州志》云∶肇庆新兴县出多香木，俗 \n名蜜香。辟恶气，杀鬼精。《晋书》云∶太康五年，大秦国献蜜香树皮纸，微褐色，有纹如 \n鱼子，极香而坚韧。观此数说，则蜜香亦沉香之类，故形状功用两相仿佛。《南越志》谓∶ \n交人称沉香为蜜香。《交州志》谓∶蜜香似沉香。《岭表录异》言∶栈香皮纸似鱼子。尤可互 \n证。杨慎《丹铅录》言蜜树是蜜蒙花树者，谬也。又枳 木亦名木蜜，不知亦同类否？详见 \n果部。 \n【气味】辛，温，无毒。 \n【主治】去臭，除鬼气（藏器）。辟恶，去邪鬼尸注心气 \n\n\n\n<目录>木部第三十四卷\\木之一\n\n<篇名>丁香\n\n内容：（宋《开宝》） \n【校正】并入《别录》鸡舌香。 \n【释名】丁子香（《嘉 》）、鸡舌香。 \n藏器曰∶鸡舌香与丁香同种，花实丛生，其中心最大者为鸡舌（击破有顺理而解为两向， \n如鸡舌，故名），乃是母丁香也。禹锡曰∶按∶《齐民要术》云∶鸡舌香，俗人以其似丁子， \n故呼为丁子香。 \n【集解】恭曰∶鸡舌香树叶及皮并似栗，花如梅花，子似枣核，此雌树也，不入香用。 \n其雄树虽花不实，采花酿之以成香。出昆仑及交州、爱州以南。 曰∶丁香生东海及昆仑 \n国。 \n志曰∶丁香生交、广、南番。按∶《广州图》上丁香，树高丈余，木类桂，叶似栎叶。花圆 \n细，黄色，凌冬不凋。其子出枝蕊上如钉，长三、四分，紫色。其中有粗大如山茱萸者，俗 \n呼为母丁香。二月、八月采子及根。一云∶盛冬生花，子，至次年春采之。颂曰∶鸡舌香， \n《唐本草》言其木似栗；《南越志》言是沉香花；《广志》言是草花蔓 \n香口。其说不定。今人皆以乳香中拣出木实似枣核者为之，坚顽枯燥，绝无气味，烧亦无 \n香，用疗气与口臭则甚乖疏，不知缘何以为鸡舌也？京下老医言∶鸡舌与丁香同种，其中最 \n大者为鸡舌，即母丁香，疗口臭最良，治气亦效。葛稚川《百一方》∶治暴气刺心痛，用鸡 \n舌香酒服。又《抱朴子》书∶以鸡舌、黄连，乳汁煎之，注目，治百疹之在目者皆愈，更加 \n精明。古方治疮痈五香连翘汤用鸡舌香，而孙真人《千金方》无鸡舌，用丁香，似为一物也。 \n其采花酿成香之说，绝无知者。慎微曰∶沈存中《笔谈》云∶予集《灵苑方》，据陈藏器《拾 \n遗》，以鸡舌为丁香母。今考之尚不然，鸡舌即丁香也。《齐民要术》言鸡舌俗名丁子香。《日 \n华子》言丁香治口气，与《三省故事》载汉时郎官日含鸡舌香，欲其奏事芬芳之说相合。及 \n《千金方》五香汤用丁香无鸡舌，最为明验。《开宝本草》重出丁香，谬矣。今世以乳香中 \n大如山茱萸者为鸡舌，略无气味，治疾殊乖。承曰∶《嘉 补注》及苏颂《图经》引诸书， \n以鸡舌为丁香。《抱朴子》言可注眼。但丁香恐不宜入眼，含之口中热臭不可近。乳香中所 \n拣者，虽无气味，却无臭气，有淡利九窍之理。诸方用治小儿惊痫，亦欲其达九窍也。 曰∶ \n丁香有雌、雄。雄者颗小；雌者大如山茱萸，更名母丁香，入药最胜。时珍曰∶雄为丁香， \n雌为鸡舌，诸说甚明，独陈承所言甚为谬妄不知乳香中所拣者，乃番枣核也，即无漏子之核， \n见果部。前人不知丁香即鸡舌，误以此物充之尔。干姜、焰硝尚可点眼，草果、阿魏番人以 \n作食料，则丁香之点眼、噙口，又何害哉？ \n【气味】辛，微温，无毒。时珍曰∶辛，温。 \n【主治】风水毒肿，霍乱心痛，去恶气（《别录》）。吹鼻，杀脑疳。入诸香中，令人身 \n香（甄权）。同姜汁，涂拔去白须 \n\\x丁香\\x（《开宝》） \n【气味】辛，温，无毒。时 \n好古曰∶纯阳。入手太阴、足少阴、阳明经。 \n曰∶方中多用雌者，力大。膏煎中若用雄，须去丁，盖乳子发人背痈也。不可见火。 \n畏郁金。 \n【主治】温脾胃，止霍乱拥胀，风毒诸肿，齿疳 。能发诸香（《开宝》）。风疳 骨槽 \n劳臭，杀虫辟恶去邪，治奶头花，止五色毒痢、疗五痔（李 ）。治口气、冷气、冷劳反胃、 \n鬼疰、蛊毒，杀酒毒，消 癖，疗肾气、奔豚气、阴痛、腹痛，壮阳，暖腰膝（大明）。疗 \n呕逆，甚验（保升）。去胃寒，理元气。气血盛者勿服（元素）。治虚哕，小儿吐泻，痘疮胃 \n虚，灰白不 \n【发明】好古曰∶丁香与五味子、广术同用，治奔豚之气。亦能泄肺，能补胃，大能疗 \n肾。 \n丁香气味尤佳。震亨曰∶口居上，地气出焉。脾有郁火，溢入肺中，失其清和之意，而浊气 \n上行，发为口气。若以丁香治之，是扬汤止沸尔。惟香薷治之甚捷。时珍曰∶宋末太医陈文 \n中，治小儿痘疮不光泽，不起发，或胀或泻，或渴或气促，表里俱虚之证。并用木香散、异 \n攻散，倍加丁香、官桂。甚者丁香三、五十枚，官桂一、二钱。亦有服之而愈者。此丹溪朱 \n氏所谓立方之时，必运气在寒水司天之际，又值严冬郁遏阳气，故用大辛热之剂发之者也。 \n若不分气血虚实寒热经络，一概骤用，其杀人也必矣。葛洪《抱朴子》云∶凡百病在目者， \n以鸡舌香、黄连、乳汁煎注之，皆愈。此得辛散苦降养阴之妙。陈承言不可点眼者，盖不知 \n此理也。 \n【附方】旧九，新十七。 \n暴心气痛∶鸡舌香末， \n酒服一钱。（《肘后方》） \n干霍乱痛，不吐不下∶ \n丁香十四枚，研末，以沸汤一升和之，顿服。不瘥更作。（思邈《千金方》） \n小儿吐泻∶丁香、橘红等分，炼蜜丸黄豆大。米汤化下。（刘氏《小儿方》） \n小儿呕吐不止∶丁香、生半夏各一钱，姜汁浸一夜，晒干为末，姜汁打面糊丸黍米大。 \n量大小，用姜汤下。《全幼心鉴》 \n婴儿吐乳∶小儿百日 内吐乳，或粪青色。 \n用年少妇人乳汁一盏，入丁香十枚，陈皮（去白）一钱，石器煎一、二十沸，细细与服。 \n（陈文中《小儿方》） \n小儿冷疳，面黄腹大，食即吐者∶母丁香七枚，为末，乳汁和蒸三次，姜汤服之。（《卫 \n生易 \n胃冷呕逆，气厥不通∶母丁香三个，陈橘皮一块（去白焙），水煎，热服。（《十便良方》）。 \n反胃吐食∶《袖珍方》∶用母丁香一两为末，以盐梅入捣和，丸芡子大。每噙一丸。《圣 \n惠方》∶用母丁香、神曲（炒）等分，为末。米饮服一钱。朝食暮吐∶丁香十五个研末，甘 \n蔗汁、姜汁和，丸莲子大。噙咽之。（《摘玄方》）。 \n反胃关格，气噎不通∶丁香、木香各一两。每服四钱，水一盏半，煎一盏。先以黄泥做 \n成碗，滤药汁于内，食前服。此方乃掾史吴安之传于都事盖耘夫有效，试之果然。土碗取其 \n助脾也。（《德生堂经验方》）。 \n伤寒呃逆及哕逆不定∶丁香一两，干柿蒂（焙）一两，为末。每服一钱，煎人参汤下。 \n（《简要济众方》） \n毒肿入腹∶鸡舌香、青木香、薰陆香、麝香各一两，水四升，煮二升，分二服。（《肘 \n后方》）。 \n食蟹致伤∶丁香末，姜汤服五分。（《证治要诀》） \n妇人崩中昼夜不止∶丁香二两。酒二升，煎一升，分服。（《梅师方》）。 \n妇人难产∶母丁香三十六粒，滴乳香三钱六分，为末，同活兔胆和杵千下，丸作三十六 \n丸。每服一丸，好酒化下，立验。名如意丹。（《颐真堂经验方》）。 \n妇人阴冷∶母丁香末，纱囊盛如指大，纳入阴中，病即已。（《本草衍义》）。 \n鼻中息肉∶丁香绵裹纳之。（《圣惠方》） \n风牙宣露，发歇口气∶鸡舌香、射干各一两，麝香一分，为末，日揩。（《圣济总录》）。 \n龋齿黑臭∶鸡舌香煮汁，含之。（《外台秘要》）。 \n唇舌生疮∶鸡舌香末，绵裹含之。（《外台》）。 \n乳头裂破∶丁香末，敷之。（《梅师方》）。 \n妒乳乳痈∶丁香末，水服方寸匕。（《梅师方》）。 \n痈疽恶肉∶丁香末，敷之，外以膏药护 \n桑蝎螫人∶丁香末，蜜调涂。（《圣惠方》）。 \n香衣辟汗∶丁香一两为末，川椒六十粒和之。 \n绢袋盛佩，绝无汗气。（《多能鄙事》）。 \n\\x丁皮\\x \n时珍曰∶即树皮也。似桂皮而浓。 \n【气味】同香。 \n【主治】齿痛（李 ）。心腹冷气 \n\\x枝\\x \n【主治】一切冷气，心腹胀满，恶心，泄泻虚滑，水谷不消（用枝杖七斤，肉豆蔻（面 \n煨）八斤，白面（炒）六斤，甘草（炒）十一斤，炒盐中三斤），为末。日 \n药院方》）。 \n\\x根\\x \n【气味】辛，热，有毒。 \n【主治】风热毒肿。不入心腹之用（《开宝》）。 \n\n\n\n<目录>木部第三十四卷\\木之一\n\n<篇名>檀香\n\n内容：（《别录》下品） \n【释名】旃檀（《纲目》）、真檀。 \n时珍曰∶檀，善木也，故字从 。 ，善也。释氏呼为旃檀，以为汤沐，犹言离垢也。 \n番人讹为真檀。云南人呼紫檀为胜沉香，即赤檀也。 \n【集解】藏器曰∶白檀出海南。树如檀。 \n恭曰∶紫真檀出昆仑盘盘国。虽不生中华，人间遍有之。 \n不香尔。 \n时珍曰∶按∶《大明一统志》云∶檀香出广东、云南，及占城、真腊、爪哇、渤泥、暹 \n罗、三佛齐、回回等国，今岭南诸地亦皆有之。树、叶皆似荔枝，皮青色而滑泽。叶廷 \n《香谱》云∶皮实而色黄者为黄檀，皮洁而色白者为白檀，皮腐而色紫者为 \n其木并坚重清香，而白檀尤良。宜以纸封收，则不泄气。王佐《格古论》云∶紫檀诸溪 \n峒出之。性坚。新者色红，旧者色紫，有蟹爪文。新者以水浸之，可染物。真者揩壁上色紫 \n，故有紫檀名。黄檀最香。俱可作带 、扇骨等物。 \n\\x白旃檀\\x \n【气味】辛，温，无毒。 \n大明曰∶热。 \n元素曰∶阳中微阴。入手太阴、足少阴，通行阳明经。 \n【主治】消风热肿毒（弘景）。治中恶鬼气，杀虫（藏器）。煎服，止心腹痛，霍乱肾气 \n痛。 \n水磨，涂外肾并腰肾痛处（大明）。散冷气，引胃气上升，进饮食（元素）。噎膈吐食。又面 \n生黑子，每夜以浆水洗拭令赤，磨汁涂之，甚良（时珍）。 \n【发明】杲曰∶白檀调气，引芳香之物，上至极高之分。最宜橙、橘之属，佐以姜、枣， \n辅以葛根、缩砂、益智、豆蔻，通行阳明之经，在胸膈之上，处咽嗌之间，为理气要药。 \n时珍曰∶《楞严经》云∶白旃檀涂身，能除一切热恼。今西南诸番酋，皆用诸香涂身，取此 \n义也。杜宝《大业录》云∶隋有寿禅师妙医术，作五香饮济人。沉香饮、檀香饮、丁香饮、 \n泽兰饮、甘松饮，皆以香为主，更加别药，有味而止渴，兼补益人也。道书檀香谓之浴香， \n不可烧供上真。 \n\\x紫檀\\x \n【气味】咸，微寒，无毒。 \n【主治】摩涂恶毒风毒（《别录》）。 \n刮末敷金疮，止血止痛。疗淋（弘景）。醋磨，敷一切猝肿（千金）。 \n【发明】时珍曰∶白檀辛温，气分之药也。 \n故能理卫气而调脾肺，利胸膈。紫檀咸寒，血分之药也。故能和营气而消肿毒，治金疮。 \n\n\n\n<目录>木部第三十四卷\\木之一\n\n<篇名>降真香\n\n内容：（《证类》） \n【释名】紫藤香（《纲目》）、鸡骨香。 \n曰∶《仙传》∶拌和诸香，烧烟直上，感引鹤降。醮星辰，烧此香为第一，度 功力极 \n验。降真之名以此。 \n时珍曰∶俗呼舶上来者为番降，亦名鸡骨，与沉香同名。 \n【集解】慎微曰∶降真香出黔南。 \n曰∶生南海山中及大秦国。其香似苏方木，烧之初不甚香，得诸香和之则特美。入药 \n以番降紫而润者为良。 \n时珍曰∶今广东、广西、云南、汉中、施州、永顺、保靖，及占城、安南、暹罗、渤泥、 \n琉球诸地皆有之。朱辅《溪蛮丛笑》云；鸡骨香即降香，本出海南。今溪峒僻处所出者，似 \n是而非，劲瘦不甚香。周达观《真腊记》云∶降香生丛林中，番人颇费砍斫之功，乃树心也。 \n其外白皮，浓八、九寸，或五、六寸。焚之气劲而远。又嵇含《草木状》云∶紫藤香，长茎 \n细叶，根极坚实，重重有皮，花白子黑。其茎截置烟炱中，经久成紫香，可降神。按∶嵇氏 \n所说，与前说稍异，岂即朱氏所谓似是而非者乎？抑中国者与番降不同乎？ \n【气味】辛，温，无毒。 \n【主治】烧之，辟天行时气，宅舍怪异。小儿带之，辟邪恶气（李 ）。疗折伤金疮， \n止血定痛，消肿生肌（时珍）。 \n【发明】时珍曰∶降香，唐、宋本草失收。唐慎微始增入之，而不着其功用。今折伤金 \n疮家多用其节，云可代没药、血竭。按∶《名医录》云∶周 被海寇刃伤，血出不止，筋如 \n断，骨如折，用花蕊石散不效。军士李高用紫金散掩之，血止痛定。明日结痂如铁，遂愈， \n且无瘢痕。叩其方，则用紫藤香瓷瓦刮下研末尔。云即降之最佳者，曾救万人。罗天益《卫 \n生宝 \n【附方】新二。 \n金疮出血∶降真香、五倍子、铜花等分为末，敷之。（《医林集要》） \n痈疽恶毒∶番降末、枫、乳香，等分为丸，熏之，去恶气甚妙。（《集简方》） \n\n\n\n<目录>木部第三十四卷\\木之一\n\n<篇名>楠\n\n内容：（《别录》下品） \n【校正】并入《海药》闸极木皮，《拾遗》 木枝叶。 \n【释名】 （与楠字同）。 \n时珍曰 \n【集解】藏器曰∶ 木高硕，叶如桑，出南方山中。 \n宗 曰∶楠材，今江南造船皆用之，其木性坚而善居水。久则当中空，为白蛾所穴。 \n时珍曰∶楠木生南方，而黔、蜀诸山尤多。其树直上，童童若幢盖之状，枝叶不相碍。 \n叶似豫章，而大如牛耳，一头尖，经岁不凋，新陈相换。其花赤黄色。实似丁香，色青，不 \n可食。干甚端伟，高者十余丈，巨者数十围，气甚芬芳，为梁栋器物皆佳，盖良材也。色赤 \n者坚，白者脆。其近根年深向阳者，结成草木山水之状，俗呼为骰柏楠，宜作器。 \n\\x楠材\\x \n【气味】辛，微温，无毒。藏器曰∶苦，温，无毒。 \n大明曰∶热，微毒。 \n【主治】霍乱吐下不止，煮汁服（《别录 \n【附方】新三。 \n水肿自足起∶削楠木、桐木煮汁渍足，并饮少许，日日为之。（《肘后方》） \n心胀腹痛，未得吐下∶取楠木削三、四两，水三升，煮三沸，饮之。（ \n耳出脓∶楠木烧研，以棉杖缴入。（《圣惠方》） \n\\x皮\\x \n【气味】苦，温，无毒。 \n【主治】霍乱吐泻，小儿吐乳，暖胃正气，并宜煎服（李 ）。 \n\n\n\n<目录>木部第三十四卷\\木之一\n\n<篇名>樟\n\n内容：（《拾遗》） \n【释名】时珍曰∶其木理多纹章，故谓之樟。 \n【集解】藏器曰∶江东KT 船多用樟木。县名豫章，因木得名。 \n时珍曰∶西南处处山谷有之。木高丈余。小叶似楠而尖长，背有黄赤茸毛，四时不凋。 \n夏开细花，结小子。木大者数抱，肌理细而错纵有纹，宜于雕刻，气甚芬烈。豫、章乃二木 \n名，一类二种也。豫即钓樟，见下条。 \n\\x樟材\\x \n【气味】辛，温，无毒。 \n【主治】恶气中恶，心腹痛鬼疰，霍乱腹胀，宿食不消，常吐酸臭水，酒煮服，无药处 \n用之。煎汤，浴香港脚、疥癣风痒。作履， \n【发明】时珍曰∶霍乱及干霍乱须吐者。以樟木屑煎浓汁吐之，甚良。又中恶 \n死者，以樟木烧烟熏之，待苏乃用药。此物辛烈香窜，能去湿气、辟邪恶故也。 \n【附方】新一。 \n手足痛风，冷痛如虎咬者∶用樟木屑一斗，急流水一石，煎极滚泡之，乘热安足于桶上 \n熏之。以草荐围住，勿令汤气入目。其功甚捷，此家传经验方也。（虞抟《医学正 \n\\x瘿节\\x \n【主治】风疰鬼邪（时珍）。 \n【附方】新一。 \n三木节散∶治风劳，面色青白，肢节沉重，膂间痛，或寒或热，或躁或嗔，思食不能食， \n被虫侵蚀，症状多端。天灵盖（酥炙，研）二两，牛黄、人中白（焙）各半两，麝香二钱， \n为末。 \n别以樟木瘤节、皂荚木瘤节、槐木瘤节各为末五两，每以三钱，水一盏，煎半盏，去滓，调 \n前末一钱，五更顿服，取下虫物为妙。（《圣惠方》） \n\n\n\n<目录>木部第三十四卷\\木之一\n\n<篇名>钓樟\n\n内容：（《别录》下品） \n【校正】并入《拾遗》枕材。 \n【释名】乌樟（弘景）、KT \n时珍曰∶樟有大、小二种，紫、淡二色。此即樟之小者。按∶郑樵《通志》云∶钓樟亦 \n樟之类，即《尔雅》所谓“KT ，无疵”是也。又相如赋云∶ 、楠、豫、章。颜师古注 \n云∶ \n豫即枕木，章即樟木。二木生至七年，乃可分别。观此，则豫即《别录》所谓钓樟者也。根 \n似乌药香，故又名乌樟。 \n【集解】弘景曰∶钓樟出桂阳、邵陵诸处，亦呼作乌樟， \n恭曰∶生郴州山谷。树高丈余。叶似楠叶而尖长，背有赤毛，若枇杷叶上毛。八月、九 \n月采根皮，晒干。 \n炳曰∶根似乌药香。 \n藏器曰∶枕生南海山谷。作KT 船，次于樟木。 \n\\x根皮\\x \n【气味】辛，温，无毒。 \n【主治】金疮止血，刮屑敷之，甚验（《别录》）。磨服，治霍乱（萧炳）。治奔豚香港脚水 \n肿，煎汤服。亦可浴疮痍疥癣风瘙，并研末敷之（大明）。 \n\\x茎叶\\x \n【主治】置门上，辟天行时气（萧炳）。 \n\n\n\n<目录>木部第三十四卷\\木之一\n\n<篇名>乌药\n\n内容：（宋《开宝》） \n【释名】旁其（《拾遗》）、 \n时珍曰∶乌以色名。其叶状似 鲫鱼，故俗呼为 树。《拾遗》作旁其，方音讹也。 \n南人亦呼为矮樟，其气似樟也。 \n【集解】藏器曰∶乌药生岭南。邕州、容州及江南。树生似茶，高丈余。一叶三丫，叶 \n青阴白。根状似山芍药及乌樟，根色黑褐，作车毂纹，横生，八月采根。其直根者不堪用。 \n颂曰∶今台州、雷州、衡州皆有之，以天台者为胜。木似茶 ，高五、七尺。叶微圆而尖， \n面青背白，有纹。四、五月开细花，黄白色。六月结实。根有极大者，又似钓樟根。然根有 \n二种∶岭南者黑褐色而坚硬，天台者白而虚软，并以八月采。根如车毂纹、形如连珠者佳。 \n或云∶天台者香白可爱，而不及海南者力大。承曰∶世称天台者为胜。今比之洪州、衡 \n州者， \n天台香味为劣，入药功效亦不及。但肉色颇赤，而差细小尔。时珍曰∶吴、楚山中极多，人 \n以为薪。根、叶皆有香气，但根不甚大，才如芍药尔。嫩 \n子，生青熟紫，核壳极薄。其仁亦香而苦。 \n\\x根\\x \n【气味】辛，温，无毒。 \n好古曰∶气浓于味，阳也。入足阳明、少阴经。 \n【主治】中恶心腹痛，蛊毒疰忤鬼气，宿食不消，天行疫瘴，膀胱肾间冷气攻冲背膂， \n妇人血气，小儿腹中诸虫（藏器）。治一切气除一切冷，霍乱、反胃吐食泻痢，痈疖疥疠， \n并解冷热，其功不可悉载。猫、犬百病，并可磨服（大明）。理元气（好古）。中气香港脚疝气， \n气厥头痛，肿胀喘急，止小便频数及白浊（时珍）。 \n【发明】宗 曰∶乌药性和，来气少，走泄多，但不甚刚猛。与沉香同磨作汤点服，治 \n胸腹冷气甚稳当。 \n时珍曰∶乌药辛温香窜，能散诸气。故《惠民和剂局方》治中风中气诸证，用乌药顺气 \n散者，先疏其气，气顺则风散也。严用和《济生方》治七情郁结，上气喘急，用四磨汤者， \n降中兼升，泻中带补也。其方以人参、乌药、沉香、槟榔各磨浓汁七分，合煎，细细咽之。 \n《朱氏集验方》治虚寒小便频数，缩泉丸，用同益智子等分为丸服者，取其通阳明、少阴经 \n也，方见草部益智子下。 \n【附方】新十一。 \n乌沉汤∶治一切气，一切冷，补五脏，调中壮阳，暖腰膝，去邪气，冷风麻痹，膀胱、 \n肾间冷气，攻冲背膂，俯仰不利，风水毒肿，吐泻转筋，症癖刺痛，中恶心腹痛，鬼气疰忤， \n天行瘴疫，妇人血气痛。用天台乌药一百两，沉香五十两，人参三两，甘草（ ）四两，为 \n末。每服半钱，姜盐汤空心点服。（《和剂局方》）一切气痛∶不拘男女，冷气、血气、肥气、 \n息贲气、伏梁气、奔豚气，抢心切痛，冷汗，喘息欲绝。天台乌药（小者，酒浸一夜，炒）、 \n茴香（炒）、青橘皮（去白，炒）、良姜（炒）等分，为末。温酒、童便调下。（《卫生家宝方》） \n男妇诸病∶香乌散∶用香附、乌药等分，为末。每服一、二钱。饮食不进，姜、枣汤下；疟 \n疾，干姜、白盐汤下；腹中有虫，槟榔汤下；头风虚肿，茶汤下；妇人冷气，米饮下；产后 \n血攻心脾痛，童便下；妇人血海痛、男子疝气，茴香汤下。（《乾坤秘韫》）。小肠疝气∶乌 \n药一两，升麻八钱。水二钟，煎一钟，露一宿，空心热服。（孙天仁《集效方》）。香港脚掣痛∶ \n乡村无药。初发时即取土乌药，不犯铁器，布揩去土，瓷瓦刮屑，好酒浸一宿。次早空心温 \n服，溏泄即愈。入麝少许，尤佳。痛入腹者，以乌药同鸡子瓦罐中水煮一日，取鸡子，切片 \n蘸食，以汤送下，甚效。（《永类钤方》）。血痢泻血∶乌药，烧存性，研，陈米饭丸梧桐子 \n大。每米饮下三十丸。（《普济方》）。 \n气厥头痛∶不拘多少，及产后头痛。天台乌药、川芎 等分，为末。每服二钱，腊茶清调下。 \n产后，铁锤烧红淬酒调下。（《济生方》）。 \n一盏，先噙后咽，吐出痰涎为愈。（《经验方》）。孕中有痈∶洪州乌药（软白香辣者）五钱， \n水一盏，牛皮胶一片，同煎至七分，温服。乃龚彦德方也。（《妇人良方》）。心腹气痛∶乌 \n药（水磨浓汁）一盏，入橘皮一片，苏一叶，煎服。（《集简方》） \n\\x嫩叶\\x \n【主治】炙碾煎饮代茗，补中益气，止小便滑数（藏器）。 \n【发明】时珍曰∶乌药，下通少阴肾经，上理脾胃元气。故丹溪朱氏 \n加乌药叶也。 \n\\x子\\x \n【主治】阴毒伤寒，腹痛欲死。取一合炒起黑烟，投水中，煎三、五沸，服一大盏，汗 \n出阳回即瘥（《斗门方》）。 \n【附录】研药 曰∶生南海诸州小树，叶如椒，根如乌药而圆小。根味苦，温，无毒。 \n主霍乱，下痢赤白，中恶蛊毒，腹内不调者。锉，水 \n\n\n\n<目录>木部第三十四卷\\木之一\n\n<篇名>香\n\n内容：（音怀。《纲目 \n【释名】兜娄婆香。 \n【集解】时珍曰∶ 香，江淮、湖岭山中有之。木大者近 \n叶青而长，有锯齿，状如小蓟叶而香，对节生。其根状如枸杞根而大，煨之甚香。《楞 \n严经》云∶坛前 \n\\x根\\x \n【气味】苦，涩，平，无毒。 \n【主治】头疖肿毒。碾末，麻脂调涂，七日腐落（时珍）。 \n\n\n\n<目录>木部第三十四卷\\木之一\n\n<篇名>必栗香\n\n内容：（《拾遗》） \n【释名】花木香、詹香。 \n【集解】藏器曰∶必栗香生高山中。叶如老椿，捣置上流，鱼悉暴腮而死。木 \n白鱼不损书也。 \n【气味】辛，温，无毒。 \n【主治】鬼疰心气，断一切恶气，煮汁服之。烧为香，杀虫、鱼（藏器）。 \n\n\n\n<目录>木部第三十四卷\\木之一\n\n<篇名>枫香脂\n\n内容：（《唐本草》） \n【释名】白胶香。 \n时珍曰∶枫树枝弱善摇，故字从风。俗呼香枫。《金光明经》谓其香为须萨折罗婆香。 \n颂曰∶《尔雅》谓枫为 ，言风至则 而鸣也。《梵书》谓之萨 罗婆香。 \n【集解】恭曰∶枫香脂，所在大山中皆有之。 \n颂曰∶今南方及关陕甚多。树甚高硕，似白杨。叶圆而作歧，有三角而香。二月有花， \n白色。乃连着实，大如鸭卵。八月、九月熟时，曝干可烧。《南方草木状》云∶枫实惟九真 \n有 \n枫木， \n南中有枫子鬼。木之老者为人形，亦呼为灵枫，盖瘤瘿也。至今越巫 \n可致灵异。 \n为枫木之林。《尔雅》注云∶其脂入地，千年为琥珀。 \n其木甚坚，有赤有白，白者细腻。其实成球，有 \n否？孙炎《尔雅正义》云∶枫子鬼乃 \n荀伯子《临 \n《宋齐丘化书》云∶老枫 \n\\x香脂\\x \n【修治】时珍曰∶凡用以齑水煮二十 \n【气味】辛、苦，平，无毒。 \n【主治】瘾疹风痒浮肿，煮水浴之。又主齿痛（《唐本》）。一切痈疽疮疥，金疮吐衄咯 \n血，活血生肌，止痛解毒。烧过揩牙，永无牙疾（时珍） \n【发明】震亨曰∶枫香属金，有水与火。其性疏通故木易有虫穴，为外科要药。近世不 \n知，误以松脂之清莹者为之，甚谬。 \n宗 曰∶枫香、松脂，皆可乱乳香。但枫香微白黄色，烧之可见真伪。 \n时珍曰∶枫香、松脂皆可乱乳香，其功虽次于乳香，而亦仿佛不远。 \n【附方 \n吐血不止∶白胶香为散。每服二钱，新汲 \n吐血衄血∶白胶香、蛤粉等分，为末。姜汁调服。（王 《百一选方》） \n吐血咯血∶《澹寮方》∶用白胶香、铜青各一钱，为末。入干柿内，纸包煨熟，食之。《圣 \n惠方》∶用白胶香（切片，炙黄）一两，新 \n金疮断筋∶枫香末敷之。（危氏方）。 \n便痈脓血∶白胶香一两。 \n为末。入麝香、轻粉少许，掺之。（《袖珍方》） \n小儿奶疽生面上∶用枫香为膏，摊贴之。（《活幼全书》） \n瘰 软疖∶白胶香一两（化开），以蓖 \n诸疮不合∶白胶香、轻粉各二钱，猪脂和涂。（《直指方》） \n一切恶疮∶水沉金丝膏∶用白胶香、沥青各一两，以麻油、黄蜡各二钱半，同熔化，入 \n冷 \n恶疮疼痛∶枫香、腻粉等分。为末。浆水洗净，贴之。（《寿亲养老书》）。 \n久近胫疮∶白胶香为末，以酒瓶上箬叶夹末，贴之。（《袖珍方》）。 \n小儿疥癣∶白胶香、黄柏、轻粉等分，为末。羊骨髓和，敷之。（《儒门事亲》） \n大便不通∶白胶香半枣大，鼠粪二枚，研匀，水和作挺。纳入肛内，良久自通。（《普 \n济方》） \n年久牙痛∶枫香脂为末。以香炉 \n鱼骨哽咽∶白胶香细细吞之。（《圣惠方》） \n\\x木皮\\x \n【气味】辛，平，有小毒（苏恭）。 \n【主治】水肿，下水气，煮汁用之（苏恭）。煎饮，止水痢为最（藏器）。止霍乱刺风冷 \n风，煎汤浴之 \n【正误】藏器曰∶枫皮性涩，能止水痢。苏云下水肿，水肿非涩药所疗，又云有毒，明 \n见其谬。 \n【附方】新一。 \n大风疮∶枫子木（烧存性，研）、轻粉等分，麻油调搽，极妙。章贡有鼓角匠病此，一 \n道人传方，遂愈。（《经验良方》） \n\\x根叶\\x \n【主治】痈疽已成，擂酒饮，以滓贴之（时珍）。 \n\\x菌\\x \n【气味】有毒，食之令人笑不止，地浆解之 \n\n\n\n<目录>木部第三十四卷\\木之一\n\n<篇名>薰陆香\n\n内容：（乳香）（《别录》上品） \n【释名】马尾香（《海药》）、天泽香（《内典 \n宗 曰∶薰陆即乳香，为其垂滴如乳头也。熔塌在地者为塌香，皆一也。 \n时珍曰∶佛书谓之天泽香，言其润泽也。又谓之多伽罗香，又曰杜噜香。李 言薰陆是 \n树皮，乳是树脂。陈藏器言乳是薰陆之类。寇宗 言是一物。 \n陈承言薰陆是总名，乳是薰陆之乳头也。今考《香谱》言乳有十余品，则乳乃熏陆中似 \n乳头之一品尔。陈承之说为近理。二物原附沉香下，宋《嘉 本草》分出二条，今据诸说， \n合并为一。 \n【集解】恭曰∶薰陆香形似白胶香，出天竺者色白，出单于者夹绿 \n曰∶按∶《广志》云∶薰陆香是树皮鳞甲 \n也，紫赤如樱桃，透明者为上。 \n云∶薰陆出大秦国。在海边有大树，枝叶正如古松，生于 \n胶。夷人采取卖与商贾，无贾则自食之。 \n之，谓之西香，南番者更佳，即乳香 \n承曰∶西出天竺，南出波斯等国。西者色黄白，南者色紫赤。日久重叠者，不成乳头， \n杂以沙石。其成乳者，乃新出未杂沙石者也。薰陆是总名，乳是薰陆之乳头也。今松脂、枫 \n脂中，亦有此状者甚多。 \n史》言乳香有一 \n松。以斤斫树，脂溢于外，结而成香，聚而成块。上品为拣香，圆大如乳头，透明，俗呼滴 \n乳。次曰明乳，其色亚于拣香。又次为瓶香，以瓶收者。又次曰袋香，言收时只置袋中。次 \n为乳塌，杂沙石者。次为黑塌，色黑。次为水湿塌，水渍色败气变者。次为斫削，杂碎不堪 \n。次为缠末，播扬为尘者。观此则乳有自流出者，有斫树溢出者。诸说皆言其树类松。寇氏 \n言类棠梨，恐亦传闻，当从前说。道书乳香、檀香谓之浴香，不可烧祀上真。 \n【修治】颂曰∶乳性至粘难碾。用时以缯袋挂于窗隙间，良久取研，乃不粘也。 \n大明曰∶入丸散，微炒杀毒，则不粘。 \n时珍曰∶或言乳香入丸药，以少酒研如泥，以水飞过，晒干用。或言以灯心同研则易细 \n。或言以糯米数粒同研，或言以人指甲二、三片同研，或言以乳钵坐热水中乳之，皆易细。 \n《外 \n【气味】微温，无毒。 \n大明曰∶乳香∶辛，热，微毒。元素曰∶苦、辛，纯阳。 \n震亨曰∶善窜，入手少阴经。 \n【主治】薰陆∶主风水毒肿，去恶气伏尸，瘾疹痒毒。乳香同功（《别录》）。乳香∶治 \n耳聋，中风口噤不语，妇人血气，止大肠泄 ，疗诸疮，令内消，能发酒，理风冷（藏器）。 \n下气益精，补腰膝，治肾气，止霍乱，冲恶中邪气，心腹痛疰气。煎膏， \n治不眠（之才）。补肾，定诸经之痛（元素）。仙方用以辟谷（李 ）。消痈疽诸毒，托里护 \n心 \n，活血定痛伸筋，治妇人难产折伤（时珍）。 \n【发明】时珍曰∶乳香香窜，能入心经，活血定痛，故为痈疽疮疡、心腹痛要药。《素 \n问》云诸痛痒疮疡皆属心火是矣。产科诸方多用之，亦取其活血之功尔。陈自明《妇人良方》 \n云∶知蕲州施少卿，得神寝丸方于蕲州徐太丞，云妇人临产月服之，令胎滑易生，极有效验。 \n用通明乳香半两，枳壳一两，为末，炼蜜丸梧桐子大，每空心酒服三十丸。李嗣立治痈疽初 \n起，内托护心散，云∶香彻疮孔中，能使毒瓦斯外出，不致内攻也。方见谷部绿豆下。按∶葛 \n洪《抱朴子》云∶浮炎洲在南海中，出薰陆香，乃树有伤穿，木胶流堕。夷人采之，恒患 \n兽啖之。此兽斫刺不死，以杖打之皮不伤，而骨碎乃死。观此，则乳香之治折伤，虽能活 \n血止痛，亦其性然也。杨清 \n【附方】旧四，新二十七。 \n口目 斜∶乳香烧烟熏之，以顺其血脉。（《证治要诀》） \n祛风益颜∶真乳香二斤，白蜜三斤。瓷器合煎如饧。每旦服二匙。（《奇效方》） \n急慢惊风∶乳香半两，甘遂半两。同研末。每服半钱，用乳香汤下，小便亦 \n《博济方》）。 \n小儿内钓腹痛∶用乳香、没药、木香等分，水煎服之。（阮氏《小儿方》）。 \n小儿夜啼∶乳香一钱，灯花七枚，为末。每服半字，乳汁下。（《圣惠方》）。 \n心气疼痛不可忍∶用乳香三两，真茶四两，为末，以腊月鹿血和，丸弹子大。每温醋化 \n一丸 \n冷心气痛∶乳香一粒，胡椒四十九粒。研，入姜汁，热酒调服。（潘氏《经验方》） \n阴症呃逆∶乳香同硫黄烧烟，嗅之。（《伤寒蕴要》） \n辟禳瘟疫∶每腊月二十四日五更，取第一汲井水浸乳香。至元旦五更温热，从小至大， \n每人以乳一块，饮水三呷，则一年无时灾。孔平仲云∶此乃宣圣之方，孔氏七十余代用之也 \n梦寐遗精∶乳香一块，拇指大，卧时细嚼，含至三更咽下，三、五服即效。（《医林集要》） \n淋癃溺血∶取乳香中夹石者，研细，米饮服一钱。（危氏《得效方》） \n难产催生∶《简要济众方》∶用黄明乳香五钱。为末，母猪血和丸梧桐子大。每酒服五丸。 \n《经验方》∶用乳香，以五月五日午时，令一人在壁内奉乳钵，一童子在壁外，以笔管自壁 \n缝中逐粒递过，放钵内研细，水丸芡子大。每服一丸，无灰酒下。《圣惠方》∶用明乳香一豆 \n大，为末，新汲水一盏，入醋少许。 \n令产妇两手捉石燕，念虑药三遍乃饮之。略行数步即下。 \n《海上方》∶用乳香、朱砂等分，为末。麝香酒服一钱，良久自下。 \n咽喉骨哽∶乳香一钱。 \n水研服之。（《卫生易简方》） \n香口辟臭∶滴乳噙之。（《摘玄方》） \n风虫牙痛不可忍者∶《梅师方》∶用薰陆香嚼，咽其汁，立瘥。《朱氏集验方》∶用乳香豆 \n许安孔中，烧烟箸烙化立止。 \n又方∶乳香、川椒末各一钱，为末，化蜡和作丸。塞孔中。《直指方》∶用乳香、巴豆等 \n分，研和蜡丸，塞之。《圣惠方》∶用乳香、枯矾等分，蜡丸。塞之。大风疠疾∶摩勒香一斤 \n（即乳头内光明者）细研，入牛乳五升，甘草末四两，瓷盒盛之，安桌子上，居中庭，安 \n剑 \n一口。夜于北极下祝祷，去盒子盖，露一夜。次日入甑中蒸，炊三斗米熟即止。夜间依前祝 \n露又蒸，如此三次乃止。每服一茶匙，空心及晚食前温酒调服。服后当有恶物出，至三日三 \n夜乃愈也。（《圣惠方》） \n漏疮脓血∶白乳香二钱，牡蛎粉一钱。为末，雪糕丸麻子大。每姜汤服三十丸。（《直 \n指方》） \n斑痘不快∶乳香研细，猪心血和，丸芡子大。每温水化服一丸。（闻人规《痘疹论》）。 \n痈疽寒颤∶乳香半两，熟水研服。颤发于脾，乳香能入脾故也。（《仁斋直指方》） \n甲疽弩肉，脓血疼痛不愈∶用乳香（为末）、胆矾（烧研）等分，敷之，内消即愈。（《灵 \n苑方》） \n玉茎作肿∶乳香、葱白等分，捣敷。（《山居四要》）。 \n野火丹毒自两足起∶乳香末，羊脂调涂。（《幼幼新书》） 疡风驳∶薰陆香、白蔹同研， \n日日揩之。并作末，水服。（《千金方》）。 \n\n\n\n<目录>木部第三十四卷\\木之一\n\n<篇名>没药\n\n内容：（宋《开宝》） \n【释名】末药。 \n时珍曰∶没、末皆梵言。 \n【集解】志曰∶没药生波斯国。其块大小不定，黑色，似安息香。 \n颂曰∶今海南诸国及广州或有之。木之根株皆如橄榄，叶青而密。岁久者，则有脂液流 \n滴在地下，凝结成块，或大或小，亦类安息香。采无时。 \n曰∶按∶徐表《南州记》云∶是波斯松脂也。状如神 \n时珍曰∶按∶《一统志》云∶没药树高硕如松，皮浓一、二寸。采时掘树下为坎，用斧 \n伐其皮 \n之误尔。所谓神香者，不知何物也？ \n【修治】同乳香。 \n【气味】苦，平，无毒。 \n【主治】破血止痛，疗金疮杖疮，诸恶疮痔漏，猝下血，目中翳晕痛肤赤（《开 \n破症瘕宿血，损伤瘀血，消肿痛（大明）。心胆虚，肝血不足（好古）。堕胎，及产后心 \n腹 \n血气痛，并入丸散服（李 ）。 \n【发明】权曰∶凡金刃所伤，打损 跌、坠马 \n调服。推陈致新，能生好血。 \n急，经络满急故痛且肿。凡打扑 跌，皆伤经络，气血不行，瘀壅作肿痛也。 \n活血，没药散血，皆能止痛消肿生肌。故二药每每相兼而用。 \n【附方】旧三，新六。 \n历节诸风，骨节疼痛，昼夜不止∶没药末半两，虎胫骨（酥炙，为末）三两。每服二钱， \n温酒调下。（《图经本草》） \n筋骨损伤∶米粉四两（炒黄），入没药、乳香末各半两，酒调成膏，摊贴之。（《御药院 \n方》） \n金刃所伤未透膜者∶乳香、没药各一钱，以童子小便半盏，酒半盏，温化服之。为末亦 \n可。（《奇效良方》）。 \n小儿盘肠气痛∶没药、乳香等分。为末。以木香磨水煎沸，调一钱服，立效。（汤氏《婴 \n孩宝书》）。 \n妇人腹痛，内伤 刺∶没药末一钱，酒服便止。（《图经本草》） \n妇人血晕∶方同上。 \n产后恶血∶没药、血竭末各一钱，童子小便、温酒各半盏，煎沸服，良久再服。恶血自 \n下，更不生痛。（《妇人良方》） \n女人异疾∶女人月事退出，皆作禽兽之形，欲来伤人。先将绵塞阴户，乃顿服没药末一 \n两，白汤调下，即愈。（危氏方） \n\n\n\n<目录>木部第三十四卷\\木之一\n\n<篇名>骐竭\n\n内容：（《唐本草》） \n【释名】血竭。 \n时珍曰∶骐 亦马名也。此物如干血，故谓之血竭。曰骐 者，隐之也。旧与紫 同条， \n紫乃此树 \n【集解】恭曰∶骐 竭树名渴留，紫 树名渴廪，二物大同小异。 \n志曰∶二物同条，功效全别。紫 色赤而黑，其叶大如盘， 从叶上出。骐 竭色黄而 \n赤，从木中出，如松脂。 \n曰∶按∶《南越志》云∶骐 竭，是紫 树之脂也。欲验真伪，但嚼之不烂如蜡者为 \n上。 \n木中流出，滴下如胶饴状，久而坚凝，乃成竭，赤作血色。采无时。旧说与紫 大都相类， \n而别是一物，功力亦殊。 曰∶凡使勿用海母血，真相似，只是味咸并腥气。骐 竭味微咸、 \n甘，似栀子气也。时珍曰∶骐 竭是树脂，紫 是虫造。按∶《一统志》云∶血竭树略如没 \n药树，其肌赤色。采法亦于树下掘坎，斧伐其树，脂流于坎，旬日取之。多出大食诸国。今 \n人试之，以透指甲者为真。 \n独孤滔《丹房镜源》云∶此物出于西胡，禀荧惑之气而结。以火烧之，有赤汁涌出，久 \n而灰不变本色者，为真也。 \n【修治】 曰∶凡使先研作粉，筛过入丸、散中用。若同众药捣，则化作尘飞也。 \n【气味】甘、咸，平，无毒。 \n【主治】心腹猝痛，金疮血出，破积血，止痛生肉，去五脏邪气（ \n一切疼痛，血气搅刺，内伤血聚，补虚，并宜酒服 \n益阳精，消阴滞气（《太 \n（大明）。散滞血诸痛，妇人血 \n【发明】时珍曰∶骐 竭，木之脂液，如人之膏血，其味甘咸而走血，盖手、足厥阴药 \n也。肝与心包皆主血故尔。河间刘氏云∶血竭除血痛，为和血之圣药，是矣。乳香、没药虽 \n主血病，而兼入气分，此则专于血分者也。 \n【附方】旧二，新十。 \n白虎风痛走注，两膝 \n新久香港脚∶血竭、乳香等分，同研 \n连面捣，丸梧桐子大。每温酒服三十丸。忌生冷。（《奇效方》）。 \n慢惊螈 ∶定魄安魂，益气。用血竭半两，乳香二钱半，同捣成剂，火炙熔丸梧桐子大。 \n每服一丸，薄荷煎汤化下。夏月用人参汤。（《御药院方》）。 \n鼻出衄血∶血竭、蒲黄等分为末，吹之。（《医林集要》）。 \n血痔肠风∶血竭末，敷之。（《直指方》）。 \n金疮出血∶骐 竭末，敷之立止。（《广利方》）。 \n产后血冲，心胸满喘，命在须臾∶用血竭、没药各一钱，研细，童便和酒调服。（《医 \n林集要》）。 \n产后血晕，不知人及狂语∶用骐 竭一两，研末。每服二钱，温酒调下。（《太平圣惠 \n方》）。 \n收敛疮口∶血竭末一字，麝香少许，大枣（烧灰）半钱，同研。津调涂之。（究原方）。 \n疮不合∶血竭末敷之，以干为度。（《济急仙方》）。 \n嵌甲疼痛∶血竭末，敷之。（《医林集要》） \n腹中血块∶血竭、没药各一两，滑石（牡丹皮同煮过）一两，为末，醋糊丸梧桐子大， \n服之 \n\n\n\n<目录>木部第三十四卷\\木之一\n\n<篇名>质汗\n\n内容：（宋《开宝》） \n【释名】时珍曰∶汗音寒，番语也。 \n【集解】藏器曰∶质汗出西番，煎柽乳、松泪、甘草、地黄并热血成之。番人试药，以 \n小儿断一足，以药纳口中，将足踏之，当时能走者良。 \n【气味】甘，温，无毒。 \n【主治】金疮伤折，瘀血内损，补筋肉，消恶血，下血气，妇人产后诸血结，腹痛内冷 \n不下食。并以酒消服之，亦敷病处（藏器）。 \n【附方】新一。 \n室女经闭，血结成块，心腹攻痛。质汗、姜黄、川大黄（炒）各半两，为末。每服一钱， \n温水下。（《圣济总录》） \n\n\n\n<目录>木部第三十四卷\\木之一\n\n<篇名>安息香\n\n内容：（《唐本草》） \n【释名】时珍曰∶此香辟恶，安息诸邪，故名。或云∶安息，国名也。梵书谓之拙贝罗 \n香。 \n【集解】恭曰∶安息香出西戎。状如松脂，黄黑色，为块。新 \n曰∶生南海波斯国，树 \n禹锡曰∶按∶段成式《酉阳杂俎》云∶安息香树出波斯国，呼为辟邪树。长二、三丈， \n皮色黄黑。叶有四角，经寒不凋。二月开花黄色，花心微碧。不结实。刻其树皮，其胶 \n如饴，名安息香，六、七月坚凝乃取之。烧之，通神明，辟众恶。 \n时珍曰∶今安南、三佛齐诸地皆有之。《一统志》云∶树如苦楝，大而且直。叶似羊桃 \n而长。木心有脂作香。叶廷 《香录》云∶此乃树脂，形色类胡桃瓤。不宜于烧，而能发众 \n香，故人取以和香。今人和香有如饧者，谓之安息油。机曰∶或言烧之能集鼠者为真。 \n【气味】辛、苦，平，无毒。 \n【主治】心腹恶气，鬼疰（《唐本》）。邪气魍魉，鬼胎血邪，辟蛊毒，霍乱风痛，男子 \n遗精，暖肾气，妇人血噤，并产后血晕（大明）。妇人夜梦鬼交，同臭黄合为丸，烧熏丹穴， \n永断（李 ）。烧之，去鬼来 \n【附方】新四。猝然心痛或经年频发∶安息香研末，沸汤服半钱。（危氏《得效方》） \n小儿肚痛，曲脚而啼∶安息香丸∶用安息香（酒蒸成膏）。沉香、木香、 \n茴 \n香各三钱，香附子、缩砂仁、炙甘草各五钱，为末。以膏和，炼蜜丸芡子大。每服一丸，紫 \n苏汤化下 \n用精猪肉四两切片，裹安息香二两，以瓶盛灰，大火上着一铜版片隔之，安香于上烧之，以 \n瓶口对痛处熏之 \n\n\n\n<目录>木部第三十四卷\\木之一\n\n<篇名>苏合香\n\n内容：（《别录》上品） \n【释名】时珍曰∶按∶郭义恭《广志》云∶此香出苏合国，因以名之 \n剑。 \n【集解】《别录》曰∶苏合香出中台川谷。 \n恭曰∶今从西域及昆仑来，紫赤色，与紫真檀相似，坚实极芳香，惟重如石，烧之灰白 \n者好。 \n颂曰∶今广州虽有苏合香，但类苏木，无香气。药中只用如膏油者，极芬烈。陶隐居以 \n为狮子矢者，亦是指此膏油者言之尔。《梁书》云∶中天竺国出苏合香，是诸香汁煎成，非 \n自然一物也。又云∶大秦国人采得苏合香，先煎其汁以为香膏，乃卖其滓与诸国贾人。是以 \n展转来达中国者，不大香也。然则广南货者，其经煎煮之余乎？今用如膏油者，乃合治成者 \n尔。 \n无滓者为上。叶廷 《香谱》云∶苏合香油出大食国。气味皆类笃耨香。沈括《笔谈》云∶ \n今之苏合香赤色如坚木，又有苏合油如 胶，人多用之。而刘梦得《传信方》言∶苏合香多 \n薄叶，子如金色，按之即少， \n放之即起 \n说，亦是油也，不必致疑。 \n【正误】弘景曰∶苏合香俗传是狮子屎，外国说不尔。今皆从西域来，亦不复入药，惟 \n供合好香尔。 \n恭曰∶此是胡人诳言，陶不悟也。 \n藏器曰∶苏合香色黄白，狮子屎色赤黑，二物相似而不同。狮子屎极臭。或云∶狮子屎 \n是西国草木皮汁所为，胡人将来，欲贵重之，故饰其名尔。 \n【气味】甘，温，无毒。 \n【主治】辟恶，杀鬼精物，温疟、蛊毒、痫痉，去三虫，除邪，令人无梦魇。久服，通 \n神明，轻身长年（《别录》）。 \n【发明】时珍曰∶苏合香气窜，能通诸窍脏腑，故其功能辟一切不正之气。按∶沈括《笔 \n谈》云∶太尉王文正公气羸多病。宋真宗面赐药酒一瓶，令空腹饮之，可以和气血，辟外邪。 \n公饮之，大觉安健。次日称谢。上曰∶此苏合香酒也。每酒一斗，入苏合香丸一两同煮。极 \n能调和五脏，却腹中诸疾。每冒寒夙兴，则宜饮一杯。自此臣庶之家皆仿为之，此方盛行于 \n时。其方本出唐玄宗《开元广济方》，谓之白术丸。后人亦编入《千金》、《外台》，治疾有殊 \n效。 \n【附方】新二。 \n苏合香丸∶治传尸骨蒸， 肺痿，疰忤鬼气，猝心痛，霍乱吐利，时气鬼魅瘴疟，赤 \n白暴痢，瘀血月闭， 癖疔肿，小儿惊痫客忤，大人中风、中气、狐狸等病。用苏合油一两， \n安息香末二两，以无灰酒熬成膏，入苏合油内。白术、香附子、青木香、白檀香、沉香、丁 \n香、麝香、荜茇、诃梨勒（煨，去核 \n为 \n末，以香膏加炼蜜和成剂，蜡纸包收。每服旋丸梧子大，早朝取井华水，温冷任意，化服四 \n丸。老人、小儿一丸。（《惠民和剂局方》） \n丸小豆大。每服二丸，白水 \n\n\n\n<目录>木部第三十四卷\\木之一\n\n<篇名>詹糖香\n\n内容：（《别录》上品） \n【释名】时珍曰∶詹言其粘，糖言其状也。 \n【集解】弘景曰∶出晋安、岑州。上真淳者难得，多以其皮及蠹虫屎杂之，惟软者为佳。 \n皆合香家要用，不正入药。 \n恭曰∶詹糖树似橘。煎枝叶为香，似沙糖而黑。出交广以南，生晋安。近方多用之。 \n时珍曰∶其花亦香，如茉莉花香气。 \n【气味】苦，微温，无毒。 \n【主治】风水毒肿，去恶气伏尸（《别录》）。治恶核恶疮 \n和胡桃、青皮捣，涂发令黑如漆（时珍）。 \n【附录】结杀 藏器曰∶结杀生西国，树之花也，极香。同胡桃仁入 \n去头风白屑，生发。 \n\n\n\n<目录>木部第三十四卷\\木之一\n\n<篇名>笃耨香\n\n内容：（《纲目》） \n【释名】 \n【集解】时珍曰∶笃耨香出真腊国，树之脂也。树如松形，其香老则溢出，色白而透明 \n者名白笃耨，盛夏不融，香气清远。土人取后，夏月以火炙树，令脂液再溢，至冬乃凝，复 \n收之。其香夏融冬结，以瓠瓢盛，置阴凉处，乃得不融。杂以树皮者则色黑，名黑笃耨，为 \n下品。 \n【气味】缺 \n【主治】面黧 。同白附子、冬瓜子、白芨、石榴皮等分，为末，酒浸三日，洗面后 \n敷之。久则面莹如玉（时珍）。 \n【附录】胆八香 时珍曰∶胆八树生交趾、南番诸国。树如稚木犀。 \n叶鲜红，色类霜枫。其实压油和诸香 之，辟恶气。 \n\n\n\n<目录>木部第三十四卷\\木之一\n\n<篇名>龙脑香\n\n内容：（《唐本草》） \n【释名】片脑（《纲目》）、羯婆罗香（《衍义》），膏名婆律香。 \n时珍曰∶龙脑者，因其状加贵重之称也。 \n以白莹如冰，及作梅花片者为良，故俗呼为冰片脑，或云梅花脑。番中又有米脑、速脑、 \n金脚脑、苍龙脑等称，皆因形色命名，不及冰片、梅花者也。清者名脑油，《金光明经》谓 \n之羯 \n恭曰∶龙脑是树根中干脂。婆律香是根下清脂。旧出婆律国，因以为名也。 \n【集解】恭曰∶龙脑香及膏香出婆律国。树形似杉木。脑形似白松脂，作杉木气，明净 \n者善。久经风日或如雀屎者不佳。或云∶子似豆蔻，皮有错甲，即杉脂也。今江南有杉木， \n未经试。或方土无脂，犹甘蕉之无实也。 \n颂曰∶今惟南海番舶贾客货之。南海山中亦有之。相传云∶其木高七、八丈，大可六、 \n七围，如积年杉木状，旁生枝，其叶正圆而背白，结实如豆蔻，皮有甲错，香即木中脂也。 \n膏即根下清液，谓之婆律膏。按∶段成式《酉阳杂俎》云∶龙脑香树名固不婆律，无花实。 \n其树有 \n其膏于树端流出，斫树作坎而承之。两说大同小异。唐天宝中交趾贡龙脑，皆如蝉、蚕之形。 \n彼人云∶老树根节方有之，然极难得。禁中呼为瑞龙脑，带之衣衿，香闻十余步外，后不复 \n有此。今海南龙脑，多用火 成片，其中亦容杂伪。入药惟贵生者，状若梅花片， \n曰∶是西海波律国波律树中脂也，状如白胶香。其龙脑油本出佛誓国，从树取之。 \n曰∶《西域记》云∶西方秣罗矩吒国，在南印度境。有羯布罗香树，干如松株而叶异 \n亦异。湿时无香，木干之后，循理析之，中有香，状类云母，色如冰雪，即龙脑香也。 \n曰∶龙脑香，南番诸国皆有之。叶廷 \n损动者，则有香。若损动，则气泄无脑矣。土人解作板，板缝有脑出，乃劈取之。大者成片 \n如花瓣，清者名脑油。《江南异闻录》云∶南唐保大中 \n璃瓶中，少顷滴沥成水，香气馥烈，大补益元气。按∶此浆与脑油稍异，盖亦其类尔。《宋 \n史》熙宁九年，英州雷震，一山梓树尽枯，中皆化为龙脑。此 \n也。 \n【修治】恭曰∶龙脑香合糯米炭、相思子贮之，则不耗。 \n时珍曰∶或言以鸡毛、相思子，同入小瓷罐密收之佳。《相感志》言以杉木炭养之更 \n良，不耗。今人多以樟脑升打乱之，不可不辨也。相思子见本条。 \n【气味】辛、苦，微寒，无毒。 曰∶苦、辛，温，无毒。 \n元素曰∶热。阳中之阳。 \n【主治】妇人难产，研末少许，新汲水服，立下（《别录》）。 \n心腹邪气，风湿积聚，耳聋，明目，去目赤肤翳（《唐本》）。内外障眼，镇心秘精，治 \n三虫五痔（李 ）。散心盛有热（好古）。入骨，治骨痛（李杲）。治大肠脱（元素）。疗喉痹 \n脑痛，鼻息 \n\\x苍龙脑\\x \n【主治】风疮 ，入膏煎良。不可点眼，伤人（李 ）。 \n\\x婆律香膏\\x \n【主治】耳聋，摩一切风（苏恭）。 \n【发明】宗 曰∶此物大通利关隔热塞，大人、小儿风涎闭塞，及暴得惊热，甚为济用。 \n然非常服之药，独行则势弱，佐使则有功。于茶亦相宜，多则掩茶气。味甚清香，为百药之 \n先，万物中香无出其右者。 \n震亨曰∶龙脑属火。世知其寒而通利，然未达其热而轻浮飞越，喜其香而贵细，动辄与 \n麝同用为桂附之助。然人之阳易动，阴易亏，不可不思。 \n杲曰∶龙脑入骨，风病在骨髓者宜用之。若风在血脉肌肉，辄用脑、麝，反引风入骨髓 \n，如油入面，莫之能出也。 \n王纶曰∶龙脑大辛善走，故能散热，通利结气。目痛、喉痹、下疳诸方多用之者，取其 \n辛散也。人欲死者吞之，为气散尽也。世人误以为寒，不知其辛散之性似乎凉尔。诸香皆属 \n阳，岂有香之至者而性反寒乎？ \n时珍曰∶古方眼科、小儿科皆言龙脑辛凉，能入心经，故治目病、惊风方多用之。痘疮 \n心热血瘀倒 者，用引猪血直入心窍，使毒瓦斯宣散于外，则血活痘发。其说皆似是而实未当 \n也。 \n目病、惊病、痘病，皆火病也。火郁则发之，从治之法，辛主发散故尔。其气先入肺， \n传于心脾，能走能散，使壅塞通利，则经络条达，而惊热自平，疮毒能出。用猪心血能引龙 \n脑入心经，非龙脑能入心也。沈存中《良方》云∶痘疮稠密，盛则变黑者。用生 猪血一橡 \n斗，龙脑半分，温酒和服。潘氏云∶一女病发热，腹痛，手足厥逆，渐加昏闷，形症极恶， \n疑是痘候。时 \n则横夭矣。又宋。文天祥、贾似道皆服脑子求死不得，惟廖莹中以热酒服数握，九窍流血而 \n死。此非脑子有毒，乃热酒引其辛香，散溢经络，气血沸乱而然尔。 \n【附方】旧二，新十二。 \n目生肤翳∶龙脑末一两，日点三、五度。（《圣济总录》） \n目赤目膜∶龙脑、雄雀屎各八分。为末，以人乳汁一合调成膏。日日点之，无有不验。 \n（《圣惠方》） \n头目风热上攻∶用龙脑末半两，南硼砂末一两，频 \n头脑疼痛∶片脑一钱，纸卷作捻， \n风热喉痹∶灯心一钱，黄柏五分（并烧存性），白矾七分（ 过），冰片脑三分，为末。 \n每以一、二分吹患处。此陆一峰家传绝妙方也。（《濒湖集简方》） \n鼻中息肉垂下者∶用片脑点之，自入。（《集简方》） \n伤寒舌出过寸者∶梅花片脑半分。为末。掺之，随手即愈。（洪迈《夷坚志》） \n中风牙噤∶无门下药者，开关散揩之。五月五日午时，用龙脑、天南星等分，为末。每 \n以一字揩齿二、三十遍，其 \n牙齿疼痛∶梅花脑、朱砂末各少许。揩之立止。（《集简方》） \n痘疮狂躁，心烦气喘，妄语或见鬼神，疮色赤未透者∶《经验后方》∶用龙脑一钱细研， \n旋以猪心血丸芡子大。每服 \n第二番血清半杯，酒半杯，和匀，入龙脑一分，温服。良久利下瘀血一、二行，疮即红活。 \n此治痘疮黑 候恶，医所不治者，百发百中。 \n内外痔疮∶片脑一、二分，葱汁化，搽之。（《简便方》） \n酒 鼻赤∶脑子、真酥，频搽。（《普济方》） \n梦漏口疮∶经络中火邪，梦漏恍惚，口疮咽燥。龙脑三钱，黄柏三两，为末，蜜丸梧桐 \n子大 \n\\x子\\x \n【气味】辛，温。气似龙脑。 \n【主治】下恶气，消食，散胀满，香人口（苏恭）。 \n【附录】元慈勒 藏器曰∶出波斯国。状似龙脑香，乃树中脂也。味甘，平，无毒。主 \n心病流血，合金疮，去腹内恶血，血痢下血，妇人带下，明目，去翳障、风泪、弩肉。 \n\n\n\n<目录>木部第三十四卷\\木之一\n\n<篇名>樟脑\n\n内容：（《纲目》） \n【释名】韶脑。 \n【集解】时珍曰∶樟脑出韶州、漳州。状似龙脑，白色如雪，樟树脂膏也。胡演升《炼 \n方》云∶煎樟脑法∶用樟木新者切片，以井水浸三日三夜，入锅煎之，柳木频搅。待汁减半， \n柳上有白霜，即滤去滓，倾汁入瓦盆内。经宿，自然结成块也。他处虽有樟木，不解取脑。 \n又炼樟脑法∶用铜盆，以陈壁土为粉糁之，却糁樟脑一重，又糁壁土，如此四、五重。以薄 \n荷安土上，再用一盆覆之，黄泥封固，于火上款款炙之。须以意度之，不可太过、不及。勿 \n令走气。候冷取出，则脑皆升于上盆，如此升两、三次，可充片脑也。 \n【修治】时珍曰∶凡用，每一两以二碗合住，湿纸糊口，文武火 之。半时许取出， \n冷定用。又法∶每一两，用黄连、薄荷六钱，白芷、细辛四钱，荆芥、密蒙花二钱，当归、 \n槐花一钱。以新土碗铺杉木片于底，安药在上，入水半盏，洒脑于上，再以一碗合住，糊口， \n安火煨之。待水干取开，其脑自升于上。以翎扫下，形似松脂，可入风热眼药。人亦多以乱 \n片脑，不可不辨。 \n【气味】辛，热，无毒。 \n【主治】通关窍，利滞气，治中恶邪气，霍乱心腹痛，寒湿香港脚，疥癣风瘙，龋齿，杀 \n虫辟蠹。着鞋中，去香港脚（时珍）。 \n【发明】时珍曰∶樟脑纯阳，与焰硝同性，水中生火，其焰益炽。 \n今丹炉及烟火家多用之。辛热香窜，禀龙火之气，去湿杀虫，此其所长。故烧烟熏衣筐 \n席簟，能辟壁虱、虫蛀。 \n间，用帛绷定，月余甚妙。王玺《医林集要》方∶治香港脚肿痛。用樟脑二两，乌头三两，为 \n末，醋糊丸弹子大。每置一丸于足心踏之，下以微火烘之，衣被围覆，汗出如涎为效。 \n【附方】新三。 \n小儿秃疮∶韶脑一钱，花椒二钱，芝麻二两，为末。以退猪汤洗后，搽 \n牙齿虫痛∶《普济方》∶用韶脑、朱砂等分，擦之神效。余居士《选奇方》∶用樟脑、黄 \n丹、肥皂（去皮核）等分，研匀蜜丸。塞孔中 \n\n\n\n<目录>木部第三十四卷\\木之一\n\n<篇名>阿魏\n\n内容：（《唐本草》） \n【校正】自草部移入此。 \n【释名】阿虞（《纲目》）、熏渠（《唐本》）、 \n时珍曰∶夷人自称曰阿，此物极臭，阿之所畏也。 \n波斯国呼为阿虞，天竺国呼为形虞，《涅 经》谓之央匮。蒙古人谓之哈昔泥，元时食 \n用以 \n【集解】恭曰∶阿魏生西番及昆仑。苗叶根茎酷似白芷，捣根汁，日、煎作饼者为上。 \n截根穿曝干者为次。体性极臭而能止臭，亦为奇物也。又婆罗门云∶熏渠即是阿魏，取根汁 \n曝之如胶，或截根晒干，并极臭。西国持咒人禁食之。常食用之，云去臭气。戎人重此，犹 \n俗中贵胡椒，巴人重负 也。 \n曰∶按∶《广志》云∶生昆仑国。是木津液，如桃胶状。其色黑者不堪，其状黄散者 \n为上。云南长河中亦有，与舶上来者滋味相似一般，只无黄色。 \n颂曰∶今惟广州有之，云是木膏液滴酿结成，与苏恭所说不同。按∶段成式《酉阳杂俎 \n》云∶阿魏木，生波斯国及伽 那国（即北天竺也）。木长八、九尺，皮色青黄。三月生叶， \n似鼠耳。无花实。断其枝，汁出如饴，久乃坚凝，名阿魏。摩伽陀僧言∶取其汁和米、豆屑 \n合酿而成。其说与广州所生者相近。 \n同而差淡薄，但无汁膏尔。 \n是也。木者出南番，取 \n云出火州及沙鹿、海牙国者，草高尺许，根株独立，枝叶如盖，臭气逼人，生取其汁 \n名阿魏。出三佛齐及暹逻国者，树不甚高，土人纳竹筒于树内，脂满其中，冬月破筒取之。 \n或云其脂最毒，人不敢近。每采时，以羊系于树下，自远射之。脂之毒着羊，羊毙即为阿魏。 \n观此，则其有二种明矣。盖其树低小如枸杞、牡荆之类，西南风土不同，故或如草如木也。 \n系羊射脂之说，俗亦相传，但无实据。谚云∶黄芩无假，阿魏无真。以其多伪也。刘纯诗云∶ \n阿魏无真却有真，臭而止臭乃为珍。 \n以半铢安熟铜器中一宿，至明沾阿魏处白如银，永无赤色；第 \n一夜，至明如鲜血色；第三将一铢安于柚树上，树立干，便是 \n器上 ，过入药。 \n【气味】辛，平，无毒。 \n【主治】杀诸小虫，去臭气，破症积，下恶气，除邪鬼蛊毒（《唐本》）。治风邪鬼疰， \n心腹中冷（李 ）。传尸冷气，辟 \n明）。解自死牛、羊、马肉诸毒 \n【发明】炳曰∶阿魏下细虫，极效。 \n时珍曰∶阿魏消肉积，杀小虫，故能解毒辟邪，治疟、痢、疳、劳、尸注、冷痛诸症。 \n按∶王 《百一选方》云∶夔州谭逵病疟半年。故人窦藏叟授方∶用真阿魏、好丹砂各 \n一两，研匀，米糊和，丸皂子大。每空心人参汤化服一丸，即愈。世人治疟，惟用常山、砒 \n霜毒 \n黄连、木香汤下，疟、痢亦多起于积滞故尔。 \n【附方】新十。 \n辟鬼除邪∶阿魏枣许为末，以牛乳或肉汁煎五、六沸服之。至暮，以乳服安息香枣许。 \n久者不过十日。忌一切菜。孙侍郎用之有效。（唐崔行功《纂要》） \n恶疰腹痛不可忍者∶阿魏末，热酒服一、二钱，立止。（《永类钤方》） \n尸疰中恶∶近死尸，恶气入腹，终身不愈。 \n用阿魏三两。每用二钱，拌面裹作馄饨十余枚，煮熟食之，日三。服至三、七日，永除。 \n忌 \n疝疼痛∶败精恶血，结在阴囊所致。用阿魏二两（醋和荞麦面作饼裹之煨熟），大槟 \n榔二枚钻孔，溶乳香填满，亦以荞面裹之煨熟，入 砂末一钱，赤芍药末一两，糊丸梧桐子 \n大。每食前，酒下三十丸。（危氏《得效方》）。 \n小儿盘肠内吊，腹痛不止∶用阿魏为末，大蒜半瓣炮熟研烂和丸麻子大。每艾汤服五丸。 \n（《总微论》）。 \n脾积结块∶鸡子五个，阿魏五分，黄蜡一两，同煎化，分作十服。每空心细嚼，温水送 \n下。诸物不忌，腹痛无妨。十日后大便下血，乃积化也。（《保寿堂经验方》）。 \n痞块有积∶阿魏五钱，五灵脂（炒烟尽）五钱，为末，以黄雄狗胆汁和，丸黍米大。空 \n心 \n唾津送下三十丸。忌羊肉、醋、面。（《扶寿精方》）。 \n胭脂各一豆大，研匀，以蒜膏和，覆虎口上，男左女右。（《圣济总录》） \n臭黄等分，为末，糊丸绿豆大。每棉裹一丸，随左右插入耳中，立效。（《圣惠方》） \n\n\n\n<目录>木部第三十四卷\\木之一\n\n<篇名>芦荟\n\n内容：（宋《开宝》） \n【校正】自草部移入此。 \n【释名】奴会（《开宝》）、讷会（《拾遗》）、 \n时珍曰∶名义未详。 \n藏器曰∶俗呼为象胆，以其味苦如胆也。 \n【集解】 曰∶芦荟生 \n颂曰∶今惟广州有来者。其木生山野中，滴脂泪而成。采之不拘时月。 \n时珍曰∶芦荟原在草部。《药谱》及《图经》所状，皆言是木脂。而《一统志》云∶爪 \n哇、三佛齐诸国所出者，乃草属，状如鲎尾，采之以玉器捣成膏。与前说不同，何哉？岂亦 \n木质草形乎？ \n【气味】苦，寒，无毒。 \n【主治】热风烦闷，胸膈间热气，明目镇心，小儿癫痫惊风，疗五疳，杀三虫及痔病疮 \n，解巴豆毒（《开宝》）。主小儿诸疳热（李 \n权）。研末，敷 齿 \n【发明】时珍曰∶芦荟，乃厥阴经药也，其功专于杀虫清热。以上诸病，皆热与虫所生 \n故也。 \n浸 \n炙 \n【附方】新一。 \n小儿脾疳∶芦荟、使君子等分，为末。每米饮服一、二钱。（《卫生易简方》） \n\n\n\n<目录>木部第三十四卷\\木之一\n\n<篇名>胡桐泪\n\n内容：（《唐本草》） \n【校正】自草部移入此。 \n【释名】胡桐碱（《纲目》）、胡桐律。 \n曰∶胡桐泪，是胡桐树脂也，故名泪。作律字者非也，律、泪声讹尔。 \n时珍曰∶《西域传》云∶车师国多胡桐。颜师古注云∶胡桐似桐，不似桑，故名胡桐。 \n虫食其树而汁出下流者，俗名胡桐泪，言似眼泪也。其入土石成块如卤碱者，为胡桐碱（音 \n减）。或云∶律当作沥，非讹也，犹松脂名沥青之义。亦通。 \n【集解】恭曰∶胡桐泪，出肃州以西平泽及山谷中。形似黄矾而坚实。有夹烂木者，云 \n是胡桐树脂沦入土石碱卤地者。其树高硕，皮叶似白杨、青桐、桑辈，故名胡桐木，堪器用。 \n保升曰∶凉州以西有之。初生似柳，大则似桑、桐。其津下入地，与土石相染，状如姜 \n极咸苦，得水便消，若矾石、硝石之类。冬月采之。大明曰∶此有二般∶木律不中入药；惟 \n用石律，石上采之，形如小石片子，黄土色者为上。颂曰∶今西番亦有商人货之。时珍曰∶ \n木泪乃树脂流出者，其状如膏油。石泪乃脂入土石间者，其状成块，以其得卤 \n药为胜。 \n【气味】咸、苦，大寒，无毒。 \n恭曰∶伏砒石。可为金银焊药。 \n【主治】大毒热，心腹烦满，水和服之，取吐。牛马急黄黑汗，水研三、二两灌之，立 \n瘥（《唐本》）。主风虫牙齿痛，杀火毒、面毒（大明）。风疳 齿，骨槽风劳。能软一切物。 \n多服令人吐（ \n【发明】颂曰∶古方稀用。今治口齿家多用，为最要之物。 \n时珍曰∶石泪入地受卤气，故其性寒能除热，其味咸能入骨软坚。 \n【附方】新六。 \n湿热牙疼，喜吸风∶胡桐泪，入麝香掺之。 \n牙疼出血∶胡桐泪半两，研末。夜夜贴之。或入麝香少许 \n走马牙疳∶胡桐碱、黄丹等分为末，掺之。（《医林集要》） \n牙疳宣露，脓血臭气者∶胡桐泪一两，枸杞根一升。每用五钱，煎水热漱。又方∶ \n胡桐泪、葶苈等分。研掺。（《圣惠方》） \n牙齿蠹黑∶乃肾虚也。胡桐泪一两，丹砂半两，麝香一分，为末，掺之。（《圣济总录》） \n\n\n\n<目录>木部第三十四卷\\木之一\n\n<篇名>返魂香\n\n内容：（《海药》） \n【集解】 曰∶按∶《 \n《内传》云∶西海聚窟州有返魂树，状如枫、柏，花、叶香闻百里。采其根于釜中水煮 \n取汁，炼之如漆，乃香成也。其名有六∶曰返魂、惊精、回生、振灵、马精、却死。凡有疫 \n死者，烧豆许熏之再活，故曰返魂。时珍曰∶张华《博物志》云∶武帝时，西域月氏国，度 \n弱水贡此香三枚，大如燕卵，黑如桑椹。值长安大疫，西使请烧一枚辟之，宫中病者闻之即 \n起，香闻百里，数日不歇。疫死未三日者，熏之皆活，乃返生神药也。此说虽涉诡怪，然理 \n外之事，容或有之，未可便指为谬也。 \n【附录】兜木香 藏器曰∶《汉武故事》云∶西王母降，烧兜木香末，乃兜渠国所进， \n如大豆。涂宫门，香闻百里。关中大疫，死者相枕，闻此香，疫皆止，死者皆起。此乃灵香， \n非常物也。 \n\n\n\n<目录>木部第三十五卷\n\n<篇名>木之二\n\n内容：（乔木类五十二种） \n\n\n\n<目录>木部第三十五卷\\木之二\n\n<篇名>柏木\n\n内容：（《本经》上品） \n【释名】黄檗（《别录》），根名檀桓。 \n时珍曰∶檗木名义未详。《本经》言檗木及根，不言檗皮，岂古时木与皮通用乎？俗作 \n黄柏者，省写之谬也。 \n【集解】《别录》曰∶柏木生汉中山谷及永昌。 \n弘景曰∶今出邵陵者，轻薄色深为胜。出东山者，浓而色浅。其根于道家入木芝品，今 \n人不知取服。又有一种小树，状如石榴，其皮黄而苦，俗呼为子柏，亦主口疮。又一种小树， \n多刺，皮亦黄色，亦主口疮。 \n在有之。今云皮黄，谬矣。按∶今俗用子柏皆多刺小树，名刺柏，非小柏也。 \n《蜀本图经》云∶黄柏树高数丈。叶似吴茱萸，亦如紫椿，经冬不凋。皮 \n其根结块，如松下茯苓。今所在有，本出房、商、合等州山谷中。皮紧，浓二、三分 \n鲜黄者上。二月、五月采皮，晒干。 \n上用之。各适其宜尔。 \n【修治】 曰∶凡使柏皮，削去粗皮，用生蜜水浸半日，漉出晒干，用蜜涂，文武火炙， \n令蜜尽为度。每五两，用蜜三两。元素曰∶二制治上焦，单制治中焦，不制治下焦也。时珍 \n曰∶黄柏性寒而沉，生用则降实火，熟用则不伤胃，酒制则治上，盐制则治下，蜜 \n【气味】苦，寒，无毒。 \n辛，阴中之阳，入足少阴经，为足太阳引经药。 \n入肾，燥湿所归，各从其类也。故《活人书 \n恶干漆，伏硫黄。 \n【主治】五脏肠胃中结热，黄胆肠痔，止泄痢，女子漏下赤白，阴伤蚀疮 \n疗惊气在皮间，肌肤热赤起，目热赤痛，口疮。久服通神（《别录》）。热 \n止消渴，杀蛀虫（藏器）。男子阴痿，及敷茎上疮，治下血如鸡鸭肝片 \n治骨蒸，洗肝明目，多泪，口干心热，杀疳虫，治蛔心痛，鼻衄，肠风下血，后分急热肿痛 \n（大明）。泻膀胱相火，补肾水不足，坚肾壮骨髓，疗下焦虚，诸痿瘫痪，利下窍，除热（元 \n素）。泻伏火，救肾水，治冲脉气逆，不渴而小便不通，诸疮痛不可忍（李杲）。 \n阴降火。得苍术，除湿清热，为治痿要药。得细辛，泻膀胱火，治口舌生疮（震亨）。 \n儿头疮（时珍）。 \n【发明】元素曰∶黄柏之用有六∶泻膀胱龙火，一也；利小便结，二也；除下焦湿肿， \n三也；痢疾先见血，四也；脐中痛，五也；补肾不足，壮骨髓，六也。凡肾水膀胱不足，诸 \n痿厥脚膝无力，于黄 汤中加用，使两足膝中气力涌出，痿软即便去也，乃瘫痪必用之药。 \n蜜炒研末，治口疮如神。故《雷公炮炙论》云∶口疮舌坼，立愈黄酥。谓以酥炙根黄，含之 \n也。 \n及黄涩者。并用酒洗黄柏、知母为君，茯苓、泽泻为佐。凡小便不通而口渴者，邪热在气分， \n肺中伏热不能生水，是绝小便之源也。法当用气味俱薄、淡渗之药，猪苓、泽泻之类，泻肺 \n火而清肺气，滋水之化源。若邪热在下焦血分，不渴而小便不通者，乃《素问》所谓无阴则 \n阳无以生、无阳则阴无以化。膀胱者州都之官，津液藏焉，气化则能出矣。法当用气味俱浓、 \n阴中之 \n破出水，双睛凸出，饮食不下，痛苦不可名状。治满、利小便、渗泄之药服遍矣。予诊之曰∶ \n此乃奉养太过，膏粱积热，损伤肾水，致膀胱久而干涸，小便不化，火又逆上，而为呕哕。 \n《难经》所谓关则不得小便，格则吐逆者。洁古老人言∶热在下焦，但治下焦，其病必愈。 \n遂处以北方寒水所化大苦寒之药，黄柏、知母各一两，酒洗焙碾，入桂一钱为引，熟水丸如 \n芡子大。每服二百丸，沸汤下。少时如刀刺前阴火烧之状，溺如瀑泉涌出，床下成流，顾盼 \n之间，肿胀消散。《内经》云∶热者寒之。肾恶燥，急食辛以润之。以黄柏之苦寒泻热、补 \n水润燥为君， \n有泻火补阴之功，非阴中之火，不可用也。火有二∶君火者，人 \n可以水灭，可以直折，黄连之属可以制之；相火者，天火也，龙雷之火也，阴火也，不可以 \n水湿折之，当从其性而伏之，惟黄柏之属可以降之。 \n有金水相生之义。黄柏无知母，犹水母之无虾 \n清肺金，滋肾水之化源。故洁古、东垣、丹溪皆以为滋阴降火要药，上古所未言也。盖气为 \n阳，血为阴。邪火煎熬，则阴血渐涸，故阴虚火动之病须之。然必少壮气盛能食者，用之相 \n宜。若中气不足而邪火炽甚者，久服则有寒中之变。近时虚损，及纵欲求嗣之人，用补阴药， \n往往以此二味为君，日日服饵。降令太过，脾胃受伤，真阳暗损，精气不暖，致生他病。盖 \n不知此物苦寒而滑渗，且苦味久服，有反从火化之害。故叶氏《医学统旨》有“四物加知母、 \n黄柏，久服伤胃，不能生阴”之戒。 \n【附方】旧十三，新三十。 \n阴火为病∶大补丸∶ \n用黄柏去皮，盐、酒炒褐为末，水丸梧子大。血虚，四物汤下；气虚，四君子汤下。（丹 \n溪方） \n等症。黄柏（去皮，切）二斤，熟糯米一升（童子小便浸之，九浸九晒，蒸过晒研）。为末， \n酒煮 \n面糊丸梧桐子大。每服一百丸，温酒送下。 \n作四分，用醇酒、蜜汤、盐 \n和丸梧桐子大。每服七十丸，白汤下。（《活人心统》） \n毒痔漏，下血不止∶孙探 \n用酒、醋、童尿各浸七日， \n下五十丸，久服除根。杨诚《经验方》百补丸∶专治诸虚赤白浊。用川柏皮（刮净）一斤（分 \n作四分，用酒、蜜、人乳、糯米泔各浸透）。炙干切研，廪米饭丸∶如上 \n皮丸∶黄柏一斤（分作四分，三分用醇酒、盐汤、童尿各浸二日焙研，一分用酥炙研末）。 \n以猪脏一条去膜，入药在内扎，煮熟捣丸。如上法服之。 \n白涂炙）。为 \n末，水丸绿豆大。每服七丸，温水下。名金虎丸。（《普济方》） \n赤芍药四钱，为末，饭丸麻子大。每服一、二十丸，食前米饮下。（阎孝忠《 \n下痢白色，昼夜三、五十行∶根黄浓者，蜜炒令焦为末，大蒜煨熟，去皮捣烂作膏和丸梧桐 \n子大。每空心，米饮下三、五十丸，日三服。神妙不可述。（ \n削皮，焙为末，用米汤和，丸粟米大。每服一、二十丸，米汤下。（《十全博救方》） \n淫及梦泄精滑∶真珠粉丸∶黄柏（炒）、真蛤粉各一斤，为末，滴水丸梧桐子大。每服一百 \n丸， \n空 \n等分为末，糊丸梧桐子大。每服八十丸，盐汤下。（《洁古家珍》） \n中有热∶宜清心丸主之。黄柏末一两，片脑一钱。炼蜜丸梧桐子大。每服十五丸，麦门冬汤 \n下。此大智禅师方也。（许学士《本事方》） \n沸，渴即饮之，恣饮，数日即止。（韦宙《独行方》） \n冬汤调服二钱，立瘥。（《经验方》） \n每用一弹子大，纱帕包之，浸水一盏，饭上蒸熟，乘热熏洗，极效。此方有金木水火土，故 \n名五行汤。一丸可用 \n品方》） \n痹痛∶黄柏片含之。又以一斤，酒一斗，煮二沸，恣饮便愈。（《肘后方》） \n不通∶苦酒和黄柏末敷之，冷即易。（《肘后方》） \n方》） \n治心脾有热，舌颊生疮。蜜炙黄柏、青黛各一分，为末，入生 \n用黄柏、细辛等分为末，掺。或用黄柏、干姜等分，亦良。 \n铜绿二钱，为末。掺之，漱去涎。（《三因方》） \n服。（《圣惠方》） \n以蔷薇根汁调涂，立效。（《圣济录》） \n香二钱半，为末，槐花煎水调作饼，贴于疮口。（《普济方》） \n末，水调，贴足心。（《普济方》） \n（《肘后方》） \n柏皮（炒）、川乌头（炮）等分，为末。唾调涂之，留头，频以米泔水润湿。（《集简方》）小 \n儿 \n脐疮不合者∶黄柏末涂之。（《子母秘录》） \n掺之即愈。（杨起《简便方》） \n疮用黄柏、黄芩等分煎汤，洗之。仍以黄柏、黄连作末，敷之。又法∶黄柏煎汤洗之，涂以 \n白蜜。（《肘 \n一味。 \n一妇病此，人无识者，用此而愈。（张杲《医说》） \n门事亲》） \n柏末，面糊调涂，效。（《宣明方》） \n\n\n\n<目录>木部第三十五卷\\木之二\n\n<篇名>檀桓\n\n内容：（《拾遗》） \n【集解】藏器曰∶檀桓乃百岁柏之根，如天门冬，长三四尺，别在一旁，以小根缀之。 \n一名檀桓芝。出《灵宝方》。 \n时珍曰∶《本经》但言黄柏根名檀桓。陈氏所说乃柏旁所生檀桓芝也，与陶弘景所说同 \n【气味】苦，寒，无毒。 \n【主治】心腹百病，安魂魄，不饥渴。久服，轻身延年通神（《别录》）。 \n长生神仙，去万病。为散，饮服方寸匕，尽一枚有验（藏器）。 \n\n\n\n<目录>木部第三十五卷\\木之二\n\n<篇名>小柏\n\n内容：（《唐本草》） \n【释名】子柏（弘景）、山石榴。 \n时珍曰∶此与金樱子、杜鹃花并名山石榴，非一物也。 \n【集解】弘景曰∶子柏树小，状如石榴，其皮黄而苦。又一种多刺，皮亦黄。并主口疮。 \n恭曰∶小柏生山石间，所在皆有，襄阳岘山东者为良。一名山石榴，其树枝叶与石榴无 \n，但花异，子细黑圆如牛李子及女贞子尔。其树皮白，陶云皮黄，恐谬矣。今太常所贮，乃 \n小树多刺而叶细者，名刺柏，非小柏也。 \n藏器曰∶凡是柏木皆皮黄。今既不黄，非柏也。小柏如石榴，皮黄，子赤如枸杞子， \n两头尖。人锉枝以染黄。若云子黑而圆，恐是别物，非小柏也。 \n时珍曰∶小柏山间时有之，小树也。其皮外白里黄，状如柏皮而薄小。 \n【气味】苦，大寒，无毒。 \n【主治】口疮疳 ，杀诸虫，去心腹中热气（《唐本》）。治 \n血崩，阿茄陀丸方中用之）。 \n\n\n\n<目录>木部第三十五卷\\木之二\n\n<篇名>黄栌\n\n内容：（宋《嘉 》） \n【集解】藏器曰∶黄栌生商洛山谷，四川界甚有之。叶圆木黄，可 \n\\x木\\x \n【气味】苦，寒，无毒。 \n【主治】除烦热，解酒疸目黄，水煮服之（藏器）。洗赤眼及汤火、 \n【附方】新一。 \n大风癞疾∶黄栌木五两（锉，用新汲水一斗浸二七日，焙研），苏方木五两，乌麻子一 \n斗 \n（九蒸九曝），天麻二两，丁香、乳香各一两，为末。以赤黍米一升淘净，用浸黄栌水煮米 \n粥捣和，丸梧桐子大。每服二、三十丸，食后浆水下，日二、夜一。（《圣济总录 \n\n\n\n<目录>木部第三十五卷\\木之二\n\n<篇名>浓朴\n\n内容：（《本经》中品） \n【校正】并入有名未用逐折。 \n【释名】烈朴（《日华》）、赤朴（《别录》）、浓皮（同）、重皮（《广雅》），树名榛（《 \n别录》），子名逐折（《别录》）。 \n时珍曰∶其木质朴而皮浓，味辛烈而色紫赤，故有浓朴、烈、赤诸名。 \n颂曰∶《广雅》谓之重皮，方书或作浓皮也。 \n【集解】《别录》曰∶浓朴生交趾、冤句。三月、九月、十月采皮 \n弘景曰∶今出建平、宜都。极浓、肉紫色为好，壳薄而白者不佳。俗方多用，道家不须 \n也。 \n颂曰∶今洛阳、陕西、江淮、湖南、蜀川山谷中往往有之，而以梓州、龙州者为上。木 \n高三、四丈，径一、二尺。春生叶如槲叶，四季不凋。红花而青实。皮极鳞皱而浓，紫色多 \n润者佳，薄 \n宗 曰∶今伊芳阳县及商州亦有，但薄而色淡，不如梓州者浓而紫色有油。 \n时珍曰∶朴树肤白肉紫，叶如槲叶。五、六月开细花，结实如冬青子，生青熟赤，有核 \n。七、八月采之，味甘美。 \n\\x皮\\x \n【修治】 曰∶凡使要紫色味辛者为好，刮去粗皮。入丸散， \n若入汤饮，用自然姜汁八两炙尽为度。 \n大明曰∶凡入药去粗皮，用姜汁炙，或浸炒用。 \n宗 曰∶味苦。不以姜制，则棘人喉舌。 \n【气味】苦，温，无毒。 \n《别录》曰∶大温。吴普曰∶神农、岐伯、雷公∶苦，无毒；李当之∶小温。 \n权曰∶苦、辛，大热。 \n元素曰∶气温，味苦、辛。气味俱浓，体重浊而微降，阴中阳也。 \n杲曰∶可升可降。 \n之才曰∶干姜为之使。恶泽泻、硝石、寒水石。忌豆，食之动气。 \n【主治】中风伤寒，头痛寒热惊悸，气血痹，死肌，去三虫（《本 \n温中益气，消痰下气，疗霍乱及腹痛胀满，胃中冷逆，胸中呕不止，泄痢淋露，除惊， \n去留热心烦满，浓肠胃（《别录》）。健脾，治反胃，霍乱转筋，冷热气，泻膀胱及五脏一切 \n气 \n虚 \n吼， \n（甄权）。 \n【发明】宗 曰∶浓朴，平胃散中用，最调中。至今此药盛行，既能温脾胃，又能走冷 \n气，为世所须也。元素曰∶浓朴之用有三∶平胃，一也；去腹胀，二也；孕妇忌之，三也。 \n虽除腹胀，若 \n药也。 \n泻 \n哉！其治腹胀者，因其味辛以提其滞气，滞行则宜去之。若气实人，误服参、 药多补气， \n胀闷或作喘，宜此泻之。 \n浓肠胃，去腹满，果 \n是 \n也。若与橘皮、苍术同用，则能除湿满，所谓温中益气是也。与解利药同用，则治伤寒头痛； \n与泻痢药同用，则浓肠胃。大抵其性味苦温，用苦则泄，用温则补也。故成无己云∶浓朴之 \n苦，以泄腹满。 \n【附方】旧九，新五。 \n浓朴煎丸∶孙兆云∶补肾不如补脾。脾胃气壮，则能饮食。饮食既进，则益营卫，养精 \n血，滋骨髓。是以《素问》云∶精不足者补之以味；形不足者，补之以气。此药大补脾胃虚 \n损，温中降气， \n皮切片），以水五升同煮干，去姜，焙朴。以干姜四两，甘 \n去草，焙姜、朴为末。用枣肉、生姜同煮熟，去姜，捣枣和，丸梧子大。每服五十丸，米饮 \n下。一方加熟附子。（王 《百一选方》） \n炙黄为末。非时米饮调下二钱匕。（《圣惠方》） \n五枚，以水一斗二升，煎取五升，入大黄四两，再煎三升。温服一升，转动更服，不动勿服。 \n（张仲景《金匮要略》） \n十 \n枚，大枳实五枚，桂二两，生姜五两，以水一斗，煎取四升。温服八合，日三。呕者，加半 \n夏五合。（《金匮要略》） \n黑）为末。以陈米饮调服二钱匕，日三服。（《斗门方》） \n朴、干姜等分为末，蜜丸梧桐子大。每服五十丸，米饮下。（鲍氏方） \n痰 \n惊∶梓朴散∶用梓州浓朴一两，半夏（汤泡七次，姜汁浸半日，晒干）一钱，以米泔三升同 \n浸 \n一百刻，水尽为度。如未尽，少加火熬干。去浓朴，只研半夏。每服半钱或一字。薄荷汤调 \n下。（钱乙《小儿直诀》） \n姜 \n二两，水六升，煎取二升，分三服。此陶隐居方也。唐·石泉公王方庆《广南方》云∶此方 \n不惟治霍乱，凡诸病皆治。《圣惠方》∶用浓朴（姜汁炙），研末。新汲水服二钱，如神。 \n痢 \n水谷久不瘥者∶浓朴三两，黄连三两，水三升，煎一升，空心细服。（《梅师 \n浓朴生研，猪脏（煮）捣和，丸梧桐子大。每姜水下三十丸。（《十便良方》） \n脾 \n不调，肾气混浊。用浓朴（姜汁炙）一两，白茯苓一钱，水、酒各一碗，煎一碗，温服。（《经 \n验良方》）。月水不通∶浓朴三两（炙切）。水三升，煎一升，分二服，空心饮。不过三、四 \n剂，神验。一加桃仁、红花。（《子母秘录 \n\\x逐折\\x \n【气味】甘，温，无毒。 \n【主治】疗鼠 ，明目益气（《别录》）。 \n【正误】《别录》有名未用曰∶逐折杀鼠，益气明目。一名百合，一名浓实，生木间， \n茎黄。七月实，黑如大豆。弘景曰∶杜仲子，亦名逐折。《别录》浓朴条下，已言子名逐折； \n而有名未用中复出逐折，主治相同，惟鼠 、杀鼠字误，未知孰是尔？所云浓实，乃浓朴实 \n也，故皮谓之浓皮。陶氏不知，援引杜仲为注，皆误矣。今正之。 \n【附录】浮烂罗勒 藏器曰∶生康国。皮似浓朴，味酸，平，无毒。 \n主一切风气，开胃补心，除冷痹，调脏腑。 \n\n\n\n<目录>木部第三十五卷\\木之二\n\n<篇名>杜仲\n\n内容：（《本经》上品） \n【释名】思仲（《别录》）、思仙（《本经》）、 \n时珍曰∶昔有杜仲服此得道，因以名之。思仲、思仙，皆由此义。其皮中有银丝如绵， \n故曰木绵。其子名逐折，与浓朴子同名。 \n【集解】《别录》曰∶杜仲生上虞山谷及上党、汉中。二月、五月 \n弘景曰∶上虞在豫州，虞、虢之虞，非会稽上虞县也。今用出建平、宜都者。状如浓朴 \n，折之多白丝者为佳。 \n保升曰∶生深山大谷，所在有之。树高数丈，叶似辛夷。 \n颂曰∶今出商州、成州、峡州近处大山中，叶亦类柘，其皮折之白丝相连。 \n江南谓之 。初生嫩叶可食，谓之 \n\\x皮\\x \n【修治】 曰∶凡使削去粗皮。每一斤，用酥一两，蜜三两， \n锉用。 \n【气味】辛，平，无毒。《别录》曰∶甘，温。权曰∶苦，暖。 \n甘。气味俱薄，沉而降，阴也。 \n参、蛇蜕皮。 \n【主治】腰膝痛，补中益精气，坚筋骨，强志，除阴下痒湿，小便余沥。久服，轻身耐 \n老（《本经》）。脚中酸疼，不欲践地（《别录》）。 \n人虚而身强直，风也。腰不利，加而用之（甄权）。能使筋骨相着（ \n风虚（好古）。 \n【发明】时珍曰∶杜仲古方只知滋肾，惟王好古言是肝经气分药，润肝燥，补 \n昔人所未发也。盖肝主筋，肾主骨。肾充则骨强，肝充则筋健。屈伸利用，皆属于筋。杜仲 \n色紫而润，味甘微辛，其气温平。甘温能补，微辛能润。故能入肝而补肾，子能令母实也。 \n按∶庞元英《谈薮》∶一少年新娶，后得脚软病，且疼甚。医作香港脚治不效。路钤孙琳诊之。 \n用 \n曰∶此乃肾虚，非香港脚也。杜仲能治腰膝痛，以酒行之，则为效容易矣。 \n【附方】旧六，新三。 \n青娥丸∶方见补骨脂下。 \n肾虚腰痛∶崔元亮《海上集验方》∶用杜仲去皮炙黄一大斤，分作十剂。每夜取一剂， \n以水一大升，浸至五更，煎三分减一，取汁，以羊肾三、四枚切下，再煮三、五沸，如作羹 \n法，和以椒、盐，空腹顿服。《圣惠方》∶入薤白七茎。箧中方∶加五味 \n腰背虚痛∶杜仲一斤切炒，酒二升，渍十日，日服三合。此陶隐居得效方也。《三因方》∶为 \n末，每旦以温酒服二钱。 \n止更服。（《肘后方》） \n炒去丝），续断二两（酒浸焙干）。为末，以山药五、 \n十丸，空心米饮下。《肘后方》∶用杜仲焙研，枣肉 \n后诸疾及胎脏不安∶杜仲去皮，瓦上焙干，木臼捣末，煮枣肉和，丸弹子大。每服一丸，糯 \n米饮下，日二服。（《胜金方》） \n\\x 芽\\x \n【气味】缺。 \n【主治】作蔬，去风毒香港脚，久积风冷，肠痔下血。亦可煎汤（苏颂）。 \n\n\n\n<目录>木部第三十五卷\\木之二\n\n<篇名>椿樗\n\n内容：（《唐本草》） \n【校正】并入《嘉 》椿荚。 \n【释名】香者名椿（《集韵》作 ，《夏书》作 ，《左传》作 ），臭者名樗（音丑居切。 \n亦作KT ），山樗名栲（ \n时珍曰∶椿樗易长而多寿考，故有椿、栲之称。《庄子》言“大椿以八千岁为春秋”是 \n矣。 \n椿香而樗臭，故椿字又作 ，其气熏也。KT 字从 ，其气臭，人呵 之也。樗亦椿音之 \n转尔。 \n痕 \n【集解】恭曰∶椿、樗二树形相似，但樗木疏、椿木实为别也。 \n颂曰∶二木南北皆有之。形干大抵相类，但椿木实而叶香可啖，樗木疏而气臭，膳夫亦 \n能熬去其气，并采无时。樗木最为无用，《庄子》所谓“吾有大木，人谓之樗，其本拥肿不 \n中绳墨，小枝曲拳不中规矩”者。《尔雅》云∶栲山樗。郭璞注云∶栲，似樗，色小白， \n生山中，因名。亦类漆树。俗语云∶ 、樗、栲、漆，相似 \n田樗无异，叶差狭尔。吴人以叶为茗。 \n宗 曰∶椿、樗皆臭，但一种有花结子，一种无花不实。世以无花而木身大，其干端直 \n者为椿，椿木用叶。其有花、荚而木身小，干多迂矮者为樗，樗用根及荚、叶。又虫部有樗 \n鸡，不言椿鸡，以显有鸡者为樗，无鸡者为椿。古人命名其义甚明。禹锡曰∶樗之有花者无 \n荚，有荚者无花。其荚夏月常生臭樗上，未见椿上有荚者。然世俗不辨椿、樗之异，故呼樗 \n荚为椿荚尔。时珍曰∶椿、樗、栲，乃一木三种也。椿木皮细肌实而赤，嫩叶香甘可茹。樗 \n木皮粗肌虚而白，其叶臭恶，歉年人或采食。栲木即樗之生山中者，木亦虚大，梓人亦或用 \n之。然爪之如腐朽，故古人以为不材之木，不似椿木坚实，可入栋梁也。 \n\\x叶\\x \n【气味】苦，温，有小毒。 \n诜曰∶椿芽多食动风，熏十二经脉、五脏六腑，令人神昏血气微。若和猪肉、热面频食 \n则中满，盖壅经络也。 \n【主治】煮水，洗疮疥风疽。樗木根、叶尤良（《唐本》）。白秃不生发，取椿、桃、楸 \n叶心捣汁，频涂之 \n\\x白皮及根皮\\x \n【修治】 曰∶凡使椿根，不近西头者为上。采出拌生葱蒸半日，锉细，以袋盛挂屋南 \n畔，阴干用。 \n时珍曰∶椿、樗木皮、根皮，并刮去粗皮，阴干，临时切焙入用。 \n【气味】苦，温，无毒。 \n权曰∶微热。 \n震亨曰∶凉而燥。 \n藏器曰∶樗根有小毒。 \n时珍曰∶樗根制硫黄、砒石、黄金。 \n【主治】疳 ，樗根尤良（《唐本》）。去口鼻疳虫，杀蛔虫疥 ，鬼疰传尸，蛊毒下血， \n及赤白久痢（藏器）。得地榆，止疳痢（萧炳）。 \n不住，肠滑泻，缩小便。蜜炙用（大明）。利溺涩（雷 ）。 \n精滑梦遗，燥下湿，去肺胃陈积之痰（震亨）。 \n【发明】诜曰∶女子血崩，及产后血不止，月信来多，并赤带下。宜取东引细椿根一大 \n握洗净，以水一大升煮汁，分服便断。小儿疳痢，亦宜多服。仍取白皮一握，粳米五十粒， \n葱白一握，炙甘草三寸，豉两合，水一升，煮半升，以意服之。枝叶功用皆同。 \n根白皮，性凉而能涩血。凡湿热为病，泻痢浊带，精滑梦遗诸症，无不用之 \n肺胃陈痰之功。治泄泻，有除湿实肠之力。但痢疾滞气未尽者，不可遽用。宜入丸散，亦可 \n煎服，不见有害。予每用炒研糊丸，看病作汤使，名固肠丸也。 \n皮色白而臭，多服微利人。盖椿皮入血分而性涩，樗皮入气 \n功虽同，而涩利之效则异，正如茯苓、芍药，赤、白颇殊也。凡血分受病不足者，宜用椿皮； \n气分受病有郁者，宜用樗皮，此心得之微也。《乾坤生意》治疮 \n汁，服二、三碗，取利数行，是其验矣。故陈藏器言樗皮有小毒， \n阳一女人，年四十六、七，耽饮无度，多食鱼蟹，畜毒在脏，日夜二、三十 \n杂下，大肠连肛门痛不堪任。医以止血痢药不效，又以肠风药则益甚，盖肠风则有血无脓。 \n如此半年余，气血渐弱，食减肌瘦。服热药则腹愈痛，血愈下；服冷药即注泄食减，服温平 \n药则病不知。如此期年，垂命待尽。或人教服人参散，一服知，二服减，三服脓血皆定，遂 \n常服之而愈。其方治大肠风虚，饮酒过度，挟热下痢脓血痛甚，多日不瘥。用樗根白皮一两， \n人参一两。为末。每服二钱，空心温酒调服，米饮亦可。忌油腻、湿面、青菜、果子、甜物、 \n鸡、猪、鱼、羊、蒜、薤等。 \n【附方】旧六，新十一。 \n去鬼气∶樗根皮一握细切，以童儿小便二升，豉一合，浸一宿，绞汁煎一沸。三、五日 \n一度，服之。（陈藏器《本草》） \n小儿疳疾∶椿白皮（晒干）二两为末，以粟米淘净研浓汁和，丸梧桐子大。十岁三、四 \n丸，米饮下，量人加 \n小儿疳痢困重者∶用樗白皮捣粉，以水和枣作大馄饨子。日晒少时，又捣，如此三遍， \n以水煮熟，空肚吞七枚。重者不过七服。忌油腻、热面、毒物。又方∶用樗根浓汁一蚬壳， \n和粟米泔等分，灌下部。再度即瘥，其验如神。 \n大人亦宜。（《外台秘要》）休息痢疾，日夜无度，腥臭不可近，脐腹撮痛∶东垣《脾胃 \n论》∶用椿根白皮、诃黎勒各半两，母丁香三十个，为末，醋糊丸梧桐子大。每服五十丸， \n米饮下。唐瑶《 \n两加木香二钱，粳 \n，兼腰痛∶取樗根一大两捣筛，以好面捻作馄饨如皂子大，水煮熟。每日空心服十枚。并无 \n禁忌，神良。（刘禹锡《传信方》） \n大。每空心米饮下三、四十丸。一加苍术、枳壳减半。（《经验方》） \n洗刮取皮，晒干为末。饮下一钱，立效。（《经验方》）。 \n粗皮，酒浸晒研，枣肉和，丸梧桐子大。每淡酒服五十丸，或酒糊丸亦可。（《儒门事亲》） \n下血经年∶樗根三钱。水一盏，煎七分，入酒半盏服。或作丸服。虚者加人参等分。即虎眼 \n树。（《仁存方》） \n阴干为末。每二两入寒食面一两，新汲水丸梧 \n水送下。忌见日，则无效。名如神丸。（《普济 \n气乘之，血渗肠间，故大便下血。用臭椿根（刮去粗皮，焙干）四两，苍术（米泔浸焙）、 \n枳壳 \n（ \n产后肠脱 \n升， \n去滓倾盆内。乘热熏洗，冷则再热，一服可作五次用，洗后睡少时。忌盐、 \n毒物，及用心劳力等事。年深者亦治之。（《妇人良方》） \n为末，粥丸梧桐子大。每空腹白汤下一百丸。又方∶椿根白皮一两半，干姜（炒黑）、白芍 \n药 \n（炒黑）、黄柏（炒黑）各二钱，为末。如上法丸服。（丹溪方） \n\\x荚\\x \n【释名】凤眼草（象形）。 \n【主治】大便下血（《嘉 》）。 \n【附方】新四。 \n肠风泻血∶椿荚半生半烧，为末。每服二钱，米饮下。（《普济方》） \n误吞鱼刺∶《生生编》∶用椿树子烧研，酒服二钱。《保寿堂方》∶用香椿树子（阴干）半 \n碗，擂碎，热酒冲服，良久连骨吐出。 \n水洗头， \n经一年眼如童子。加 \n六月四日、七月七日、八月三日、九月二十日、十月二十三日、十一月二十九日、十二月十 \n四日洗之。（《卫生易简方》） \n\n\n\n<目录>木部第三十五卷\\木之二\n\n<篇名>漆\n\n内容：（《本经》上品） \n【释名】 。 \n时珍曰∶许慎《说文》云∶漆本作 ，木汁可以髹物，其字象水滴而下之形也。 \n【集解】《别录》曰∶干漆生汉中山谷。夏至后采，干之。 \n弘景曰∶今梁州漆最甚，益州亦有。广州漆性急易燥。其诸处漆桶中自然干者，状如蜂 \n房孔孔隔者为佳。 \n保升曰∶漆树高二、三丈余，皮白，叶似椿，花似槐，其子似牛李子，木心黄。六月、 \n七月刻取滋汁。金州者最善。漆性并急，凡取时须荏油解破，故淳者难得，可重重别制拭之。 \n上等清漆，色黑如 ，若铁石者好。黄嫩若蜂窠者不佳。颂曰∶今蜀、汉、金、峡、襄、歙 \n州皆有之。以竹筒钉入木中，取汁。崔豹《古今注》 \n汁则成漆也。 \n得阴湿，虽寒月亦易干，亦物之性也。若沾渍人，以油治之。凡验漆，惟稀者以物蘸起，细 \n而不断，断而急收起；又涂于干竹上，荫之速干者，并佳。 \n移栽易成，有利。其身如柿，其叶如椿。以金州者为 \n有云∶微扇光如镜，悬丝急似钩。撼成琥珀色，打着有 \n而大。六月取汁漆物，黄泽如金，即《唐书》所谓黄漆者也。入药仍当用黑漆。广南漆作饴 \n糖气，沾沾无力。 \n\\x干漆\\x \n【修治】大明曰∶干漆入药，须捣碎炒熟。不尔，损人肠胃 \n若是湿漆，煎干更好。亦有烧存性者。 \n【气味】辛，温，无毒。权曰∶辛、咸。宗 曰∶苦。 \n元素曰∶辛，平，有毒。降也，阳中阴也。 \n之才曰∶半夏为之使。畏鸡子，忌油脂。 \n弘景曰∶生漆毒烈，人以鸡子和服之去虫，犹自啮肠胃也。畏漆人乃致死者。外气亦 \n能使身肉疮肿，自有疗法。 \n大明曰∶毒发，饮铁浆并黄栌汁、甘豆汤、吃蟹，并可制之。 \n时珍曰∶今人货漆多杂桐油，故多毒。《淮南子》云∶蟹见漆而不干。《相感志》云∶漆 \n得蟹而成水。盖物性相制也。凡人畏漆者，嚼蜀椒涂口鼻则可免。生漆疮者，杉木汤、紫苏 \n汤、漆姑草汤、蟹汤浴之，皆良。 \n【主治】绝伤，补中，续筋骨，填髓脑，安五脏，五缓六急，风寒湿痹。生漆∶去长虫。 \n久服，轻身耐老（《本经》）。干漆∶疗咳嗽，消瘀血痞结腰痛，女子疝瘕，利小肠，去蛔虫 \n（《别录》）。杀三虫，主女人经脉不通 \n滞，破日久凝结之瘀血（元素）。 \n【发明】弘景曰∶《仙方》用蟹消漆为水，炼服长生。《抱朴子》云∶淳漆不粘者，服之 \n通神长生。或以大蟹投其中，或以云母水，或以玉水合 \n一年，六甲、行厨至也。 \n则积滞去后，补性内 \n时珍曰∶漆性毒而杀虫，降而行血。所主诸症虽繁，其功只在二者而已。 \n【附方】旧四，新七。 \n小儿虫病∶胃寒危恶症，与痫相似者。干漆（捣烧烟尽）、白芜荑等分，为末。米饮服 \n一字至一钱。（杜壬方）。 \n九种心痛及腹胁积聚滞气∶筒内干漆一两，捣炒烟尽，研末，醋煮面糊丸梧桐子大。每 \n服五丸至九丸，热酒下。（《简要济众》） \n丈夫疝气、小肠气撮痛者，并宜服二圣丸。湿漆一两，熬一食顷，入干漆末一两，和丸梧桐 \n子大。每服三、四丸，温酒下。怕漆人不可服。（《经验方 \n治女人月经瘀闭不来，绕脐寒疝痛彻， \n炒烟尽），牛膝末一两，以生地黄汁一升，入银、石器中慢熬，俟可丸，丸如梧桐子大。每 \n服一丸，加至三、五丸，酒、饮任下，以通为度。《产宝方》∶治女 \n欲呕，不得睡。用当归四钱，干漆三钱（炒烟尽），为末，炼蜜丸梧桐子大。每服十五丸， \n空 \n心温酒下。《千金》∶治女人月水不通，脐下坚如杯，时发热往来，下痢羸瘦 \n生肉症，不可治也。干漆一斤（烧研），生地黄二十斤（取汁 \n每 \n服三丸，空心酒下。 \n满，盐泥固济，锻赤，放冷研散。每服一、二钱，热酒下。但是产后诸疾皆可服。 \n经验方》） \n子大。每服二七丸，温酒下，日二服。（《千金方》）。 \n筒吸之。（《圣济总录》）。 \n十丸至百丸。（《直指方》）。 \n\\x漆叶\\x \n【气味】缺。 \n【主治】五尸劳疾，杀虫。曝干研末，日用酒服一钱匕（时珍）。 \n【发明】颂曰∶《华佗传》载∶彭城樊阿，少师事佗。佗授以漆叶青粘散方，云服之去 \n三虫，利五脏，轻身益气，使人头不白。阿从其言，年五百余岁。漆叶所在有之。青粘生丰 \n沛、彭城及朝歌。一名地节，一名黄芝。主理五脏，益精气。本出于迷人入山，见仙人服之， \n以告佗。佗以为佳，语阿。阿秘之。近者人见阿之寿而气力强盛，问之。因醉误说，人服多 \n验。后无复有人识青粘，或云即黄精之正叶者也。 \n时珍曰∶按∶葛洪《抱朴子》云∶漆叶、青粘，凡薮之草也。樊阿服之，得寿二百岁， \n而耳目聪明，犹能持针治病。此近代之实事，良史所记注者也。洪说犹近于理，前言阿年五 \n百岁者，误也。或云青粘即葳蕤。 \n\\x漆子\\x \n【主治】下血（时珍）。 \n\\x漆花\\x \n【主治】小儿解颅、腹胀、交胫不行方中用之（时珍）。 \n\n\n\n<目录>木部第三十五卷\\木之二\n\n<篇名>梓\n\n内容：（《本经》下品） \n【释名】木王。 \n时珍曰∶梓，或作 ，其义未详。 \n按∶陆佃《埤雅》云∶梓为百木长，故呼梓为木王。盖木莫良于梓，故《书》以梓材名 \n篇，《礼》以梓人名匠，朝廷以梓宫名棺也。罗愿云∶屋室有此木，则余材皆不震。其为木 \n王可知。 \n【集解】《别录》曰∶梓白皮生河内山谷。 \n弘景曰∶此即梓树之皮。梓有三种，当用朴素不腐者。 \n颂曰∶今近道皆有之，宫寺人家园亭亦多植之。木似桐而叶小，花紫。《尔雅》云∶椅 \n，梓。郭璞注云∶即楸也。《诗· 风》云∶椅、桐、梓、漆，爰伐琴瑟。陆机注云∶楸之 \n疏理白色而生子者为梓，梓实桐皮为椅，大同而小异也。入药当用有子者。又一种鼠梓，一 \n名，亦楸属也。枝叶木理皆如楸。今人谓之苦楸，江东人谓之虎梓。《诗·小雅》云“北 \n山有 ”是也。鼠李一名鼠梓，或云即此。然花实都不相类，恐别一物而名同尔。 \n楸 \n生山谷间，与梓树本同末异，或以为一物者误矣。 \n皆不堪。 \n梓、 、楸，一物四名。而陆机《诗疏》以楸之疏理白色生子者为梓，梓实桐皮者为椅。贾 \n思勰《齐民要术》又以白色有角者为梓，即角楸也，又名子楸。黄色无子者为椅楸，又名荆 \n黄楸。但以子之有无为别。其角细长如箸，其长近尺，冬后叶落而角犹在树。其实亦名豫章。 \n时珍曰∶梓木处处有之。有三种∶木理白者为梓，赤者为楸，梓之美纹者为椅，楸之 \n。诸家疏注，殊欠分明。桐亦名椅，与此不同。此椅即尸子所“谓荆有长松、文椅”者也。 \n\\x梓白皮\\x \n【气味】苦，寒，无毒。 \n【主治】热毒，去三虫（《本经》）。 \n疗目中疾，主吐逆胃反。小儿热疮，身头热烦，蚀疮，煎汤浴之，并捣敷（《别录》）。 \n煎汤洗小儿壮热，一切疮疥，皮肤瘙痒（大明）。治温病复感寒邪，变为胃 ，煮汁饮之（时 \n珍）。 \n【附方】新一。 \n时气温病，头痛壮热，初得一日∶用生梓木削去黑皮，取里白者切一升，水二升五合煎 \n汁。每服八合，取瘥。（《肘后方》） \n\\x叶\\x \n【主治】捣敷猪疮。饲猪，肥大三倍（《本经》）。 \n疗手脚火烂疮（《别录》）。 \n弘景曰∶桐叶、梓叶肥猪之法未见，应在商丘子《养猪经》中。 \n恭曰∶二树花叶饲猪，并能肥大且易养，见李当之《本草》及《博物志》，然不云敷猪 \n疮也。 \n【附方】新一。 \n风癣疙瘩∶梓叶、木绵子、羯羊屎、鼠屎等分，入瓶中合定，烧取汁涂之。（《试效录 \n验方》） \n\n\n\n<目录>木部第三十五卷\\木之二\n\n<篇名>楸\n\n内容：（《拾遗》） \n【释名】 。 \n时珍曰∶楸叶大而早脱，故谓之楸； 叶小而早秀，故谓之 。唐时立秋日，京师卖楸 \n叶，妇女、儿童剪花戴之，取秋意也。《尔雅》云∶叶小而 ， 。叶大而 ，楸。 ，音 \n鹊，皮粗也。 \n【集解】见梓下。 \n周定王曰∶楸有二种。一种刺楸，其树高硕，皮色苍白，上有黄白斑点，枝梗间多大刺 \n。叶似楸而薄，味甘，嫩时炸熟，水淘过拌食。 \n时珍曰∶楸有行列，茎干直耸可爱。至秋垂条如线，谓之楸线，其木湿时脆，燥则坚， \n故谓之良材，宜作棋枰，即梓之赤者也。 \n\\x木白皮\\x \n【气味】苦，小寒，无毒。 曰∶微温。 \n【主治】吐逆，杀三虫及皮肤虫。煎膏，粘敷恶疮疽 ，痈肿疳痔。除脓血，生肌肤， \n长筋骨（藏器）。消食涩肠下气，治上气咳嗽。亦入面药（ \n效 \n【附方】旧一，新一。 \n疮∶楸枝作煎，频洗取效。（《肘后方》） \n白癜风疮∶楸白皮五斤，水五斗，煎五升，去滓，煎如稠膏。日三摩之。（《圣济总录》）。 \n\\x叶\\x \n【气味】同皮。 \n【主治】捣敷疮肿。煮汤，洗脓血。冬取干叶用之。诸痈肿溃及内有刺不出者，取叶十 \n重贴之（藏器。出《范汪方》）。 \n【发明】时珍曰∶楸乃外科要药，而近人少知。葛常之《韵语阳秋》云∶有人患发背 \n溃坏，肠胃可窥，百方不瘥。一医用立秋日太阳未升时，采楸树叶，熬之为膏，敷其外；内 \n以云母膏作小丸服，尽四两，不累日而愈也。东晋范汪，名医也，亦称楸叶治疮肿之功。则 \n楸有拔毒排脓之力可知。 \n【附方】旧七，新一。 \n上气咳嗽，腹满羸瘦者∶楸叶三斗，水三斗，煮三十沸，去滓，煎至可，丸如枣大。以 \n筒纳入下部中，立愈。（崔元亮《海上集验方》）。 \n一切毒肿不问硬软∶取楸叶十重敷肿上，旧帛裹之，日三易之。当重重有毒瓦斯为水，流 \n在叶上。冬月取干叶，盐水浸软，或取根皮捣烂，敷之皆效。止痛消肿，食脓血，胜于众药。 \n（《范汪东阳方》）。 \n十五斤，以水一石，净釜中煎取三斗，又换锅煎取七、八升，又换锅煎取二升，乃纳不津器 \n中。用时先取麻油半合，蜡一分，酥一栗子许，同消化。又取杏仁七粒，生姜少许，同研。 \n米粉二钱，同入膏中搅匀。先涂疮上，经二日来乃拭却，即以篦子匀涂楸煎满疮上，仍以软 \n帛裹之。且日一拭，更上新药。不过五、六上，已破者即便生肌，未破者即内消。瘥后须将 \n慎半年。采药及煎时，并禁孝子、妇人、僧道、鸡犬见之。（ \n不瘥。楸叶及根皮为末，敷之。（《圣惠方》） \n儿发不生∶楸叶中心，捣汁频涂。（《千金翼》）。 \n，烧干去泥，入水少许，绞汁，铜器慢熬如稀饧，瓷合收之。每旦点之。（《普济方》）。 \n小儿秃疮∶楸叶捣汁，涂之。（《子母秘录》） \n\n\n\n<目录>木部第三十五卷\\木之二\n\n<篇名>桐\n\n内容：（《本经》下品） \n【释名】白桐（弘景）、黄桐（《图经》）、 \n时珍曰∶《本经》桐叶，即白桐也。桐华成筒，故谓之桐。其材轻虚，色白而有绮纹， \n故俗谓之白桐、泡桐，古谓之椅桐也。先花后叶，故《尔雅》谓之荣桐。或言其花而不实者， \n未之察也。陆机以椅为梧桐，郭璞以 \n【集解】《别录》曰∶桐叶生桐柏山谷。 \n弘景曰∶桐树有四种∶青桐，叶、皮青，似梧桐而无子；梧桐，皮白，叶似青桐而有子， \n子肥可食；白桐，一名椅桐，人家多植之，与冈桐无异，但有花、子，二月开花，黄紫色， \n《礼 \n颂曰∶桐处处有之。陆机《草木疏》言白桐宜为琴瑟。云南 人，取花中白毳淹渍，绩以 \n为布，似毛布，谓之华布。椅，即梧桐也。今江南人作油者，即冈桐也，有子大于梧子。江 \n南有 桐，秋开红花，无实。有紫桐，花如百 \n宗曰∶《本经》桐叶不指定是何桐，致难执用。但四种各有治疗。白桐，叶三杈，开白花， \n不结子。无花者为冈桐，不中作琴，体重。荏桐，子可作桐油。梧桐，结子可食。时珍曰∶ \n陶注桐有四种，以无子者为青桐、冈桐，有子者为梧桐、白桐。寇注言白桐、冈桐皆无子。 \n苏注以冈桐为油桐。而贾思勰《齐民要术》言∶实而皮青者为梧桐，华而不实者为白桐。 \n白桐冬结似子者，乃是明年之华房，非子也。冈桐即油桐也，子大有油。其说与陶氏相反。 \n以今咨访，互有是否。盖白桐即泡桐也。叶大径尺，最易生长。皮色粗白，其木轻虚，不生 \n虫蛀，作器物、屋柱甚良。二月开花，如牵牛花而白色。结实大如巨枣，长寸余，壳内有子 \n片，轻虚如榆荚、葵实之状，老则壳裂，随风飘扬。其花紫色者名冈桐。荏桐即油桐也。青"}, {"n": 30, "text": "卷三十\n\n桐即梧桐之无实者。按∶陈翥《桐谱》，分别白桐、冈桐甚明。云∶白花桐，纹理粗而体性 \n慢，喜生朝阳之地。因子而出者，一年可起三、四尺；由根而出者，可五、七尺。其叶圆大 \n而尖长有角，光滑而毳。先花后叶。花白色，花心微红。其实大二、三寸，内为两房，房内 \n有肉，肉上有薄片，即其子也。紫花桐，纹理细而体性坚，亦生朝阳之地，不如白桐易长。 \n其叶三角而圆，大如白桐，色青多毛而不光，且硬，微赤。亦先花后叶，花色紫。其实亦同 \n白桐而微尖，状如诃子而粘，房中肉黄色。二桐皮色皆一，但花、叶小异，体性坚、慢不同 \n尔。亦有冬月复花者。 \n\\x桐叶\\x \n【气味】苦，寒，无毒。 \n【主治】恶蚀疮着阴（《本经》）。 \n消肿毒，生发（时珍）。 \n【附方】新四。 \n手足肿浮∶桐叶煮汁渍之，并饮少许。或加小豆，尤妙。（《圣惠方》） \n痈疽发背大如盘，臭腐不可近∶桐叶醋蒸粘贴。退热止痛，渐渐生肉收口，极验秘方也 \n。（《医林正宗》） \n发落不生∶桐叶一把，麻子仁三升，米泔煮五、六沸，去滓。日日洗之则长。（《肘后 \n方》）。 \n发白染黑∶经霜桐叶及子，多收捣碎，以甑蒸之，生布绞汁，沐头。（《普济方》） \n\\x木皮\\x \n【主治】五痔，杀三虫（《本经》）。疗奔豚气病（《别录》）。五淋。沐发，去头风，生 \n发滋润（甄权）。治恶疮，小儿丹毒，煎汁涂之（时珍）。 \n【附方】新三。 \n肿从脚起∶削桐木煮汁，渍之，并饮少许。（《肘后方》）。 \n伤寒发狂∶六、七日热极狂言，见鬼欲走。取桐皮（削去黑，擘断四寸）一束，以酒五 \n合， \n水一升，煮半升，去滓顿服。当吐下青黄汁数升，即瘥。（《肘 \n跌扑伤损∶水桐树皮，去青留白，醋炒捣敷。（《集简方》） \n\\x花\\x \n【主治】敷猪疮。饲猪，肥大三倍（《本经》）。 \n【附方】 \n眼见诸物∶禽虫飞走，乃肝胆之疾。青桐子花、酸枣仁、玄明粉、羌活各一两，为末。 \n每服二钱，水煎和滓，日三服。（《经验良方》） \n\n\n\n<目录>木部第三十五卷\\木之二\n\n<篇名>梧桐\n\n内容：（《纲目》） \n【释名】榇。 \n时珍曰∶梧桐名义未详。《尔雅》谓之榇，因其可为棺，《左传》所谓“桐棺三寸”是矣。 \n旧附桐下，今别出条。 \n【集解】弘景曰∶梧桐皮白，叶似青桐，而子肥可食。颂曰∶陶氏谓白桐一名椅桐。陆 \n机谓梓实桐皮为椅，即今梧桐。是二种俱有椅名也。《遁甲书》云∶梧桐可知日月正闰。生 \n十二叶，一边有六叶，从下数一叶为一月，至上十二叶。有闰十三叶，小余者。视之，则知 \n闰何月也。故曰梧桐不生则九州异。宗 曰∶梧桐四月开嫩黄小花，一如枣花。枝头出丝， \n堕地成油，沾渍衣履。五、六月结子，人收炒食，味如菱、芡。此是《月令》“清明桐始华” \n者。时珍曰∶梧桐处处有之。树似桐而皮青不 ，其木无节直生，理细而性紧。叶似桐而稍 \n小，光滑有尖。其花细蕊，坠下如醭。其荚长三寸许，五片合成，老则裂开如箕，谓之 鄂。 \n其子缀于 鄂上，多者五、六，少或二、三。子大如胡椒，其皮皱。罗愿《尔雅翼》云∶梧 \n桐多阴，青皮白骨，似青桐而多子。其木易生，鸟衔子堕辄生。但晚春生叶，早秋即凋。古 \n称凤凰非梧桐不栖，岂亦食其实乎？《诗》云∶梧桐生矣，于彼朝阳。《齐民要术》云∶梧 \n桐生山石间者，为乐器更鸣响也。 \n\\x木白皮\\x \n【气味】缺。 \n【主治】烧研，和乳汁涂须发，变黄赤（时珍）。治肠痔（苏颂。《删繁方》治痔，青龙 \n五生膏 \n\\x叶\\x \n【主治】发背，炙焦研末，蜜调敷，干即易（《肘后》）。 \n\\x子\\x \n【气味】甘，平，无毒。 \n【主治】捣汁涂，拔去白发，根下必生黑者。又治小儿口疮，和鸡子烧存性，研掺（时 \n珍）。 \n\n\n\n<目录>木部第三十五卷\\木之二\n\n<篇名>罂子桐\n\n内容：（《拾遗》） \n【释名】虎子桐（《拾遗》）、荏桐（《衍义》） \n时珍曰∶罂子，因实状似罂也。虎子，以其毒也。荏者，言其油似荏油也。 \n【集解】藏器曰∶罂子桐生山中。树似梧桐。 \n颂曰∶南人作油者，乃冈桐也。有子大于梧子。 \n宗 曰∶荏桐，早春先开淡红花，状如鼓子花，成筒子。子可作桐油。 \n时珍曰∶冈桐即白桐之紫花者。油桐枝、干、花、叶并类冈桐而小，树长亦迟，花 \n亦微红。 \n但其实大而圆，每实中有二子或四子，大如大风子。其肉白色，味甘而吐人。亦或谓之 \n紫花桐。人多种莳收子，货之为油，入漆家及 船用，为时所须。人多伪之，惟以篾圈蘸起 \n如鼓面者为真。 \n\\x桐子油\\x \n【气味】甘、微辛，寒，有大毒。 \n大明曰∶冷，微毒。时珍曰∶桐油吐人，得酒即解。 \n【主治】摩疥癣虫疮毒肿。毒鼠至死（藏器）。敷恶疮，及宣水肿，涂鼠咬处。能辟鼠 \n（大 \n明）。涂胫疮、汤火伤疮。吐风痰喉痹，及一切诸疾，以水和油，扫入喉中探吐；或以子研 \n末，吹入喉中取吐。又点灯烧铜箸头，烙风热烂眼，亦妙（时珍）。 \n【附方】新七。 \n痈肿初起∶桐油点灯，入竹筒内熏之，得出黄水即消。（《医林正宗》）。 \n血风 疮∶胡粉 过研，桐油调作隔纸膏，贴之。又方∶用船上陈桐油锻石 过，又以 \n人发拌桐油炙干为末，仍以桐油调作膏，涂纸上，刺孔贴之。（杨起《简便方》）。 \n脚肚风疮如癞∶桐油、人乳等分，扫之。数次即愈。（《集简方》）。 \n酒渣赤鼻∶桐油入黄丹、雄黄，敷之。（《摘玄方》）。 \n冻疮皲裂∶桐油一碗，发一握。熬化瓶收。每 \n解砒石毒∶桐油二升，灌之。吐即毒解。（华佗危病方） \n【附录】KT 桐（音而郢切） \n藏器曰∶生山谷间。状似青桐，叶有丫。人取皮以沤丝。木皮味甘，温，无毒。治蚕 \n咬毒瓦斯入腹，末服之。鸡犬食蚕欲死者，煎汁灌之，丝烂即愈。叶∶主蛇、虫、蜘蛛咬毒， \n捣烂封之。 \n\n\n\n<目录>木部第三十五卷\\木之二\n\n<篇名>海桐\n\n内容：（宋《开宝》） \n【释名】刺桐。 \n曰∶生南海山谷中，树似桐而皮黄白色，有刺，故以名之。 \n【集解】颂曰∶海桐生南海及雷州，近海州郡亦有之。叶大如手，作三花尖。皮若梓白 \n皮，而坚韧可作绳，入水不烂。不拘时月采之。又云∶岭南有刺桐，叶如梧桐。其花附干而 \n生，侧敷如掌，形若金凤，枝干有刺，花色深红。江南有 \n时珍曰∶海桐皮有巨刺，如鼋甲之刺，或云即刺桐皮也。按∶嵇含《南方草木状》云∶ \n九真有刺桐，布叶繁密。三月开花，赤色照映，三、五房凋，则三、五复发。陈翥《桐谱》 \n云∶刺桐生山谷中。 \n纹理细紧，而性喜拆裂。体有巨刺，如 树。其叶如枫。 桐身青，叶圆大而长。高三、 \n四尺，便有花成 \n\\x木皮\\x \n【气味】苦，平，无毒。大明曰∶温。 \n【主治】霍乱中恶，赤白久痢，除疳 疥癣，牙齿虫痛，并煮服及含之。水浸洗目，除 \n肤赤（《开宝》）。主腰脚不遂，血脉顽痹，腿膝疼 \n洗赤目（时珍）。 \n【发明】颂曰∶古方多用浸酒治风蹶。 \n南唐筠州刺史王绍颜撰《续传信方》云∶顷年予在姑孰，得腰膝痛不可忍。医以肾脏风 \n毒攻刺诸药莫疗。因览刘禹锡《传信方》备有此验。修服一剂，便减五分。其方用海桐皮二 \n两，牛 \n净洗焙干 \n晚各一次，长令醺醺。此方不得添减，禁毒食。 \n分，及去风杀虫。 \n【附方】新三。 \n风癣有虫∶海桐皮、蛇床子等分，为末。以腊猪脂调，搽之。（艾元英《如宜方》） \n风虫牙痛∶海桐皮煎水，漱之。（《圣惠方》）。 \n中恶霍乱∶海桐皮，煮汁服之。（《圣济总录》） \n\\x刺桐花\\x \n【主治】止金疮血，殊效（苏颂）。 \n【附录】鸡桐 时珍曰∶生岭南山间。其叶如楝。用叶煮汤，洗渫足 \n\n\n\n<目录>木部第三十五卷\\木之二\n\n<篇名>楝\n\n内容：（《本经》下品） \n【释名】苦楝（《图经》），实名金铃子。 \n时珍曰∶按∶罗愿《尔雅翼》云∶楝叶可以练物，故谓之楝。其子如小铃，熟则黄色。 \n名金铃，象形也。 \n【集解】《别录》曰∶楝实生荆山山谷。 \n弘景曰∶处处有之。俗人五月五日取叶佩之，云辟恶也。 \n恭曰∶此有雌雄两种∶雄者无子，根赤有毒，服之使人吐，不能止，时有至死者；雌者 \n有子，根白微毒。入药当用雌者。 \n颂曰∶楝实以蜀川者为佳。木高丈余，叶密如槐而长。三、四月开花，红紫色，芬香 \n满庭。实如弹丸，生青熟黄，十二月采之。根采无时。 \n时珍曰∶楝长甚速，三、五年即可作椽。其子正如圆枣，以川中者为良。王祯《农书》 \n言 食其实。应劭《风俗通》言獬豸食其叶。宗懔《岁时记》言蛟龙畏楝，故端午以叶包 \n粽，投江中祭屈原。 \n\\x实\\x \n【修治】 曰∶凡采得晒干，酒拌令透，蒸待皮软，刮去皮，取肉去核用。凡使肉不使 \n核，使核不使肉。如使核，捶碎，用浆水煮一伏时，晒干。其花落子，谓之石茱萸，不入药 \n用。 \n【气味】苦，寒，有小毒。 \n元素曰∶酸、苦，平。阴中之阳。 \n时珍曰∶得酒煮，乃寒因热用也。茴香为之使。 \n【主治】温疾伤寒，大热烦狂，杀三虫，疥疡，利小便水道（《本经》）。主中大热狂， \n失心躁闷，作汤浴，不入汤使（甄权）。入心及小肠，止上下部腹痛（李杲）。泻膀胱（好古）。 \n治诸疝虫痔（时珍）。 \n【发明】元素曰∶热厥暴痛，非此不能除。 \n时珍曰∶楝实，导小肠、膀胱之热，因引心包相火下行，故心腹痛及疝气为要药。甄权 \n乃言不入汤使，则《本经》何以有治热狂、利小便之文耶？近方治疝，有四治、五治、七治 \n诸法，盖亦配合之巧耳。 \n【附方】旧三，新八。 \n热厥心痛或发或止，身热足寒，久不愈者∶先灸太溪、昆仑，引热下行。内服金铃散∶ \n用金铃子、玄胡索各一两，为末。每服三钱，温酒调下。（洁古《活法机要》）。小儿冷疝气 \n痛，肤囊浮肿∶金铃子（去核）五钱，吴茱萸二钱半，为末，酒糊丸黍米大。每盐汤下二、 \n三 \n十丸。（《全幼心鉴》） \n皮），巴豆二百个（微打破），以面二升，同于铜铛内炒至金铃子赤为度 \n末，巴、面不用。每服三钱，热酒或醋汤调服。一方∶入盐炒茴香半两。（《经验方》）。 \n疝肿痛∶《澹寮方》楝实丸∶治钓肾偏坠，痛不可忍。用川楝子肉五两，分作五分∶ \n一两 \n用破故纸二钱炒黄，一两用小茴香三钱、食盐半钱同炒，一两用莱菔子一钱同炒，一两用牵 \n牛子三钱同炒，一两用斑蝥七枚（去头、足）同炒。拣去食盐、莱菔、牵牛、斑蝥，只留故 \n纸、茴香，同研为末，以酒打面糊丸梧桐子大。每空心酒下五十丸。《得效方》楝实丸∶治 \n一切疝气肿痛，大有神效。用川楝子（酒润取肉）一斤，分作四分∶四两用小麦一合，斑蝥 \n四 \n十九个，同炒熟，去蝥；四两用小麦一合，巴豆四十九枚，同炒熟，去豆；四两用小麦一合， \n巴戟肉一两，同炒熟，去戟；四两用小茴香一合，食盐一两，同炒熟，去盐。加破故纸（酒 \n炒）一两，广木香（不见火）一两，为末，酒煮面糊丸梧桐子大。每服五十丸，盐汤空心下， \n日三服。《直指方》楝实丸∶治外肾胀大，麻木痛破，及奔豚疝气。用川楝子四十九个，分 \n七处切取肉∶七个用小茴香五钱同炒，七个用破故纸二钱半同炒，七个用黑牵牛二钱半同炒， \n七个用食盐二钱同炒，七个用萝卜子二钱半同炒，七个用巴豆十四个同炒，七个用斑蝥十四 \n个（去头、足）同炒。拣去萝卜子、巴豆、斑蝥三味不用。入青木香五钱，南木香、官桂各 \n二 \n钱半，为末，酒煮面糊丸梧桐子大。每服三十丸，食前用盐汤下，一日三服。脏毒下血∶苦 \n楝子炒黄为末，蜜丸梧桐子大。米饮每吞十丸至二十丸。（《经验方》）。腹中长虫∶楝实以 \n淳苦酒渍一宿，绵裹，塞入谷道中三寸许，日二易之。（《外台秘要》）。 \n合，捣 \n为末。每温酒服一钱。（《圣惠方》）。 \n米饮下。（《摘玄方》）。 \n\\x根及木皮\\x \n【气味】苦，微寒，微毒。 \n大明曰∶雄者根赤有毒，吐泻杀人，不可误服。雌者入服食，每一两可入糯米五十粒同 \n煎，杀毒。若泻者，以冷粥止之。不泻者，以热葱粥发之。 \n【主治】蛔虫，利大肠（《别录》）。苦酒和，涂疥癣甚良（弘景）。治游风热毒，风疹恶 \n疮疥癞，小儿壮热，并煎汤浸洗（大明）。 \n【附方】旧四，新六。 \n消渴有虫∶苦楝根白皮一握切焙，入麝香少许，水二碗，煎至一碗，空心饮之，虽困顿 \n不妨。下虫如蛔而红色，其渴自止。消渴有虫，人所不知。（洪迈《夷坚志》） \n小儿蛔虫∶楝木皮削去苍皮，水煮汁，量大小饮之。 \n《斗门方》∶用为末，米饮服二钱。《集简方》∶用根皮，同鸡卵煮熟，空心食之。次日 \n虫 \n。《简便方》∶用楝根白皮（去粗）二斤切，水一斗，煮取汁三升，沙锅熬成膏。五更初，温 \n酒服一匙，以虫下为度。 \n小儿诸疮∶恶疮、秃疮、蠼 疮、浸淫疮，并宜楝树皮或枝烧灰敷之。干者猪脂调。（《千 \n金方》）。 \n口中 疮∶东行楝根细锉，水煮浓汁，日日含漱，吐去勿咽。（《肘后方》）。 \n蜈蚣蜂伤∶楝树枝、叶汁，涂之良。（杨起《简便方》）。 \n疥疮风虫∶楝根皮、皂角（去皮、子）等分。为末。猪脂调涂。（《奇效方》） \n\\x花\\x \n【主治】热痱，焙末掺之。铺席下，杀蚤、虱（时珍）。 \n\\x叶\\x \n【主治】疝入囊痛，临发时煎酒饮（时珍）。 \n\n\n\n<目录>木部第三十五卷\\木之二\n\n<篇名>槐\n\n内容：（《本经》上品） \n【校正】并入《嘉 》槐花、槐胶。 \n【释名】 （音怀）。 \n时珍曰∶按∶《周礼》外朝之法，面三槐，三公位焉。吴澄注云∶槐之言怀也，怀来人 \n于此也。王安石释云∶槐华黄，中怀其美，故三公位之。《春秋元命包》云∶槐之言归也。 \n古者树槐，听讼其下，使情归实也。 \n【集解】《别录》曰∶槐实生河南平泽。可作神烛。 \n颂曰∶今处处有之。其木有极高硕者。按∶《尔雅》槐有数种∶叶大而黑者名 槐，昼 \n合夜开者名守宫槐，叶细而青绿者但谓之槐，其功用不言有别。四月、五月开黄花，六月、 \n七月结实。七月七日采嫩实，捣汁作煎。十月采老实入药。皮、根采无时。医家用之最多。 \n时珍曰∶槐之生也，季春五日而兔目，十日而鼠耳，更旬而始规，二旬而叶成。初生嫩 \n炸熟，水淘过食，亦可作饮代茶。或采槐子种畦中，采苗食之亦良。其木材坚重，有青黄白 \n黑色。其花未开时，状如米粒，炒过煎水染黄甚鲜。其实作荚连珠，中有黑子，以子连多 \n为好。《周礼》∶秋取槐、檀之火。《淮南子》∶老槐生火。《天玄主物簿》云∶老槐生丹。槐 \n之神异如此。 \n\\x槐实\\x \n【修治】 曰∶凡采得，去单子并五子者，只取两子、三子者，以铜锤捶破，用乌牛乳 \n浸一宿，蒸过用。 \n【气味】苦，寒，无毒。 \n《别录》曰∶酸、咸。之才曰∶景天为之使。 \n【主治】五内邪气热，止涎唾，补绝伤，火疮，妇人乳瘕，子藏急痛（《本经》）。久服， \n明目益气，头不白，延年。治五痔疮 ，以七月七日取之，捣汁铜器盛之，日煎令可，丸如 \n鼠屎，纳窍中，日三易乃愈。又堕胎（《别录》）。 \n治大热难产（甄权）。杀虫去风。合房阴干煮饮，明目，除热泪，头脑心胸间热风烦闷， \n风眩欲倒，心头吐涎如醉， 如舡车上者（藏器）。治丈夫、女人阴疮湿痒。催生，吞七 \n粒 \n（大明）。疏导风热（宗 ）。 \n治口齿风，凉大肠，润肝燥（李杲）。 \n【发明】好古曰∶槐实纯阴，肝经气分药也。治证与桃仁同。 \n弘景曰∶槐子，以十月巳日采相连多者，新盆盛，合泥百日，皮烂为水，核如大豆。服 \n之令脑满，发不白而长生。 \n颂曰∶折嫩房角作汤代茗，主头风，明目补脑。水吞黑子，以变白发。扁鹊明目使发不 \n落法∶十月上巳日，取槐子去皮，纳新瓶中，封口二七日。初服一枚，再服二枚，日加一枚。 \n至十日，又从一枚起，终而复始。令人可夜读书，延年益气力，大良。 \n时珍曰∶按∶《太清草木方》云∶槐者虚星之精。十月上巳日采子服之，去百病，长 \n生通神。《梁书》 \n言∶庾肩吾常服槐实，年七十余，发鬓皆黑，目看细字，亦其验也。古方以子入冬月牛 \n胆中渍之，阴干百日，每食后吞一枚。云久服明目通神，白发还黑。有痔及下血者，尤宜服 \n之。 \n【附方】旧一，新四。 \n槐角丸∶治五种肠风泻血。粪前有血名外痔，粪后有血名内痔，大肠不收名脱肛，谷道 \n四面 肉如奶名举痔，头上有孔名 疮，内有虫名虫痔，并皆治之。槐角（去梗，炒）一两， \n地榆、当归（酒焙）、防风、黄芩、枳壳（麸炒）各半两，为末，酒糊丸梧桐子大。每服五 \n十丸，米饮下。（《和剂局方》）。 \n大肠脱肛∶槐角、槐花各等分，炒为末。用羊血蘸药，炙熟食之，以酒送下。猪腰子（去 \n皮）蘸炙亦可。（《百一选方》）内痔外痔∶许仁则方∶用槐角子一斗，捣汁晒稠，取地胆为 \n末，同煎，丸梧桐子大。每饮服十丸。兼作挺子，纳下部。或以苦参末代地胆亦可。（《外 \n台秘要》） \n目热昏暗∶槐子、黄连（去须）各二两，为末，蜜丸梧桐子大。每浆水下二十丸，日二 \n服。（《圣济总录》）。 \n\\x槐花\\x \n【修治】宗 曰∶未开时采收，陈久者良，入药炒用。染家以水煮一沸出之，其稠滓为 \n饼，染色更鲜也。 \n【气味】苦，平，无毒。 \n元素曰∶味浓气薄，纯阴也。 \n【主治】五痔，心痛眼赤，杀腹脏虫，及皮肤风热，肠风泻血，赤白痢，并炒研服（大 \n明 \n凉大肠（元素）。炒香频嚼，治失音及喉痹，又疗吐血衄血，崩中漏下 \n【发明】时珍曰∶槐花味苦、色黄、气凉，阳明、厥阴血分药也。故所主之病，多属二 \n经。 \n【附方】旧一，新二十。 \n衄血不止∶槐花、乌贼鱼骨等分，半生半炒为末，吹之。（《普济方》）舌衄出血∶槐花 \n末，敷之即止。（《朱氏集验》）。 \n吐血不止∶槐花烧存性，入麝香少许，研匀，糯米饮下三钱。（《普济方》）。 \n咯血唾血∶槐花炒研。每服三钱，糯米饮下，仰卧一时取效。（朱氏 \n小便尿血∶槐花（炒）、郁金（煨）各一两，为末。每服二钱，淡豉汤下，立效。（《箧 \n中秘宝方》）。 \n大肠下血∶《经验方》∶用槐花、荆芥穗等分，为末。酒服一钱匕。《集简方》∶用柏叶三 \n钱，槐花六钱，煎汤日服 \n暴热下血∶生猪脏一条，洗净控干，以炒槐花末填满扎定，米醋沙锅内煮烂，擂丸弹子 \n大，晒干。每服一丸，空心 \n酒毒下血∶槐花（半生半炒）一两，山栀子（焙）五钱，为末。 \n新汲水服二服。（《经验良方》） \n脏毒下血∶新槐花炒研，酒服三钱，日三服。或用槐白皮煎汤服。（《普济方》）。 \n妇人漏血不止∶槐花烧存性，研。每服二、三钱，食前温酒下。（《圣惠方》）。 \n血崩不止∶槐花三两，黄芩二两，为末。每服半两，酒一碗，铜秤锤一枚，桑柴火烧红， \n浸入酒内，调服。忌口。（ \n中风失音∶炒槐花，三更后仰卧嚼咽。（危氏《得效方》）。 \n痈疽发背∶凡人中热毒，眼花头晕，口干舌苦，心惊背热，四肢麻木，觉有红晕在背后 \n者。即取槐花子一大抄，铁杓炒褐色，以好酒一碗汗之。乘热饮酒，一汗即愈。如未退，再 \n炒一服，极效。纵成脓者，亦无不愈。彭幸庵云∶此方三十年屡效者。（刘松石《保寿堂方》） \n杨梅毒疮∶乃阳明积热所生。槐花四两略炒，入酒二盏，煎十余沸，热服。胃虚寒者勿用。 \n（《集简方》） \n外痔长寸∶ \n疔疮肿毒∶一切痈疽发背，不问已成未成，但 痛者皆治。槐花（微炒）、核桃仁二两， \n无灰酒一钟，煎十余沸，热服。未成者二、三服，已成者一、二服见效。（《医方摘要》）发 \n背散血∶槐花、绿豆粉各一升，同炒作象牙色，研末。用细茶一两，煎一碗，露一夜，调末 \n三钱敷之，留头。勿犯妇女手。（《摄生众妙方》） \n下血血崩∶槐花一两，棕灰五钱，盐一钱，水三钟，煎减半服。（《摘玄方》） \n白带不止∶槐花（炒）、牡蛎（ ）等分。为末。每酒服三钱，取效。（同上） \n\\x叶\\x \n【气味】苦，平，无毒。 \n【主治】煎汤，治小儿惊痫壮热，疥癣及疔肿。 \n皮、茎同用（大明）。邪气产难绝伤，及瘾疹牙齿诸风，采嫩叶食（孟 \n【附方】旧二，新一。 \n霍乱烦闷∶槐叶、桑叶各一钱，炙甘草三分，水煎服之。（《圣惠方》）。 \n肠风痔疾∶用槐叶一斤，蒸熟晒干研末，煎饮代茶。久服明目。（《食医心镜》）。 \n鼻气窒塞∶以水五升煮槐叶，取三升，下葱、豉调和再煎，饮。（《千金方》）。 \n\\x枝\\x \n【气味】同叶。 \n【主治】洗疮及阴囊下湿痒。八月断大枝，候生嫩 ，煮汁酿酒，疗大风痿痹甚效（《别 \n录》）。炮热，熨蝎毒（恭）。 \n青枝烧沥，涂癣。 黑，揩牙去虫。煎汤，洗痔核（颂）。烧灰，沐头长发（藏器）。治 \n赤目、崩漏（时珍）。 \n【发明】颂曰∶刘禹锡《传信方》着硖州王及郎中槐汤灸痔法甚详。以槐枝浓煎汤先洗 \n痔，便以艾灸其上七壮，以知为度。 \n王及素有痔疾，充西川安抚使判官，乘骡入骆谷，其痔大作，状如胡瓜，热气如火，至 \n驿僵仆。邮吏用此法灸至三、五壮，忽觉热气一道入肠中，因大转泻，先血后秽，其痛甚楚。 \n泻后 \n【附方】旧五，新一。 \n风热牙痛∶槐枝烧热烙之。（《圣惠方》）。 \n胎赤风眼∶槐木枝如马鞭大，长二尺，作二段齐头。麻油一匙，置铜钵中。晨使童子一 \n人，以其木研之，至暝乃止。令仰卧，以涂目，日三度瘥。 \n九种心痛∶当太岁上取新生槐枝一握，去两头，用水三大升，煎取一升，顿服。（《千 \n金》）。 \n崩中赤白，不问远近∶取槐枝烧灰，食前酒下方寸匕，日二服。（《梅师方》）。 \n胎动欲产，日月未足者∶取槐树东引枝，令孕妇手把之，即易生。（《子母秘录》）。 \n阴疮湿痒∶槐树北面不见日枝，煎水洗三、五遍。冷再暖之。（孟诜《必效方》）。 \n\\x木皮、根白皮\\x \n【气味】苦，平，无毒。 \n【主治】烂疮，喉痹寒热（《别录》）。煮汁，淋阴囊坠肿气痛。煮浆水，漱口齿风疳 \n血（甄权）。治中风皮肤不 \n汤火疮。煎膏，止痛长肉，消痈肿（大明）。 \n【附方】旧四，新二。 \n中风身直，不得屈伸反复者∶取槐皮黄白者切之，以酒或水六升，煮取二升，稍稍服之。 \n（《肘后方》） \n破伤中风∶避阴槐枝上皮，旋刻一片，安伤处，用艾灸皮上百壮。不痛者灸至痛，痛者 \n灸至不痛，用手摩之。（《普济》）风虫牙痛∶槐树白皮一握切，以酪一升煮，去滓，入盐少 \n许，含漱。（《广济方》） \n下脓血∶多取槐白皮浓煮汁，先熏后洗。良久欲大便，当有虫出，不过三度即愈。仍以皮为 \n末，绵裹纳下部中。（《梅师方》）。 \n\\x槐胶\\x \n【气味】苦，寒，无毒。 \n【主治】一切风，化涎，肝脏风，筋脉抽掣，及急风口噤，或四肢不收顽痹，或毒风周 \n身如虫行，或破伤风，口眼偏斜，腰脊强硬。任作汤、散、丸、煎，杂诸药用之。亦可水煮 \n和药为丸（《嘉 》）。煨热，绵裹塞 \n\\x槐耳\\x \n见菜部木耳。 \n\n\n\n<目录>木部第三十五卷\\木之二\n\n<篇名>檀\n\n内容：（《拾遗》） \n【释名】时珍曰∶朱子云∶檀，善木也。其字从 以此。 者善也。 \n【集解】藏器曰∶按∶苏恭言∶檀似秦皮。其叶堪为饮。树体细，堪作斧柯。至夏有不 \n生者，忽然叶开，当有大水。农人候之以占水旱，号为水檀。又有一种叶如檀，高五、六尺， \n生 \n但不香尔。 \n榆、荚 相似。故俚语云∶斫檀不谛得荚 ，荚 尚可得驳马 \n皮色青白，多癣驳也。檀木宜杵、 、锤器之用 \n\\x皮及根皮\\x \n【气味】辛，平，有小毒。 \n【主治】皮和榆皮为粉食，可断谷救荒。根皮∶涂疮疥，杀虫（藏器）。 \n\n\n\n<目录>木部第三十五卷\\木之二\n\n<篇名>荚\n\n内容：（《唐本草》） \n【释名】系迷（《诗疏》）、羿先（同 \n【集解】恭曰∶荚 叶似木槿及榆，作小树，其子如溲疏，两两相并，四四相对，而色 \n赤味甘。陆机《诗疏》云∶檀、榆之类也。所在山谷有之。藏器曰∶生北土山林中。皮堪为 \n索。 \n\\x枝叶\\x \n【气味】甘、苦，平、无毒。 \n【主治】三虫，下气消谷。煮汁和米作粥，饲小儿甚美（《唐本》）。作粥，灌六畜疮中 \n生蛆，立出（藏器）。 \n\n\n\n<目录>木部第三十五卷\\木之二\n\n<篇名>秦皮\n\n内容：（《本经》中品） \n【校正】并入（《拾遗》 \n【释名】 皮（音岑）、 木（音寻）、石檀（《别录》）、樊 （弘景）、盆桂（《日华》）、 \n苦树（苏恭）、苦枥。时珍曰∶秦皮本作 皮。其木小而岑高，故以为名。人讹为 木，又 \n讹为秦。或云本出秦地，故得秦名也。高诱注《淮南子》云∶ ，苦枥木也。恭曰∶树叶似 \n檀，故名石檀。俗因味苦，呼为苦树。 \n【集解】《别录》曰∶秦皮生庐江川谷及冤句水边。二月、八月采 \n弘景曰∶俗云是樊 皮，而水渍以和墨书，色 \n恭曰∶此树似檀，叶细，皮有白点而不粗错，取皮渍水便碧色，书纸看之皆青色者，是 \n真。 \n颂曰∶今陕西州郡及河阳亦有之。其木大都似檀，枝干皆青绿色。叶如匙头许大而不 \n光。并无花实，根似槐根。俗呼为白 木。 \n\\x皮\\x \n【气味】苦，微寒，无毒。《别录》曰∶大寒。 \n普曰∶神农、雷公、黄帝、岐伯∶酸，无毒；李当之∶小寒。 \n权曰∶平。恶苦瓠、防葵。 \n之才曰∶恶吴茱萸。大戟为之使。 \n【主治】风寒湿痹洗洗寒气，除热，目中青翳白膜。久服，头不白，轻身（《本经》）。 \n疗男子少精，妇人带下，小儿痫，身热。可作洗目汤。久服，皮肤光泽，肥大有子（《 \n别录》）。明目，去目中久热，两目赤肿疼痛，风泪不止。作汤，浴小儿身热。煎水澄清， \n洗赤目极效 \n【发明】弘景曰∶秦皮俗方惟以疗目，道家亦有用处。大明曰∶秦皮之功，洗肝益精， \n明目退热。元素曰∶秦皮沉也，阴也。其用有四∶治风寒湿邪成痹，青白幻翳遮睛，女子崩 \n中带下，小儿风热惊痫。好古曰∶痢则下焦虚，故张仲景白头翁汤，以黄柏、黄连、秦皮同 \n用，皆苦以坚之也。秦皮浸水青蓝色，与紫草同用，治目病以增光晕，尤佳。时珍曰∶ 皮， \n色青气寒，味苦性涩，乃是厥阴肝、少阳胆经药也。故治目病、惊痫，取其平木也。治下痢、 \n崩带，取其收涩也。又能治男子少精，益精有子，皆取其涩而补也。故《老子》云∶天道贵 \n涩。此药乃服食及惊痫崩痢 \n云∶ 皮 \n水，言能使水沸者，谬也。 \n【附方】旧三，新三。 \n赤眼生翳∶秦皮一两，水一升半，煮七合，澄清。日日温洗。一方加滑石、黄连等分。 \n（《外台秘要》） \n眼暴肿痛∶秦皮、黄连各一两，苦竹叶半升，水二升半，煮取八合，食后温服。此乃谢 \n道人方也。（《外台秘要》）。 \n赤眼睛疮∶秦皮一两。清水一升，白碗中浸，春夏一食顷以上，看碧色出，即以箸头缠 \n绵，仰卧点令满眼，微痛勿畏，良久沥去热汁。日点十度以上，不过两日瘥也。（《外台秘 \n要》） \n眼弦挑针∶乃肝脾积热。锉秦皮，夹沙糖，水煎，调大黄末一钱，微利佳。（《仁斋直 \n指方》） \n血痢连年∶秦皮、鼠尾草、蔷薇根等分，以水煎取汁，铜器重釜煎成，丸如梧桐子大。 \n每服五、六丸，日二服。稍增，以知为度。亦可煎饮。 \n天蛇毒疮，似癞非癞∶天蛇，乃草间黄花蜘蛛也。人被其螫，为露水所濡，乃成此疾。 \n以秦皮煮汁一斗，饮之即瘥。（沈存中） \n\n\n\n<目录>木部第三十五卷\\木之二\n\n<篇名>合欢\n\n内容：（《本经》中品） \n【释名】合昏（《唐本》）、夜合（《日华》）、 \n树。 \n颂曰∶崔豹《古今注》云∶欲蠲人之忿，则赠以青裳。青裳，合欢也。植之庭除，使人 \n不忿。故嵇康《养生论》云∶合欢蠲忿，萱草忘忧。 \n藏器曰∶其叶至暮即合，故云合昏。 \n时珍曰∶按∶王 《百一选方》云∶夜合俗名萌葛，越人谓之乌赖 \n谓之尸利洒树。 \n【集解】《本经》曰∶合欢生豫州河内山谷。树如狗骨树。 \n《别录》曰∶生益州山谷。 \n弘景曰∶俗间少识，当以其非疗病之功也。 \n恭曰∶此树叶似皂荚及槐，极细。五月花发，红白色，上有丝茸。秋实作荚，子极薄细 \n。所在山谷有之，今东西京第宅山池间亦有种者，名曰合昏。 \n颂曰∶今汴洛间皆有之，人家多植于庭除间。木似梧桐，枝甚柔弱。叶似皂角，极细而 \n繁密，互相交结。每一风来，辄自相解了，不相牵缀。采皮及叶用，不拘时月。 \n宗 曰∶合欢花，其色如今之醮晕线，上半白，下半肉红，散垂如丝，为花之异。其绿 \n叶至夜则合也。嫩时炸熟水淘，亦可食。 \n\\x木皮\\x（去粗皮炒用） \n【气味】甘，平，无毒。 \n【主治】安五脏，和心志，令人欢乐无忧。久服，轻身明目，得所欲（《本经》）。煎膏， \n消痈肿，续筋骨（大明）。杀虫。捣末，和铛下墨，生油调，涂蜘蛛咬疮 \n器）折伤疼痛，花研末，酒服二钱匕（宗 ）。 \n【发明】震亨曰∶合欢属土，补阴之功甚捷。长肌肉，续筋骨，概可见矣。与白蜡同入 \n膏用神效，而外科家未曾录用何也？ \n【附方】旧二，新三。 \n肺痈唾浊，心胸甲错∶取夜合皮一掌大，水三升，煮取一半，分二服。（韦宙《独行方》）。 \n扑损折骨∶夜合树皮（即合欢皮，去粗皮，炒黑色）四两，芥菜子（炒）一两，为末。每服 \n二钱，温酒卧时服，以滓敷之，接骨甚妙。（王 《百一选方》）发落不生∶合欢木灰二合， \n墙衣五合，铁精一合，水萍末二合，研匀，生油调涂，一夜一次。（《普济方》）。小儿撮口∶ \n夜合花枝浓煮汁，拭口中，并洗之。（《子母秘录》） \n槐枝、桑枝、石榴枝各五两（并生锉）。糯米五升，黑豆五升，羌活二两， \n七 \n斤半。先以水五斗煎五枝，取二斗五升，浸米、豆蒸熟，入曲与防风、羌活如常酿酒法，封 \n三七日，压汁。每饮五合，勿过醉致吐，常令有酒气也。（《奇效良 \n\n\n\n<目录>木部第三十五卷\\木之二\n\n<篇名>皂荚\n\n内容：（《本经》下品） \n【释名】皂角（《纲目》）、鸡栖子（《纲目》） \n时珍曰∶荚之树皂，故名。《广志》谓之鸡栖子，曾氏方谓之乌犀，《外丹本草》谓 \n之悬刀。 \n【集解】《别录》曰∶皂荚生雍州山谷及鲁。邹县，如猪牙者良。 \n九月、十月采荚，阴干。 \n弘景曰∶处处有之，长尺二者良。俗人见其有虫孔而未尝见虫形，皆言不可近，令人恶 \n病，殊不尔也。其虫状如草叶上青虫，荚微黑便出，所以难见。 \n恭曰∶此物有三种∶猪牙皂荚最下，其形曲戾薄恶，全无滋润，洗垢不去；其尺二者， \n粗大长虚而无润；若长六、七寸，圆浓节促直者，皮薄多肉，味浓大好。 \n颂曰∶所在有之，以怀、孟州者为胜。木极有高硕者。《本经》用如猪牙者，陶用尺二 \n者 \n虽殊 \n长而尖。枝间多刺。夏开细黄花。结实有三种∶一种 \n一种长而瘦薄，枯燥不粘。以多脂者为佳。其树多刺难上，采时以蔑箍其树，一夜自落，亦 \n一异也。有不结实者，树凿一孔，入生铁三、五斤，泥封之，即结荚。人以铁砧捶皂荚，即 \n自损。铁碾碾之，久则成孔。铁锅爨之，多爆片落。岂皂荚与铁有感召之情耶？ \n\\x皂荚\\x \n【修治】 曰∶凡使，要赤肥并不蛀者，以新汲水浸一宿，用铜刀削去粗皮，以酥反复 \n炙透，捶去子、弦用。每荚一两，用酥五钱。 \n好古曰∶凡用有蜜炙、酥炙、绞汁、烧灰之异，各依方法。 \n【气味】辛、咸，温，有小毒。 \n好古曰∶入厥阴经气分。 \n时珍曰∶入手太阴、阳明经气分。 \n之才曰∶柏实为之使。恶麦门冬，畏空青、人参、苦参。 \n机曰∶伏丹砂、粉霜、硫黄、 砂。 \n【主治】风痹死肌邪气，风头泪出，利九窍，杀精物（《本经 \n疗腹胀满，消谷，除咳嗽囊结，妇人胞不落，明目益精。可为沐药，不入汤（《别录》）。 \n通关节，除头风，消痰杀虫，治骨蒸，开胃，中风口噤（大明）。破坚症，腹中痛，能堕 \n胎。又将浸酒中，取尽其精，煎成膏涂帛，贴一切肿痛（甄权）。溽暑久雨时，合苍术烧烟， \n辟瘟疫邪湿气 \n气，治咽喉痹塞，痰气喘咳，风疠疥癣（时珍）。 \n【发明】好古曰∶皂荚厥阴之药。《活人书》治阴毒正阳散内用皂荚，引入厥阴也。 \n时珍曰∶皂荚属金，入手太阴、阳明之经。金胜木，燥胜风，故兼入足厥阴，治风木之 \n病。其味辛而性燥，气浮而散。吹之导之，则通上下诸窍；服之则治风湿痰喘肿满，杀虫； \n涂之则散肿消毒，搜风治疮。按∶庞安时《伤寒总病论》云∶元 五年，自春至秋，蕲、黄 \n二郡人患急喉痹，十死八、九，速者半日、一日而死。黄州推官潘昌言得黑龙膏方，救活数 \n人也。其方 \n入口。用大皂荚四十挺切，水三斗，浸一夜，煎至一斗半。入人参末半两，甘草末一两，煎 \n至五升，去滓。入无灰酒一升，釜煤二匕，煎如饧，入瓶封，埋地中一夜。每温酒化下一匙， \n或扫入喉内，取恶涎尽为度。后含甘草片。又孙用和《家传秘宝方》云∶凡人猝中风，昏昏 \n如醉，形体不收，或倒或不倒，或口角流涎出，斯须不治，便成大病。此症风涎潮于上，胸 \n痹气不通，宜用急救稀涎散吐之。用大皂荚（肥实不蛀者）四挺（去黑皮），白矾（光明者） \n一两， \n为末。每用半钱，重者三字，温水调灌。不大呕吐，只是微微稀冷涎或出一升、二升。当待 \n惺惺，乃用药调治。不 \n两，生矾末半两，腻粉半两，水调一、二钱，过咽即吐涎。用 \n【附方】旧二十，新三十七。 \n中风口噤不开，涎潮壅上∶皂角一挺（去皮），猪脂涂炙黄色，为末。每服一钱，温酒 \n调下 \n中风口 ∶皂角五两，去皮为末，三年大醋和之，左 涂右，右 涂左，干更上之。（《 \n外台秘要》）。 \n中暑不省∶皂荚一两（烧存性），甘草一两（微炒），为末。温水调一钱，灌之。（《澹寮 \n方》） \n鬼魇不寤∶皂荚末刀圭，吹鼻中，能起死人。（《千金方》） \n自缢将绝∶皂角末吹鼻中。（《外台方》）。 \n水溺卒死一宿者，尚可活∶纸裹皂荚末纳下部，须臾出水即活。（《外台秘要》）。 \n急喉痹塞，逡巡不救∶灵苑方∶皂荚生研末。每以少许点患处，外以醋调浓封项下。须 \n臾便破，出血即愈。或 水灌之，亦良。《直指方》∶用 \n米醋半盏，煎七分，破出脓血即愈。 \n咽喉肿痛∶牙皂一挺（去皮，米醋浸炙七次，勿令太焦），为末。每吹少许入咽，吐涎 \n即止。（《圣济总录》） \n风痫诸痰∶五痫膏∶治诸风，取痰如神。大皂角半斤去皮、子，以蜜四两涂上，慢火炙 \n透捶碎，以热水浸一时， 取汁，慢火熬成膏。入麝香少许，摊在夹绵纸上，晒干，煎作纸 \n花。每用三、四片，入淡浆水一小盏中洗淋下，以筒吹汁入鼻内。待痰涎流尽，吃芝麻饼一 \n个，涎尽即愈，立效。（《普济方》） \n风邪痫疾∶皂荚（烧存性）四两，苍耳根、茎、叶（晒干）四两，密陀僧一两，为末， \n成丸 \n梧桐子大，朱砂为衣。每服三、四十丸，枣汤下，日二服。稍退，只服二十丸。名抵住丸。 \n（《永类方》）。 \n服 \n五、七十丸，白汤下。（《简便方》）。 \n取汁，慢熬至可丸，丸如 \n以皂角膏和匀，入明矾少许，以柿饼捣膏，丸如弹子，噙之。（《圣 \n不得卧∶皂荚丸∶用皂荚炙，去皮、子，研末，蜜丸梧桐子大。每服一丸，枣膏汤下，日三、 \n夜一服。（张仲景方） \n粒， \n一荚入杏仁十粒。用姜汁制杏仁，麻油制巴豆，蜜制半夏，一处火炙黄色为 \n手心，临卧以姜汁调之，吃下神效。（余居士《选奇方》） \n（《千金方》）。 \n丸，取微利为度。不利更服，一日一服。（《必效方》） \n黄为末。酒一斗，石器煮沸，服一升，日三服。（《肘后方》） \n烧研，粥饮下三钱，立通。《宣明方》铁脚丸∶用皂荚炙，去皮、子，为末，酒面糊丸。每 \n服五十丸，酒下。《圣惠方》∶用皂荚烧烟于桶内，坐上熏之，即通。 \n用不蛀皂角（去皮、子，醋涂炙焦为末）一钱，巴豆七枚（去油、膜）。以淡醋研好墨和， \n丸麻子大。每服三丸，食后陈橘皮汤下，日三服。隔一日增一丸，以愈为度。（《经验方》）。 \n胸腹胀满，欲令瘦者∶猪牙皂角相续量长一尺，微火煨，去皮、子，捣筛，蜜丸大如梧 \n桐子。 \n服时先吃羊肉两脔，汁三、 \n水即止药，瘥后一月，不得食肉及诸油腻。（崔元亮《海上集验方》）。 \n荚去皮炙黄，锉三升，酒一斗，渍透煮沸。每服一升，一日三服。（《肘后方》）。 \n皂荚续成一尺以上，酥一大两微涂缓炙，酥尽捣筛，蜜丸梧桐子大。每日空腹饮下十五丸， \n渐增至二十丸。重者不过两剂愈。 \n皂荚树皮、皂荚刺各一斤，同烧灰，以水三斗，淋汁再淋，如此三、五度，煎之候少凝，入 \n麝香末一分，以童子小便浸蒸饼，丸小豆大。每空心温水下七丸。（《圣惠方》）。 \n皂角、赤小豆为末，酒、醋调，贴肿处。（《永类方》）。 \n（肥者），烧赤为末。以水五合和，顿服之。阴病极效。（《千金方》）。 \n皂角，烧研，新汲水一中盏，姜汁、蜜各少许，和二钱服之。先以暖水淋浴后服药，取汗即 \n愈。（《圣惠》） \n子，蜜炙捶碎，入水 取浓汁，熬成膏。 \n事亲》） \n仍加白矾少许，黄泥固济， 研。日擦之。（杨诚《经验方》）。 \n用皂荚末涂齿上，有涎吐之。《十全方》∶用猪牙皂角、食盐等分， \n大皂角二十挺，以姜汁、地黄汁蘸炙十遍，为末。日用揩牙甚妙。（《普济方》）。 \n皂角末，吹豆许入鼻，取嚏即安。（《梅师方》）。 \n酥炙三次，研末），精羊肉十两（细切捣烂）。和丸梧桐子大。每温水下二十丸。（《圣惠》） \n。 \n大肠脱肛∶不蛀皂角五挺，捶碎，水 取汁二升 \n下，令皂角气行，则不再作。仍以皂角去皮，酥炙为末，枣肉和丸，米饮下三十丸。（《圣 \n惠方 \n调敷之，良。（《梅师方》）。 \n摊 \n贴患处，频以水润之，即效。又方∶用猪牙皂角七片煨黄，去皮、弦，出火毒，为末。空心 \n温酒服五钱。（《袖珍方》）。 \n妇人吹乳∶《袖珍方》∶用猪牙皂角去皮，蜜炙为末。酒服一钱。又诗云∶妇人吹奶法如 \n何？ \n皂角烧灰蛤粉和。热酒一杯调八字，管教时刻笑呵呵。 \n入麝香少许，人粪少许，和涂。五日后根出。（《普济方》）。 \n烧黑为末，去痂敷之，不过三次即愈。（邓笔峰《卫生杂兴》）。 \n拭干。以少油麻捣烂，涂之。（《肘后方 \n方）。 \n大。每酒下五十丸。（《直指方》）。 \n珍方》）。 \n咽喉骨哽∶猪牙皂角二条切碎，生绢袋盛缝满，线缚项中，立消。（《简便方》）。 \n皂角末吹鼻取嚏。（《圣惠方》）。九里蜂毒∶皂荚钻孔，贴叮处，艾灸孔上三、五壮即安。（《救 \n急方》）。 \n\\x子\\x \n【修治】 曰∶拣取圆满坚硬不蛀者，以瓶煮熟，剥去硬皮一重，取向里白肉两片， \n去黄，以铜刀切，晒用。其黄消人肾气。 \n【气味】辛，温，无毒。 \n【主治】炒，舂去赤皮，以水浸软，煮熟，糖渍食之，疏导五脏风热壅（宗 ）。核中 \n白肉，入治肺药。核中黄心，嚼食，治膈痰吞酸（苏颂）。仁，和血润肠（李杲）。 \n治风热大肠虚秘，瘰 肿毒疮癣（时珍）。 \n【发明】机曰∶皂角核烧存性，治大便燥结。其性得湿则滑，滑则燥结自通也。 \n时珍曰∶皂荚味辛属金，能通大肠阳明燥金，乃辛以润之之义，非得湿则滑也。 \n【附方】旧三，新十一。 \n腰脚风痛不能履地∶皂角子一千二百个洗净，以少酥熬香为末，蜜丸梧子大。每空心以 \n蒺藜子、酸枣仁汤下三十丸。（《千金方》）。 \n大肠虚秘∶风人、虚人、香港脚人，大肠或秘或利。用上方服至百丸，以通为度。 \n下痢不止，诸药不效∶服此三服，宿垢去尽，即变黄色，屡验。皂角子，瓦焙为末，米 \n糊丸梧桐子大。每服四、五十丸，陈茶下。（《医方摘 \n肠风下血∶皂荚子、槐实各一两，用粘谷糠炒香，去糠为末。陈粟米饮下一钱。名神效 \n散。（《普济方》）。 \n里急后重∶不蛀皂角子（米糠炒过）、枳壳（炒）等分，为末，饭丸梧桐子大。每米饮 \n下三十丸。（《普济方》）。 \n小儿流涎，脾热有痰∶皂荚子仁半两，半夏（姜汤泡七次）一钱二分，为末，姜汁丸麻 \n子大。 \n恶水入口及皂荚水入口，热痛不止∶以皂荚子（烧存性）一分，沙糖半两，和膏，含之。 \n（《博济方》）。 \n妇人难产∶皂角子二枚，吞之。（《千金方》）。 \n风虫牙痛∶皂角子末，绵裹弹子大两颗，醋煮热，更互熨之，日三、五度。（《圣惠方 \n粉滓面 ∶皂角子、杏仁等分，研匀。夜以津和，涂之。（《圣惠方》）。 \n预免疮疖∶凡小儿每年六月六日，照年岁吞皂荚子，可免疮疖之患。大人亦可吞七枚， \n或二十一枚。林静斋所传方也。（吴 《扶寿方 \n便痈初起∶皂角子七个研末，水服效。一方∶照年岁吞之。（《儒门 \n一切疔肿∶皂角子仁作末，敷之。五日愈。（《千金方》）。 \n年久瘰 ∶阮氏《经验方》∶用不蛀皂角子一百粒，米醋一升， 砂二钱，同煮干，炒 \n令酥。看 子多少，如一个服一粒，十个服十粒，细嚼米汤下。酒浸煮服亦可。《圣济总录》 \n言∶虚人不可用 砂也。 \n\\x刺\\x（一名天丁） \n【气味】辛，温，无毒。 \n【主治】米醋熬嫩刺作煎，涂疮癣有奇效（苏颂）。治痈肿妒乳，风疠恶疮，胎衣不下， \n杀虫（时珍）。 \n【发明】杨士瀛曰∶皂荚刺能引诸药性上行，治上焦病。 \n震亨曰∶能引至痈疽溃处，甚验。 \n时珍曰∶皂荚刺治风杀虫，功与荚同，但其锐利直达病所为异耳。《神仙传》云∶左亲 \n骑军崔言∶一旦得大风恶疾，双目昏盲，眉发自落，鼻梁崩倒，势不可救。遇异人传方∶用 \n皂角刺三斤烧灰，蒸一时久，晒干为末。食后浓煎大黄汤调一匕，饮之。一旬眉发再生，肌 \n润目明。 \n后入山修道，不知所终。又刘守真《保命集》云∶疠风乃营气热，风寒客于脉而不去。 \n宜先用桦皮散服五、七日，后灸承浆穴七壮。三灸后，每旦早服桦皮散，午以升麻葛根汤下 \n钱氏泻青 \n仍戒房 \n服，直候虫尽为绝根也。新虫嘴赤，老虫嘴黑。 \n【附方】新十二。 \n小儿重舌∶皂角刺灰，入朴硝或脑子少许，漱口，掺入舌下，涎出自消。（《普济方》）。 \n小便淋闭∶皂角刺（烧存性）、破故纸等分，为末。无灰酒服。（《圣济总录》）。 \n肠风下血∶便前近肾肝，便后近心肺。皂角刺灰二两，胡桃仁、破故纸（炒）、槐花（炒） \n各一两，为末。每服一钱，米饮下。（《普济方》）。 \n伤风下痢∶风伤久不已，而下痢脓血，日数十度。用皂角刺、枳实（麸炒）、槐花（生 \n用） \n各半两，为末，炼蜜丸梧桐子大。每服三十丸，米汤下，日二服。（《袖珍方 \n胎衣不下∶皂角棘烧为末。每服一钱，温酒调下。（熊氏《补遗》）。 \n妇人乳痈∶皂角刺（烧存性）一两，蚌粉一钱，和研。每服一钱，温酒下。（《直指方》）。 \n乳汁结毒，产后乳汁不泄，结毒者。皂角刺、蔓荆子各（烧存性）等分为末。每温酒服二 \n钱。（《袖珍方》）。 \n腹内生疮∶在肠脏不可药治者。取皂角刺不拘多少，好酒一碗，煎至七分，温服。其脓 \n血悉从小便中出，极效。不饮酒者，水煎亦可。（ \n疮肿无头∶皂角刺烧灰，酒服三钱。嚼葵子三、五粒。其处如针刺为效。（《儒门事亲》）。 \n癌瘭恶疮∶皂角刺（烧存性，研），白芨少许，为末，敷之。（《直指方》）。 \n大风疠疮∶《选奇方》∶用黄柏末、皂角刺灰各三钱，研匀，空心酒服。取下虫物，并不 \n损人。食白粥两、三日，服补气药数剂。名神效散。如四肢肿，用针刺出水再服。忌一切鱼、 \n肉、发风之物。取下虫大小长短其色不一，约一、二升，其病乃愈也。（《仁存方》）。 \n发背不溃∶皂角刺（麦麸炒黄）一两，绵黄 （焙）一两，甘草半两，为末。每服一大 \n钱，酒一盏，乳香一块，煎七分，去滓温服。（《普济本事方》） \n\\x木皮、根皮\\x \n【气味】辛，温，无毒。 \n【主治】风热痰气，杀虫（时珍）。 \n【附方】新二。 \n肺风恶疮瘙痒∶用木乳（即皂荚根皮，秋冬采如罗纹者，阴干炙黄）、白蒺藜（炒）、黄 \n、人参、枳壳（炒）、甘草（炙）等分为末。沸汤每服一钱。（《普济方》）。产后肠脱 \n用皂角树皮半斤，皂角核一合，川楝树皮半斤，石莲子（炒，去心）一合，为粗末，以水煎 \n汤，乘热以物围定，坐熏洗之。挹干，便吃补气丸药一服，仰睡。（《妇人良方》） \n\\x叶\\x \n【主治】入洗风疮渫用（时珍）。 \n【附录】鬼皂荚 藏器曰∶生江南泽畔。状如皂荚，高一、二尺。作汤浴，去风疮疥癣。 \n叶，去衣垢，沐发令长 \n\n\n\n<目录>木部第三十五卷\\木之二\n\n<篇名>肥皂荚\n\n内容：（《纲目》） \n【集解】时珍曰∶肥皂荚生高山中。其树高硕，叶如檀及皂荚叶。五、六月开白花，结 \n荚长三、四寸，状如云实之荚，而肥浓多肉。内有黑子数颗，大如指头，不正圆，其色如漆 \n而甚坚。中有白仁如栗，煨熟可食。亦可种之。十月采荚煮熟，捣烂和白面及诸香作丸，澡 \n身面，去垢而腻润，胜于皂荚也。《相感志》言∶肥皂荚水，死金鱼，辟马蚁， 见之则不 \n就。亦物性然耳。 \n\\x荚\\x \n【气味】辛，温，微毒。 \n【主治】去风湿下痢便血，疮癣肿毒（时珍）。 \n【附方】新九。 \n肠风下血∶独子肥皂（烧存性），一片为末，糕糊丸；一片为末，米饮调，吞下。（《普 \n济方》） \n下痢禁口∶肥皂荚一枚，以盐实其内，烧存性，为末。以少许入白米粥内，食之即效。 \n（《乾坤生意》）。 \n风虚牙肿∶老人肾虚，或因凉药擦牙致痛。用独子肥皂，以青盐实之，烧存性，研末 \n掺之。或入生樟脑十五文。（《卫生家宝方》）。 \n头耳诸疮，眉癣、燕窝疮∶并用肥皂（ 存性）一钱，枯矾一分。研匀，香油调，涂之。 \n（《摘玄方》）。 \n小儿头疮∶因伤汤水成脓，出水不止。用肥皂烧存性，入腻粉，麻油调搽。（《海上方》）。 \n腊梨头疮，不拘大人、小儿∶用独核肥皂（去核，填入沙糖，入巴豆二枚扎定，盐泥包， \n存性），入槟榔、轻粉五、七分，研匀，香油调搽。先以灰汁洗过，温水再洗，拭干乃搽。 \n一宿见效，不须再洗。（《普济方》）。 \n癣疮不愈∶以川槿皮煎汤，用肥皂（去核及内膜）浸汤时时搽之。（杨起《简便方》）。 \n便毒初起∶肥皂捣烂敷之，甚效。（《简便方》）。 \n玉茎湿痒∶肥皂一个。烧存性，香油调搽即愈。（《摄生方》） \n\\x核\\x \n【气味】甘，腥，温，无毒。 \n【主治】除风气（时珍）。 \n\n\n\n<目录>木部第三十五卷\\木之二\n\n<篇名>无患子\n\n内容：（宋《开宝》） \n【释名】桓（《拾遗》）、木患子（《纲目》）、 \n珠子 \n藏器曰∶桓、患字，声讹也。崔豹《古今注》云∶昔有神巫曰瑶KT 能符劾百鬼，得 \n鬼则以此 \n也。 \n，与薏苡同名。《纂文》言其木名卢鬼木。山人呼为肥珠子、油珠子，因其实如肥油而子圆 \n如珠也。 \n【集解】藏器曰∶无患子，高山大树也。子黑如漆珠。《博物志》云∶桓叶似榉柳叶。 \n核坚正黑如 ，可作香缨及浣垢。 \n宗 曰∶今释子取为念珠，以紫红色、小者佳。入药亦少。西洛亦有之。 \n时珍曰∶生高山中。树甚高硕，枝叶皆如椿，特其叶对生。五、六月开白花。结实大如 \n弹丸，状如银杏及苦楝子，生青熟黄，老则纹皱。黄时肥如油炸之形，味辛气 \n下有二小子，相粘承之。实中一核，坚黑似肥皂荚之核，而正圆如珠。壳中有仁如榛子仁， \n亦辛 ，可 \n甚妙。《山海经》云∶秩 \n中饮之，辟恶气，浣衣去垢，核坚正黑。即此也。今武当山中所出鬼见愁，亦是树荚之子， \n其形正如刀豆子而色褐，彼人亦以穿数珠。别又是一物，非无患也。 \n\\x子皮\\x（即核外肉也） \n【气味】微苦，平，有小毒。 \n【主治】浣垢，去面 。喉痹，研纳喉中，立开。又主飞尸（藏器）。 \n【附方】新二。 \n洗头去风明目。用 子皮、皂角、胡饼、菖蒲同捶碎，浆水调作弹子大。每用泡汤洗头 \n良。（《多能鄙事》） \n洗面去 ∶ 子肉皮，捣烂，入白面和，丸大丸。每日用洗面，去垢及 甚良。（《集 \n简方》）。 \n\\x子中仁\\x \n【气味】辛，平，无毒。 \n【主治】烧之，辟邪恶气（藏器）。 \n煨食，辟恶，去口臭（时珍）。 \n【附方】新一。 \n牙齿肿痛∶肥珠子一两，大黄、香附各一两，青盐半两，泥固 研。日用擦牙。（《普 \n济方》） \n\n\n\n<目录>木部第三十五卷\\木之二\n\n<篇名>栾华\n\n内容：（《本经》下品） \n【集解】《别录》曰∶栾华生汉中川谷。五月采。 \n恭曰∶此树叶似木槿而薄细。花黄似槐而稍长大。子壳似酸浆，其中有实如熟豌豆，圆 \n黑坚硬，堪为数珠者，是也。五月、六月花可收，南人以染黄甚鲜明，又以疗目赤烂。 \n今南方及汴中园圃间，或有之。 \n珠，未见入药。 \n\\x华\\x \n【气味】苦，寒，无毒。 \n之才曰∶决明为之使。 \n【主治】目痛泪出伤 ，消目肿（《本经》）。合黄 \n\n\n\n<目录>木部第三十五卷\\木之二\n\n<篇名>无食子\n\n内容：（《唐本草》） \n【释名】没石子（《开宝》）、墨石子（《炮炙 \n曰∶波斯人，每食以代果，故番胡呼为没食子。梵书无与没同音。今人呼为墨石、没 \n石，转传讹矣。 \n【集解】恭曰∶无食子生西戎沙碛间。树似柽。 \n禹锡曰∶按∶段成式《酉阳杂俎》云∶无食子出波斯国，呼为摩泽树。高六、七丈，围 \n八、九尺。叶似桃叶而长。三月开花白色，心微红。子圆如弹丸，初青，熟乃黄白。虫蚀成 \n孔者入药用。其树一年生无食子。一年生拔屡子，大如指，长三寸，上有壳，中仁如栗黄可 \n啖。 \n年则生麻荼泽，即没石子也。间岁互生，一根异产如此。《一统志》云∶没石子出大食诸地。 \n树如 \n\\x子\\x \n【修治】 曰∶凡使，勿犯铜铁，并被火惊。用颗小、无 米者妙。用浆水于砂盆中研 \n令尽，焙干再研，如乌犀色入药。 \n【气味】苦，温，无毒。 \n【主治】赤白痢，肠滑，生肌肉（《唐本》）。肠虚冷痢，益血生精，和气安神，乌髭发， \n治阴毒痿，烧灰用（李 ）。 \n温中，治阴疮阴汗，小儿疳 ，冷滑不禁（马志）。 \n【发明】宗 曰∶没石子，合他药染须，造墨家亦用之。 \n曰∶张仲景用治阴汗，烧灰，先以汤浴了，布裹灰扑之，甚良。 \n【附方】旧三，新五。 \n血痢不止∶没石子一两为末，饮丸小豆大。每食前米饮下五十丸。（《普济方》）。 \n小儿久痢∶没石子二个，熬黄研末，作馄饨食之。（《宫气方》）。 \n产后下痢∶没石子一个，烧存性，研末。冷即酒服，热即用饮下，日二。（《子母秘录》）。 \n牙齿疼痛∶绵裹无食子末一钱咬之，涎出吐去。（《圣济总录》）。 \n鼻面酒 ∶南方没石子有孔者，水磨成膏。夜夜涂之，甚妙。（危氏《得效方》）。 \n口鼻急疳∶没石子末，吹下部，即瘥。（《千金方》）。 \n大小口疮∶没石子（炮）三分，甘草一分。研末掺之。月内小儿生者，少许置乳上吮之， \n入口即啼，不过三次。（《圣 \n足趾肉刺∶无食子三枚，肥皂荚一挺。烧存性，为末。醋和敷之，立效。（《奇效方》） \n\n\n\n<目录>木部第三十五卷\\木之二\n\n<篇名>诃黎勒\n\n内容：（《唐本草》） \n【释名】诃子。 \n时珍曰∶诃黎勒，梵言天主持来也。 \n【集解】恭曰∶诃黎勒生交州、爱州。 \n颂曰∶今岭南皆有而广州最盛。树似木患子，花白。子形似栀子、橄榄，青黄色，皮肉 \n相着。七月、八月实熟时采，六路者佳。《岭南异物志》云∶ \n极小而味不涩，皆是六路。每岁州贡，只以此寺者。寺有古井，木根蘸水，水味不咸。每子 \n熟时，有佳客至，则院僧煎汤以延之。其法用新摘诃子五枚，甘草一寸，破之，汲井水同煎， \n色若新茶。今其寺谓之干明古寺，尚在，旧木犹有六、七株。南海风俗 \n必尽如昔时之法也。诃子未熟时，风飘堕者，谓之随风子，曝干收之，益小者佳，彼人尤珍 \n贵之。 \n个个毗头也。若诃黎勒文只有六路。或多或少，并是杂路勒 \n路，号曰榔精勒，涩不堪用。 \n【修治】 曰∶凡用诃黎勒，酒浸后蒸一伏时，刀削去路，取肉锉焙用。用核则去肉。 \n【气味】苦，温，无毒。权曰∶苦、甘。 \n炳曰∶苦、酸。 曰∶酸，涩，温。 \n好古曰∶苦、酸，平。苦重酸轻，味浓，阴也，降也。 \n【主治】冷气，心腹胀满，下食（《唐本》）。 \n破胸膈结气，通利津液，止水道，黑髭发（甄权）。 \n下宿物，止肠 久泄，赤白痢（萧炳）。消痰下气，化食开胃，除烦治水，调中，止呕 \n吐霍乱，心腹虚痛，奔豚肾气，肺气喘急，五膈气，肠风泻血，崩中带下，怀孕漏胎，及胎 \n动欲生，胀闷气喘。并患痢人肛门急痛，产妇阴痛，和蜡烧烟熏之，及煎汤熏洗（大明）。 \n治痰嗽咽喉不利，含三数枚殊胜（苏颂）。实大肠，敛肺 \n【发明】宗 曰∶诃黎勒，气虚人亦宜缓缓煨熟少服。此物虽涩肠而又泄气，其味苦涩 \n故尔。 \n药 \n气实者 \n降火之功也。 \n时珍曰∶诃子同乌梅、五倍子用则收敛，同橘皮、浓朴用则下气，同人参用则能补肺治 \n咳嗽。 \n东垣言嗽药不用者，非矣。但咳嗽未久者，不可骤用尔。嵇含《草木状》言作饮久服， \n令髭 \n曰∶诃黎皮主嗽，肉主眼涩痛。波斯人将诃黎勒、大腹等在舶上，用防不虞。或遇大 \n鱼放涎滑水中数里，船不能通，乃煮此洗其涎滑，寻化为水，则其治气消痰功力可知矣。 \n慎微曰∶《金光明经》。流水长者子除病品云∶热病下药，服诃黎勒。又《广异记》云∶ \n高仙芝在大食国得诃黎勒，长五寸，置抹肚中，便觉腹中痛，因大利十余行，疑诃黎勒为祟。 \n后问大食长老。云∶此物人带一切病消，利者乃出恶物尔。仙芝宝之，后被诛，失所在。 \n颂曰∶诃黎主痢，《唐本草》不载。张仲景治气痢有方。唐·刘禹锡《传信方》云∶予 \n赤白下，诸药服遍久不瘥，转为白脓。令狐将军传此方∶用诃黎勒三枚，两炮一生，并 \n取皮末之，以沸浆水一合服之。若只水痢，加一钱匕甘草末；若微有脓血，加二匕；血多， \n加三匕。 \n【附方】旧十，新五。 \n下气消食∶诃黎一枚为末，瓦器中水一大升，煎三、两沸，下药更煎三、五沸，如曲尘 \n色，入少盐，饮之。（《食医心镜》）。 \n一切气疾、宿食不消∶诃黎一枚，入夜含之，至明嚼咽。又方∶诃黎三枚，湿纸包，煨 \n熟去核，细嚼，以牛乳下。（《千金方》）。 \n气嗽日久∶生诃黎一枚，含之咽汁。瘥后口爽，不知食味，却煎槟榔汤一碗服，立便有 \n味。此知连州 \n呕逆不食∶诃黎勒皮二两。炒研，糊丸梧桐子大。空心汤服二十丸，日三服。（《广济 \n方》）。 \n风痰霍乱，食不消，大便涩∶诃黎三枚，取皮为末。和酒顿服，三、五次妙。（《外台 \n秘要》）。 \n小儿霍乱∶诃黎一枚，为末。沸汤服一半，未止再服。（《子母 \n小儿风痰壅闭，语音不出，气促喘闷，手足动摇∶诃子（半生半炮，去核）、大腹皮等 \n分，水煎服。名二圣散。（《全幼心鉴》）。 \n风热冲顶、热闷∶诃黎二枚（为末），芒硝一钱。同入醋中，搅令消，摩涂热处。（《外 \n台秘要》）。 \n气痢水泻∶诃黎勒十枚面裹， 火煨熟，去核研末，粥饮顿服。亦可饭丸服。一加木香。 \n又长服方∶诃黎勒、陈橘皮、浓朴各三两，捣筛，蜜丸大如梧子。每服二、三十丸，白汤下。 \n（《图经本草》）。 \n水泻下痢∶诃黎勒（炮）二分，肉豆蔻一分，为末。米饮每服二钱。（《圣惠方》）。 \n下痢转白∶诃子三个，二炮一生，为末，沸汤调服。 \n水痢，加甘草末一钱。（《普济方》）。 \n赤白下痢∶诃子十二个，六生六煨，去核，焙为末。赤痢，生甘草汤下；白痢，炙甘草 \n汤下。不过再服。（赵原阳《济急方》）。 \n妒精下疳∶大诃子烧灰，入麝香少许，先以米泔水洗，后搽之。或以荆芥、黄柏、甘草、 \n马鞭草、葱白煎汤洗亦可。昔方士周守真医唐靖烂茎一、二寸，用此取效也。（洪迈《夷坚 \n志》） \n\\x核\\x \n【主治】磨白蜜注目，去风赤涩痛，神良（苏颂）。 \n止咳及痢（时珍）。 \n\\x叶\\x \n【主治】下气消痰，止渴及泄痢，煎饮服，功同诃黎（时珍。唐·包佶有“病中谢李吏 \n部惠诃黎勒叶”诗）。 \n\n\n\n<目录>木部第三十五卷\\木之二\n\n<篇名>婆罗得\n\n内容：（宋《开宝》） \n【释名】婆罗勒。 \n时珍曰∶婆罗得，梵言重生果也。 \n【集解】 曰∶婆罗得 \n时珍曰∶按∶王焘《外台秘要》∶婆罗勒似蓖麻子，但以指甲爪之，即有汁出。即此物 \n也。 \n\\x子\\x \n【气味】辛，温，无毒。 \n【主治】冷气块，温中，补腰肾，破 癖，可染髭发令黑（藏器）。 \n【附方】新一。 \n拔白生黑∶婆罗勒十颗（去皮，取汁），熊脂二两，白马 膏（炼过）一两，生姜（炒） \n一两，母丁香半两，二味为末，和匀。每拔白点之，揩令入肉，即生黑者。此严中丞所用方 \n也。（孟诜《近效方》） \n\n\n\n<目录>木部第三十五卷\\木之二\n\n<篇名>榉\n\n内容：（《别录》下品） \n【释名】榉柳（《衍义》）、鬼柳。 \n时珍曰∶其树高举，其木如柳，故名。山人讹为鬼柳。郭璞注《尔雅》作柜柳，云似柳， \n皮可煮饮也。 \n【集解】弘景曰∶榉树山中处处有之。皮似檀、槐，叶如栎、槲。 \n人多识之。 \n恭曰∶所在皆有，多生溪涧水侧。叶似樗而狭长。树大者连抱，高数仞，皮极粗浓，殊 \n不似檀。 \n宗 曰∶榉木，今人呼为榉柳。其叶谓柳非柳，谓槐非槐。最大者，木高五、六丈，合 \n二、三人抱。湖南北甚多，然亦不材也，不堪为器，嫩皮取以缘栲栳及箕唇。 \n时珍曰∶榉材红紫，作箱、案之类甚佳。郑樵《通志》云∶榉乃榆类而 烈，其实亦如 \n榆钱之状。乡人采其叶为甜茶。 \n\\x木皮\\x \n【修治】 曰∶凡使勿用三、四年者无力，用二十年以来 \n生者良。剥下去粗皮，细锉蒸之，从巳至未，出焙干用。 \n【气味】苦，大寒，无毒。 \n【主治】时行头痛，热结在肠胃（《别录》）。夏日煎饮，去热（弘景）。俗用煮汁服，疗 \n水气，断痢（苏恭）。安胎，止 \n【附方】旧一，新四。 \n通身水肿∶榉树皮煮汁，日饮。（《圣惠方》）。 \n毒瓦斯攻腹，手足肿痛∶榉树皮，和槲皮煮汁，煎如饴糖，以桦皮煮浓汁化饮。（《肘后 \n方》）。 \n蛊毒下血∶榉皮一尺，芦根五寸，水二升，煮一升，顿服。当下蛊出。（《千金方》）。 \n小儿痢血∶梁州榉皮二十分（炙），犀角十二分，水三升，煮取一升，分三服取瘥。（《古 \n今录验》方）。 \n飞血赤眼∶榉皮（去粗皮，切）二两，古钱七文，水一升半，煎七合，去滓热洗，日二 \n次。（《圣济总录》）。 \n\\x叶\\x \n【气味】苦，冷，无毒。 \n【主治】 贴火烂疮，有效（苏恭）。治肿烂恶疮，盐捣 之 \n\n\n\n<目录>木部第三十五卷\\木之二\n\n<篇名>柳\n\n内容：（《本经》下品） \n【释名】小杨（《说文》）、杨柳。 \n弘景曰∶柳，即今水杨柳也。 \n恭曰∶柳与水杨全不相似。水杨叶圆阔而尖，枝条短硬。柳叶狭长而青绿，枝条长软。 \n陶以柳为水杨，非也。 \n藏器曰∶江东人通名杨柳，北人都不言杨。杨树枝叶短，柳树枝叶长。 \n时珍曰∶杨枝硬而扬起，故谓之杨；柳枝弱而垂流，故谓之柳，盖一类二种也。苏恭所 \n说为是。按∶《说文》云∶杨，蒲柳也。从木， 声。柳，小杨也。从木， 声 \n音酉。又《尔雅》云∶杨，蒲柳也。旄，泽柳也。柽，河柳也 \n可称杨，故今南人犹并称杨柳。俞宗本《种树书》言∶顺插为柳，倒插为杨。其说牵强，且 \n失扬起之意。 \n【集解】《别录》曰∶柳华生琅邪川泽。 \n颂曰∶今处处有之，俗所谓杨柳者也。其类非一∶蒲柳即水杨也，枝劲韧可为箭 ，多 \n生河北。杞柳生水旁，叶粗而白，木理微赤，可为车毂。今人取其细条，火逼令柔，屈作箱 \n箧，《孟子》所谓杞柳为 \n插之皆生。春初生柔荑，即开黄蕊花。至春晚叶长成后，花中 \n绒，因风而飞。子着衣物能生虫，入池沼即化为浮萍。古者春取榆、柳之火。陶朱公言种柳 \n千树，可足柴炭。其嫩芽可作饮汤。 \n\\x柳华\\x \n【释名】柳絮（《本经》）。 \n【正误】见下。 \n【气味】苦，寒，无毒。 \n【主治】风水黄胆，面热黑（《本经》）。痂疥恶疮金疮。柳实∶主溃痈，逐脓血。 \n子汁∶疗渴（《别录》）。华∶主止血，治湿痹，四肢挛急，膝痛（甄权）。 \n【发明】弘景曰∶柳华熟时，随风状如飞雪，当用其未舒时者。子亦随花飞止，应水渍 \n汁尔。 \n藏器曰∶《本经》以柳絮为花，其误甚矣。花即初发时黄蕊，其子乃飞絮也。 \n承曰∶柳絮可以捍毡，代羊毛为茵褥，柔软性凉，宜与小儿卧尤佳。 \n宗 曰∶柳花黄蕊干时絮方出，收之贴灸疮良。絮之下连小黑子，因风而起，得水湿便 \n生，如苦 、地丁之花落结子成絮。古人以絮为花，谓花如雪者，皆误矣。藏器之说为是。 \n又有实及子汁之文，诸家不解，今人亦不见用。 \n时珍曰∶《本经》主治风水黄胆者，柳花也。《别录》主治恶疮金疮、溃痈逐脓血，《药 \n性论》止血疗痹者，柳絮及实也。花乃嫩蕊，可捣汁服。子与絮连，难以分别，惟可贴疮止 \n血裹痹之用。所谓子汁疗渴者，则连絮浸渍，研汁服之尔。又崔实《四民月令》言∶三 \n月 \n【附方】新六。 \n吐血咯血∶柳絮焙研，米饮服一钱。（《经验方》）。 \n金疮血出∶柳絮封之。即止。（《外台秘要》）。 \n面上脓疮∶柳絮、腻粉等分。以灯盏油调涂。（《普济方》）。 \n走马牙疳∶杨花，烧存性，入麝香少许，搽。（《保幼大全》）。 \n大风疠疮∶杨花（四两，捣成饼，贴壁上，待干取下，米泔水浸一时取起，瓦焙研末） \n二两，白花蛇、乌蛇各一条（去头尾，酒浸取肉），全蝎、蜈蚣、蟾酥、雄黄各五钱，苦参、 \n天麻各一两，为末，水煎麻黄取汁熬膏，和丸梧桐子大，朱砂为衣。每服五十丸，温酒下。 \n一日三服，以愈为度。（孙氏《集效良方》）。 \n\\x叶\\x \n【气味】同华。 \n【主治】恶疥痂疮马疥，煎煮洗之，立愈。又疗心腹内血，止痛（《别录》）。煎水，洗 \n漆疮（弘景）。天行热病，传尸骨蒸劳，下水气。煎膏，续筋骨，长肉止痛。主服金石人发 \n大热闷，汤火疮毒入腹热闷，及疔疮（《日华》）。疗白 \n【附方】旧一，新五。 \n小便白浊∶清明柳叶煎汤代茶，以愈为度。（《集简方》）。 \n小儿丹烦∶柳叶一斤。水一斗，煮取汁三升，拓洗赤处，日七、八度。（《子母秘录》）。 \n眉毛脱落∶垂柳叶阴干为末，每姜汁于铁器中调，夜夜摩之。（《圣惠方》）。 \n猝得恶疮不可名识者∶柳叶或皮，水煮汁，入少盐，频洗之。（《肘后方》）。 \n面上恶疮∶方同上。 \n痘烂生蛆∶嫩柳叶铺席上卧之，蛆尽出而愈也。（李楼《奇方》） \n\\x枝及根白皮\\x \n【气味】同华。 \n【主治】痰热淋疾。可为浴汤，洗风肿瘙痒。煮酒，漱齿痛（苏恭）。小儿一日、五日 \n寒热，煎枝浴之（藏器）。 \n煎服，治黄胆白浊。酒煮，熨诸痛肿，去风止痛消肿（时珍）。 \n【发明】颂曰∶柳枝、皮及根亦入药。 \n葛洪《肘后方》∶治痈疽、肿毒、妒乳等多用之。韦宙《独行方》∶主疔疮及反花疮，并 \n煎柳枝、叶作膏涂之。今人作浴汤、 \n时珍曰∶柳枝去风消肿止痛。其嫩枝削为牙杖，涤齿甚妙。 \n【附方】旧十，新十。 \n黄胆初起∶柳枝，煮浓汁半升，顿服。（《外台秘要》） \n脾胃虚弱，不思饮食，食下不化，病似翻胃噎膈∶清明日取柳枝一大把熬汤，煮小米作 \n饭，洒面滚成珠子，晒干，袋悬风处。每用烧滚水随意下米，米沉住火，少时米浮，取看无 \n硬心则熟，可顿食之。久则面散不粘矣，名曰络索米。（杨起《简便方》）。 \n走注气痛∶气痛之病，忽有一处如打扑之状，不可忍，走注不定，静时，其处冷如霜雪， \n此皆暴寒伤之也。以白酒煮杨柳白皮，暖熨之。有赤点处， 去血妙。凡诸猝肿急痛，熨之 \n皆即止。（姚增坦《集验方》）。 \n风毒猝肿∶方同上。 \n阴猝肿痛∶柳枝（三尺长）二十枚，细锉，水煮极热，以故帛裹包肿处，仍以热汤洗之。 \n（《集验方》）。 \n项下瘿气∶水涯露出柳根三十斤，水一斛，煮取五升，以糯米三斗，如常酿酒，日饮。 \n（《范汪方》）。 \n齿龈肿痛∶垂柳枝、槐白皮、桑白皮、白杨皮等分，煎水，热含冷吐。又方∶柳枝、槐 \n枝、桑枝煎水熬膏，入姜汁 \n风虫牙痛∶杨柳白皮卷如指大，含咀，以汁渍齿根，数过即愈。又方∶柳枝一握锉，入 \n少盐花，浆水煎，含甚验。又方∶柳枝（锉）一升，大豆一升，合炒，豆熟，瓷器盛之，清 \n酒三升，渍三日。频含漱涎，三日愈。（《古今录验》）。 \n耳痛有脓∶柳根，细切，熟捣封之，燥即易之。（《斗门方》）。 \n漏疮肿痛∶柳根红须，煎水日洗。《摘玄方》∶用杨柳条罐内烧烟熏之，出水即效。 \n乳痈妒乳，初起坚紫，众疗不瘥∶柳根皮熟捣火温，帛裹熨之。冷更易，一宿消。（《肘后方》）。 \n反花恶疮，肉出如饭粒，根深脓溃∶柳枝叶三斤，水五升，煎汁二升，熬如饧。日三涂 \n之。（《圣惠方》）。 \n天灶丹毒，赤从背起∶柳木灰，水调涂之。（《外台秘要》）。 \n汤火灼疮∶柳皮烧灰，涂之。亦可以根白皮煎猪脂，频敷之。（《肘后方》）。 \n痔疮如瓜，肿痛如火∶柳枝煎浓汤洗之，艾灸三、五壮。王及郎中病此，驿吏用此方灸 \n之，觉热气入肠，大下血秽至痛，一顷遂消，驰马而去。（《本事方》） \n\\x柳胶\\x \n【主治】恶疮，及结砂子（时珍）。 \n\\x柳寄生\\x \n见后寓木类。 \n\\x柳耳\\x \n见菜部木耳。 \n\\x柳蠹\\x \n见虫部。 \n\n\n\n<目录>木部第三十五卷\\木之二\n\n<篇名>柽柳\n\n内容：（音侦。宋《开宝》） \n【释名】赤柽（《日华》）、赤杨（《古今注》） \n垂丝柳《纲目》、人柳（《纲目》）、三眠柳（《衍义》）、观音柳。 \n时珍曰∶按∶罗愿《尔雅翼》云∶天之将雨，柽先知之，起气以应，又负霜雪不 \n乃木之圣者也。故字从圣，又名雨师。或曰∶得雨则垂垂如丝，当作雨丝。又《三辅故事》 \n云∶汉武帝苑中有柳，状如人，号曰人柳，一日三起三眠。则柽柳之圣，又不独知雨、负雪 \n而已。今俗称长寿仙人柳，亦曰观音柳，谓观音用此洒水也。宗 曰∶今人谓之三春柳，以 \n其一年三秀故名。 \n【集解】志曰∶赤柽木生河西沙地。皮赤色，细叶。 \n禹锡曰∶《尔雅》∶柽，河柳也。郭璞注云∶今河旁赤茎小杨也。陆机《诗疏》云∶生 \n水旁，皮赤如绛，枝叶如松。 \n时珍曰∶柽柳小干弱枝，插之易生。赤皮，细叶如丝，婀娜可爱。一年三次作花，花穗 \n长三、四寸，水红色如蓼花色。南齐时，益州献蜀柳，条长，状若丝缕者，即此柳也。段成 \n式《酉阳杂俎》言∶凉州有赤白柽，大者为炭，其灰汁可以煮铜为银。故沈炯赋云∶柽似柏 \n而香。王祯《农书》云∶山柳赤而脆，河柳白而明。则柽又有白色者也。宗 ∶汴京甚多。 \n河西戎人取滑枝为鞭。 \n\\x木\\x \n【气味】甘、咸，温，无毒。 \n【主治】剥驴马血入肉毒，取木片火炙熨之，并煮汁浸之。（《开宝》）。枝叶∶消痞， \n解酒毒，利小便（时珍）。 \n【附方】新三。 \n腹中痞积∶观音柳煎汤，露一夜，五更空心饮数次，痞自消。（《卫生易简方》） \n一切诸风，不问远近∶柽叶半斤（切，枝亦可），荆芥半斤，水五升，煮二升，澄清， \n入白蜜五合，竹沥五合，新瓶盛之，油纸封，入重汤煮一伏时。每服一小盏，日三服。（《普 \n济方》） \n\\x柽乳\\x（即脂汁） \n【主治】合质汗药，治金疮 \n\n\n\n<目录>木部第三十五卷\\木之二\n\n<篇名>水杨\n\n内容：（《唐本草》） \n【释名】青杨（《纲目》）、蒲柳（《尔雅》）、蒲杨（《古今注》）、蒲 （音移）、 柳（《古 \n今注》）、 \n时珍曰∶杨枝硬而扬起，故谓之杨。多宜水 蒲萑之地，故有水杨、蒲柳、萑苻之名。 \n【集解】恭曰∶水杨叶圆阔而尖，枝条短硬，与柳全别。柳叶狭长，枝条长软。 \n颂曰∶《尔雅》∶杨，蒲柳也。其枝劲韧，可为箭 。《左传》所谓 \n苻。今河北沙地多生之。杨柳之类亦多。崔豹《古今注》云∶白杨叶圆，青杨叶长，柳叶长 \n而细， 杨叶圆而弱。水 \n理亦赤。然今人鲜能分别。 \n类。 \n尤多，花与柳同。 \n\\x枝叶\\x \n【气味】苦，平，无毒。 \n【主治】久痢赤白，捣汁一升服，日二，大效（《唐本》）。 \n主痈肿痘毒（时珍）。 \n【发明】时珍曰∶水杨根治痈肿，故近人用枝叶治痘疮。魏直《博爱心鉴》云∶痘疮数 \n日陷顶，浆滞不行，或风寒所阻者。宜用水杨枝叶（无叶用枝）五斤，流水一大釜，煎汤温 \n浴 \n之。如冷添汤，良久照见累起有晕丝者，浆行也。如不满，再浴之。力弱者，只洗头、面、 \n手、足。如屡浴不起者，气血败矣，不可再浴。始出及痒塌者，皆不可浴。 \n痘不行浆，乃气涩血滞，腠理固密，或风寒外阻而然。浴令暖气透达，和畅郁蒸，气血 \n通彻，每随暖气而发，行浆贯满，功非浅也。若内服助气血药，借此升之，其效更速，风寒 \n亦不得而阻之矣。直见一妪在村中用此有验，叩得其方，行之百发百中，慎勿易之，诚有燮 \n理之妙也。盖黄钟一动而蛰虫启户，东风一吹而坚冰解释，同一春也。群书皆无此法，故详 \n着之。 \n\\x木白皮及根\\x \n【气味】同华。 \n【主治】金疮痛楚，乳痈诸肿，痘疮（时珍）。 \n【发明】时珍曰∶按∶李仲南《永类钤方》云∶有人治乳痈，持药一根，生擂贴疮，其 \n热如火，再贴遂平。求其方，乃水杨柳根也。葛洪《肘后方》，治乳痈用柳根。则杨与柳性 \n气不远，可通用也 \n【附方】新一。 \n金疮苦痛∶杨木白皮，熬燥碾末，水服方寸匕，仍敷之，日三次。（《千金方》） \n\n\n\n<目录>木部第三十五卷\\木之二\n\n<篇名>白杨\n\n内容：（《唐本草》） \n【释名】独摇。 \n宗 曰∶木身似杨微白，故曰白杨，非如粉之白也。 \n时珍曰∶郑樵《通志》言∶白杨，一名高飞，与 杨同名。今俗通呼 杨为白杨，且白 \n杨亦因风独摇，故得同名也。 \n【集解】恭曰∶白杨取叶圆大、蒂小，无风自动者。 \n藏器曰∶白杨，北土极多，人种墟墓间，树大皮白。其无风自动者，乃 \n颂曰∶今处处有之，北土尤多。株甚高硕，叶圆如梨叶，皮白色，木似杨，采无时。崔 \n豹《古今注》云∶“白杨叶圆，青杨叶长”，是也。 \n宗 曰∶陕西甚多，永、耀间居人修盖，多此木也。其根易生，斫木时碎札入土即生根， \n故易繁植，土地所宜尔。风才至，叶如大雨声。谓无风自动，则无此事。但风微时，其叶孤 \n绝处，则往往独摇，以其蒂细长，叶重大，势使然也。 \n时珍曰∶白杨木高硕。叶圆似梨而肥大有尖，面青而光，背甚白色，有锯齿。木肌细白 \n，性坚直，用为梁 ，终不挠曲。与 杨乃一类二种也，治病之功，大抵仿佛。嫩叶亦可救 \n荒，老叶可作酒曲料。 \n\\x木皮\\x \n【修治】 曰∶凡使，铜刀刮去粗皮蒸之，从巳至未。以布袋盛，挂屋东角，待干用。 \n【气味】苦，寒，无毒。大明曰∶酸，冷。 \n【主治】毒风香港脚肿，四肢缓弱不随，毒瓦斯游 在皮肤中，痰癖等，酒渍服之（《唐本》）。 \n去风痹宿血，折伤，血沥在骨肉间，痛不可忍，及皮肤风瘙肿，杂五木为汤，浸损处 \n治扑损瘀血，并煎酒服。煎膏，可续筋骨（大明）。煎汤日饮， \n煎浆水入盐含漱，治口疮。煎水酿酒，消瘿气（时珍）。 \n【附方】旧一，新一。 \n妊娠下痢∶白杨皮一斤，水一斗，煮取二升，分三服。（《千金方》） \n项下瘿气∶秫米三斗炊熟，取圆叶白杨皮十两，勿令见风，切，水五升，煮取二升，渍 \n曲末五两，如常酿酒。每旦一盏，日再服。 \n\\x枝\\x \n【主治】消腹痛，治吻疮（时珍）。 \n【附方】旧二，新一。 \n口吻烂疮∶白杨嫩枝，铁上烧灰，和脂敷之。（《外台秘要》）。 \n腹满癖坚如石，积年不损者∶《必效方》∶用白杨木东南枝（去粗皮，辟风细锉）五升。 \n熬 \n黄，以酒五升淋讫，用绢袋盛滓，还纳酒中，密封再宿。每服一合，日三服。（《外台秘要》）。 \n面色不白∶白杨皮十八两，桃花一两，白瓜子仁三两，为末。每服方寸匕，日三服。五十日， \n面及手足皆白。（《圣济总录》） \n\\x叶\\x \n【主治】龋齿，煎水含漱。又治骨疽久发，骨从中出，频捣敷之（时珍）。 \n\n\n\n<目录>木部第三十五卷\n\n<篇名>木之二\n\n内容：（音夫移。《拾遗》） \n【释名】 杨（《古今注》）、 \n时珍曰∶ 乃白杨同类，故得杨名。按∶《尔雅》∶ \n唐棣， 也。崔豹曰∶ 杨，江东呼为夫 。圆叶弱蒂，微风则大摇，故名高飞，又曰 \n独摇。陆机以唐棣为郁李者，误矣。郁李乃常棣，非唐棣也。 \n【集解】藏器曰∶ 木生江南山谷。树大十数围，无风叶动，花反而后合，《诗》云∶ \n“棠棣之华，偏其反而”，是也。时珍曰∶ 杨与白杨是同类二种，今南人通呼为白杨，故 \n俚人有“白杨叶，有风掣，无风掣”之语。其入药之功大抵相近。 \n\\x木皮\\x \n【气味】苦，平，有小毒。 \n【主治】去风血香港脚疼痹， 损瘀血，痛不可忍，取白皮火炙，酒浸服之。和五木皮煮 \n汤，捋香港脚，杀瘃虫风瘙。烧作灰，置酒中，令味正，经时不败（藏器）。 \n【发明】时珍曰∶白杨、 杨皮，并杂五木皮煮汤，浸捋损痹诸痛肿。所谓五木者，桑、 \n槐、桃、楮、柳也。并去风和血。 \n【附方】新一。 \n妇人白崩∶ 杨皮半斤，牡丹皮四两，升麻、牡蛎（ ）各一两。每用一两，酒二钟， \n煎一钟，食前服。（ \n\n\n\n<目录>木部第三十五卷\\木之二\n\n<篇名>松杨\n\n内容：（《拾遗》） \n【校正】并入《唐本草》椋子木。 \n【释名】椋子木（音凉）。 \n时珍曰∶其材如松，其身如杨，故名松杨。《尔雅》云∶椋即来也。其阴可荫凉，故曰 \n椋木。 \n藏器曰∶江西人呼为凉木。松杨县以此得名。 \n【集解】藏器曰∶松杨生江南林落间。大树，叶如梨。 \n志曰∶椋子木，叶似柿，两叶相当。子细圆如牛李，生青熟黑。其木坚重，煮汁色赤。 \n郭璞云∶椋材中车辋。八月、九月采木，晒干用。 \n\\x木\\x \n【气味】甘、咸，平，无毒。 \n【主治】折伤，破恶血，养好血，安胎止痛生肉（《唐本》）。 \n\\x木皮\\x \n【气味】苦，平，无毒。 \n【主治】水痢不问冷热，浓煎令黑，服一升（藏器）。 \n\n\n\n<目录>木部第三十五卷\\木之二\n\n<篇名>榆\n\n内容：（俞、由二音。《本经》上品） \n【释名】零榆（《本经》），白者名 \n时珍曰∶按∶王安石《字说》云∶榆沈俞柔，故谓之榆。其 \n。其荚飘零，故曰零榆。 \n【集解】《别录》曰∶榆皮生颖川山谷。二月采皮，取白曝干。八月采实。并勿令中湿， \n湿则伤人。弘景曰∶此即今之榆树，取皮刮去上赤皮，亦可临时用之，性至滑利。初生荚仁， \n以作糜羹，令人多睡，嵇康所谓“榆令人瞑”也。恭曰∶榆三月实熟，寻即落矣。今云八月 \n采 \n实，恐误也。藏器曰∶江东无大榆。有刺榆，秋实。故《经》云八月采者，误也。刺榆，皮 \n不滑利。 \n颂曰∶榆，处处有之。三月生荚，古人采仁以为糜羹，今无复食者，惟用陈老实作酱耳 \n。按∶《尔雅疏》云∶榆类有数十种，叶皆相似，但皮及木理有异耳。刺榆有针刺如柘，其 \n叶如榆，瀹为蔬羹，滑于白榆，即《尔雅》所谓“枢、 ”，《诗经》所谓山有枢是也。白榆 \n先生叶，却着荚，皮白色，二月剥皮，刮去粗 ，中极滑白，即《尔雅》所谓“榆，白 ” \n是 \n也。荒岁农人取皮为粉，食之当粮，不损人。四月采实。宗 曰∶榆皮，初春先生荚者是也。 \n嫩时收贮为羹茹。嘉 中，丰沛人缺食多用之。时珍曰∶邢 《尔雅疏》云∶榆有数十种， \n今人不能尽别，惟知荚榆、白榆、刺榆、榔榆数者而已。荚榆、白榆皆大榆也。有赤、白二 \n种。白者名 ，其木甚高硕。未生叶时，枝条间先生榆荚，形状似钱而小，色白成串，俗呼 \n榆钱。后方生叶，似山茱萸叶而长，尖KT 润泽。嫩叶炸，浸淘过可食。故《内则》云∶ \n堇、 、 、榆、免、 ， 以滑之。三月采榆钱可作羹，亦可收至冬酿酒。瀹过晒干可 \n为酱，即榆仁酱也。崔实 \n与此相近，但味稍苦耳。诸榆性皆扇地，故其下五谷不植。古人春取榆火。今人采其白皮为 \n榆面，水调和香剂，粘滑胜于胶漆。 \n承曰∶榆皮湿捣如糊，用粘瓦石极有力。汴洛人以石为碓嘴，用此胶之。 \n\\x白皮\\x \n【气味】甘，平，滑利，无毒。 \n【主治】大小便不通，利水道，除邪气。 \n久服，断谷轻身不饥。其实尤良（《本经》）。疗肠胃邪热气，消肿，治小儿头疮痂 （《别 \n录》）。通经脉。 \n捣涎，敷癣疮（大明）。滑胎，利五淋，治 喘，疗不眠（甄权）。 \n生皮捣，和三年醋滓，封暴患赤肿，女人妒乳肿，日六、七易，效（孟诜）。利窍，渗 \n湿热，行津液 \n【发明】诜曰∶高昌人多捣白皮为末，和菜菹食甚美，令人能食。仙家长服，服丹石人 \n亦服之，取利关节故也。 \n时珍曰∶榆皮、榆叶，性皆滑利下降，手足太阳、手阳明经药也。故人小便不通，五淋 \n肿满，喘嗽不眠，经脉胎产诸症宜之。本草十剂云∶滑可去着，冬葵子、榆白皮之属。盖亦 \n取其利窍渗湿热，消留着有形之物尔。气盛而壅者宜之。若胃寒而虚者，久服渗利，恐泄真 \n气。《 \n【附方】旧九，新九。 \n断谷不饥∶榆皮、檀皮为末，日服数合。（《救荒本草》）。 \n喘不止∶榆白皮，阴干，焙为末。每日旦夜用水五合，末二钱，煎如胶，服。（《药 \n性论》）。 \n久嗽欲死∶许明有效方∶用浓榆皮削如指大，去黑，刻令如锯，长尺余，纳喉中频出入 \n，当吐脓血而愈。（《古今录验》）。 \n虚劳白浊∶榆白皮二升，水二斗，煮取五升，分五服。（《千金方》）。 \n小便气淋∶榆枝、石燕子煎水，日服。（《普济方》）。 \n五淋涩痛∶榆白皮，阴干，焙研。每以二钱，水五合，煎如胶，日二服。（《普济方》）。 \n渴而尿多，非淋也∶用榆皮二斤，去黑皮，以水一斗，煮取五升，一服三合，日三服。 \n（《外台秘要》）。 \n身体暴肿∶榆皮捣末，同米作粥食之，小便 \n临月易产∶榆皮焙为末。临月，日三服方寸匕，令产极易。（陈承《本草别说》）。 \n堕胎下血不止∶榆白皮、当归（焙）各半两，入生姜，水煎服之。（《普济方》）。 \n胎死腹中或母病欲下胎∶榆白皮煮汁，服二升。（《子母秘录》）。 \n身首生疮∶榆白皮末，油和涂之，虫当出。（杨氏《产乳》） \n火灼烂疮∶榆白皮，嚼涂之。（《千金髓》）。 \n五色丹毒∶俗名游肿，犯者多死， \n小儿虫疮∶榆皮末和猪脂涂绵上，覆之。虫出立瘥。（《千金方》）。 \n痈疽发背∶榆根白皮切，清水洗，捣极烂，和香油敷之，留头出气。燥则以苦茶频润， \n不 \n小儿瘰 ∶榆白皮，生捣如泥，封之。频易。（《必效方》）。 \n小儿秃疮∶醋和榆白皮末，涂之，虫当出。（《子母秘录》）。 \n\\x叶\\x \n【气味】同上。 \n【主治】嫩叶作羹及炸食，消水肿，利小便，下石淋，压丹石（藏器。时珍曰∶曝干为 \n末，淡盐水拌，或炙、或晒干，拌菜食之，亦辛滑下水气）。煎汁，洗酒 鼻。同酸枣仁等 \n分蜜丸，日服，治胆热虚劳 \n\\x花\\x \n【主治】小儿痫，小便不利，伤热（《别录》）。 \n\\x荚仁\\x \n【气味】微辛，平，无毒。 \n【主治】作糜羹食，令人多睡（弘景）。主妇人带下，和牛肉作羹食（藏器）。子酱，似 \n芜荑，能助肺，杀诸虫，下气，令人能食，消心腹间恶气，猝心痛，涂诸疮癣，以陈者良（孟 \n诜）。 \n\\x榆耳\\x \n见木耳。 \n\n\n\n<目录>木部第三十五卷\\木之二\n\n<篇名>朗榆\n\n内容：（《拾遗》） \n【集解】藏器曰∶朗榆生山中，状如榆，其皮有滑汁，秋生荚，如 \n时珍曰∶大榆，二月生荚，朗榆八月生荚，可分别。 \n\\x皮\\x \n【气味】甘，寒，无毒。 \n【主治】下热淋，利水道，令人睡（藏器）。治小儿解颅 \n\n\n\n<目录>木部第三十五卷\\木之二\n\n<篇名>芜荑\n\n内容：（《本经》中品） \n【释名】 荑（《尔雅》）、无姑（《本经》、 （音殿唐），木名 （音偏）。 \n时珍曰∶按∶《说文》云∶ ，山 榆也。有刺，实为芜荑。《尔雅》云∶无姑，其实荑。 \n又云∶ 荑， \n恭曰∶ 乃 二字之误。 \n【集解】《别录》曰∶芜荑生晋山川谷。三月采实，阴干。 \n弘景曰∶今惟出高丽，状如榆荚，气臭如 ，彼人皆以作酱食之。性杀虫，置物中亦辟 \n蛀，但患其臭。 \n恭曰∶今延州、同州者甚好。 \n志曰∶河东、河西处处有之。 \n颂曰∶近道亦有之，以太原者良。大抵榆类而差小，其实亦早成，比榆乃大，气臭。郭 \n璞《尔雅注》云∶无姑，姑榆也。生山中，叶圆而浓，剥取皮合渍之，其味辛香，所谓芜荑 \n也。采实阴干用。今人又多取作屑，以 五味，惟陈者良。人收藏之多以盐渍，则失气味， \n但宜食品，不堪入药。 曰∶按∶《广州记》云∶生大秦国，是波斯芜荑也。 \n气膻者良，乃山榆仁也。 \n辛。人多以外物相和 \n【气味】辛，平，无毒。 \n权曰∶苦，平。 \n曰∶辛，温。 \n诜曰∶作酱甚香美，功尤胜于榆仁。可少食之，过多发热，为辛故也。秋月食之，尤宜 \n人。 \n【主治】五内邪气，散皮肤骨节中淫淫温行毒，去三虫，化食（《本经》）。逐寸白，散 \n肠中 喘息（《别录》）。主积冷气，心腹症痛，除肌肤节中风淫淫如虫行（《甄权》）。五 \n脏皮 \n（大 \n明） \n热疮。和蜜，治湿癣。和沙牛酪或马酪，治一切疮（孟诜）。 \n【附方】旧三，新七。 \n脾胃有虫，食即作痛，面黄无色∶以石州芜荑仁二两，和面炒黄色为末。非时米饮服二 \n钱匕。（《千金方》） \n制杀诸虫∶生芜荑、生槟榔各四两，为末，蒸饼丸梧子大。每服二十丸，白汤下。（《本 \n事方》。 \n疳热有虫，瘦悴，久服充肥∶用榆仁一两，黄连一两，为末，猪胆汁七枚和，入碗内， \n饭上蒸之，一日蒸一次，九蒸乃入麝香半钱，汤浸蒸饼和，丸绿豆大。每服五、七丸至一、 \n二十丸，米饮下。（钱氏《小儿直诀》）。 \n荑、干漆（烧存性）等分，为末。米饮调服一字至一钱。（杜壬方）。 \n捣 \n烂，纸压去油，为末，以雄猪胆汁丸梧桐子大。每服九丸，甘草汤下，日五服。三日断根。 \n（《普济方》）。 \n陈米饮下三十丸。久服，去三尸，益神驻颜。此方得之章镣，曾用得力。（王绍颜《续 \n方》）。 \n并下气佳。（《外台秘要》）。 \n麦（炒）、黄连（炒）各一钱，为末，猪胆汁打糊丸黍米大。每 \n能去 \n心窍恶血。（《全幼心鉴》）。 \n腹中鳖瘕∶平时嗜酒，血入于酒则为酒鳖；平时多气，血凝于气则为气鳖；虚劳痼冷，败血 \n杂痰，则为血鳖。摇头掉尾，如虫之行，上侵人咽，下蚀人肛，或附胁背，或隐胸腹，大则 \n如鳖，小或如钱。治法惟用芜荑（炒）煎服之，兼用暖胃益血理中之类，乃可杀之。若徒事 \n雷丸、锡灰之类，无益也。（《仁斋直指方》） \n\n\n\n<目录>木部第三十五卷\\木之二\n\n<篇名>苏方木\n\n内容：（《唐本草》） \n【释名】苏木。 \n时珍曰∶海岛有苏方国，其地产此木，故名。今人省呼为苏木尔。 \n【集解】恭曰∶苏方木自南海、昆仑来，而交州、爱州亦有之。树似庵罗，叶若榆叶而 \n无涩，抽条长丈许，花黄，子生青熟黑。其木，人用染绛色。 \n曰∶按∶徐表《南州记》云∶生海畔。 \n叶似绛，木若女贞。 \n时珍曰∶按∶嵇含《南方草木状》云∶苏方树类槐，黄花黑子，出九真。煎汁忌铁器， \n则色黯。其木蠹之粪名曰紫纳，亦可用。暹罗国人贱用如薪。 \n【修治】 曰∶凡使去上粗皮并节。若得中心纹横如紫角者，号曰木中尊，其力倍常百 \n等。须细锉重捣，拌细梅树枝蒸之，从巳至申，阴干用。 \n【气味】甘、咸，平，无毒。 \n杲曰∶甘、咸，凉。可升可降，阳中阴也。 \n好古曰∶味甘而微酸、辛，其性平。 \n【主治】破血。产后血胀闷欲死者，水煮五两，取浓汁服（《 \n妇人血气心腹痛，月候不调及蓐痨，排脓止痛，消痈肿扑损瘀血，女人失音血噤，赤白 \n痢，并后分急痛（大明）。虚劳血癖气壅滞，产后恶露不安，心腹搅痛，及经络不通，男女 \n中风，口噤不语。并宜细研乳头香末方寸匕，以酒煎苏方木，调服，立吐恶物瘥（《海药》）。 \n霍乱呕逆，及人常呕吐，用水煎服（藏器）。破疮疡死血，产后败血 \n【发明】元素曰∶苏木性凉，味微辛。发散表里风气，宜与防风同用。又能破死血，产 \n后血肿胀满欲死者宜之。 \n【附方】旧一，新五。 \n产后血晕∶苏方木三两，水五升，煎取二升，分再服。（《肘后方》）。 \n产后气喘，面黑欲死，乃血入肺也∶用苏木二两，水两碗，煮一碗，入人参末一两服。 \n随时加减，神效不可言。（胡氏方）。 \n破伤风病∶苏方木（为散）三钱，酒服立效。 \n名独圣散。（《普济方》）。 \n香港脚肿痛∶苏方木、鹭鸶藤等分，细锉，入淀粉少许，水二斗，煎一斗五升，先熏后洗。 \n（《普济方》）。 \n偏坠肿痛∶苏方木二两，好酒一壶煮熟，频饮立好。（《集简方》）。 \n金疮接指∶凡指断及刀斧伤。用真苏木末敷之，外以蚕茧包缚完固，数日如故。（《摄 \n生方》） \n\n\n\n<目录>木部第三十五卷\\木之二\n\n<篇名>乌木\n\n内容：（《纲目》） \n【释名】乌 木（ ，音漫）、 \n时珍曰∶木名文木，南人呼文如 ，故也。 \n【集解】时珍曰∶乌木出海南、云南、南番。叶似棕榈。其木漆黑，体重坚致，可为箸 \n及器物。有间道者，嫩木也。南人多以系木染色伪之。《南方草物状》云∶文木树高七、八 \n丈，其色正黑，如水牛角，作马鞭，日南有之。《古今注》云∶乌文木出波斯，舶上将 \n乌文KT 然。温、括、婺等州亦出之，皆此物也。 \n【气味】甘、咸，平，无毒。 \n【主治】解毒，又主霍乱吐利，取屑研末，温酒服（时珍）。 \n\n\n\n<目录>木部第三十五卷\\木之二\n\n<篇名>桦木\n\n内容：（宋《开宝》） \n【释名】KT 。 \n藏器曰∶晋·中书令王 《伤寒身验方》中作KT 字。 \n时珍曰∶画工以皮烧烟熏纸，作古画字，故名KT 。俗省作桦字也。 \n【集解】藏器曰∶桦木似山桃，皮堪为烛。 \n宗 曰∶皮上有紫黑花匀者，裹鞍、弓、镫。 \n时珍曰∶桦木生辽东及临洮、河州、西北诸地。其木色黄，有小斑点红色，能收肥腻。 \n其皮浓而轻虚软柔，皮匠家用衬靴里，及为刀靶之类，谓之暖皮。胡人尤重之。以皮卷蜡， \n可作烛点。 \n\\x木皮\\x \n【气味】苦，平，无毒。 \n【主治】诸黄胆，浓煮汁饮之良（《开宝》）。 \n煮汁冷冻饮料，主伤寒时行热毒疮，特良。即今豌豆疮也（藏器）。 \n烧灰合他药，治肺风毒（宗 ）。治乳痈（时珍）。 \n【附方】旧一，新四。 \n乳痈初发∶肿痛结硬欲破，一服即瘥。以北来真桦皮烧存性，研，无灰酒温服方寸匕， \n即卧，觉即瘥也。（沈存中《灵苑方》）。 \n乳痈腐烂∶靴内年久桦皮，烧灰。 \n酒服一钱，日一服。（唐瑶《经验》）。 \n肺风毒疮∶遍身疮疥如疠，及瘾疹瘙痒，面上风刺，妇人粉刺，并用桦皮散主之。桦皮 \n（烧灰）四两，枳壳（去穣，烧）四两，荆芥穗二两，炙甘草半两，各为末，杏仁（水煮过， \n去 \n皮、尖）二两（研泥烂），研匀。每服二钱，食后温酒调下。疮疥甚者，日三服。（《和剂方》）。 \n小便热短∶桦皮浓煮汁，饮。（《集简方》）。染黑须发∶KT 皮一片，包侧柏一枝，烧烟 \n熏香油碗 \n\\x脂\\x \n【主治】烧之，辟鬼邪（藏器）。 \n\n\n\n<目录>木部第三十五卷\\木之二\n\n<篇名>木\n\n内容：（《拾遗》） \n【释名】 \n【集解】藏器曰∶生林泽山谷。木文侧戾，故曰 \n【气味】甘，温，无毒。 \n【主治】风血羸瘦，补腰脚，益阳道，宜浸酒饮（藏器）。 \n\n\n\n<目录>木部第三十五卷\\木之二\n\n<篇名>榈木\n\n内容：（《拾遗》） \n【集解】藏器曰∶出安南及南海。用作床几，似紫檀而色赤，性坚 \n时珍曰∶木性坚，紫红色。亦有花纹者，谓之花榈木，可作器皿、扇骨诸物。俗作花梨 \n，误矣。 \n【气味】辛，温，无毒。 \n【主治】产后恶露冲心，症瘕结气，赤白漏下，并锉煎服（李 ）。破血块，冷嗽，煮 \n汁热服。为枕令人头痛，性热 \n\n\n\n<目录>木部第三十五卷\\木之二\n\n<篇名>棕榈\n\n内容：（《宋嘉 》） \n【释名】 榈。 \n时珍曰∶皮中毛缕如马之鬃KT ，故名。KT ，俗作棕。KT ，音闾，鬣也。 ，音 \n并。 \n【集解】颂曰∶棕榈出岭南、西川，今江南亦有之。木高一、二丈，无枝条。叶大而圆， \n有如车轮，萃于树杪。其下有皮重叠裹之，每皮一匝，为一节。二旬一采，皮转复生上。六、 \n七月生黄白花。八、九月结实，作房如鱼子，黑色。九月、十月采其皮用。《山海经》云∶ \n石翠之山，其木多棕是也。藏器曰∶其皮作绳，入土千岁不烂。昔有人开冢得一索，已生根。 \n岭南有桄榔、槟榔、椰子、冬叶、虎散、多罗等木，叶皆与 榈相类。时珍曰∶棕榈，川、 \n广甚多，今江南亦种之，最难长。初生叶如白芨叶；高二、三尺则木端数叶大如扇，上耸， \n四散歧裂，其茎三棱，四时不凋。其干正直无枝，近叶处有皮裹之，每长一层即为一节。干 \n身赤黑，皆筋络，宜为钟杵，亦可旋为器物。其皮有丝毛，错纵如织，剥取缕解，可织衣、 \n帽、褥、椅之属，大为时利。每岁必两、三剥之，否则树死，或不长也。三月于木端茎中出 \n数黄苞，苞中有细子成列，乃花之孕也，状如鱼腹孕子，谓之棕鱼，亦曰棕笋。渐长出苞， \n则成花穗，黄白色。结实累累，大如豆，生黄熟黑，甚坚实。或云∶南方此木有两种∶一种 \n有皮丝，可作绳；一种小而无丝，惟叶可作帚。郑樵《通志》以为王彗者，非也。王彗乃落 \n帚之名，即地肤子。别有蒲葵，叶与此相似而柔薄，可为扇、笠，许慎《说文》以为棕榈亦 \n误矣。 \n\\x笋及子花\\x \n【气味】苦，涩，平，无毒。 \n藏器曰∶有小毒，戟人喉，未可轻服。 \n曰∶温，有大毒，不堪食。 \n时珍曰∶棕鱼，皆言有毒不可食，而广、蜀人蜜煮、醋浸，以供佛、寄远，苏东坡亦有 \n食棕笋诗，乃制去其毒尔。 \n【主治】涩肠，止泻痢肠风，崩中带下，及养血（藏器）。 \n【附方】新一。 \n大肠下血∶棕笋煮熟，切片晒干为末，蜜汤或酒服一、二钱。（《集简方》） \n\\x皮\\x \n【气味】同子。 \n【主治】止鼻衄吐血，破症，治肠风赤白痢，崩中带下，烧存性用（大明）。主金疮疥 \n癣， \n生肌止血（李 ）。 \n【发明】宗 曰∶棕皮烧黑，治妇人血露及吐血，须佐以他药。 \n时珍曰∶棕灰性涩，若失血去多，瘀滞已尽者，用之切当，所谓涩可去脱也。与乱发同 \n用更良。年久败棕入药尤妙。 \n【附方】新六。 \n鼻血不止∶棕榈灰，随左右吹之。（黎居士方）。 \n血崩不止∶棕榈皮，（烧存性，）空心淡酒服三钱。一方∶加 白矾等分。 \n血淋不止∶棕榈皮（半烧半炒）为末，每服二钱，甚效。（《卫生家宝方》）。 \n下血不止∶棕榈皮半斤，栝蒌一个，烧灰。每服二钱，米饮调下。（《百一选方》）。 \n水谷痢下∶棕榈皮烧研，水服方寸匕。（《近效方》）。 \n小便不通∶棕皮毛（烧存性，）以水酒服二钱即通利，累试甚验。（《摄生方》） \n\n\n\n<目录>木部第三十五卷\\木之二\n\n<篇名>木\n\n内容：（ ，良刃切。《拾遗》） \n【释名】 木（音潭）。 \n【集解】藏器曰∶ 木生江南深山大树。树有数种，取叶浓大白花者入药，自余灰入染 \n家用。 \n时珍曰∶此木最硬，梓人谓之 筋木是也。木入染绛用，叶亦可酿酒。 \n\\x木灰\\x \n【气味】甘，温，小毒。 \n【主治】猝心腹症瘕，坚满 癖。淋汁八升，酿米一斗，待酒熟，每温饮半合，渐增至 \n一、二盏，即愈（藏器。出《肘后》）。 \n\n\n\n<目录>木部第三十五卷\\木之二\n\n<篇名>柯树\n\n内容：（《拾遗》） \n【释名】木奴。 \n【集解】 曰∶按∶《广志》云∶生广南山谷。波斯家用木为船舫者也。 \n\\x白皮\\x \n【气味】辛，平，有小毒。 \n【主治】大腹水病。采皮煮汁去滓，煎令可，丸如梧桐子大。平旦空心饮下三丸，须臾 \n又一丸，气、水并从小便出也（藏器）。 \n\n\n\n<目录>木部第三十五卷\\木之二\n\n<篇名>乌木\n\n内容：（《唐本草》） \n【释名】 臼。 \n时珍曰∶乌 ，乌喜食其子，因以名之。陆龟蒙诗云∶行歇每依鸦舅影，挑频时见鼠姑 \n心。是矣。鼠姑，牡丹也。或云∶其木老则根下黑烂成臼，故得此名。郑樵《通志》言“乌 \n即柜柳”者，非。 \n【集解】恭曰∶生山南平泽。树高数仞，叶似梨、杏。五月开细花，黄白色。子黑色。 \n藏器曰∶叶可染皂。子可压油，燃灯极明。 \n宗 曰∶叶如小杏叶，但微薄而绿色差淡。子八、九月熟，初青后黑，分为三瓣。 \n时珍曰∶南方平泽甚多。今江西人种植，采子蒸煮，取脂浇烛货之。子上皮脂，胜于仁 \n也。 \n\\x根白皮\\x \n【气味】苦，微温，有毒。 \n大明曰∶性凉，慢火炙干黄乃用。 \n【主治】暴水，症结积聚（《唐本》）。 \n【发明】时珍曰∶乌 根性沉而降，阴中之阴，利水通肠，功胜大戟。一野人病肿满气 \n壮，令掘此根捣烂，水煎服一碗，连行数行而病平。气虚人不可用之。此方出《太平圣惠方》， \n言其功神 \n【附方】旧一，新九。 \n小便不通∶乌 根皮煎汤，饮之。（《肘后方》）。 \n大便不通∶乌 木根方长一寸，劈破，水煎半盏，服之立通。不用多吃。其功神圣，兼 \n能取水。（《斗门方》） \n二便关格，二、三日则杀人∶乌 东南根白皮，干为末，热水服二钱。先以芒硝二两， \n煎汤服，取吐甚效。（《肘后方》）。 \n水气虚肿，小便涩∶乌 皮二两，槟榔、木通各一两，为末。每服二钱，米饮下。（《圣 \n惠方》） \n香港脚湿疮，极痒有虫∶乌 根，为末敷之，少时有涎出良。（《摘玄方》）。 \n尸注中恶，心腹痛刺，沉 \n调朱砂末一钱，服之。《肘后方》无朱砂。（《永类方》）。 \n暗疔昏狂，疮头凸红∶ 树根经行路者，取二尺许，去皮捣烂，井华水调一盏服。待泻 \n过，以三角银杏仁浸油，捣 患处。（《圣济总录》）。 \n婴儿胎毒满头∶用水边乌 树根晒研，入雄黄末少许，生油调搽。（《经验良方》）。 \n鼠莽砒毒∶乌 根半两，擂水服之。（《医方大成》）。 \n盐 痰喘∶ 树皮，去粗捣汁，和飞面作饼，烙熟。早晨与儿吃三、四个，待吐下盐涎 \n乃佳。如不行，热茶催之。（《摘玄方》） \n\\x叶\\x \n【气味】同根。 \n【主治】食牛马六畜肉，生疔肿欲死者。捣自然汁一、二碗，顿服得大利，去毒即愈。 \n未利再服。冬用根（时 \n\\x 油\\x \n【气味】甘，凉，无毒。 \n【主治】涂头，变白为黑。服一合，令人下利，去阴下水气。炒子作汤亦可（藏器）。 \n涂一切肿毒疮疥 \n【附方】新二。 \n脓 疥疮∶ 油二两，水银二钱，樟脑五钱，同研，频入唾津，不见星乃止。以温汤洗 \n净疮，以药填入。（ \n小儿虫疮∶用旧绢作衣，化 油涂之，与儿穿着。次日虫皆出油上，取下 之有声是也。 \n别以油衣与穿，以虫尽为度（《濒湖集简 \n\n\n\n<目录>木部第三十五卷\\木之二\n\n<篇名>巴豆\n\n内容：（《本经》下品） \n【释名】巴菽（《本经》）、刚子（《炮炙》）、 \n时珍曰∶此物出巴蜀，而形如菽豆，故以名之。《宋本草》一名巴椒，乃菽字传讹也。 \n雷《炮炙论》又分紧小色黄者为巴，有三棱色黑者为豆，小而两头尖者为刚子。云巴与豆 \n可用，刚子不可用（杀人）。其说殊乖。盖紧小者是雌，有棱及两头尖者是雄。雄者峻利， \n雌者稍缓也。用之得宜，皆有功力；用之失宜，参、术亦能为害，况巴豆乎？ \n【集解】《别录》曰∶巴豆生巴郡川谷。八月采，阴干用之，去心、皮。 \n颂曰∶今嘉州、眉州、戎州皆有之。木高一、二丈。叶如樱桃而浓大，初生青色，后渐 \n黄赤，至十二月叶渐凋，二月复渐生，四月旧叶落尽，新叶齐生，即花发成穗，微黄色。五、 \n六月结实作房，生青，至八月熟而黄，类白豆蔻，渐渐自落，乃收之。一房有三瓣，一瓣一 \n子，共三子。子仍有壳，用之去壳。戎州出者，壳上有纵纹，隐起如线，一道至两、三道。 \n彼土人呼为金线巴豆，最为上等，他处亦稀有。 \n时珍曰∶巴豆房似大风子壳而脆薄，子及仁皆似海松子。所云似白豆蔻者，殊不类。 \n【修治】弘景曰∶巴豆最能泻人，新者佳，用之去心、皮，熬令黄黑，捣如膏，乃和丸 \n散。 \n曰∶凡用巴与豆，敲碎，以麻油并酒等煮干研膏用。每一两，用油、酒各七合。 \n大明曰∶凡入丸散，炒用不如去心、膜，换水煮五度（各一沸也）。 \n时珍曰∶巴豆有用仁者，用壳者，用油者，有生用者，麸炒者，醋煮者，烧存性者，有 \n研烂以纸包压去油者（谓之巴豆霜）。 \n【气味】辛，温，有毒。 \n《别录》曰∶生温、熟寒，有大毒。 \n普曰∶神农、岐伯、桐君∶辛，有毒；黄帝∶甘，有毒。李当之∶热。 \n元素曰∶性热味苦，气薄味浓，体重而沉降，阴也。 \n杲曰∶性热味辛，有大毒，浮也，阳中阳也。 \n时珍曰∶巴豆气热味辛，生猛熟缓，能吐能下，能止能行，是可升可降药也。《别录》 \n言其熟则性寒，张氏言其降，李氏言其浮，皆泥于一偏矣。盖此物不去膜则伤胃，不去心则 \n作呕，以沉香水浸则能升能降，与大黄同用泻入反缓，为其性相畏也。王充《论衡》云∶万 \n物含太 \n之才曰∶芫花为之使。畏大黄、黄连、芦笋、菰笋、藜芦、酱、豉、冷水，得火良，恶 \n草，与牵牛相反。中其毒者，用冷水、黄连汁、大豆汁解之。 \n【主治】伤寒温疟寒热，破症瘕结聚坚积留饮痰癖，大腹水胀，荡练五脏六腑，开通闭 \n塞，利水谷道，去恶肉，除鬼毒蛊疰邪物，杀虫鱼（《本经》）。 \n疗女子月闭烂胎，金疮脓血，不利丈夫阴。杀斑蝥蛇虺毒。可炼饵之，益血脉，令人色 \n好，变化与鬼神通（《别录》）。治十种水肿，痿痹，落胎（《药性》）。通宣一切病，泄壅滞， \n除风补劳，健脾开胃，消痰破血，排脓消肿毒，杀腹脏虫，治恶疮息肉，及疥癞疔肿（《日 \n华》）。 \n导气消积，去脏腑停寒，治生冷硬物所伤（元素）。治泻痢惊痫，心腹痛疝气，风 ， \n耳聋，喉痹牙痛，通利关窍（时珍） \n【发明】元素曰∶巴豆乃斩关夺门之将，不可轻用。 \n震亨曰∶巴豆去胃中寒积。无寒积者勿用。 \n元素曰∶世以巴豆热药治酒病膈气，以其辛热能开肠胃郁结也。但郁结虽开，而亡血液 \n，损其真阴。 \n从正曰∶伤寒风湿，小儿疮痘，妇人产后，用之下膈，不死亦危。奈何庸人畏大黄而不 \n畏巴豆，以其性热而剂小耳。岂知以蜡匮之，犹能下后使人津液枯竭，胸热口燥，耗却天真， \n留毒不去，他病转生。故下药宜以为禁。 \n藏器曰∶巴豆主症癖 气，痞满积聚，冷气血块，宿食不消，痰饮吐水。取青黑大者， \n每日空腹服一枚，去壳勿令白膜破，乃作两片（并四边不得有损缺）吞之，以饮压令下。少 \n顷 \n腹内热如火，利出恶物。虽利而不虚，若久服亦不利。白膜破者不用。 \n好古曰∶若急治，为水谷道路之剂，去皮、心、膜、油，生用。若缓治为消坚磨积之剂， \n炒去烟令紫黑用，可以通肠，可以止泻，世所不知也。张仲景治百病客忤备急丸用之。 \n时珍曰∶巴豆峻用则有戡乱劫病之功，微用亦有抚缓调中之妙。譬之萧、曹、绛、灌， \n乃勇猛武夫，而用之为相，亦能辅治太平。王海藏言其可以通肠，可以止泻，此发千古之秘 \n也。一老妇年六十余，病溏泄已五年，肉食、油物、生冷犯之即作痛。服调脾、升提、止涩 \n诸药，入腹则泄反甚。延余诊之，脉沉而滑，此乃脾胃久伤，冷积凝滞所致。王太仆所谓大 \n寒凝内，久利溏泄，愈而复发，绵历岁年者。法当以热下之，则寒去利止。遂用蜡匮巴豆丸 \n药五十丸与服，二日大便不通亦不利，其泄遂愈。自是每用治泄痢积滞诸病，皆不泻而病愈 \n者近百人。妙在配合得宜，药病相对耳。苟用所不当用，则犯轻用损阴之戒矣。 \n【正误】弘景曰∶道家亦有炼饵法，服之云可神仙。人吞一枚便死，而鼠食之三年重三 \n十斤，物性乃有相耐如此。 \n时珍曰∶汉时方士言巴豆炼饵，令人色好神仙，《名医别录》采入本草。张华《博物志 \n》言鼠食巴豆重三十斤。一谬一诬，陶氏信为实语，误矣。又言人吞一枚即死，亦近过情， \n今并正之。 \n【附方】旧十三，新二十六。 \n一切积滞∶巴豆一两，蛤粉二两，黄柏三两，为末，水丸绿豆大。每水下五丸。（《医 \n学切问》） \n寒 宿食久饮不消，大便闭塞∶巴豆仁一升，清酒五升，煮三日三夜，研熟，合酒微火 \n煎令可，丸如豌豆大。每服一丸，水下。欲吐者，二丸。（《千金方》）。 \n水蛊大腹，动摇水声，皮肤色黑∶巴豆九十枚（去心、皮，熬黄）。杏仁六十枚（去皮、 \n尖，熬黄），捣丸小豆大。水下一丸，以利为度。勿饮酒。（张文仲《备急方》）。 \n飞尸鬼击中恶，心痛腹胀，大便不通∶走马汤∶用巴豆二枚（去皮、心，熬黄），杏仁 \n二枚，以绵包椎碎，热汤一合，捻取白汁服之，当下而愈。量老小用之。（ \n食疟积疟∶巴豆（去皮、心）二钱，皂荚（去皮、子）六钱，捣丸绿豆大。一服一丸， \n冷汤下。（《肘后方》）。 \n积滞泄痢，腹痛里急∶杏仁（去皮、尖）、巴豆（去皮、心）各四十九个，同烧存性， \n研泥， \n熔蜡和，丸绿豆大。每服二、三丸，煎大黄汤下，间日一服。一加百草霜三钱。（刘守真《宣 \n明方》）。 \n气痢赤白∶巴豆一两。去皮、心，熬研，以熟猪肝丸绿豆大。空心米饮下三、四丸，量 \n人用。此乃郑獬侍御所传方也。（《经验方》）。 \n泻血不止∶巴豆一个。去皮，以鸡子开一孔纳入，纸封煨熟，去豆食之，其病即止。虚 \n人分作二服，决效。（《普济方》）。 \n小儿下痢赤白∶用巴豆（煨熟，去油）一钱，百草霜二钱。研末，飞罗面煮糊，丸黍米 \n大，量人用之。赤用甘草汤，白 \n夏月水泻不止∶巴豆一粒，针头烧存性，化蜡和作一丸。倒流水下。（危氏《得效方》）。 \n小儿吐泻∶巴豆一个（针穿灯上烧过），黄蜡一豆大（灯上烧，滴入水中）。同杵丸黍米 \n大。每用五、七丸，莲子、灯心汤下。（同上）。 \n伏暑霍乱伤冷，吐利烦渴∶水浸丹∶用巴豆二十五个（去皮、心及油），黄丹（炒，研） \n一两二钱半，化黄蜡和，丸绿 \n干霍乱病∶心腹胀痛，不吐不利，欲死。巴豆一枚（去皮、心），热水研服，得吐、利 \n即定也。二便不通∶巴豆（连油）、黄连各半两，捣作饼子。先滴葱、盐汁在脐内，安饼于 \n上，灸二七壮，取利为度。（《杨氏家藏 \n寒痰气喘∶青橘皮一片，展开入刚子一个，麻扎定，火上烧存性，研末。姜汁和酒一钟， \n呷服。天台李翰林用此治莫秀才，到口便止，神方也。（张杲《医说》）。 \n风湿痰病∶人坐密室中，左用滚水一盆，右用炭火一盆，前置一桌，书一册。先将无油 \n新巴豆四十九粒研如泥，纸压去油，分作三饼。如病在左，令病患将右手仰置书上，安药于 \n掌心，以碗安药上，倾热水入碗内。水凉即换，良久汗出，立见神效。病在右安左掌心。一 \n云随左右安之。（《保寿堂经验方》）。 \n阴毒伤寒∶心结，按之极痛，大小便闭，但出气稍暖者。急取巴豆十粒研，入面一钱， \n捻作饼，安脐内，以小艾炷灸五壮，气达即通。此太师陈北山方也。（《仁斋直指方》） \n解中药毒∶巴豆（去皮，不去油）、马牙硝等分，研丸。冷水服一弹丸。（《初虞世方》）。 \n喉痹垂死，只有余气者∶巴豆去皮，线穿，内入喉中，牵出即苏。（《千金》）。 \n缠喉风痹∶巴豆两粒，纸卷作角，切断两头，以针穿作孔子，入鼻中，气透即通。（《胜 \n金方》）。 \n伤寒舌出∶巴豆一粒，去油取霜，以纸捻卷，内入鼻中。舌即收上。（《普济方》）。 \n舌上出血如簪孔∶巴豆一枚，乱发鸡子大，烧研，酒服。（《圣惠》）。 \n中风口 ∶巴豆七枚去皮，研，左 涂右手心，右 涂左手心，仍以暖水一盏安药上。 \n须臾即正，洗去。（《圣惠方》）。 \n小儿口疮不能食乳∶刚子一枚，连油研，入黄丹少许，剃去囟上发，贴之。四边起粟泡， \n便用温水洗去，乃以菖蒲汤再洗，即不成疮，神效。（《瑞竹堂方 \n风虫牙痛∶《圣惠》∶用巴豆一粒（煨黄去壳）。蒜一瓣，切一头，剜去中心，入豆在内 \n盖定，绵裹，随左右塞耳中。《经验方》∶用巴豆一粒研，绵裹咬之。又方∶针刺巴豆，灯上 \n烧令烟出， \n天丝入咽∶凡露地饮食，有飞丝入上，食之令人咽喉生疮。急以白矾、巴豆烧灰，吹入 \n即愈。（《琐碎录》）。 \n耳猝聋闭∶巴豆一粒。蜡裹，针刺孔通气，塞之取效。（《经验》）。 \n风瘙隐疹，心下迷闷∶巴豆五十粒（去心、皮）。水七升，煮三升，以帛染拭之，随手 \n愈。（《千金翼》）。 \n疥疮搔痒∶巴豆十粒。炮黄去皮、心，右顺手研，入酥少许，腻粉少许，抓破点上，不 \n得近目并外肾上。如熏目着肾，则以黄丹涂之，甚妙。（《十全方》）。 \n荷钱癣疮∶巴豆仁三个，连油杵泥，以生绢包擦，日一、二次，三日痊好。（碑以正《经 \n验方》）。 \n一切恶疮∶巴豆三十粒，麻油煎黑，去豆，以油调硫黄、轻粉末，频涂取效。（《普济》）。 \n痈疽恶肉∶乌金膏∶解一切疮毒，及腐化瘀肉，最能推陈致新。巴豆仁炒焦，研膏，点 \n痛处则解毒，涂瘀肉上则自化。加乳香少许亦可。若毒深不能收敛者，宜作捻 之，不致成 \n疮。（《外科理例》）。 \n疣痣黑子∶巴豆一钱（锻石炒过），人言一钱，糯米五分（炒）。研点之。（《怪症方》）。 \n箭镞入肉不可拔出者∶用新巴豆仁（略熬），与蜣螂同研涂之，斯须痛定，微痒忍之， \n待极痒不可忍，便撼拔动之，取出，速以生肌膏敷之而痊。亦治疮肿。夏侯郸在润州得此方， \n后至洪州，旅舍主人妻病背疮，呻吟不已，郸用此方试之，即痛止也。（《经验方》）。 \n小儿痰喘∶巴豆一粒。杵烂，绵裹塞鼻，男左女右，痰即自下。（龚氏《医鉴》）。 \n牛疫动头∶巴豆二粒（研），生麻油三两，浆水半升，和灌之。（贾相公《牛经》）。 \n\\x油\\x \n【主治】中风痰厥气厥，中恶喉痹，一切急病，咽喉不通，牙关紧闭。以研烂巴豆绵 \n纸包，压取油作捻点灯，吹灭熏鼻中，或用热烟刺入喉内，即时出涎或恶血便苏。又舌上 \n无故出血，以熏舌之上下，自止（时珍）。 \n\\x壳\\x \n【主治】消积滞，治泻痢（时珍）。 \n【附方】新二。 \n一切泻痢∶脉浮洪者，多日难已；脉微小者，服之立止。名胜金膏。巴豆皮、楮叶同烧 \n存性研，化蜡丸绿豆大。每甘草汤下五丸。（刘河间《宣明方》）。 \n痢频脱肛，黑色坚硬∶用巴豆壳烧灰，芭蕉自然汁煮，入朴硝少许，洗软，用真麻油点 \n火滴于上，以枯矾、龙骨少许为末，掺肛头上，以芭蕉叶托入。（ \n\\x树根\\x \n【主治】痈疽发背，脑疽鬓疽大患。掘取洗捣，敷患处，留头，妙不可言。收根阴干， \n临时水捣亦可（时珍。出杨诚《经验方》）。 \n\n\n\n<目录>木部第三十五卷\\木之二\n\n<篇名>大风子\n\n内容：（《补遗》） \n【释名】时珍曰∶能治大风疾，故名。 \n【集解】时珍曰∶大风子，今海南诸国皆有之。按∶周达观《真腊记》云∶大风乃大树 \n之子，状如椰子而圆。其中有核数十枚，大如雷丸子。中有仁白色，久则黄而油，不堪入药。 \n\\x仁\\x \n【修治】时珍曰∶取大风子油法∶用子三斤（去壳及黄油者），研极烂，瓷器盛之，封 \n口入滚汤中，盖锅密封，勿令透气，文武火煎至黑色如膏，名大风油，可以和药。 \n【气味】辛，热，有毒。 \n【主治】风癣疥癞，杨梅诸疮，攻毒杀虫（时珍）。 \n【发明】震亨曰∶粗工治大风病，佐以大风油。殊不知此物性热，有燥痰之功而伤血， \n至有病将愈而先失明者。 \n时珍曰∶大风油治疮，有杀虫劫毒之功，盖不可多服。用之外涂，其功不可没也。 \n【附方】新五。 \n大风诸癞∶大风子油一两，苦参末三两，入少酒，糊丸梧桐子大。每服五十丸，空心温 \n酒下。仍以苦参汤洗之。（《普济方》）。 \n大风疮裂∶大风子（烧存性，）和麻油、轻粉研涂。仍以壳煎汤洗之。（《岭南卫生方》）。 \n杨梅恶疮∶方同上。 \n风刺赤鼻∶大风子仁、木鳖子仁、轻粉、硫黄为末，夜夜唾调涂之。 \n手背皴裂∶大风子捣泥，涂之。（《寿域》）。 \n\n\n\n<目录>木部第三十五卷\\木之二\n\n<篇名>海红豆\n\n内容：（《海药》） \n【释名】 \n【集解】 曰∶按∶徐表《南州记》云∶生南海人家园圃中。大树而生，叶圆有荚。近 \n时蜀中种之亦成。 \n时珍曰∶树高二、三丈，叶似梨叶而圆。按∶宋祁《益部方物图》云∶红豆叶如冬青而 \n圆泽，春开花白色，结荚枝间。其子累累如缀珠，若大红豆而扁，皮红肉白，以似得名，蜀 \n人用为果 。 \n\\x豆\\x \n【气味】微寒，有小毒。 \n【主治】人黑皮 花癣，头面游风。宜入面药及澡豆（李 ）。 \n\n\n\n<目录>木部第三十五卷\\木之二\n\n<篇名>相思子\n\n内容：（《纲目》） \n【释名】红豆。 \n时珍曰∶按∶《古今诗话》云∶相思子圆而红。故老言∶昔有人殁于边，其妻思之，哭 \n于树下而卒，因以名之。此与韩凭冢上相思树不同，彼乃连理梓木也。或云即海红豆之类， \n未审的否？ \n【集解】时珍曰∶相思子生岭南。树高丈余，白色。其叶似槐，其花似皂荚，其荚似扁 \n豆。其子大如小豆，半截红色，半截黑色，彼人以嵌首饰。段公路《北户录》言∶有蔓生， \n用子收龙脑香相宜，令香不耗也。 \n【气味】苦，平，有小毒，吐人。 \n【主治】通九窍，去心腹邪气，止热闷头痛，风痰瘴疟，杀腹脏及皮肤内一切虫，除蛊 \n毒。取二七枚研服，即当吐出（时珍）。 \n【附方】新三。 \n瘴疟寒热∶相思子十四枚，水研服，取吐立瘥。（《千金》）。 \n猫鬼野道∶眼见猫鬼，及耳有所闻。用相思子、蓖麻子、巴豆各一枚，朱砂（末）、蜡 \n各 \n四铢，合捣丸如麻子大，含之。即以灰围患人，面前着一斗灰火，吐药入火中，沸即画十字 \n于火上 \n解中蛊毒∶《必效方》∶用未钻相思子十四枚，杵碎为末。温水半盏，和服。欲吐抑之勿 \n吐，少顷当大吐。轻者但服七枚。非常神效。（《外台秘要》）。 \n\n\n\n<目录>木部第三十五卷\\木之二\n\n<篇名>猪腰子\n\n内容：（《纲目》） \n【集解】时珍曰∶猪腰子生柳州。蔓生结荚，内子大若猪之内肾，状酷似之，长三、四 \n寸，色紫而肉坚。彼人以充土宜，馈送中土。 \n【气味】甘、微辛，无毒。 \n【主治】一切疮毒及毒箭伤，研细，酒服一、二钱，并涂之（时珍）。 \n\n\n\n<目录>木部第三十五卷\\木之二\n\n<篇名>石瓜\n\n内容：（《纲目》） \n【集解】时珍曰∶石瓜出四川峨眉山中及芒部地方。其树修干，树 \n状似桑。其花浅黄色。结实如缀，长而不圆，壳裂则子见，其形似瓜，其坚如石，煮液黄色。 \n【气味】苦，平，微毒。 \n【主治】心痛。煎汁，洗风痹（时珍）。 \n\n\n\n<目录>木部第三十六卷\n\n<篇名>木之三\n\n内容：（灌木类五十一种） \n\n\n\n<目录>木部第三十六卷\\木之三\n\n<篇名>桑\n\n内容：（《本经》中品） \n【释名】子名椹。 \n时珍曰∶徐锴《说文解字》云∶ ，音若，东方自然神木之名，其字象形。桑乃蚕所食， \n异于东方自然之神木，故加木于 下而别之。《典术》云∶桑乃箕星之精。 \n【集解】颂曰∶方书称桑之功最神，在人资用尤多。《尔雅》云∶桑辨有葚者栀。又云∶ \n女桑， 桑。 桑，山桑。郭璞云∶辨，半也。葚与椹同。一半有椹，一半无椹，名栀。俗 \n间呼桑之小而条长者，皆为女桑。其山桑似桑，材中弓弩； 桑，丝中琴瑟，皆材之美者也 \n，他木鲜及之。 \n桑，叶尖而长。以子种者，不若压条而分者。桑生黄衣，谓之金桑，其木必将槁矣。《种树 \n书》云∶桑以构接则桑大。桑根下埋龟甲，则茂盛不蛀。 \n\\x桑根白皮\\x \n【修治】《别录》曰∶采无时。出土上者杀人。 \n弘景曰∶东行桑根乃易得，而江边多出土，不可轻信。 \n时珍曰∶古本草言桑根见地上者名马领，有毒杀人。旁行出土者名伏蛇，亦有毒而治心 \n痛。故吴淑《事类赋》云∶伏蛇疗疾，马领杀人。 \n曰∶凡使，采十年以上向东畔嫩根，铜刀刮去青黄薄皮一重，取里白皮切，焙干用。 \n其皮中涎勿去之，药力俱在其上也。忌铁及铅。或云∶木之白皮亦可用。煮汁染褐色，久不 \n落。 \n【气味】甘，寒，无毒。权曰∶平。 \n大明曰∶温。 \n元素曰∶苦、酸。 \n杲曰∶甘、辛，寒。可升可降，阳中阴也。 \n好古曰∶甘浓而辛薄，入手太阴经。 \n之才曰∶续断、桂心、麻子为之使。 \n【主治】伤中，五劳六极，羸瘦，崩中绝脉，补虚益气（《本经》）。去肺中水气，唾血 \n热渴，水肿腹满胪胀，利水道，去寸白，可以缝金疮（《别录》）。治肺气喘满，虚劳客热头 \n痛，内补不足（甄权）。煮汁饮，利五脏。入散用，下一切风气水气（孟诜）。调中下气，消 \n痰止渴，开胃下食，杀腹脏虫，止霍乱吐泻。研汁，治小儿天吊惊痫客忤，及敷鹅口疮，大 \n验 \n【发明】杲曰∶桑白皮，甘以固元气之不足而补虚，辛以泻肺气之有余而止嗽。又云∶ \n桑白皮泻肺，然性不纯良，不宜多用。 \n时珍曰∶桑白皮长于利小水，乃实则泻其子也，故肺中有水气及肺火有余者宜之。十剂 \n云∶燥可去湿，桑白皮、赤小豆之属是矣。宋医钱乙治肺气热盛，咳嗽而后喘，面肿身热， \n泻白散∶用桑白皮（炒）一两，地骨皮（焙）一两，甘草（炒）半两。每服一、二钱，入粳 \n米百粒， \n水煎，食后温服。桑白皮、地骨皮皆能泻火从小便去，甘草泻火而缓中，粳米清肺而养血， \n此乃泻肺诸方之准绳也。元医罗天益言其泻肺中伏火而补正气，泻邪所以补正也。若肺虚而 \n小便利者，不宜用之。 \n颂曰∶桑白皮作线缝金疮肠出，更以热鸡血涂之。唐·安金藏剖腹，用此法而愈。 \n【附方】旧九，新五。 \n咳嗽吐血，甚者殷鲜∶桑根白皮一斤，米泔浸三宿，刮去黄皮，锉细，入糯米四两，焙 \n干为末。每服一钱，米饮下。（《经验方》）。 \n消渴尿多∶入地三尺桑根，剥取白皮，炙黄黑，锉。以水煮浓汁，随意饮之。亦可入少 \n米，勿用盐。（《肘后方》）。 \n产后下血∶炙桑白皮，煮水饮之。（《肘后方》）。 \n血露不绝∶锯截桑根，取屑五指撮，以醇酒服之，日三服。（《肘后方》）。 \n坠马拗损∶桑根白皮五斤为末，水一升煎膏，敷之便止。已后亦无宿血，终不发动。（《经 \n验后方》）。 \n金刃伤疮∶新桑白皮，烧灰，和马粪涂疮上，数易之。亦可煮汁服之。（《广利方》）。 \n杂物眯眼∶新桑根白皮洗净捶烂，入眼，拨之自出。（《圣惠方 \n发鬓堕落∶桑白皮（锉）二升。以水淹浸，煮五、六沸，去滓，频频洗沐，自不落也。 \n（《千金方》）。 \n发槁不泽∶桑根白皮、柏叶各一斤，煎汁沐之即润。（《圣惠方》）。 \n小儿重舌∶桑根白皮煮汁，涂乳上饮之。（《子母秘录》）。 \n小儿流涎∶脾热也，胸膈有痰。新桑根白皮，捣自然汁涂之，甚效。干者煎水。（《圣惠 \n方》） \n小儿天吊，惊痫客忤∶家桑东行根取研汁服。（《圣惠方》）。 \n小儿火丹∶桑根白皮，煮汁浴之。或为末，羊膏和涂之。（《千金方》）。 \n石痈坚硬不作脓者∶蜀桑白皮阴干为末，烊胶和酒调敷，以软为度。（《千金方》）。 \n\\x皮中白汁\\x \n【主治】小儿口疮白漫漫，拭净涂之便愈。又涂金刃所伤燥痛，须臾血止，仍以白皮裹 \n之，甚良（苏颂）。涂蛇、蜈蚣、蜘蛛伤，有验 \n【附方】旧一，新三。 \n小儿鹅口∶桑白皮汁，和胡粉涂之。（《子母秘录》）。 \n小儿唇肿∶桑木汁涂之，即愈。（《圣惠方》）。 \n解百毒瓦斯∶桑白汁一合，服之，须臾吐利自出。（《肘后方》）。 \n破伤中风∶桑沥、好酒，对和温服，以醉为度。醒服消风散。（《 \n\\x桑椹\\x（一名文武实） \n【主治】单食，止消渴（苏恭）。利五脏关节，通血气。久服不饥，安魂镇神，令人聪 \n明， \n变白不老。多收曝干为末，蜜丸日服（藏器）。捣汁饮，解中酒毒。酿酒服，利水气消肿（时 \n珍）。 \n【发明】宗 曰∶《本经》言桑甚详，然独遗乌椹，桑之精英尽在于此。采摘微研，以 \n布滤汁，石器熬成稀膏，量多少入蜜熬稠，贮瓷器中。每抄一、二钱，食后、夜卧，以沸汤 \n点服。治服金石发热口渴，生精神及小肠热，其性微凉故也。《仙方》晒干为末，蜜和为丸， \n酒服亦良。 \n时珍曰∶椹有乌、白二种。杨氏《产乳》云∶孩子不得与桑椹，令儿心寒，而陆机《诗 \n疏》云∶鸠食桑椹多则醉伤其性，何耶？《四民月令》云∶四月宜饮桑椹酒，能理百种风热。 \n其法用椹汁三斗，重汤煮至一斗半，入白蜜二合，酥油一两，生姜一合，煮令得所，瓶收。 \n每服一合，和酒饮之。亦可以汁熬烧酒，藏之经年，味力愈佳。史言魏武帝军乏食，得干椹 \n以济饥。金 \n【附方】旧一，新七。 \n水肿胀满∶水不下则满溢，水下则虚竭还胀，十无一活，宜用桑椹酒治之。桑心皮切， \n以水二斗，煮汁一斗，入桑椹再煮，取五升，以糯饭五升，酿酒饮。（《 \n瘰 结核∶文武膏∶用文武实（即桑葚子）二斗（黑熟者），以布取汁，银、石器熬成 \n薄膏。每白汤调服一匙，日三服。（《保命集》）。 \n诸骨哽咽∶红椹子细嚼，先咽汁，后咽滓，新水送下。干者亦可。（《圣惠方》）。 \n小儿赤秃∶桑椹取汁，频服。（《千金方》）。 \n小儿白秃∶黑葚入罂中曝三七日，化为水，洗之，三七日神效。（《圣济录》）。 \n拔白变黑∶黑葚一斤，蝌蚪一斤，瓶盛封闭，悬屋东头一百日，尽化为黑泥，以染白发 \n如漆。（陈藏器《本草》）。 \n发白不生∶黑熟桑椹，水浸日晒，搽涂，令黑而复生也。（《千金方》）。 \n阴症腹痛∶桑椹绢包风干，过伏天，为末。每服三钱，热酒下，取汗。（《集简方》）。 \n\\x叶\\x \n【气味】苦、甘，寒，有小毒。 \n大明曰∶家桑叶∶暖，无毒。 \n【主治】除寒热，出汗（《本经》）。汁，解蜈蚣毒（《别录》）。煎浓汁服，能除香港脚水 \n肿，利大小肠（苏恭）。炙熟煎饮，代茶止渴（孟诜）。煎饮，利五脏，通关节，下气。嫩叶 \n煎酒服，治一切风。蒸熟捣， 风痛出汗，并扑损瘀血。 烂，涂蛇、虫伤（大明）。研汁， \n治 \n金疮及小儿吻疮。煎汁服，止霍乱腹痛吐下，亦可以干叶煮之。鸡桑叶，煮汁熬膏服，去老 \n风及宿血（藏器）。治劳热咳嗽，明目长发（时珍）。 \n【发明】颂曰∶桑叶可常服。神仙服食方∶以四月桑茂盛时采叶。又十月霜后三分，二 \n分已落时，一分在者，名神仙叶，即采取，与前叶同阴干捣末，丸、散任服，或煎水代茶饮 \n之。又霜后叶煮汤，淋渫手足，去风痹殊胜。又微炙和桑衣煎服，治痢及金疮诸损伤，止血。 \n震亨曰∶经霜桑叶研末，米饮服，止盗汗。 \n时珍曰∶桑叶乃手、足阳明之药，汁煎代茗，能止消渴。 \n【附方】旧二，新十一。 \n青盲洗法∶昔武胜军宋仲孚患此二十年，用此法，二年目明如故。新采青桑叶阴干， \n月按日就地上烧存性。每以一合，于瓷器内煎减二分，倾出澄清，温热洗目，至百度，屡试 \n有验。正月初八，二月初八，三月初六，四月初四，五月初五，六月初二，七月初七，八月 \n二十，九月十二，十月十七，十一月初二，十二月三十。（《普济方》）。 \n风眼下泪∶腊月不落桑叶煎汤，日日温洗。或入芒硝。（《集简方》）。 \n赤眼涩痛∶桑叶为末，纸卷烧烟熏鼻取效，《海上方》也。（《普济方》）。 \n头发不长∶桑叶、麻叶煮泔水沐之，七次可长数尺。（《千金方》）。 \n吐血不止∶晚桑叶焙研，凉茶服三钱。只一服止，后用补肝肺药。（《圣济总录》）。 \n小儿渴疾∶桑叶不拘多少，逐片染生蜜，线系蒂上，绷，阴干。细切，煎汁日饮代茶。 \n（ \n霍乱转筋，入腹烦闷∶桑叶一握，煎饮，一、二服立定。（《圣惠方》）。 \n大肠脱肛∶黄皮桑树叶三升，水煎过，带温罨纳之。（《仁斋直指方》）。 \n肺毒风疮，状如大风∶绿云散∶用好桑叶。净洗，蒸熟（一宿候），晒干，为末。水调 \n二钱匕服。（《经验后方》）。 \n痈口不敛∶经霜黄桑叶，为末。敷之。（《直指方》）。 \n穿掌肿毒∶新桑叶研烂， 之即愈。（《通玄论》）。 \n汤火伤疮∶经霜桑叶（烧存性，）为末，油和敷之。三日愈。（《医学正传》）。 \n手足麻木不知痛痒∶霜降后桑叶煎汤，频洗。（《救急方》） \n\\x枝\\x \n【气味】苦，平。 \n【主治】遍体风痒干燥，水气、香港脚、风气，四肢拘挛，上气眼晕，肺气咳嗽，消食利 \n小便。久服轻身，聪明耳目，令人光泽。疗口干及痈疽后渴，用嫩条细切一升，熬香煎饮， \n亦无禁忌。久服，终身不患偏风（苏颂。出《近效方》，名桑枝煎。一法∶用花桑枝寸锉， \n炒香，瓦器煮减一半，再入银器，重汤熬减一半。或入少蜜亦可）。 \n【发明】颂曰∶桑枝不冷不热，可以常服。《抱朴子》言∶《仙经》云∶一切仙药，不得 \n桑煎不服。 \n时珍曰∶煎药用桑者，取其能利关节，除风寒湿痹诸痛也。观《灵枢经》治寒痹内热， \n用桂酒法，以桑炭炙布巾，熨痹处；治口僻用马膏法，以桑钩钩其口，及坐桑灰上，皆取此 \n意也。又痈疽发背不起发，或瘀肉不腐溃，及阴疮、瘰 、流注、 疮、顽疮、恶疮久不愈 \n者，用桑木炙法，未溃则拔毒止痛，已溃则补接阳气，亦取桑通关节，去风寒，火性畅达， \n出郁毒之意。其法以干桑木劈成细片，扎作小把，然火吹息，炙患处。每吹炙片时，以瘀肉 \n腐动为度，内服补托药，诚良方也。又按∶赵 《养 漫笔》云∶越州一学录少年苦嗽，百 \n药不效。或令用南向柔桑条一束，每条寸折纳锅中，以水五碗，煎至一碗，盛瓦器中，渴即 \n饮之，服一月而愈。此亦桑枝煎变法尔。 \n【附方】旧二，新四。 \n服食变白，久服通血气，利五脏∶鸡桑嫩枝，阴干为末，蜜和作丸。每日酒服六十丸。 \n（《圣惠方》）。 \n水气香港脚∶桑条二两，炒香，以水一升，煎二合。每日空心服之，亦无禁忌。（《圣济 \n总录》）。 \n风热臂痛∶桑枝一小升切炒。水三升，煎二升，一日服尽。许叔微云∶尝病臂痛，诸 \n药不效，服此数剂寻愈。观《本草切用》及《图经》言其不冷不热，可以常服；《抱朴子》 \n言∶一 \n解中蛊毒∶令人腹内坚痛，面黄青色，淋露骨立，病变不常。桑木心（锉）一斛，着釜中， \n以水淹令上有三寸，煮取二斗，澄清，微火煎得五升。空心服五合，则吐蛊毒出也。（《肘 \n后方》）。 \n刺伤手足，犯露水肿痛，多杀人∶以桑枝三条， 火炮热，断之，以头熨疮上令热，冷 \n即易之，尽三条则疮自 \n紫白癜风∶桑枝十斤，益母草三斤。水五斗，慢火煮至五斤，去滓再煎成膏。每卧时温酒调 \n服半合，以愈为度。 \n\\x桑柴灰\\x \n【气味】辛，寒，有小毒。 \n【主治】蒸淋取汁为煎，与冬灰等分，同灭痣疵黑子，蚀恶肉。煮小豆食，大下水胀。 \n敷金疮，止血生肌（苏恭）。桑霜，治噎食积块（时珍）。 \n【附方】旧五，新六。 \n目赤肿痛∶桑灰一两。黄连半两，为末。每以一钱泡汤，澄清洗之。（《圣济总录》）。 \n洗青盲眼∶正月八，二月八，三月六，四月四，五月五，六月二，七月七，八月二十， \n九月十二，十月十七，十一月二十六，十二月三十日。每遇上件神日，用桑柴灰一合，煎汤 \n沃之，于瓷器中，澄取极清，稍热洗之。如冷即重汤顿温，不住手洗。久久视物如鹰鹘也。 \n一法以桑灰、童子小便和作丸。每用一丸，泡汤澄洗。（《经验方》）。 \n尸疰鬼疰∶其病变动，乃有三十六种至九十九种，使人寒热淋沥，恍惚默默，不得知所 \n苦，累年积月，以至于死，复传亲人，宜急治之。用桑树白皮曝干，烧灰二斗，着甑中蒸透， \n以釜中汤三、四斗，淋之又淋，凡三度极浓，澄清只取二斗，以渍赤小豆二斗，一宿，曝干 \n复渍，灰汁尽乃止，以豆蒸熟。以羊肉或鹿肉作羹，进此豆饭，初食一升至二升，取饱。微 \n者，三、四斗愈；极者七、八斗愈。病去时，体中自觉疼痒淫淫。若根本不尽，再为之。神 \n效方也。（《肘后方》）。 \n腹中症瘕∶方见介部鳖下。 \n身面水肿，坐卧不得∶取东引花桑枝，烧灰淋汁，煮赤小豆。每饥即饱食之，不得吃汤 \n饮 \n面上痣疵∶寒食前后，取桑条，烧灰，淋汁，入锻石熬膏，以自己唾调点之，自落也。 \n（《皆效方》）。 \n白癜驳风∶桑柴灰二斗，甑内蒸之，取釜内热汤洗。不过五、六度，瘥。（《圣惠方》）。 \n大风恶疾，眉发脱落∶以桑柴灰热汤淋取汁，洗头面（以大豆水研浆，解释灰味，弥佳）。 \n次用熟水，入绿豆面濯之。三日 \n狐尿刺人，肿痛欲死∶热桑灰汁渍之，冷即易。（《肘后方》）。 \n金疮作痛∶桑柴灰筛细，敷之。（《梅师方》）。 \n疮伤风水，肿痛入腹，则杀人∶多以桑灰淋汁渍之，冷复易。（《梅师方》）。 \n头风白屑∶桑灰淋汁沐之，神良。（《圣惠方》）。 \n桑耳、桑黄 见菜部木耳。 \n桑花 见草部苔类。 \n桑寄生 见后寓木类。 \n桑柴火 见火部。 \n桑螵蛸 见虫部。 \n桑蠹 见虫部。 \n\n\n\n<目录>木部第三十六卷\\木之三\n\n<篇名>柘\n\n内容：（宋《嘉 》） \n【释名】时珍曰∶按∶陆佃《埤雅》云∶柘宜山石，柞宜山阜。柘之 \n【集解】宗 曰∶柘木里有纹，亦可旋为器。其叶可饲蚕，曰柘蚕，然叶硬，不及桑叶。 \n入药以无刺者良。 \n时珍曰∶处处山中有之。喜丛生。干疏而直。叶丰而浓，团而有尖。其叶饲蚕，取丝作 \n琴瑟，清响胜常。《尔雅》所谓棘茧，即此蚕也。《考工记》云∶弓人取材以柘为上。其实状 \n如桑子，而圆粒如椒，名隹子（隹音锥）。其木染黄赤色，谓之柘黄，天子所服。《相感志》 \n云∶柘木以酒醋调矿灰涂之，一宿则作间道乌木纹。物性相伏也。 \n木白皮、东行根白皮 \n【气味】甘，温，无毒。 \n【主治】妇人崩中、血结，疟疾（大明）。煮汁酿酒服，主风虚耳聋，补劳损虚羸，腰"}]);
